INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'hunter', 'cocktail', '헌터 — 위스키와 체리 히링, 두 가지 재료가 만들어내는 의외의 복잡한 풍미', '「헌터(Hunter) 칵테일」은 잘 알려지지 않은 칵테일이지만, 확실히 칵테일 마니아 사이에서는 어느 정도 인지도를 가지고 있으며, 특히 일본의 칵테일 씬을 좋아하는 분들이라면 한 번쯤은 들어봤을 법한 칵테일입니다.', '/articles/hunter/00.webp',
  'https://blog.naver.com/shakinglikebartender/224381235796', false,
  '[{"kind":"figure","src":"/articles/hunter/00.webp","width":966,"height":966},{"kind":"quote","text":"75% Rye Whiskey"},{"kind":"quote","text":"25% Cherry Brandy"},{"kind":"paragraph","text":"「헌터(Hunter) 칵테일」은 잘 알려지지 않은 칵테일이지만, 확실히 칵테일 마니아 사이에서는 어느 정도 인지도를 가지고 있으며, 특히 일본의 칵테일 씬을 좋아하는 분들이라면 한 번쯤은 들어봤을 법한 칵테일입니다."},{"kind":"figure","src":"/articles/hunter/01.webp","width":273,"height":132,"caption":"Jack''s Manual (1908)"},{"kind":"paragraph","text":"1908년 출판된 Jacob A. Grohusko의 저서인 「Jack''s Manual」에서 등장한 것이 이 칵테일에 대한 가장 오래된 기록이며, 라이 위스키와 체리브랜디를 3:1의 비율로 만들었습니다."},{"kind":"paragraph","text":"이후 몇십 년 동안 다양한 칵테일 북에서 일부 변형이 추가되는 식의 레시피도 있었으나, 라이 위스키와 체리브랜디를 3:1 또는 2:1 비율로 하는 기본 구조 자체는 크게 변형되지 않고 소개되었습니다."},{"kind":"paragraph","text":"다만, 그 외에 인기를 끌었다는 식의 기록은 없는 걸 보니, 딱히 메인스트림에 있던 칵테일이라 보기는 어려울 것 같습니다."},{"kind":"figure","src":"/articles/hunter/02.webp","width":966,"height":966},{"kind":"quote","text":"칵테일 레시피"},{"kind":"quote","text":"버번 위스키 vs 라이 위스키"},{"kind":"paragraph","text":"- 라이 or 버번 위스키 45ml / Rye or  Bourbon Whiskey 45ml"},{"kind":"paragraph","text":"- 체리 히링 15ml / Cherry Heering 15ml"},{"kind":"paragraph","text":"- (옵션) 마라스키노 체리 1개"},{"kind":"paragraph","text":"이 칵테일에서 제일 중요한 건 기주입니다."},{"kind":"paragraph","text":"이에 관련해서 진 바질 스매시라는 불후의 모던 클래식 칵테일을 만든 요르그 마이어와 일본 긴자의 Bar High Five의 오너이자 세계적으로 유명한 바텐더인 우에노 히데츠구의 흥미로운 일화가 있습니다(출처: difford''s guide)."},{"kind":"paragraph","text":"요르그 마이어에 따르면, 우에노 히데츠구는 그에게 노아스밀(Noah''s Mill) 버번과 체리 히링을 2:1로 한 헌터 칵테일을 소개하면서 버번이 이 칵테일과 완벽한 궁합을 이루기 때문에 변경했다고 합니다."},{"kind":"paragraph","text":"다만, 이 노아스밀은 버번이긴 하지만 제 생각에는 꽤나 라이 위스키스러운 민트, 스파이시함이 느껴지는 버번이기 때문에 조금 의아한 면이 있기는 합니다만, 그 당시와 맛이 변했을 수도 있죠."},{"kind":"paragraph","text":"개인적으로는 기주는 결국 어떤 캐릭터를 내고 싶을지에 따라 다를 것 같습니다. 예를 들어 라이 위스키를 사용하게 되면 비교적 드라이하고, 스파이시함에 체리 캐릭터를 더하는 느낌이, 버번 위스키를 사용하게 되면 체리·바닐라·캐러멜 캐릭터의 비교적 달고 묵직한 느낌이 주가 됩니다."},{"kind":"paragraph","text":"또한, 같은 라이 위스키, 버번 위스키라 하더라도 브랜드 및 매시빌 등에 따라 맛이 또 다르기 때문에, 만들기 전에 기주의 맛을 참고해서 정하는 게 좋지 않을까 싶습니다."},{"kind":"figure","src":"/articles/hunter/03.webp","width":966,"height":966},{"kind":"quote","text":"How to Mix?"},{"kind":"paragraph","text":"1. 믹싱 글라스에 모든 재료를 넣어줍니다."},{"kind":"paragraph","text":"2. 믹싱 글라스에 얼음을 채워주고, 스터해줍니다."},{"kind":"paragraph","text":"3. 차게 해 둔 잔에 부어줍니다."},{"kind":"paragraph","text":"4. 마라스키노 체리를 넣어줍니다(*옵션)."},{"kind":"paragraph","text":"헌터 칵테일은 라이 위스키의 캐릭터에 체리 히링의 캐릭터가 자연스럽게 더해져 풍미를 확장시키는 느낌이 듭니다."},{"kind":"paragraph","text":"구체적으로 가벼운 바닐라와 스파이시한 풍미를 시작으로, 묵직한 체리 및 건포도 등의 풍미가 따뜻한 향신료와 함께 이어지고, 은은한 쌉쌀함이 남습니다. 상당히 복잡한 맛이고, 어딘가 맨하탄을 떠올리게 하기도 합니다."},{"kind":"paragraph","text":"헌터 칵테일은 2개의 재료만이 사용되고, 그중에서 체리 브랜디는 체리 히링을 사용하는 것이 권장되기 때문에 기주에 따라 맛이 천차만별이 될 수 있습니다. 또한, 재료가 적어 만들기도 상당히 어려운 칵테일입니다."}]'::jsonb, 'published', '2026-08-17T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'rum-and-soda', 'cocktail', '럼앤소다 — 다니엘 크레이그의 제임스 본드는 왜 첫 잔으로 럼을 선택했을까', '다니엘 크레이그가 새로운 제임스 본드로 데뷔한 영화 《카지노 로얄 (2006)》은 그가 살인 면허(00)를 막 취득한 초기의 이야기를 다룹니다.', '/articles/rum-and-soda/00.webp',
  'https://blog.naver.com/shakinglikebartender/224350382073', false,
  '[{"kind":"figure","src":"/articles/rum-and-soda/00.webp","width":966,"height":966},{"kind":"quote","text":"\"Large Mount Gay and Soda, please\""},{"kind":"paragraph","text":"다니엘 크레이그가 새로운 제임스 본드로 데뷔한 영화 《카지노 로얄 (2006)》은 그가 살인 면허(00)를 막 취득한 초기의 이야기를 다룹니다."},{"kind":"paragraph","text":"이 영화에서 다니엘 크레이그의 제임스 본드가 가장 처음으로 주문해서 마시는 술은 본드 하면 잘 알려진 칵테일인 마티니가 아니라, 바로 바베이도스의 마운트 게이 럼(Mount Gay)으로 만든 럼앤소다입니다."},{"kind":"paragraph","text":"제임스 본드는 상당한 애주가로서, 많은 칵테일을 마시는 건 이미 잘 알려져 있는 사실입니다. 다만, 다니엘 크레이그가 제임스 본드로 낙점된 이후, 왜 첫 칵테일로 럼소다를 선택했을까 생각했을 때 개인적으로 2가지의 추측이 가능하지 않을까 싶습니다."},{"kind":"quote","text":"영화 배경인 카리브해의 지역 및 기후 특성"},{"kind":"paragraph","text":"제임스 본드가 럼 앤 소다를 주문한 곳은 아열대 및 열대 기후를 가진 카리브해의 대표적인 휴양지, 바하마입니다. 이러한 현지 기후 특성상 도수가 높은 마티니 같은 칵테일은 어울리지 않을 것이고, 본드는 카리브해의 열기를 식히기 위한 한 잔이 필요했겠죠."},{"kind":"paragraph","text":"또한, 본드는 럼 중에서도 마운트 게이를 정확히 지목해서 주문을 하는데, 이 럼은 바하마와 같은 카리브해 연안에 위치한 섬나라인 바베이도스에서 생산됩니다."},{"kind":"paragraph","text":"즉, 현지의 술을 베이스로 하는 칵테일을 기후에 맞춰 주문한 건데, 이는 제임스 본드가 현지에 꽤나 익숙한 듯한 인상을 줍니다."},{"kind":"quote","text":"새로운 제임스 본드의 캐릭터성의 은유적 표현"},{"kind":"paragraph","text":"다니엘 크레이그 이전 세대의 제임스 본드들은 대부분 흐트러짐 없는 완벽한 수트 핏을 유지하며, 어떤 위기 상황에서도 여유를 잃지 않는 귀족적이고 세련된 이미지의 스파이를 고수해 왔습니다."},{"kind":"paragraph","text":"설정상 제임스 본드라는 인물 자체가 전통적인 영국 상류층 출신의 엘리트였기에, 그들이 극 중 마시는 술 역시 샴페인이나 마티니처럼 상류층의 코드를 공유하는 주류가 대부분이었습니다."},{"kind":"paragraph","text":"반면, 럼(Rum)은 역사적으로 오랜 시간 동안 선원이나 노동자 계층에서 주로 소비되던 거칠고 품질이 낮은 술이라는 이미지가 강했습니다."},{"kind":"paragraph","text":"이런 배경을 두고 보면, 다니엘 크레이그의 제임스 본드가 첫 술로 기존의 세련된 주류 대신 거친 느낌의 ''럼 앤 소다''를 선택한 것은 꽤나 흥미로운 대목으로, 제임스 본드의 스크린 상에서의 변화를 암시하는 장치로 사용되지 않았을까 싶습니다."},{"kind":"paragraph","text":"즉, 이번 제임스 본드는 기존까지 관객들이 생각하던 상류층의 세련된 신사적인 이미지의 본드가 아니라, 거칠고 대담한 야성미를 가진 본드라는 것을 칵테일 한 잔으로 보여주었다는 것이죠."},{"kind":"figure","src":"/articles/rum-and-soda/01.webp","width":966,"height":966},{"kind":"quote","text":"칵테일 레시피"},{"kind":"paragraph","text":"- 바베이도스 럼 40ml"},{"kind":"paragraph","text":"- 탄산수 120ml"},{"kind":"paragraph","text":"작중 실제 사용되었던 럼은 마운트 게이의 코어 라인 중 하나인 이클립스(Eclipse)로, 엑스-아메리칸 위스키 캐스크에서 숙성시킨 골드 럼입니다."},{"kind":"paragraph","text":"다만, 우리나라에는 수입되지 않는 제품이니, 플렌터레이(플렌테이션)의 바베이도스 럼을 사용했습니다."},{"kind":"figure","src":"/articles/rum-and-soda/02.webp","width":966,"height":966},{"kind":"quote","text":"How to Mix?"},{"kind":"paragraph","text":"1. 하이볼 글라스에 럼과 얼음을 채운 후, 럼을 식혀줄 정도로만 스터 해줍니다."},{"kind":"paragraph","text":"2. 탄산수를 채워주고, 얼음을 위아래로 몇 번 들었다 놔줍니다."},{"kind":"paragraph","text":"럼앤소다는 결국에는 럼 하이볼로, 아주 간단한 칵테일이며, 당연히 어떤 럼을 선택해서 만드냐에 따라 맛이 천차만별입니다. 개인적으로는 숙성감이 과하지 않은 골드 럼으로 만드는 게 가장 부담스럽지 않을 것 같습니다."},{"kind":"paragraph","text":"플렌터레이 바베이도스 럼으로 만든 럼앤소다는 ''열대과일, 바닐라, 후숙된 바나나, 본드나 고무스러운 느낌, 럼 특유의 알콜감''이 은은하게 느껴지는, 부담스럽지 않고 청량한 한 잔이었습니다."},{"kind":"paragraph","text":"국내에는 아직까지 다양한 종류의 럼이 들어오지는 않지만, 최근에는 그래도 포스퀘어, 워시팍, 푸써스와 같은 재밌는 럼이 수입되고 있는 점이 상당히 고무적입니다."}]'::jsonb, 'published', '2026-07-18T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'bobby-burns', 'cocktail', '바비 번스 — 이름 뒤의 이야기만큼이나 복잡한 향미', '「바비 번스」는 일반적으로 스코틀랜드의 국민 시인인 로버트 번스*를 기리기 위해 만들어진 칵테일로 알려져 있으며, 그의 생일을 기념하는 번스 나이트(Burns Night) 행사에서 자주 언급되는 칵테일입니다.', '/articles/bobby-burns/00.webp',
  'https://blog.naver.com/shakinglikebartender/224308583292', false,
  '[{"kind":"figure","src":"/articles/bobby-burns/00.webp","width":966,"height":966},{"kind":"quote","text":"로버트 번스(Robert Burns)와 바비 번스"},{"kind":"paragraph","text":"「바비 번스」는 일반적으로 스코틀랜드의 국민 시인인 로버트 번스*를 기리기 위해 만들어진 칵테일로 알려져 있으며, 그의 생일을 기념하는 번스 나이트(Burns Night) 행사에서 자주 언급되는 칵테일입니다."},{"kind":"paragraph","text":"*로버트의 애칭이 바비(Bobby)"},{"kind":"paragraph","text":"다만, 칵테일 이름이 로버트 번스의 이름과 같다는 점 말고는 근거가 빈약하며, 오히려 알버트 크로켓(Albert Stevens Crockett)은 본인의 저서에서 다른 가능성을 제시합니다."},{"kind":"figure","src":"/articles/bobby-burns/01.webp","width":472,"height":187,"caption":"Old Waldorf-Astoria Bar Days(1931)"},{"kind":"paragraph","text":"크로컷은 로버트 번스라는 이름의 칵테일을 소개하면서 스코틀랜드의 시인의 이름을 따왔을 것이라면서도, 옛 월도프 호텔 바의 단골손님이었던 시가 판매원의 이름을 땄을 가능성도 있다고 기록했습니다."},{"kind":"paragraph","text":"실제로 옛 월도프 호텔의 바가 개장 및 운영되던 시기에 로버트 번스라는 이름의 시가 브랜드 내지는 시가 판매점이 있었다는 점에서 실제 해당 시가 브랜드(또는 판매점)의 이름이 붙었을 가능성이 있다는 주장이 제기되기도 합니다."},{"kind":"quote","text":"칵테일의 확립"},{"kind":"paragraph","text":"바비 번스라는 이름의 칵테일의 가장 오래된 기록은 1899년까지 거슬러 올라가나, 스카치 위스키·진저 코디얼·오렌지 비터스 등이 들어가는 현재의 바비 번스와는 상당히 다른 칵테일입니다."},{"kind":"paragraph","text":"1900년대 초반에는 베이비 번스(Baby Burns)라는 이름으로 현재와 비슷한 레시피의 칵테일이 기록되었으며, 그 외에도 보비 번스(Bobbie Burns), 로버트 번스 등 의 다양한 레시피와 이름의 칵테일이 기록되었습니다."},{"kind":"figure","src":"/articles/bobby-burns/02.webp","width":502,"height":155,"caption":"The Savoy Cocktail Book(1930)"},{"kind":"paragraph","text":"이후, 현재의 바비 번스는 해리 크래독(Harry Cradock)의 저서 사보이 칵테일 북(The Savoy Cocktail Book)에 기록된 이름과 내용을 바탕으로 정립되게 되었습니다."},{"kind":"figure","src":"/articles/bobby-burns/03.webp","width":966,"height":966},{"kind":"quote","text":"칵테일 레시피"},{"kind":"paragraph","text":"- 스카치 위스키 45ml"},{"kind":"paragraph","text":"- 스윗 버무스 15ml"},{"kind":"paragraph","text":"- 베네딕틴 돔 5~8ml"},{"kind":"paragraph","text":"- 가니시: 레몬 껍질"},{"kind":"figure","src":"/articles/bobby-burns/04.webp","width":966,"height":966},{"kind":"quote","text":"How to Mix"},{"kind":"paragraph","text":"1. 믹싱 글라스에 모든 재료를 넣는다."},{"kind":"paragraph","text":"2. 믹싱 글라스에 얼음을 채워주고, 스터해준다."},{"kind":"paragraph","text":"3. 차게 해 둔 잔에 부어준다."},{"kind":"paragraph","text":"4. 레몬 껍질을 짜서 오일을 뿌려준다."},{"kind":"paragraph","text":"바비 번스는 아주아주 복합적인 맛의 칵테일로, 스카치의 바닐라함과 숙성감, 버무스의 와인스러움과 향신료, 베니딕틴의 꿀과 약간의 허브함까지 정말 다양한 캐릭터가 느껴지는 칵테일입니다."},{"kind":"paragraph","text":"스카치 위스키의 경우는 각자 좋아하는 걸 사용하시면 될 것 같은데, 개인적으로는 피트가 없고, 숙성감이 과하지 않은 싱글몰트 또는 블렌디드 스카치 위스키를 사용하는 것을 추천드립니다."},{"kind":"paragraph","text":"또한, 바비 번스가 재료적으로나 만들어진 시기상(또는 기록상) 롭 로이(Rob Roy)라는 칵테일의 변형이 아닐까 생각하고 있으며, 제 레시피는 이를 염두에 둔 비율입니다. 또, 그러한 접근법으로 앙고스투라 비터를 첨가하기도 하구요."},{"kind":"paragraph","text":"유튜브에도 다양한 레시피가 있으니, 참고해서 본인만의 비율을 만들어가는 재미가 있는 칵테일이고, 스카치·버무스·베네딕틴의 밸런스를 절묘하게 맞추기 생각보다 어렵기도 한 칵테일입니다."},{"kind":"paragraph","text":"개인적으로 스카치 위스키 칵테일을 추천해달라 하는 경우 항상 상위권에 드는 칵테일이고, 나이트캡에 딱 어울릴만한 칵테일이라 상각됩니다."}]'::jsonb, 'published', '2026-06-07T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'bobby-burns' AND c.slug = 'bobbyburns';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'giffard-home-cocktails', 'cocktail', '아침의 햇살부터 밤의 티파티까지 — 지파드 시럽·리큐르로 하루를 담은 홈칵테일', '아침부터 밤까지, 지파드 시럽과 리큐르로 만든 홈칵테일 모음. 지파드의 지원을 받아 쓴 제휴 콘텐츠다.', '/articles/giffard-home-cocktails/00.webp',
  'https://blog.naver.com/shakinglikebartender/224295903778', true,
  '[{"kind":"paragraph","text":"\"본 콘텐츠는 지파드로부터 제품 및 활동 지원을 받아 작성되었습니다.\""},{"kind":"figure","src":"/articles/giffard-home-cocktails/00.webp","width":966,"height":966},{"kind":"paragraph","text":"이번 지파드 서포터즈 홈칵테일 팀미션에서는 하루가 흘러가는 분위기를 두 잔의 칵테일을 지파드 시럽과 지파드 리큐르로 표현해보았습니다."},{"kind":"paragraph","text":"햇살이 가장 부드러운 아침부터 이른 오후의 공기부터, 하루 끝에 천천히 내려앉는 밤의 온도까지 지파드 시럽과 지파드 리큐르를 활용해 시간의 흐름을 한 잔 안에 담아보려 노력했습니다"},{"kind":"figure","src":"/articles/giffard-home-cocktails/01.webp","width":966,"height":966},{"kind":"figure","src":"/articles/giffard-home-cocktails/02.webp","width":966,"height":1449},{"kind":"figure","src":"/articles/giffard-home-cocktails/03.webp","width":966,"height":966},{"kind":"paragraph","text":"《Sunday Spritz》"},{"kind":"paragraph","text":"이른 낮시간 창문으로 햇빛이 밝게 비추는 순간을 떠올리며 만든 논알콜 칵테일로, 복잡한 맛보다는 가볍고 산뜻한 인상을 남기기 위해 허브와 시트러스 중심으로 구성했습니다."},{"kind":"paragraph","text":"로즈마리의 은은한 허브감과 함께 블러드오렌지의 달큰한 과실감이 자연스럽게 이어지고, 논알콜 스파클링 와인과 탄산수의 기포가 전체적인 분위기를 가볍게 정리해줍니다."},{"kind":"paragraph","text":"이름에서도 알 수 있듯이 칵테일의 구조는 햇살과 아주 잘 어울리는 여러 스프리츠 계열의 칵테일을 참고해서 만들었는데, 칵테일의 분위기와 맛 모두 이른 브런치와 잘 어우러지는 칵테일입니다."},{"kind":"paragraph","text":"📍Recipe"},{"kind":"paragraph","text":"지파드 로즈마리 시럽 30ml"},{"kind":"paragraph","text":"지파드 블러드오렌지 시럽 10ml"},{"kind":"paragraph","text":"논알콜 스파클링 와인 90ml"},{"kind":"paragraph","text":"탄산수 90ml"},{"kind":"paragraph","text":"📍Garnish"},{"kind":"paragraph","text":"오렌지 하프 휠 / 로즈마리"},{"kind":"paragraph","text":"📍How to Mix"},{"kind":"paragraph","text":"1. 잔에 로즈마리, 블러드오렌지 시럽을 넣고, 탄산수를 살짝 넣어준다."},{"kind":"paragraph","text":"2. 얼음을 넣고 잠시 스터해준다."},{"kind":"paragraph","text":"3. 논알콜 스파클링 와인과 탄산수를 넣고, 얼음을 움직여 섞어준다."},{"kind":"paragraph","text":"4. 오렌지와 로즈마리로 가니시해준다."},{"kind":"figure","src":"/articles/giffard-home-cocktails/04.webp","width":966,"height":966},{"kind":"figure","src":"/articles/giffard-home-cocktails/05.webp","width":966,"height":966},{"kind":"figure","src":"/articles/giffard-home-cocktails/06.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/giffard-home-cocktails/07.webp","width":966,"height":967},{"kind":"paragraph","text":"《Garden Tea Party》"},{"kind":"paragraph","text":"밤에는 조금 더 차분하고 깊은 무드로 접근했는데, 앞선 허브감과 과실감의 연장선상에서 정원이 있는 티 파티가 밤까지 이어진다면 어떤 맛일까 상상하며 만든 칵테일입니다."},{"kind":"paragraph","text":"럼의 묵직한 베이스 위에 피치와 카시스 리큐르로 과실감을 더하고, 자스민 티의 플로럴한 캐릭터와 시나몬의 따뜻한 향신료 캐릭터를 겹쳐 정원에서 즐기는 밤 공기처럼 부드럽고 천천히 퍼지는 느낌을 표현했습니다."},{"kind":"paragraph","text":"클레리파이드 밀크 펀치 방식으로 완성해 투명하게 만들고, 다양한 꽃을 가니시로 해서 정원에서의 티 파티에 어울릴만한 느낌으로 표현했습니다."},{"kind":"paragraph","text":"📍Recipe"},{"kind":"paragraph","text":"플렌터레이 화이트 럼 45ml"},{"kind":"paragraph","text":"지파드 크렘 드 페슈  20ml"},{"kind":"paragraph","text":"지파드 크렘 드 카시스 10ml"},{"kind":"paragraph","text":"트리플섹 15ml"},{"kind":"paragraph","text":"자스민 티 50ml"},{"kind":"paragraph","text":"레몬즙 17ml"},{"kind":"paragraph","text":"시나몬 시럽 15ml"},{"kind":"paragraph","text":"우유 50ml"},{"kind":"paragraph","text":"📍Garnish"},{"kind":"paragraph","text":"오렌지 슬라이스 / 자스민 잎 / 식용꽃"},{"kind":"paragraph","text":"📍How to Mix"},{"kind":"paragraph","text":"1. 우유, 가니시 이외의 재료를 모두 섞어준다."},{"kind":"paragraph","text":"2. 우유에 섞은 재료를 부어주면서 저어준다."},{"kind":"paragraph","text":"3. 잠시 후 커피 필터로 걸러준다."},{"kind":"paragraph","text":"4. 걸러진 칵테일을 얼음이 든 잔에 부어주고, 가니시해준다"},{"kind":"paragraph","text":"이번 팀미션에서는 단순히 두 잔의 칵테일을 만드는 것을 넘어, 아침부터 밤까지 이어지는 하루의 흐름과 분위기를 지파드만의 향과 맛으로 표현해보고자 했습니다."},{"kind":"paragraph","text":"가볍고 밝은 햇살이 떠오르는 낮의 무드부터, 천천히 온도가 내려앉는 밤의 공기까지. 서로 다른 시간대의 감정을 각기 다른 스타일의 칵테일 안에 담아내며, 지파드가 가진 다양한 매력을 자연스럽게 풀어내고 싶었습니다."},{"kind":"paragraph","text":"\"지나친 음주는 뇌졸중, 기억력 손상이나 치매를 유발합니다. 임신 중 음주는 기형아 출생 위험을 높입니다.\""}]'::jsonb, 'published', '2026-05-25T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'beer-americano', 'cocktail', '비어 아메리카노 — 맥주로 더한, 산뜻하고 폭신한 아메리카노의 변형', '「비어 아메리카노」는 이름에서도 알 수 있듯이 클래식 칵테일 중 하나인 아메리카노에 맥주라는 요소를 더한 칵테일로, 약 10년 전에 밀라노의 Cafe Trussardi에서 토마소 세카(Tommaso Cecca)라는 바텐더에 의해 만들어졌다고 합니다.', '/articles/beer-americano/00.webp',
  'https://blog.naver.com/shakinglikebartender/224270366931', false,
  '[{"kind":"figure","src":"/articles/beer-americano/00.webp","width":966,"height":966},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"「비어 아메리카노」는 이름에서도 알 수 있듯이 클래식 칵테일 중 하나인 아메리카노에 맥주라는 요소를 더한 칵테일로, 약 10년 전에 밀라노의 Cafe Trussardi에서 토마소 세카(Tommaso Cecca)라는 바텐더에 의해 만들어졌다고 합니다."},{"kind":"paragraph","text":"기본적으로 아메리카노에서 탄산수를 맥주로 바꾼 것인데, 사실 단순히 캄파리+버무스에 맥주를 넣는다던가, 맥주에 캄파리를 소량 넣어서 마시는 방식은 이전부터 꽤 있었어서 식상해 보일 수도 있습니다."},{"kind":"paragraph","text":"다만, 토마소 세카는 하나의 변형을 주는데, 바로 맥주를 휘핑해서 실질적으로 거품을 넣는다는 것으로, 이 칵테일의 특별함이 여기에 있습니다."},{"kind":"paragraph","text":"맥주하면 청량한 탄산감을 생각하게 되는 게 당연합니다. 그러나 여기서는 맥주를 휘핑해 거품을 내서 칵테일에 넣어주는데, 칵테일에 폭신폭신한 질감을 더해주게 됩니다."},{"kind":"paragraph","text":"기존의 클래식한 아메리카노가 캄파리와 스윗 버무스에 탄산수를 더해 쓴 맛을 비교적 가볍고 청량하게 즐길 수 있는 칵테일이라면, 비어 아메리카노는 폭신한 질감과 맥주의 풍미로 보다 부드럽고 무게감은 잃지 않게 즐길 수 있는 칵테일이라 할 수 있습니다."},{"kind":"figure","src":"/articles/beer-americano/01.webp","width":966,"height":966},{"kind":"figure","src":"/articles/beer-americano/02.webp","width":966,"height":966},{"kind":"paragraph","text":"Ingredietns"},{"kind":"paragraph","text":"30ml 캄파리 (Campari)"},{"kind":"paragraph","text":"30ml 스윗 버무스 (Sweet Vermouth)"},{"kind":"paragraph","text":"맥주(가급적 가볍고 깔끔한 느낌)"},{"kind":"paragraph","text":"가니시: 오렌지 껍질 또는 휠"},{"kind":"figure","src":"/articles/beer-americano/03.webp","width":966,"height":966},{"kind":"figure","src":"/articles/beer-americano/04.webp","width":966,"height":966},{"kind":"figure","src":"/articles/beer-americano/05.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 얼음을 채운 하이볼 잔에 맥주 외의 재료를 넣고, 스터한다."},{"kind":"paragraph","text":"2. 맥주를 휘핑해서 거품을 만들어준다."},{"kind":"paragraph","text":"3. 커품을 잔에 따라준다."},{"kind":"paragraph","text":"4. 바스푼으로 잘 섞어준다."},{"kind":"paragraph","text":"5. 오렌지 웨지로 가니시한다."},{"kind":"paragraph","text":"맥주라는 요소가 들어간 것치고 생각보다 쓴맛이 안나고, 오히려 들큰하면서도 산뜻하며, 폭신폭신한 질감이 상당히 매력적인 칵테일입니다."},{"kind":"paragraph","text":"어떤 맥주가 오리지널 레시피에 쓰였는지는 모르겠으나, 대부분 가벼운 캐릭터의 라거를 사용하라고 설명하고 있습니다."},{"kind":"paragraph","text":"아메리카노라는 칵테일의 변형인데다가 맥주까지 들어가기 때문에 재료만 보면 탄산을 기대하게 되지만, 맥주를 휘핑해 거의 거품을 더해주는 것이기 때문에 탄산은 없고, 폭신한 느낌이 더해집니다."},{"kind":"paragraph","text":"캄파리의 쓴맛을 꽤나 가려주면서도, 그 쌉쌀들큰한 캐릭터가 산뜻하게 다가오니 캄파리를 싫어하시는 분들이라도 가볍게 마실 수 있을 것 같네요."},{"kind":"paragraph","text":"정말 기분 좋은 식전주로 어울리고, 봄 또는 가을에 마시면 가장 좋을 것 같습니다."}]'::jsonb, 'published', '2026-04-30T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'beer-americano' AND c.slug = 'beeramericano';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'sloe-gin-fizz', 'cocktail', '슬로 진 피즈 — 진 피즈의 새콤달콤한 변형', '「슬로 진 피즈」는 일반적인 진 피즈(Gin Fizz)에서 기주를 진에서 슬로 진으로 변경한 아주 간단한 변형으로, 그 기원 자체는 명확하지 않지만 아무래도 슬로 진의 상업화와 칵테일 문화의 발전이 맞물리며 형성된 것으로 보입니다.', '/articles/sloe-gin-fizz/00.webp',
  'https://blog.naver.com/shakinglikebartender/224233308186', false,
  '[{"kind":"figure","src":"/articles/sloe-gin-fizz/00.webp","width":966,"height":966},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"「슬로 진 피즈」는 일반적인 진 피즈(Gin Fizz)에서 기주를 진에서 슬로 진으로 변경한 아주 간단한 변형으로, 그 기원 자체는 명확하지 않지만 아무래도 슬로 진의 상업화와 칵테일 문화의 발전이 맞물리며 형성된 것으로 보입니다."},{"kind":"paragraph","text":"슬로진은 이전부터 영국 가정에서 많이 만들어지던 리큐르로, 토지 경계를 구분하기 위한 울타리에서 흔히 볼 수 있는 블랙손(Blackthorn) 가지의 열매인 슬로베리를 진에 침출하는 방식으로 만들어집니다."},{"kind":"paragraph","text":"이 슬로베리는 그대로 먹기에는 떫고 신맛이 강하기 때문에 진에 담가 설탕과 함께 침출하기 시작했고, 단순히 병에 담아 만들 수 있을 정도로 간단했기 때문에 자연스럽게 가정에서 편하게 만들어 마실 수 있게 되었습니다."},{"kind":"paragraph","text":"이 슬로 진의 역사는 생각보다 꽤나 오래되었는데, 진 브랜드 중 하나인 십스미스(Sipsmith)에서는 1717년에 쓰인 한 시에서 홈메이드 슬로 진이 사회적 병폐로 언급된 사례를 소개하기도 합니다."},{"kind":"paragraph","text":"이렇게 영국 가정에서 만들어지던 슬로 진은 19세기 말 ~ 20세기 초에 영국에서 상업적으로 생산되기 시작하였다고 합니다."},{"kind":"paragraph","text":"또한, 19세기 말에는 이미 여러 칵테일 관련 저서에서 다양한 기주의 피즈(Fizz)류 칵테일이 소개되었으며, 특히 제리 토마스의 저서 ''바텐더스 가이드''의 1876년판 부록에서 ''Fiz''라는 이름으로 여러 피즈류 칵테일이 소개됩니다."},{"kind":"paragraph","text":"이러한 흐름을 종합해 보면, 슬로진피즈는 약 19세기 말에 탄생하지 않았을까 추정해 볼 수 있으며, 가정에서 만들어진 술이 상업화를 거쳐 바의 칵테일 문화로 편입된 독특한 이력의 칵테일이라 할 수 있습니다."},{"kind":"figure","src":"/articles/sloe-gin-fizz/01.webp","width":966,"height":966},{"kind":"paragraph","text":"Ingredietns"},{"kind":"paragraph","text":"45ml 슬로 진 (Sloe Gin)"},{"kind":"paragraph","text":"20ml 레몬즙 (Lemon Juice)"},{"kind":"paragraph","text":"10ml 심플 시럽(Simple Syrup)"},{"kind":"paragraph","text":"탄산수 (Soda Water)"},{"kind":"figure","src":"/articles/sloe-gin-fizz/02.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 탄산수 외의 재료를 셰이커에 넣는다"},{"kind":"paragraph","text":"2. 셰이커에 얼음을 넣고 셰이킹한다"},{"kind":"paragraph","text":"3. 얼음을 채운 하이볼 잔에 부어준다"},{"kind":"paragraph","text":"4. 탄산수를 적당량 2~3번에 나누어 부어준다"},{"kind":"paragraph","text":"5. 바스푼으로 얼음을 위아래로 들어 섞어준다"},{"kind":"paragraph","text":"슬로 진 피즈는 그 원형인 진 피즈와는 다르게 풍부한 과실미가 있는 칵테일로, 슬로 진의 도수가 26%이기 때문에 도수가 훨씬 낮아 알콜감이 느껴지지 않아 마시기 아주 편합니다."},{"kind":"paragraph","text":"베리류 및 핵과류의 달큰한 과실감에 레몬의 상큼함이 더해져서 전체적으로 새콤달콤한 맛이 주를 이루고, 탄산이 더해져 가볍고 청량한 느낌을 줍니다. 개인적으로는 로즈시럽 같은 느낌도 살짝 있는 거 같네요."},{"kind":"paragraph","text":"가볍고 새콤달콤한 맛으로 봄 ~ 여름에 마시기 딱 좋을 법한 칵테일입니다."},{"kind":"paragraph","text":"탄산수를 따를 때, 거품이 확 올라오기 때문에 2~3번에 끊어서 조심조심히 넣는 게 팁이라면 팁이라 할 수 있겠네요"}]'::jsonb, 'published', '2026-03-29T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'sloe-gin-fizz' AND c.slug = 'sloeginfizz';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'corpse-reviver-no-2', 'cocktail', '콥스 리바이버 넘버 2 — 죽은 자를 깨우는 칵테일', '「콥스 리바이버」라는 이름은 이미 19세기부터 존재하였는데, 가장 오래된 기록은 1861년 런던에서 출판된 잡지 ''펀치(Punch)''에서 슬링(Sling), 스톤 월(Stone Wall)이라는 칵테일과 함께 언급되는 것입니다.', '/articles/corpse-reviver-no-2/00.webp',
  'https://blog.naver.com/shakinglikebartender/224034950340', false,
  '[{"kind":"figure","src":"/articles/corpse-reviver-no-2/00.webp","width":966,"height":966},{"kind":"paragraph","text":"「콥스 리바이버」라는 이름은 이미 19세기부터 존재하였는데, 가장 오래된 기록은 1861년 런던에서 출판된 잡지 ''펀치(Punch)''에서 슬링(Sling), 스톤 월(Stone Wall)이라는 칵테일과 함께 언급되는 것입니다."},{"kind":"paragraph","text":"이 시기에는 숙취를 더 강한 술로 달래는 해장술이 유행했다고 하는데, 이 당시에는 콥스 리바이버가 특정 칵테일 또는 레시피로서의 의미가 아니라 이름 그대로 \"해장을 위한 술\"이라는 의미로 쓰였을 것이라는 주장이 주를 이룹니다."},{"kind":"paragraph","text":"가장 오래된 레시피는 1871년에 출판된 책인 The Gentlemen''s Table Guide에서 처음 언급되는데, 브랜디와 마라스키노 리큐르가 동량으로 들어가고, 보커스 비터가 들어가는 등 현재의 유명한 레시피들과는 전혀 다릅니다."},{"kind":"figure","src":"/articles/corpse-reviver-no-2/01.webp","width":462,"height":196,"caption":"The Savoy Cocktail Book(1930)"},{"kind":"paragraph","text":"콥스 리바이버는 정말 많은 종류가 있지만, 현재 가장 유명한 콥스 리바이버는 넘버 2로, 넘버 1과 함께 1930년 해리 크래독의 저서인 The Savoy Cocktail Book에서 처음 소개되었습니다."},{"kind":"paragraph","text":"레시피 밑을 보면 \"4잔을 연속으로 빠르게 마시면 되살아난 시체도 다시 죽을 것\"이라는 내용이 적혀있는데, 칵테일 이름의 뜻인 \"죽은 자도 부활시키는 것\"을 바탕으로 너무 빠르게 많이 마시지 말라는 위트 있는 경고라 할 수 있죠."},{"kind":"figure","src":"/articles/corpse-reviver-no-2/02.webp","width":966,"height":966},{"kind":"paragraph","text":"원래 콥스 리바이버 넘버 2의 레시피는 들어가는 재료들이 동량으로 되어 있지만, 그렇게 밸런스가 좋다고 느껴지지는 않습니다."},{"kind":"paragraph","text":"콥스 리바이버 넘버 2도 처음 기록으로 등장한 지 거의 100년이 되어가는 술이기 때문에 다양한 비율의 레시피가 있으니 그걸 비교해 보면서 본인에게 맞는 비율을 찾아가는 것도 좋을 것 같습니다."},{"kind":"figure","src":"/articles/corpse-reviver-no-2/03.webp","width":966,"height":966},{"kind":"paragraph","text":"1. 압생트 외의 모든 재료를 셰이커에 넣는다."},{"kind":"paragraph","text":"2. 차게 해둔 잔 안에 압생트를 뿌려 린싱해준다."},{"kind":"paragraph","text":"3. 셰이커에 얼음을 채우고, 셰이킹한다."},{"kind":"paragraph","text":"4. 잔에 따라준다."},{"kind":"paragraph","text":"압생트의 경우는 스프레이가 없다면 1바스푼 정도를 잔에 넣고, 잔 안에 전체적으로 묻을 수 있도록 잔을 돌려준 후,  남은 압생트를 버려주면 됩니다."},{"kind":"paragraph","text":"콥스 리바이버 넘버 2는 시트러스의 새콤달콤함, 릴레의 약간의 와인 같은 캐릭터, 중심을 잡아주는 진의 보타니컬함 살짝에 미묘하게 느껴지는 압생트의 풍미가 함께 느껴지는 재미있는 칵테일입니다."},{"kind":"paragraph","text":"개인적으로는 사실 맛 자체가 해장술보다는 지쳐 있을 때에 마시면 기운이 날 것 같은 칵테일이라고 생각됩니다."}]'::jsonb, 'published', '2025-10-08T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'corpse-reviver-no-2' AND c.slug = 'corpsereviver2';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'nagoya-bar-curacao', 'bar', '바 큐라소 — 사이드카 한 잔, 잔의 차이가 만든 맛', '「바 큐라소」는 나고야의 사카에 지역의 한 빌딩에 위치해 있는 바로, 오렌지 리큐르의 일종인 큐라소를 이름으로 하고 있는 곳입니다. 아마도 사장님이 큐라소류 칵테일을 좋아하시는 듯.', '/articles/nagoya-bar-curacao/00.webp',
  'https://blog.naver.com/shakinglikebartender/224016293039', false,
  '[{"kind":"figure","src":"/articles/nagoya-bar-curacao/00.webp","width":966,"height":543},{"kind":"figure","src":"/articles/nagoya-bar-curacao/01.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/nagoya-bar-curacao/02.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/nagoya-bar-curacao/03.webp","width":966,"height":1288},{"kind":"paragraph","text":"「바 큐라소」는 나고야의 사카에 지역의 한 빌딩에 위치해 있는 바로, 오렌지 리큐르의 일종인 큐라소를 이름으로 하고 있는 곳입니다. 아마도 사장님이 큐라소류 칵테일을 좋아하시는 듯."},{"kind":"paragraph","text":"첫 잔으로는 역시 하이볼을 추천을 부탁드렸고, 스카이 섬(Isle of Skye)의 신생 증류소라고 하는 토라벡(토라베이그/Torabhaig)을 추천 받았습니다."},{"kind":"paragraph","text":"스카이 섬 + 신생이라는 조합에 호기심을 못이겨 주문을 했는데, 하이볼로 마시기 딱 좋은 정도의 피트감, 약간의 짭짤한 해초, 고소함이 느껴져 맛있게 마셨습니다."},{"kind":"paragraph","text":"조금 찾아보니 토라벡은 탈리스커에 이어 스카이 섬에서 두 번째로 허가받은 증류소이며, 2017년에 지어져 2021년에 첫 위스키 제품을 출시했다고 합니다. 제가 마신 건 두 번째로 출시된 제품이자 Allt Gleann이라는 이름의 싱글몰트라 합니다."},{"kind":"paragraph","text":"여기도 이전에 갔던 바 반즈처럼 사진을 찍을 때 조명을 비춰주시는 게 포인트"},{"kind":"figure","src":"/articles/nagoya-bar-curacao/04.webp","width":966,"height":1288},{"kind":"paragraph","text":"다음 잔으로는 역시 바의 이름에 따라서 큐라소가 들어간 칵테일을 요청드렸는데, 사이드카(Sidecar)를 내어주셨습니다."},{"kind":"paragraph","text":"셰이킹이 그렇게 강하지 않았는데도 공기가 생각보다 많이 주입된 게 신기했는데, 제가 마셔본 사이드카 중에서 세 손가락에 꼽을 정도로 맛있었습니다. 밸런스가 정말 좋아서 극한의 밸런스충인 저에게 딱 맞는 한 잔."},{"kind":"paragraph","text":"사이드카와 관련해서 이런 저런 얘기를 나눴는데, 그 중에 가장 신기했던 건 잔에 따라서도 칵테일의 맛이 달라진다는 사장님의 얘기였습니다."},{"kind":"paragraph","text":"제가 엥?스러운 반응을 하자 다른 칵테일 잔을 주시길래 거기에 따라 마셔봤더니 정말 맛이 달랐다는 게 충격적이었습니다. 그래서 본인은 칵테일을 여러 잔에 따라서 바셔보고 잔을 결정한다고."},{"kind":"paragraph","text":"개인적으로 느낀 전 ''V''자처럼 샤프한 잔은 레몬의 신맛이 두드러졌고, ''U''자처럼 둥근 잔은 좀 더 꼬냑스러운 느낌이 중심을 잘 잡는 느낌이었습니다. 얇은 림은 필수."},{"kind":"figure","src":"/articles/nagoya-bar-curacao/05.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/nagoya-bar-curacao/06.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/nagoya-bar-curacao/07.webp","width":966,"height":1288},{"kind":"paragraph","text":"바 큐라소는 칵테일이 정말 맛있었지만, 위스키나 다른 스피릿 라인업도 꽤 많이 갖춰져 있습니다. 이 중에서 같은 나고야에 있는 바인 ''루빈스 베이스(Rubin''s-Vase)'' 픽 위스키 중에 시크릿 오크니가 있어서 한 잔 마셔봤는데, 이거 꽤 괜찮았습니다."},{"kind":"paragraph","text":"그 외에 한국에서 보기 정말 어렵지만, 아주 애정하는 마르(Marc) 중에 부르고뉴 지방의 마르가 있어서 이것도 한 잔 마셔주고, 아쉬워서 머레이 맥다비드의 쿨일라도 한 잔 마셨는데, 쿨일라는 굳이 싶었습니다."},{"kind":"paragraph","text":"얘길 들어보니 사장님이 이전에 요이치 증류소에서 견습(?)을 했었는데, 그 인연으로 조만간 요이치 증류소에서 바틀을 보내준다고 하셨으니, 나고야에 방문하시는 분들 중 일본 위스키 관심 있는 분들은 방문을 추천드립니다."},{"kind":"paragraph","text":"바 큐라소는 개인적으로 칵테일을 좋아하시는 분들에게 더 추천드리고 싶기는 하지만, 그렇다고 위스키 라인업이 부실한 건 절대 아닙니다. 편하게 방문해서 즐겨주시길."}]'::jsonb, 'published', '2025-09-21T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'bar-barns', 'bar', '바 반즈 — 히노키에 담긴 진토닉', '나고야 후시미의 지하, 타베로그 4점대의 바. 편백나무 마스에 서브되는 진토닉이 첫 모금부터 다른 얼굴을 보여준다.', '/articles/bar-barns/00.webp',
  'https://blog.naver.com/shakinglikebartender/223980767545', false,
  '[{"kind":"figure","src":"/articles/bar-barns/00.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/bar-barns/01.webp","width":966,"height":543},{"kind":"paragraph","text":"「반즈」는 나고야 후시미역과 사카에역 사이에 있는 한 빌딩의 지하에 위치한 바로, 특이하게 타베로그에서 4점대를 넘기고 있는 바입니다. 타베로그에서 바가 4점대인 경우는 흔치 않은데 말이죠."},{"kind":"paragraph","text":"4점대의 점수에 걸맞게 예약이 꽉 차있는데, 방문 전에 예약을 하고 방문하던가, 아예 저처럼 오픈하자마자 방문해서 뒷 시간대의 예약시간까지 1~2시간 즐기는 걸 추천드립니다."},{"kind":"paragraph","text":"바를 방문하면 메뉴판은 딱히 없는 것 같고, 먼저 물 수건을 건네준 다음 꽤나 빠르게 주문을 받습니다."},{"kind":"quote","text":"급작스럽긴 하지만,"},{"kind":"quote","text":"첫 잔은 어떻게 준비해 드릴까요?"},{"kind":"figure","src":"/articles/bar-barns/02.webp","width":966,"height":966},{"kind":"figure","src":"/articles/bar-barns/03.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/bar-barns/04.webp","width":966,"height":1288},{"kind":"paragraph","text":"사실 이 바를 찾은 이유는 반즈만의 독특한 진 토닉 때문입니다. 반즈에서는 진 토닉을 히노키(편백나무)로 만든 마스(되)에 서브해 주는데, 이로 인해서 칵테일에 나무의 특성이 자연스럽게 스며듭니다."},{"kind":"paragraph","text":"히노키의 캐릭터가 진 토닉에 배어 나오게 되면서 아주아주 복잡한 캐릭터를 만들어내게 되는데, 글로 잘 표현하기가 정말 어렵네요."},{"kind":"paragraph","text":"마시다가 유자소금을 올려서 같이 마시는 걸 얘기해 주셨는데, 이건 개인적으로 굳이 싶기는 했습니다. 아마 이 칵테일의 첫 모금에 꽤나 충격을 받아서 그러지 않았을까 싶네요."},{"kind":"figure","src":"/articles/bar-barns/05.webp","width":966,"height":1289},{"kind":"figure","src":"/articles/bar-barns/06.webp","width":966,"height":1288},{"kind":"paragraph","text":"친구는 메뉴에 있던 오오바(청차조기 잎)를 사용한 칵테일을 추천받았는데,  달콤 상큼하고, 꽤나 자극적인 칵테일로 이것도 정말 맛있게 마셨습니다."},{"kind":"paragraph","text":"듣기로는 어떤 손님이 이 칵테일이 맛있어서 9잔을 연거푸 마셨고, 그게 최고 기록이라고 하던데,  개인적으로 납득이 되는 맛이었습니다."},{"kind":"paragraph","text":"정확히 기억은 안 나는데, 온천 근처에서 만들어진 오오바를 사용한 진에 홈메이드 오오바 리큐르를 사용한다고 했던 것 같습니다."},{"kind":"figure","src":"/articles/bar-barns/07.webp","width":966,"height":966},{"kind":"paragraph","text":"다음으로는 사이드카를 주문했는데, 코앵트로는 못 봤지만 기주인 레미 마틴은 올드보틀로 만들어주셨습니다. 맛은 생각했던 레미 마틴 올드보틀로 만든 사이드카 그대로."},{"kind":"paragraph","text":"이 사이드카에서 가장 마음에 들었던 게 바로 잔이었는데, 세라믹 잔으로 기주인 꼬냑의 원재료인 포도가 그려져 있는 것이 아주 멋진 센스라 생각됐습니다."},{"kind":"figure","src":"/articles/bar-barns/08.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/bar-barns/09.webp","width":966,"height":1288},{"kind":"paragraph","text":"반즈는 칵테일도 아주 훌륭하지만, 위스키 종류도 아주 훌륭합니다. 특히, 반즈에서 픽한 독립병입 위스키들이 있는데, 가격은 꽤 나가는 편이지만 맛 자체는 훌륭하다고 생각됩니다."},{"kind":"paragraph","text":"왼쪽의 보틀이 반즈 픽의 쿨리인데, 아무래도 거의 막바지인데다가 아이리시 위스키이다 보니 점잖은 면은 있지만, 꽤나 섬세하고, 거의 라벨 그대로의 캐릭터를 가지고 있습니다. 개인적으로 많이 느낀 건 딸기의 캐릭터."},{"kind":"paragraph","text":"오른쪽은 도쿄에 있는 ''아일라''라는 바를 위해 병입된 스프링뱅크인데, 개인적으로 고숙성 스프링뱅크를 선호하지 않아서 크게 와닿지는 않았습니다. 단순히 생년 빈티지+바 이름 때문에 마신 기억이..."},{"kind":"figure","src":"/articles/bar-barns/10.webp","width":966,"height":966},{"kind":"paragraph","text":"반즈는 바텐더분들이 아주아주 젠틀하시고, 특이하게 칵테일을 찍을 때마다 라이트를 비춰주는 점이 재미있으며, 칵테일이 정말 정말 맛있습니다."},{"kind":"paragraph","text":"개인적으로 타베로그에서의 바의 평점은 믿지 않는 편인데, 이곳의 평점이 4점대인 걸 납득할 수 있었습니다."},{"kind":"paragraph","text":"나고야를 가게 된다면 한 번쯤은 방문하시는 걸 강력하게 추천드리고, 인기가 아주 많으니 예약 또는 방문 전 자리가 있는지 문의는 필수일 것 같습니다."}]'::jsonb, 'published', '2025-08-23T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'vesper', 'cocktail', '베스퍼 — 제임스 본드가 사랑한 칵테일', '이언 플레밍이 쓰고 제임스 본드가 바텐더에게 직접 읊은 레시피. 진 3, 보드카 1, 릴레 블랑 0.5의 파괴적인 한 잔.', '/articles/vesper/00.webp',
  'https://blog.naver.com/shakinglikebartender/223972463957', false,
  '[{"kind":"figure","src":"/articles/vesper/00.webp","width":966,"height":966},{"kind":"heading","text":"About the Cocktail"},{"kind":"paragraph","text":"「베스퍼」는 이언 플레밍(Ian Fleming)의 소설 카지노 로얄(Casino Royale)에서 제임스 본드가 바텐더에게 직접 레시피를 읊어주는 것으로 처음 등장하며, 베스퍼 마티니(Vesper Martini)라고 불리기도 합니다."},{"kind":"quote","text":"Three measures of Gordon''s, one of vodka, half a measure of Kina Lillet."},{"kind":"quote","text":"Shake it very well until it''s ice-cold, then add a large thin slice of lemon peel. Got it?"},{"kind":"paragraph","text":"저는 소설을 보지는 않았지만, 다니엘 크레이그 주연의 007 시리즈에서도 이 칵테일이 등장하는데, 역시 2006년에 개봉한 007 카지노 로얄에서 등장하게 됩니다."},{"kind":"paragraph","text":"영화에서는 꽤나 로맨틱하고 애틋한 장치로 쓰이기도 하는데, 연인인 베스퍼 린드에게 이 칵테일의 이름을 ''베스퍼''라 해야겠다고 하면서 그 이유를 \"한 번 맛보고 나면 다른 건 마실 수 없기 때문\"이라고 합니다."},{"kind":"paragraph","text":"속편에서는 볼리비아로 향하는 비행기의 바에 합류한 매티스가 무슨 술을 마시냐고 묻자, 본드가 대답을 못하는 와중에 바텐더가 위의 레시피를 읊어줍니다. 이때, 본드는 이 술을 6잔이나 마신 상태라 하는데, 베스퍼에 대한 그리움과 애틋함을 은근하게 드러냅니다."},{"kind":"figure","src":"/articles/vesper/01.webp","width":966,"height":966},{"kind":"heading","text":"Recipe"},{"kind":"paragraph","text":"45ml 진"},{"kind":"paragraph","text":"15ml 보드카"},{"kind":"paragraph","text":"7.5-10ml 릴레 블랑"},{"kind":"paragraph","text":"레몬 껍질"},{"kind":"paragraph","text":"재료로 들어가는 진, 보드카, 릴레 블랑이 3 : 1 : 0.5의 비율로 들어가는, 거의 술을 때려 붓다시피 하는 파괴적인 레시피입니다."},{"kind":"paragraph","text":"원래는 퀴닌이 들어가는 키나 릴레(Kina Lillet)를 사용하는데, 1986년에 릴레에서 쓴맛을 내는 퀴닌의 함량을 줄이고, 단맛을 높이는 식으로 레시피를 변경하며, 이름을 현재의 릴레 블랑으로 바꾸게 됩니다."},{"kind":"paragraph","text":"몇몇 바텐더들의 말로는 ''코키 아메리카노(Cocchi Americano)''가 그래도 키나 릴레와 좀 더 가깝다고 하니 맛을 비교해 보는 것도 재미있을 것 같습니다."},{"kind":"figure","src":"/articles/vesper/02.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 레몬 껍질 이외의 재료를 셰이커에 넣는다."},{"kind":"paragraph","text":"2. 셰이커에 얼음을 채우고, 셰이킹한다."},{"kind":"paragraph","text":"3. 잔에 따른 후, 레몬 껍질에서 오일을 짜준다."},{"kind":"paragraph","text":"4. 레몬 껍질을 다듬어서 장식한다(옵션)."},{"kind":"heading","text":"맛"},{"kind":"paragraph","text":"- 잔을 입에 가져대면 자연스럽게 나는 기분 좋은 레몬향"},{"kind":"paragraph","text":"- 보태니컬, 허브와 약간의 술 자체의 단맛"},{"kind":"paragraph","text":"- 살짝 느껴지는 릴레의 와인스러운 뉘앙스"},{"kind":"paragraph","text":"- 비교적 깔끔하고, 깨끗한 맛"},{"kind":"paragraph","text":"베스퍼는 재료 대부분의 양을 진과 보드카가 차지하기 때문에 도수가 상당히 높은 칵테일이며, 맛에 변화를 줄 수 있는 요소가 그렇게 많지는 않습니다."},{"kind":"paragraph","text":"''왜 술만 들어가는데 셰이킹을 하지?''라는 근본적인 의문이 생길 수 있는데, 아마 다음과 같은 이유를 들 수 있지 않을까 싶습니다."},{"kind":"paragraph","text":"- ''스팅어''처럼 술만 들어가더라도 셰이킹은 할 수 있다."},{"kind":"paragraph","text":"- 마티니를 셰이킹해서 마시는 제임스 본드의 취향이 반영된 것."},{"kind":"paragraph","text":"물론, 스터를 해서 만들더라도 전혀 문제는 없고, 가장 큰 차이는 칵테일에 들어가게 되는 물의 양이지 않을까 싶습니다. 술만 들어갔기 때문에 액체에 주입된 공기도 금방 빠지는 거 같기도 하구요."},{"kind":"paragraph","text":"개인적으로는 원작처럼 셰이킹을 하는 걸 더 좋아하는데, 물이 좀 들어가야 알콜이 안튀는 것 같아서 그런 것 같습니다."}]'::jsonb, 'published', '2025-08-16T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'vesper' AND c.slug = 'vesper';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'b-and-b', 'cocktail', '비앤비 — 베네딕틴과 꼬냑, 단순함 속에서 피어나는 깊은 풍미', '「B&B」는 Benedictine & Brandy의 약자로, 이름 그대로 베네딕틴 돔과 브랜디(주로 꼬냑)의 두 가지 재료로 만들어내는 꽤나 간단한 칵테일입니다.', '/articles/b-and-b/00.webp',
  'https://blog.naver.com/shakinglikebartender/223922952994', false,
  '[{"kind":"figure","src":"/articles/b-and-b/00.webp","width":966,"height":966},{"kind":"paragraph","text":"「B&B」는 Benedictine & Brandy의 약자로, 이름 그대로 베네딕틴 돔과 브랜디(주로 꼬냑)의 두 가지 재료로 만들어내는 꽤나 간단한 칵테일입니다."},{"kind":"paragraph","text":"비앤비에 대해서 가장 잘 알려진 이야기는 1930년대, 당시 뉴욕의 유명한 사교클럽이었던 ''21 Club''의 바텐더에 의해서 탄생했다는 것입니다."},{"kind":"figure","src":"/articles/b-and-b/01.webp","width":499,"height":160,"caption":"https://euvs-vintage-cocktail-books.cld.bz/1910-The-Barkeeper-s-Manual-by-Raymond-E-Sullivan-second-edition/32/"},{"kind":"paragraph","text":"그러나, 사실 비앤비는 이미 1910년에 레이먼드 설리번(Raymond E. Sullivan)의 저서인 ''The Barkeeper''s Manual''에서 푸스카페 스타일의 칵테일로 기록된 적이 있습니다. 현재의 비율과는 다르게 베네딕틴과 꼬냑의 비율이 2:1이었죠."},{"kind":"paragraph","text":"즉, 베네딕틴과 꼬냑의 조합은 이미 존재했었는데, 베네딕틴이 19세기에 상품화되어 판매된 것을 생각해 본다면 1910년 이전에 이미 비앤비 조합이 존재했을 수도 있을 거라는 추측도 무리는 아닙니다."},{"kind":"paragraph","text":"아무튼, 이 칵테일은 해외에서도 꽤나 인기가 많았던 모양인지 1937년에는 베네딕틴에서 자체적으로 베네딕틴 60%와 프랑스 브랜디 40%를 섞은 일종의 RTD 제품인 B&B by Benedictine을 출시하기도 하였습니다."},{"kind":"figure","src":"/articles/b-and-b/02.webp","width":966,"height":966},{"kind":"heading","text":"Recipe"},{"kind":"paragraph","text":"30ml 꼬냑"},{"kind":"paragraph","text":"30ml 베네딕틴 돔(Benedictine DOM)"},{"kind":"paragraph","text":"비앤비는 칵테일 이름대로 재료가 두 가지 밖에 들어가지 않습니다만, 취향에 따라서 비율을 조정하는 재미가 있는 칵테일입니다. 주로 1:1이나 꼬냑과 베네딕틴을 2:1로 만드는 게 일반적이죠."},{"kind":"paragraph","text":"가니시는 굳이 필요 없지만, 한다면 오렌지 껍질을 살짝 짜주는 정도면 충분할 것 같습니다."},{"kind":"figure","src":"/articles/b-and-b/03.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 잔에 재료를 넣고 충분히 젓는다."},{"kind":"paragraph","text":"2. 잔에 채우고, 조금만 스터한다."},{"kind":"paragraph","text":"3. 큰 얼음으로 교체해준다."},{"kind":"paragraph","text":"비앤비 같은 칵테일은 도수가 높기 때문에 약간 시간을 들여가면서 마시게 됩니다. 그러니 메이킹 시에는 칵테일 자체에 *다일루션이 소량만 필요하며, 잔 안에 얼음이 있기 때문에 오래 스터할 필요가 없습니다."},{"kind":"paragraph","text":"*얼음이 녹으면서 음료에 물이 섞여 희석되는 현상"},{"kind":"paragraph","text":"개인적으로는 70~80% 정도의 맛을 낼 정도만 스터한 후, 잔 안의 얼음이 녹으면서 희석되는 것을 선호하는 편입니다."},{"kind":"paragraph","text":"큰 얼음으로 처음부터 만들거나, 얼음을 교체하지 않아도 되지만, 새로운 큰 얼음으로 서브하는 게 최대한 얼음이 느리게 녹게 되는 장점이 있습니다."},{"kind":"figure","src":"/articles/b-and-b/04.webp","width":966,"height":966},{"kind":"paragraph","text":"비앤비는 베네딕틴의 사프론, 꿀, 허브 캐릭터와 함께 느껴지는 꼬냑의 풍미가 매우 인상적인 칵테일로, 들어가는 재료가 2개 밖에 없는데, 베네딕틴의 맛은 정해져 있으니 어떤 꼬냑을 쓰냐에 따라서 맛이 꽤 달라집니다."},{"kind":"paragraph","text":"비앤비를 즐기는 방법은 이외에도 푸스카페 스타일, 따뜻하게 뎁혀서 마시는 스타일 등 다양하게 있기도 합니다만, 개인적으로는 이런 빌드 스타일이 제일 마음에 드네요."}]'::jsonb, 'published', '2025-07-05T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'b-and-b' AND c.slug = 'bnb';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'shoyojurin', 'cocktail', '조엽수림 — 차의 길을 따라 걷는, 쌉쌀하고 고요한 숲 같은 한 잔', '「조엽수림」은 그 기원에 대해서는 잘 알려지지 않은 칵테일입니다만, 일본 만화 바텐더에 따르면 산토리 스쿨에서 강사를 했었던 바텐더 ''후쿠니시 에이조''에 의해서 만들어졌다고 합니다.', '/articles/shoyojurin/00.webp',
  'https://blog.naver.com/shakinglikebartender/223921937397', false,
  '[{"kind":"figure","src":"/articles/shoyojurin/00.webp","width":966,"height":966},{"kind":"heading","text":"About the Cocktail"},{"kind":"paragraph","text":"「조엽수림」은 그 기원에 대해서는 잘 알려지지 않은 칵테일입니다만, 일본 만화 바텐더에 따르면 산토리 스쿨에서 강사를 했었던 바텐더 ''후쿠니시 에이조''에 의해서 만들어졌다고 합니다."},{"kind":"paragraph","text":"조엽수림은 녹차 리큐르를 단독 기주로 하는데, 산토리 스쿨에서 만들어진 만큼, 산토리에서 생산하는 헤르메스 그린 티 리큐르가 원조일 것으로 보입니다. 산토리에서는 이 리큐르가 1950년대에 처음 발매됐다고 할 정도로 오래된 리큐르입니다."},{"kind":"paragraph","text":"조엽수림은 ''습기가 많은 곳에 분포되어 있는 상록 활엽수를 주로 한 삼림 군계''라고 하는데, 만화 바텐더에서는 히말라야 중턱에서 동남아시아, 중국, 한반도를 거쳐 일본에 이르는 차의 루트와 일치한다고 표현합니다."},{"kind":"paragraph","text":"칵테일의 색과 스토리에 딱 맞는 이름이라는 뜻이죠. 저는 차에 대해서 잘 모르기 때문에 정말 신빙성 있는 이야기인지는 둘째로 치고..."},{"kind":"figure","src":"/articles/shoyojurin/01.webp","width":966,"height":966},{"kind":"heading","text":"Recipe"},{"kind":"paragraph","text":"45ml 녹차 리큐르"},{"kind":"paragraph","text":"120~135ml 우롱차"},{"kind":"paragraph","text":"조엽수림은 녹차 리큐르 + 우롱차라는 차에 차를 더하는 특이한 칵테일입니다. 맛의 변화를 주는 재료가 적기 때문에 어떤 우롱차를 쓰느냐가 중요한데, 너무 맛이 연한 것은 피하도록 합시다."},{"kind":"figure","src":"/articles/shoyojurin/02.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 차게 식혀둔 긴 잔에 얼음을 채운다."},{"kind":"paragraph","text":"2. 녹차 리큐르를 넣고 살짝 스터해준다."},{"kind":"paragraph","text":"3. 우롱차를 넣고, 얼음을 몇 번 올렸다 내려줍니다."},{"kind":"heading","text":"맛"},{"kind":"paragraph","text":"- 쌉쌀하고, 달큰한 차"},{"kind":"paragraph","text":"- 살짝 쌉쌀하고 텁텁한 끝 맛"},{"kind":"paragraph","text":"조엽수림은 도수도 낮은 편이고, 굳이 따지자면 달큰한 맛이 좀 있는 편에 속하는 칵테일이기 때문에 마시기 꽤나 편한 칵테일이며, 개인적으로는 식후 또는 마지막 한 잔으로 어울리는 칵테일이라 생각합니다."}]'::jsonb, 'published', '2025-07-04T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'shoyojurin' AND c.slug = 'shoyojurin';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'kingston-negroni', 'cocktail', '킹스톤 네그로니 — 자메이카 펑크로 완성한 클래식의 변주', '「킹스톤 네그로니」는 이름에서도 단번에 알 수 있듯이 클래식 칵테일인 네그로니의 변형입니다. 다만, 여기에서는 ''진''이 아니라 ''럼''이 기주로 들어가게 되죠.', '/articles/kingston-negroni/00.webp',
  'https://blog.naver.com/shakinglikebartender/223914797273', false,
  '[{"kind":"figure","src":"/articles/kingston-negroni/00.webp","width":966,"height":966},{"kind":"heading","text":"About the Cocktail"},{"kind":"paragraph","text":"「킹스톤 네그로니」는 이름에서도 단번에 알 수 있듯이 클래식 칵테일인 네그로니의 변형입니다. 다만, 여기에서는 ''진''이 아니라 ''럼''이 기주로 들어가게 되죠."},{"kind":"paragraph","text":"킹스톤 네그로니는 2010년 전후로 유명 바텐더인 호아킨 시모(Joaquin Simo)에 의해 탄생했으며, 당시 주류 수입업자로부터 ''스미스 앤 크로스(Smith & Cross)''라는 럼을 건네받고 5분 만에 만들어냈다고 합니다."},{"kind":"paragraph","text":"이 스미스 앤 크로스라는 럼은 자메이카 럼, 그중에서도 *오버 프루프 럼(Overproof Rum)에 해당하기 때문에 아주아주 강렬한 캐릭터를 자랑합니다."},{"kind":"paragraph","text":"*도수가 100proof(50%) 이상인 럼"},{"kind":"figure","src":"/articles/kingston-negroni/01.webp","width":966,"height":966},{"kind":"paragraph","text":"럼은 흔히 지역에 따라서 가지는 특징이 있기도 한데, 자메이카 럼은 ''펑키함(Funky)''이 특징으로, 개인적으로는 과하게 후숙된 바나나, 열대 과일들, 약간의 따뜻한 계열의 향신료들이 삐죽삐죽하게 느껴지는 캐릭터라 생각합니다."},{"kind":"paragraph","text":"아무튼 스미스 앤 크로스는 이런 펑키함과 높은 도수로 인해서 클래식 칵테일과는 궁합이 좋지 않을 것 같지만, 오히려 이 점이 캐릭터가 강한 캄파리와 잘 어울러서 독특한 캐릭터의 네그로니를 만들어냅니다."},{"kind":"figure","src":"/articles/kingston-negroni/02.webp","width":966,"height":966},{"kind":"heading","text":"Recipe"},{"kind":"paragraph","text":"30ml 자메이카 럼"},{"kind":"paragraph","text":"30ml 캄파리"},{"kind":"paragraph","text":"30ml 스위트 버무스"},{"kind":"paragraph","text":"가니시: 오렌지 껍질"},{"kind":"paragraph","text":"자메이카 럼은 ''펑키함''이라는 특수한 캐릭터를 가지고 있기 때문에 다른 지역의 럼으로 만들게 되면 그냥 럼 네그로니가 되어 버립니다. 스미스 앤 크로스를 구하기 어렵다면 도수가 아쉽긴 하지만 ''애플톤(Appleton)''이 그 대안이 될 수 있습니다."},{"kind":"paragraph","text":"스위트 버무스 같은 경우에는 스미스 앤 크로스와 캄파리 둘 다 캐릭터가 꽤나 강하니 코키 디 토리노, 안티카 포뮬라 등과 같이 어느 정도 캐릭터가 강한 것들을 사용하는 걸 추천드립니다."},{"kind":"figure","src":"/articles/kingston-negroni/03.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 락 글라스에 모든 재료를 넣는다."},{"kind":"paragraph","text":"2. 얼음을 넣고, 스터해준다."},{"kind":"paragraph","text":"3. 오렌지 껍질의 오일을 잔 위에 뿌려준다."},{"kind":"paragraph","text":"4. 사용한 오렌지 껍질을 다듬어서 넣어준다."},{"kind":"heading","text":"맛"},{"kind":"paragraph","text":"- 허브감이 덜한 네그로니"},{"kind":"paragraph","text":"- 후숙된 바나나, 흑당(?), 초콜릿, 향신료"},{"kind":"paragraph","text":"- 클래식 네그로니보다는 단순한 맛"},{"kind":"paragraph","text":"- 복합성은 떨어지지만, 통통 튀고 자극적인 매력"},{"kind":"paragraph","text":"킹스톤 네그로니는 클래식한 네그로니보다는 허브감이 훨씬 덜하고 단순한데다가, 술의 들큰함과 후숙된 바나나의 캐릭터 등으로 오히려 더 쉽게 마실 수도 있습니다."},{"kind":"paragraph","text":"마실 때는 도수감이 크게 느껴지지는 않습니다만, 아마 네그로니의 변형 중 가장 도수가 놓은 칵테일이니 마실 때에는 주의해야겠습니다."}]'::jsonb, 'published', '2025-06-28T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'kingston-negroni' AND c.slug = 'kingstonnegroni';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'caipiroska', 'cocktail', '카이피로스카 — 보드카로 간단하게 담아낸 브라질의 국민 칵테일의 변형', '「카이피로스카」는 브라질의 국민 칵테일인 카이피리냐(Caipirinha)의 변형으로, 기주를 카샤샤(Cachaca)에서 보드카로 바꾼 아주 간단한 변주로, 카이피로브스카(Caipirovska)로 불리기도 합니다.', '/articles/caipiroska/00.webp',
  'https://blog.naver.com/shakinglikebartender/223892302657', false,
  '[{"kind":"figure","src":"/articles/caipiroska/00.webp","width":966,"height":966},{"kind":"heading","text":"About the Cocktail"},{"kind":"paragraph","text":"「카이피로스카」는 브라질의 국민 칵테일인 카이피리냐(Caipirinha)의 변형으로, 기주를 카샤샤(Cachaca)에서 보드카로 바꾼 아주 간단한 변주로, 카이피로브스카(Caipirovska)로 불리기도 합니다."},{"kind":"paragraph","text":"카이피리냐는 브라질의 상파울루 지역에서 오래전부터 시작된 것으로 알려져 있으며, 브라질에서는 국민 칵테일로 취급될 정도로 많은 사랑을 받고 있다고 합니다."},{"kind":"paragraph","text":"카이피로스카가 어떻게 만들어졌는지는 정확히 알 수는 없습니다만, 대부분 80~90년대에 보드카가 전 세계적으로 인기를 끌었던 시기에 처음 만들어졌다고 추측하고 있습니다."},{"kind":"paragraph","text":"우리나라에서도 편의점 앱 등을 통해서 카샤샤를 구할 수 있기는 한데, 아무래도 사용할 곳이 많지 않고, 보드카가 훨씬 구하기 쉽기 때문에 카이피리냐보다 이 칵테일을 추천하는 편입니다."},{"kind":"figure","src":"/articles/caipiroska/01.webp","width":966,"height":966},{"kind":"heading","text":"Recipe"},{"kind":"paragraph","text":"50~60ml 보드카"},{"kind":"paragraph","text":"라임 반 개"},{"kind":"paragraph","text":"3~4barspoon 설탕"},{"kind":"paragraph","text":"라임은 개체마다 양이 다르기 때문에 작은 라임이면 라임 즙을 살짝 더 넣어줍니다."},{"kind":"figure","src":"/articles/caipiroska/02.webp","width":966,"height":966},{"kind":"figure","src":"/articles/caipiroska/03.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. *라임 반 개를 머들링하기 좋게 자른다."},{"kind":"paragraph","text":"2. 라임과 설탕을 잔에 넣고, 머들링한다."},{"kind":"paragraph","text":"3. **크러시드 아이스를 넣고, 다소 길게 섞는다."},{"kind":"paragraph","text":"4. 얼음을 더 채워주고, 라임을 가니시로 올린다."},{"kind":"paragraph","text":"*라임은 되도록이면 6등분, 또는 9등분으로 깍둑썰기하는 걸 추천합니다. 웨지를 그대로 넣으면 잔에 비해서 조각이 좀 클 수 있어서 머들링이 잘 안될 수 있습니다."},{"kind":"paragraph","text":"**크러시드 아이스는 편의점 커피 얼음을 사용해도 괜찮고, 꼭 크러시드 아이스가 아니어도 괜찮습니다."},{"kind":"figure","src":"/articles/caipiroska/04.webp","width":966,"height":1288},{"kind":"heading","text":"맛"},{"kind":"paragraph","text":"- 리프레시 하기 좋은 달고 상큼한 칵테일"},{"kind":"paragraph","text":"- 비교적 직관적이고 단순한 맛"},{"kind":"paragraph","text":"카이피로스카는 재료도 구하기 쉽고, 만들는 과정도 쉬운 편인지라 더운 여름에 간편하게 마시기 딱 좋은 칵테일입니다."},{"kind":"paragraph","text":"또한, 딸기나 블루베리 등을 함께 넣는 종류의 카이피로스카 변형도 다수 존재하니 좀 더 달고 과일의 맛을 느끼고 싶다면 쉽고 자유롭게 변형이 가능하기도 하죠."}]'::jsonb, 'published', '2025-06-08T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'caipiroska' AND c.slug = 'caipiroska';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'white-negroni', 'cocktail', '화이트 네그로니 — 클래식의 무게감을 덜어, 밝고 섬세하게 해석한 프렌치식 변주', '「화이트 네그로니」는 현대에 만들어진 네그로니의 변형 중 아마 가장 유명한 칵테일이지 않을까 싶습니다.', '/articles/white-negroni/00.webp',
  'https://blog.naver.com/shakinglikebartender/223890597534', false,
  '[{"kind":"figure","src":"/articles/white-negroni/00.webp","width":966,"height":966},{"kind":"heading","text":"About the Cocktail"},{"kind":"paragraph","text":"「화이트 네그로니」는 현대에 만들어진 네그로니의 변형 중 아마 가장 유명한 칵테일이지 않을까 싶습니다."},{"kind":"paragraph","text":"2001년 여름, 당시 플리머스 진(Plymouth)의 디렉터였던 닉 블랙넬(Nick Blacknell)은 주류 박람회(Vinexpo)에 참여하기 위해, 런던의 바텐더 웨인 콜린스(Wayne Collins)는 칵테일 경연 대회에 참여하기 위해 프랑스로 향했습니다."},{"kind":"paragraph","text":"두 사람은 대회 전날에 보르도(Bordeaux) 근처 메독(Medoc)의 한 게스트 하우스에서 머물렀는데, 매우 더운 날씨로 인해서 아주 차갑고, 상쾌한 네그로니를 마시고 싶어졌습니다."},{"kind":"figure","src":"/articles/white-negroni/01.webp","width":966,"height":725},{"kind":"paragraph","text":"그러나 마을은 너무 작고 시골이라 괜찮은 바가 없어 보였고, 둘은 마을 리쿼샵에 들어가서 네그로니의 재료를 찾기로 하는데, 여기서 콜린스는 ''프랑스 재료로 네그로니를 만들어보자''는 아이디어를 내게 됩니다."},{"kind":"paragraph","text":"그렇게 해서 캄파리처럼 쌉쌀하고 단맛이 나는 프랑스의 아페리티프인 수즈(Suze)와 와인 베이스 아페리티프인 릴레 블랑(Lillet Blanc)에 플리머스 진을 사용해서 이 칵테일이 만들어집니다."},{"kind":"paragraph","text":"블랙넬은 이 칵테일을 ''화이트 네그로니''라 부르자고 했는데, 네그로니의 색인 어두운 적갈색이니 완전히 반대되게 ''화이트''로 부르자고 한 것 같은데, 실상은 금색 또는 노란색에 가깝죠."},{"kind":"figure","src":"/articles/white-negroni/02.webp","width":966,"height":966},{"kind":"heading","text":"Recipe"},{"kind":"paragraph","text":"45ml 진"},{"kind":"paragraph","text":"30ml 릴레 블랑"},{"kind":"paragraph","text":"22.5ml 수즈"},{"kind":"paragraph","text":"가니시: 레몬 껍질(or 자몽 껍질)"},{"kind":"paragraph","text":"*화이트 네그로니는 처음에는 네그로니의 변형이니 만큼 1:1:1의 비율로 만들어졌을 것으로 보이긴 하지만, 시간이 지나면서 다양한 비율의 레시피가 생기게 됩니다. 그러니 만들어보고 입맛에 가장 잘 맞는 비율을 골라주시면 됩니다."},{"kind":"figure","src":"/articles/white-negroni/03.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 락 글라스에 모든 재료를 넣는다."},{"kind":"paragraph","text":"2. 얼음을 채워주고, 스터한다."},{"kind":"paragraph","text":"3. 레몬 껍질의 오일을 잔 위에 뿌려준다."},{"kind":"paragraph","text":"4. 사용한 레몬 껍질을 다듬어서 넣어준다."},{"kind":"heading","text":"맛"},{"kind":"paragraph","text":"- 진의 도수감과 보타니컬함이 중심을 잡아줌"},{"kind":"paragraph","text":"- 수즈의 달큰하면서도 살짝 쌉쌀한 뿌리 식물 캐릭터가 은은하게 나타남"},{"kind":"paragraph","text":"- 릴레의 달큰한 와인 캐릭터가 생각보다 이 칵테일의 밸런스를 맞추려 노력하는 느낌"},{"kind":"paragraph","text":"- 클래식 네그로니보다 한껏 가볍고, 섬세한 캐릭터"},{"kind":"paragraph","text":"화이트 네그로니는 일반적인 네그로니를 생각하고 마시게 된다면 고개를 갸웃할 수 있는 맛이기는 합니다만, 캄파리와 수즈 모두 뿌리 식물 캐릭터를 가지고 있는 만큼 어느정도는 공유하는 캐릭터가 있습니다."},{"kind":"paragraph","text":"당연히 비율마다 맛이 다르게 되는데, 재료들 간의 밸런스를 맞추는 것이 정말 어려운 칵테일이라 생각되며, 가니시는 자몽 껍질이나 자몽 웨지가 좀 더 쌉쌀한 맛을 살려줄 수 있어서 잘 어울린다고 생각합니다."},{"kind":"paragraph","text":"수즈 경우, 저는 해외직구를 했는데, 우리나라로는 수입되지 않는 제품입니다. 그래도 맛이 좀 다르긴 하지만 아베제(Aveze)라는 수즈와 같이 용담(Gentain) 리큐르가 수입되기는 하니 참고해주세요."}]'::jsonb, 'published', '2025-06-06T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'white-negroni' AND c.slug = 'whitenegroni';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'boston-cooler', 'cocktail', '보스턴 쿨러 — 레몬의 산미와 생강의 청량감을 담은 칵테일', '「보스턴 쿨러」는 이름에서도 볼 수 있듯이 "쿨러(Cooler)"라는 카테고리의 칵테일로, 쿨러란 현재에는 주로 "기주+시트러스 즙+당+탄산 믹서"의 형태로 만들어지는 칵테일입니다.', '/articles/boston-cooler/00.webp',
  'https://blog.naver.com/shakinglikebartender/223887226154', false,
  '[{"kind":"figure","src":"/articles/boston-cooler/00.webp","width":966,"height":966},{"kind":"paragraph","text":"About the Cockail"},{"kind":"paragraph","text":"「보스턴 쿨러」는 이름에서도 볼 수 있듯이 \"쿨러(Cooler)\"라는 카테고리의 칵테일로, 쿨러란 현재에는 주로 \"기주+시트러스 즙+당+탄산 믹서\"의 형태로 만들어지는 칵테일입니다."},{"kind":"paragraph","text":"형태만 보면 \"피즈(Fizz)\", \"콜린스(Collins)\"나 \"벅(Buck)\" 계열의 칵테일들을 떠올리게 하는데, 사실 구분에 큰 의미가 없다시피 합니다."},{"kind":"figure","src":"/articles/boston-cooler/01.webp","width":601,"height":119,"caption":"The Fine Art of Mixing drinks(1948)"},{"kind":"paragraph","text":"이에 대해 데이비드 엠버리(David A. Embury)는 그의 저서에서 쿨러는 근본적으로 \"홀시스 넥(Horse''s Neck)의 변형\"이라고 표현하기도 했는데, 이건 아마 ''렘센 쿨러(Remsen Cooler)\"라는 칵테일이 \"쿨러\"류의 원조라는 견해 때문에 그런 것 같습니다."},{"kind":"paragraph","text":"다만, 갈수록 대부분의 쿨러 계열 칵테일들이 시트러스 즙과 당을 필요로 했기 때문에, 현재와는 좀 맞지 않는 부분도 있다고 생각됩니다."},{"kind":"figure","src":"/articles/boston-cooler/02.webp","width":966,"height":1287},{"kind":"paragraph","text":"개인적으로 보스턴 쿨러에서 가장 흥미로운 점은, 분명 이 칵테일이 서양에서 만들어진 것으로 보이나, 현재에는 서양에서의 인지도는 전혀 없고, 일본이나 우리나라 정도에서나 인지도가 있다는 점입니다."},{"kind":"paragraph","text":"영문으로 보스턴 쿨러를 검색해 보면 칵테일에 대한 내용은 거의 없고, 진저에일에 바닐라 아이스크림을 플로팅 한 디트로이트 지역의 음료만 주로 검색되는데 말이죠."},{"kind":"figure","src":"/articles/boston-cooler/03.webp","width":966,"height":966},{"kind":"heading","text":"Recipe"},{"kind":"paragraph","text":"*45ml 럼"},{"kind":"paragraph","text":"18~20ml 레몬즙"},{"kind":"paragraph","text":"**10ml 시럽(1:1 심플 시럽의 경우)"},{"kind":"paragraph","text":"진저비어 or 진저에일"},{"kind":"paragraph","text":"*럼은 아무 럼이나 사용해도 무관한데, 좀 더 다양한 맛을 내고 싶다면 골드 럼을 사용한다던가, 자메이칸 럼을 사용하는 것도 하나의 방법입니다."},{"kind":"paragraph","text":"**리치 심플 시럽을 사용하는 경우에는 양을 살짝만 줄이는 걸 추천합니다."},{"kind":"figure","src":"/articles/boston-cooler/04.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 진저비어 외의 모든 재료를 셰이커 안에 넣는다."},{"kind":"paragraph","text":"2. 얼음을 채우고, 셰이킹 한다."},{"kind":"paragraph","text":"3. 긴 잔에 얼음을 채우고, 셰이커에서 부어준다."},{"kind":"paragraph","text":"4. 진저비어를 더해주고,"},{"kind":"paragraph","text":"얼음을 위아래로 두 세번 움직여준다."},{"kind":"paragraph","text":"5. 레몬 휠을 넣어준다."},{"kind":"paragraph","text":"보스턴 쿨러의 맛"},{"kind":"paragraph","text":"- 상큼 달달하고, 생강의 알싸한 맛이 매력적인 맛"},{"kind":"paragraph","text":"- 약간의 탄산감"},{"kind":"paragraph","text":"- 모스코뮬에서 럼의 풍미가 추가된 느낌"},{"kind":"paragraph","text":"보스턴 쿨러는 상큼함, 생강의 알싸한 맛, 탄산감으로 인해서 꽤 리프레시가 되는 칵테일로, 개인적으로는 봄부터 가을까지 첫 잔으로 또는 음식과 함께 마시기에 꽤 좋은 칵테일이라 생각됩니다."}]'::jsonb, 'published', '2025-06-03T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'boston-cooler' AND c.slug = 'bostoncooler';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'bamboo', 'cocktail', '뱀부 — 군더더기 없이, 깔끔하고 조용한 한 잔', '「뱀부」는 흔히 1890년대에 일본의 *요코하마 그랜드 호텔에서 독일계 미국인 바텐더였던 루이스 에핑어(Louis Eppinger)에 의해서 만들어졌다고 하는데, 그 출처는 위의 윌리엄 부스비(William Boothby)의 **저서인 것으로 보입니다', '/articles/bamboo/00.webp',
  'https://blog.naver.com/shakinglikebartender/223862015358', false,
  '[{"kind":"figure","src":"/articles/bamboo/00.webp","width":966,"height":966},{"kind":"heading","text":"About the Cocktail"},{"kind":"figure","src":"/articles/bamboo/01.webp","width":674,"height":186,"caption":"**The World''s Drinks and How to Mix Them(1908)"},{"kind":"paragraph","text":"「뱀부」는 흔히 1890년대에 일본의 *요코하마 그랜드 호텔에서 독일계 미국인 바텐더였던 루이스 에핑어(Louis Eppinger)에 의해서 만들어졌다고 하는데, 그 출처는 위의 윌리엄 부스비(William Boothby)의 **저서인 것으로 보입니다."},{"kind":"paragraph","text":"*관동대지진 후 「호텔 뉴 그랜드」가 후신으로 세워져 현재까지 영업"},{"kind":"figure","src":"/articles/bamboo/02.webp","width":524,"height":181,"caption":"1886.9.11. Western Kansas world"},{"kind":"paragraph","text":"그러나 1886년 9월 11일에 발간된 ''Western Kansas world''에 따르면 뱀부는 이미 영국인에 의하여 전파되어 뉴욕에서 인기를 끌고 있었다고 합니다. 다만, 어떤 셰리와 버무스를 사용한 것인지는 알 수 없죠."},{"kind":"paragraph","text":"개인적으로 여기서 주목해야 할 점은 영국인에 의해서 만들어졌다는 게 아니라 \"몇 영국인들에 의해 소개되되어 왔다.\"라는 점이라 생각됩니다."},{"kind":"paragraph","text":"에핑어는 1880년대 초중반에 미국 북서부의 항구도시에서 술집과 레스토랑을 활발하게 운영했는데, ''이 영국인들이 여기서 에핑어의 뱀부를 맛보고 다른 도시로 이동해 소개했을까?''하는 상상을 할 수 있게 해주죠."},{"kind":"paragraph","text":"하지만 결국 이에 대한 더 이상의 기록이나 증거는 없습니다."},{"kind":"figure","src":"/articles/bamboo/03.webp","width":966,"height":1288},{"kind":"paragraph","text":"어찌 됐건 셰리+버무스의 조합으로 만들어진 뱀부라는 칵테일이 1880년대 중반부터 존재했고, 1890년대~1910년대 사이에 버무스의 종류만 다른 「아도니스」라는 칵테일이 만들어진 것을 보면, 당시 이러한 조합이 새로운 것이 아니었다고도 짐작할 수 있습니다."},{"kind":"paragraph","text":"그렇다 보니 \"에핑어가 뱀부라는 칵테일의 창작자\"인지 정확히 알 수 없습니다. 그러나 만들어진 시기는 신빙성이 없더라도 적어도 에핑어가 창작했다는 기록이 존재하기 때문에 현재까지도 통설로 여겨지고 있습니다."},{"kind":"figure","src":"/articles/bamboo/04.webp","width":966,"height":966},{"kind":"heading","text":"Recipe"},{"kind":"paragraph","text":"45ml 피노 셰리(Fino Sherry)"},{"kind":"paragraph","text":"15ml 드라이 버무스(Dry Vermouth)"},{"kind":"paragraph","text":"*1dash 오렌지 비터(Orange Bitters)"},{"kind":"paragraph","text":"*8~10drops"},{"kind":"paragraph","text":"아도니스 칵테일처럼 뱀부에도 꽤나 다양한 레시피가 존재합니다. 비율, 셰리의 종류, 비터의 조합을 다르게 한다는 식으로 말이죠."},{"kind":"paragraph","text":"그렇지만 뱀부라는 칵테일 자체가 일본의 이미지를 떠올리게 하는 칵테일인 만큼 살짝 드라이하고, 깔끔한 맛을 위해서는 피노 셰리를 사용하는 걸 추천드립니다."},{"kind":"figure","src":"/articles/bamboo/05.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 모든 재료를 믹싱 글라스에 넣는다."},{"kind":"paragraph","text":"2. 믹싱 글라스에 얼음을 채워준다."},{"kind":"paragraph","text":"3. 스터 후, 잔에 따라준다."},{"kind":"paragraph","text":"뱀부의 맛"},{"kind":"paragraph","text":"- 드라이하고, 깔끔하며, 약간은 떫고 약간의 독특한 짠맛"},{"kind":"paragraph","text":"- 피노 셰리에서 오는 약간의 견과류 캐릭터"},{"kind":"paragraph","text":"- 버무스에서 오는 약간의 허브와 향신료 캐릭터"},{"kind":"paragraph","text":"뱀부는 낮은 도수감과 특유의 깔끔함 등으로 인해서 흔히 식전주로 인식되는 칵테일입니다. 일본에서도 잘 알려져 있는 칵테일이지만, 서양 쪽에서도 꽤나 인기 있는 것으로 보입니다."}]'::jsonb, 'published', '2025-05-11T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'bamboo' AND c.slug = 'bamboo';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'banana-boulevardier', 'cocktail', '바나나 불바디에 — 진지한 클래식에 얹은 장난스러운 바나나', '「바나나 불바디에」는 클래식 칵테일인 불바디에의 간단한 변형으로, 휴스턴의 앤빌 바 & 레퓨지(Anvil Bar & Refuge)에서 2015년 8월에 총괄 매니저였던 테리 윌리엄스(Terry Williams)에 의해 만들어졌다고 합니다.', '/articles/banana-boulevardier/00.webp',
  'https://blog.naver.com/shakinglikebartender/223856829267', false,
  '[{"kind":"figure","src":"/articles/banana-boulevardier/00.webp","width":966,"height":966},{"kind":"heading","text":"About the Cocktail"},{"kind":"paragraph","text":"「바나나 불바디에」는 클래식 칵테일인 불바디에의 간단한 변형으로, 휴스턴의 앤빌 바 & 레퓨지(Anvil Bar & Refuge)에서 2015년 8월에 총괄 매니저였던 테리 윌리엄스(Terry Williams)에 의해 만들어졌다고 합니다."},{"kind":"paragraph","text":"이 칵테일이 만들어지게 된 계기가 꽤 단순한데, 어느 날 윌리엄스는 메뉴 개발 후에 소량 남아있던 바나나 리큐르를 비우고 싶어 했습니다."},{"kind":"paragraph","text":"그렇게 윌리엄스는 캄파리와 바나나 리큐르를 샷잔에 동률로 섞어서 마셔봤는데, 이게 엄청나게 맛있었다고 합니다. 그 후에 이 조합은 바나나 불바디에를 만들어내게 되었다고."},{"kind":"figure","src":"/articles/banana-boulevardier/01.webp","width":966,"height":966},{"kind":"heading","text":"Recipe"},{"kind":"paragraph","text":"30ml 버번 위스키(Bourbon Whiskey)"},{"kind":"paragraph","text":"15ml 캄파리(Campari)"},{"kind":"paragraph","text":"15ml *바나나 리큐르(Banana Liqueur)"},{"kind":"paragraph","text":"30ml 스위트 버무스(Sweet Vermouth)"},{"kind":"paragraph","text":"*오리지널 레시피에서는 지파드 프리미엄 브라질 바나나 사용"},{"kind":"paragraph","text":"가니시: 오렌지 껍질, 말린 바나나(옵션)"},{"kind":"figure","src":"/articles/banana-boulevardier/02.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 가니시 외의 재료를 락 잔에 넣어준다."},{"kind":"paragraph","text":"2. 잔에 얼음을 채우고, 스터 해준다."},{"kind":"paragraph","text":"3. 잔 위로 오렌지 껍질을 짜서 오일을 더해주고,"},{"kind":"paragraph","text":"사용한 껍질과 말린 바나나를 넣어준다."},{"kind":"figure","src":"/articles/banana-boulevardier/03.webp","width":966,"height":966},{"kind":"paragraph","text":"바나나 불바디에의 맛"},{"kind":"paragraph","text":"- 쨍하고 확실한 바나나의 맛"},{"kind":"paragraph","text":"- 캄파리의 쌉쌀함과 오렌지 캐릭터"},{"kind":"paragraph","text":"- 버무스의 허브감"},{"kind":"paragraph","text":"- 중심을 잡아주는 버번의 견과류 캐릭터"},{"kind":"paragraph","text":"- 마지막에는 바나나맛+버번의 바닐라, 견과류가 혀에 남음"},{"kind":"paragraph","text":"바나나 불바디에는 개인적으로 꽤나 단맛이 강한 칵테일이었는데, 바나나 리큐르와 캄파리의 비율을 살짝 조정해 주는 게 더 낫다고 생각합니다."},{"kind":"paragraph","text":"우드포드 리저브에는 좀 풀리고 난 뒤에 바나나 캐릭터가 다른 버번에 비해 강하다고 생각하는데, 이 칵테일의 기주로 쓰니 꽤 만족스러웠습니다."},{"kind":"paragraph","text":"전체적으로 아주 간단한 변형이기는 하지만, 쉽게 생각하기 어렵고 재미있는 조합의 칵테일이라 생각됩니다."},{"kind":"paragraph","text":"바나나의 캐릭터가 캄파리의 캐릭터와도 꽤 재밌는 조화를 이룬다는 생각이 들고, 기주를 버번이 아니라 오버프루프 자메이칸 럼으로 만들면 아주 펑키하고 재밌는 네그로니 변형이 되지 않을까도 싶습니다."}]'::jsonb, 'published', '2025-05-06T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'banana-boulevardier' AND c.slug = 'bananaboulevardier';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'adonis', 'cocktail', '아도니스 — 저도수로 즐기는 셰리와 스위트 버무스의 잔잔한 여운', '「아도니스」는 아주 오래된 칵테일로, 그와 관련된 이야기는 그다지 많지 않습니다.', '/articles/adonis/00.webp',
  'https://blog.naver.com/shakinglikebartender/223854364359', false,
  '[{"kind":"figure","src":"/articles/adonis/00.webp","width":966,"height":966},{"kind":"heading","text":"About the Cocktail"},{"kind":"paragraph","text":"「아도니스」는 아주 오래된 칵테일로, 그와 관련된 이야기는 그다지 많지 않습니다. 일단 공통적으로 1884년에 초연된 후 브로드웨이에서 500회 이상 공연된 동명의 뮤지컬에서 이름을 따왔다고 합니다."},{"kind":"paragraph","text":"어떤 설에서는 뉴욕의 *「월도프-아스토리아(Waldorf-Astoria) 호텔」에서 만들어졌다고도 합니다만, 정확한 근거가 있는 건 아니고 추정되는 정도인 것 같습니다.*1893~1929"},{"kind":"paragraph","text":"이와 관련해서는 difford''s Guide에서 아주 자세하게 소개하고 있습니다."},{"kind":"paragraph","text":"살펴보자면 1887년 3월 27일 자로 발행된 뉴욕 한 신문의 칼럼에서 처음으로 ''아도니스''라는 이름의 칵테일에 관한 일화가 나오는데, 이 아도니스가 우리가 현재 아는 그 아도니스가 맞는지는 알 수 없습니다."},{"kind":"paragraph","text":"하지만, 이후에 *자크 스트라우브의 저서에서 현재 우리가 아는 아도니스가 소개되었고, 이후 **알버트 스티븐스 크로켓의 두 저서에서 그 이름의 유래가 소개되었습니다."},{"kind":"paragraph","text":"*Straub''s Manual of Mixed Drinks(1913)"},{"kind":"paragraph","text":"**Old Waldorf Bar Days(1931), Old Waldorf-Astoria Bar Book(1935)"},{"kind":"paragraph","text":"종합해 보자면, \"적어도 1913년 이전에 아마도 월도프-아스토리아 호텔의 바에서 아도니스가 만들어졌을 것이다!\"라고 추정할 수는 있겠죠."},{"kind":"quote","text":"''왜 하필 월도프-아스토리아 호텔일까?''"},{"kind":"paragraph","text":"뮤지컬 ''아도니스''는 당시 브로드웨이에서 큰 인기를 끈 뮤지컬."},{"kind":"paragraph","text":"정보와 문화가 퍼지는 속도가 느렸기 때문에 동명의 칵테일은 뉴욕에서 만들어졌을 것."},{"kind":"paragraph","text":"당시 쉐리 와인과 버무스는 가격대가 높은 주류, 주로 상류층이 즐기던 술, 고급 레스토랑이나 호텔에서나 취급."},{"kind":"paragraph","text":"월도프-아스토리아 호텔은 당대 상류층과 저명인사들이 방문하던 곳으로, 사교의 중심지였음."},{"kind":"paragraph","text":"*1931년과 1935년에 호텔의 칵테일 레시피를 담은 책들이 출판될 정도."},{"kind":"paragraph","text":"당시에 이미 맨하탄, 마티니처럼 버무스를 사용하는 칵테일들이 이미 존재했음"},{"kind":"paragraph","text":"*해당 책들에서 아도니스 이름의 유래에 대해 설명"},{"kind":"paragraph","text":"이런 점들 때문에 이 칵테일이 월도프-아스토리아 호텔에서 만들어졌다고 추정하는 것은 꽤 합당해 보입니다."},{"kind":"figure","src":"/articles/adonis/01.webp","width":966,"height":966},{"kind":"heading","text":"Recipe"},{"kind":"paragraph","text":"아도니스의 레시피는 정말 다양합니다. 1:1 ~ 3:1로 비율이 다양하고, 피노 쉐리 말고 다른 쉐리를 쓴다든지, 피노 쉐리에 다른 쉐리도 블렌딩한다든지 만드는 사람마다 천차만별입니다."},{"kind":"paragraph","text":"이것저것 시도해 보시고 입맛에 맞는 아도니스를 찾아가는 게 가장 좋겠죠."},{"kind":"figure","src":"/articles/adonis/02.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 모든 재료를 믹싱 글라스에 넣어줍니다."},{"kind":"paragraph","text":"2. 믹싱 글라스에 얼음을 채우고, 스터합니다."},{"kind":"paragraph","text":"3. 칵테일 잔에 따라줍니다."},{"kind":"paragraph","text":"아도니스의 맛"},{"kind":"paragraph","text":"- 압도적인 감칠맛"},{"kind":"paragraph","text":"- 와인스러움에 더해 약간의 한약스러운 맛"},{"kind":"paragraph","text":"- 약간의 오렌지에 더불어, 아주 살짝 열대과일 같은 느낌도 스쳐감"},{"kind":"paragraph","text":"- 약간의 견과류의 캐릭터"},{"kind":"paragraph","text":"- 복잡한 향신료, 허브, 차의 캐릭터가 훅하고 지나감."},{"kind":"paragraph","text":"그 외"},{"kind":"paragraph","text":"- 아도니스는 ''뱀부(Bamboo)''에서 드라이 버무스를 스위트 버무스로 바꾼 칵테일로, 어느 정도 비슷한 캐릭터를 공유"},{"kind":"paragraph","text":"- 뱀부와 더불어 도수가 낮은 편의 칵테일로, 주로 식전주로 소개되고 있기도"},{"kind":"paragraph","text":"- 인지도면에서는 뱀부만큼의 유명세를 가지고 있지는 못함"}]'::jsonb, 'published', '2025-05-03T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'adonis' AND c.slug = 'adonis';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'rob-roy', 'cocktail', '롭 로이 — 맨하탄의 스코틀랜드 출신 형제, 스카치 위스키를 사용한 맨하탄', '가장 많이 언급되는 이야기에 따르면, 「롭 로이」는 「월도프-아스토리아(Waldorf-Astoria) 호텔」의 한 바텐더에 의하여 1894년에 만들어졌다고 합니다.', '/articles/rob-roy/00.webp',
  'https://blog.naver.com/shakinglikebartender/223846355977', false,
  '[{"kind":"figure","src":"/articles/rob-roy/00.webp","width":966,"height":966},{"kind":"heading","text":"About the Cocktail"},{"kind":"paragraph","text":"가장 많이 언급되는 이야기에 따르면, 「롭 로이」는 「월도프-아스토리아(Waldorf-Astoria) 호텔」의 한 바텐더에 의하여 1894년에 만들어졌다고 합니다."},{"kind":"paragraph","text":"그 이름은 오페레타(Operetta) ''롭 로이''의 초연을 기념하기 위하여 지어졌는데, 이 오페레타의 주인공인 ''로버트 로이 멕그리거(Robert Roy MacGregor)''의 약칭이기도 합니다."},{"kind":"paragraph","text":"이 ''롭 로이''라는 인물은 스코틀랜드의 민속 영웅이라고 하는데, 들어가는 재료를 생각하면 그럴듯한 작명 센스긴 하죠."},{"kind":"paragraph","text":"다만, 이 설에 대해서는 어느 정도 의문점이 존재합니다."},{"kind":"figure","src":"/articles/rob-roy/01.webp","width":966,"height":1288},{"kind":"quote","text":"정말 월도프-아스토리아 호텔에서 만들어졌을까?"},{"kind":"paragraph","text":"이미 10년 전인 1884년에 다른 이름으로 스카치 + 버무스 조합의 칵테일이 존재했음."},{"kind":"paragraph","text":"그 이전에 이미 기주만 다른 맨하탄(Manhattan)이 존재했음."},{"kind":"paragraph","text":"당시에는 스윗 버무스가 들어간 칵테일이 크게 유행하였음."},{"kind":"paragraph","text":"이런 점들을 보면 정말 월도프-아스토리아 호텔에서 롭로이 칵테일이 \"탄생\"하였는지에는 약간의 의문이 들기는 합니다만, 모든 칵테일에는 이야기가 필요한 법이니까요."},{"kind":"figure","src":"/articles/rob-roy/02.webp","width":966,"height":966},{"kind":"heading","text":"Recipe"},{"kind":"paragraph","text":"45ml 스카치 위스키(Scotch Whisky)"},{"kind":"paragraph","text":"15ml 스윗 버무스(Sweet Vermouth)"},{"kind":"paragraph","text":"*1~2dashes 앙고스투라 아로마틱 비터"},{"kind":"paragraph","text":"(Angostura Aromatic Bitters)"},{"kind":"paragraph","text":"*8~20drops"},{"kind":"paragraph","text":"가니시: 오렌지 껍질, 마라스키노 체리(옵션)"},{"kind":"paragraph","text":"롭 로이는 대부분 맨하탄처럼 기주와 버무스가 2:1 또는 3:1이 가장 대중적인 비율입니다. 입맛과 사용하시는 버무스에 따라서 마음에 드는 비율로 만드시면 되겠습니다."},{"kind":"paragraph","text":"또, 기주에 있어서 블렌디드 스카치 위스키를 사용해도 전혀 상관 없습니다만, 개인적으로는 캐릭터가 확실한 싱글 몰트 위스키를 사용하시는 걸 추천드립니다."},{"kind":"paragraph","text":"개인적으로는 점잖고, 부드럽고 살짝 달큰한 롭 로이는 발베니 12년 더블우드를 사용하고 있습니다. 어떤 분들은 피트 위스키를 소량 첨가하기도 하더군요. 이 부분도 취향대로."},{"kind":"figure","src":"/articles/rob-roy/03.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 가니시 외의 재료를 믹싱글라스에 넣습니다."},{"kind":"paragraph","text":"2. 얼음을 채우고, 스터합니다."},{"kind":"paragraph","text":"3. 칵테일 잔에 따라줍니다."},{"kind":"paragraph","text":"4. 잔 위로 *오렌지 껍질을 짜서 오일을 뿌립니다."},{"kind":"paragraph","text":"5. 마라스키노 체리를 하나 넣어습니다(옵션)"},{"kind":"paragraph","text":"*오렌지 껍질은 취향에 따라서 버리거나,"},{"kind":"paragraph","text":"다듬어서 잔에 꽃아서 장식해줍니다."},{"kind":"paragraph","text":"롭 로이의 맛"},{"kind":"paragraph","text":"- 바닐라 느낌이 적고, 더욱 섬세한 캐릭터의 맨하탄 같은 느낌"},{"kind":"paragraph","text":"- 생각보다 달큰하고, 복잡한 맛"},{"kind":"paragraph","text":"- 사용하는 스카치에 따라서 편차가 좀 있는 맛"},{"kind":"paragraph","text":"개인적으로 맨하탄보다는 롭 로이를 더 좋아하는 편인데, 스카치 위스키를 좋아하시는 분들이라면 꼭 한 번쯤은 마셔보시는 걸 추천드리는 편입니다."}]'::jsonb, 'published', '2025-04-25T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'rob-roy' AND c.slug = 'robroy';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'milk-and-honey-mokpo', 'bar', '밀크앤허니 — 목포에서 만난 스피크이지 바', '노크하면 작은 창이 먼저 열리는 목포의 스피크이지 바. 사샤 페트라스케의 이름을 이어받은 클래식 칵테일이 있다.', '/articles/milk-and-honey-mokpo/00.webp',
  'https://blog.naver.com/shakinglikebartender/223840422282', false,
  '[{"kind":"figure","src":"/articles/milk-and-honey-mokpo/00.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/milk-and-honey-mokpo/01.webp","width":966,"height":543},{"kind":"paragraph","text":"「밀크앤허니」는 목포의 평화공원 근처에 위치한 바로, 지방에서는 보기 드물게 스피크이지(Speakeasy) 콘셉트로 운영하고 있는 곳입니다."},{"kind":"paragraph","text":"스피크이지 바란 미국 금주령 시대에 생긴 개념으로, \"겉으로 봐서는 바라고는 생각할 수 없는 외관에 아는 사람만 알음알음 찾아가는 바\"입니다."},{"kind":"paragraph","text":"90년대 후반 ~ 2000년대 초부터 미국을 중심으로 ''사샤 페트라스케''에 의해 다시 유행하게 된 콘셉트로, 현재에는 국내에서도 심심찮게 찾아볼 수 있습니다."},{"kind":"paragraph","text":"''밀크 앤 허니(Milk & Honey)''라는 바 이름은 아마 사샤 페트라스케가 뉴욕에서 운영했었던 동명의 바에서 따온 것으로 보이는데, 이 바의 지향점을 엿볼 수 있는 부분입니다."},{"kind":"paragraph","text":"밀크앤허니에서는 스피크이지 콘셉트에 따라서 문을 노크하면 문 위의 작은 창을 열어 확인을 하고, 문을 열어주는 식입니다."},{"kind":"figure","src":"/articles/milk-and-honey-mokpo/02.webp","width":966,"height":966},{"kind":"paragraph","text":"바에 들어서면 한 쪽 벽면에는 사샤 페트라스케의 글귀를 적어 놓았고. 내부 사진을 깜빡하고 안찍었는데, 바테이블 + 별도의 테이블로 나뉘어져 있습니다."},{"kind":"figure","src":"/articles/milk-and-honey-mokpo/03.webp","width":966,"height":966},{"kind":"heading","text":"첫 잔은 역시 하이볼"},{"kind":"paragraph","text":"첫 잔은 당연히 하이볼을 생각하고 있었는데, 기주에 올드 파 12년이 있길래 바로 주문했습니다. 아직까지 올드 파로 하이볼을 마셔본 적이 없었거든요. 첫 입을 마셔보고 ''아, 다른 칵테일이 기대된다''는 생각이 바로 들었습니다."},{"kind":"figure","src":"/articles/milk-and-honey-mokpo/04.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/milk-and-honey-mokpo/05.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/milk-and-honey-mokpo/06.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/milk-and-honey-mokpo/07.webp","width":966,"height":1289,"caption":"왼쪽부터 김렛, 사이드카, 사제락, 네그로니"},{"kind":"paragraph","text":"친구와 함께 가서 서로 좋아하는 칵테일을 두 잔씩 시켰는데, 개인적으로 최근에 방문한 바 중에 제 입맛에 가장 맞았습니다."},{"kind":"paragraph","text":"예를 들어서 사이드카 같은 경우에는 쥬시하고, 살짝 무게감 있고, 거품층이 생기는 걸 좋아하는데, 딱 이 취향에 맞는 맛이었습니다. 네그로니도 쓴맛과 단맛의 밸런스가 절묘했던."},{"kind":"paragraph","text":"제가 클래식 칵테일을 워낙 좋아하다 보니, 이곳의 시그니처를 못 마셨던 게 살짝 아쉬웠지만, 마신 칵테일들이 전부 맛있었습니다."},{"kind":"figure","src":"/articles/milk-and-honey-mokpo/08.webp","width":966,"height":1287},{"kind":"figure","src":"/articles/milk-and-honey-mokpo/09.webp","width":966,"height":1288},{"kind":"paragraph","text":"칵테일 외에도 이곳에서는 3가지 술을 골라서 15ml(?)씩 주문할 수가 있었는데, 평소에는 좀 가격대가 있어서 마시기 망설여지던 녀석들을 마시기에 딱 좋습니다."},{"kind":"paragraph","text":"그래서 평소에 친구와 궁금했던 데킬라 ''클라세 아줄 레포사도''와 위스키 ''탈리스커 DE'', ''아란 증류소의 익스플로러 시리즈 중에서 킬도넌 & 플라다 아일랜드''를 주문해 봤습니다. ''드루마둔''은 사장님이 비교해 보라고 주신 서비스."},{"kind":"paragraph","text":"개인적으로 그중에서는 킬도넌 & 플라다 아일랜드가 가장 기억에 남는데, 50.4도임에도 도수감이 느껴지지 않고, 모난 부분 없이 꽤나 달큰했었습니다. 구할 수만 있으면 한 병 구하고 싶을 정도."},{"kind":"paragraph","text":"제가 밀크앤허니를 방문했을 때는 아마 2월 정도였던 걸로 기억하는데, 클래식 칵테일이 정말 맛있어서 다음잔이 기대되고, 가격이 합리적이었어서 인상 깊었던 바였습니다."},{"kind":"paragraph","text":"방문하신다면 클래식 칵테일이나, 모던 클래식 칵테일을 꼭 한 잔 정도는 주문해보시길"}]'::jsonb, 'published', '2025-04-20T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'boulevardier', 'cocktail', '불바디에 — 버번 위스키를 사용한 네그로니의 형제 칵테일', '1920년대에 미국에서는 금주법이 시행되면서 많은 미국인들이 유럽, 특히 파리로 건너가 술과 문화를 자유롭게 즐겼으며, 그 중 유명한 곳으로 「해리스 뉴욕 바(Harry’s New York Bar)」가 있었습니다.', '/articles/boulevardier/00.webp',
  'https://blog.naver.com/shakinglikebartender/223839734664', false,
  '[{"kind":"figure","src":"/articles/boulevardier/00.webp","width":966,"height":966},{"kind":"heading","text":"About the Cocktail"},{"kind":"paragraph","text":"1920년대에 미국에서는 금주법이 시행되면서 많은 미국인들이 유럽, 특히 파리로 건너가 술과 문화를 자유롭게 즐겼으며, 그 중 유명한 곳으로 「해리스 뉴욕 바(Harry’s New York Bar)」가 있었습니다."},{"kind":"paragraph","text":"이 곳의 주인이던 해리 맥켈혼(Harry McElhone)이 1927년 출간한 칵테일 책 Barflies and Cocktails의 마지막 부분에 ''아서 모스(Arthur Moss)''가 쓴 에세이인 ''Cocktails Round Town''이 있는데, 여기서 불바디에가 처음 기록되었습니다."},{"kind":"quote","text":"Now is the time for all good Barflies to come to the aid of the party, since Erskinne Gwynne crashed in with his Boulevardier Cocktail; 1/3 Campari, 1/3 Italian vermouth, 1/3 Bourbon whisky."},{"kind":"paragraph","text":"여기서 모스는 에르스킨 그윈(Erskine Gwynne)이라는 인물이 그의 불바디에와 난입했다고 적었는데, 이게 그윈이라는 인물이 창작한 칵테일인지, 아니면 그냥 그윈이 좋아하는 칵테일인 건지가 좀 모호합니다."},{"kind":"figure","src":"/articles/boulevardier/01.webp","width":966,"height":966},{"kind":"paragraph","text":"본질적으로 불바디에는 네그로니(Negroni)의 변형이면서도, 이전에 포스팅한 같은 저서에서 등장하는 ''올드 팔(Old Pal)''이라는 칵테일과 아주 유사한 구조의 형제 칵테일이기도 합니다."},{"kind":"paragraph","text":"불바디에와 올드 팔은 위스키, 버무스, 캄파리의 구조는 동일한데, 위스키와 버무스에서 차이가 나는 칵테일로, 이로 인해 불바디에가 올드 팔보다는 기본적으로 묵직한 느낌이 있습니다."},{"kind":"figure","src":"/articles/boulevardier/02.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"30ml 버번 위스키(Bourbon Whiskey)"},{"kind":"paragraph","text":"30ml 캄파리(Campari)"},{"kind":"paragraph","text":"30ml 스윗 버무스(Sweet Vermouth)"},{"kind":"paragraph","text":"가니시: 오렌지 껍질(Orange Peel)"},{"kind":"figure","src":"/articles/boulevardier/03.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 온더락 잔에 모든 재료를 넣어줍니다."},{"kind":"paragraph","text":"2. 얼음을 채우고, 스터해줍니다."},{"kind":"paragraph","text":"3. 잔 위로 오렌지 껍질을 짜서 오일을 뿌려줍니다."},{"kind":"paragraph","text":"4. 사용한 껍질을 다듬어서 잔에 넣어줍니다."},{"kind":"paragraph","text":"불바디에의 맛"},{"kind":"paragraph","text":"- 묵직하면서도 부드러운 바닐리함, 달큰하면서도 씁쓸함, 허브감"},{"kind":"paragraph","text":"- 진으로 만든 네그로니보다는 허브감 자체는 살짝 덜합니다."},{"kind":"paragraph","text":"- 초콜레티한 맛도 나는데, 아마도 코키 디 토리노와 우드포드 리저브의 조합 때문인 것 같습니다."},{"kind":"paragraph","text":"팁?"},{"kind":"paragraph","text":"- 사용하는 버번의 캐릭터에 따라서 맛이 꽤 다르게 만들어지기도 하니 이런저런 기주를 많이 경험해 보는 것이 좋습니다."},{"kind":"paragraph","text":"- 올드 팔과 같이 쇼트 칵테일 잔에 업 스타일로 서브하기도 하는데, 이건 개인의 취향에 맞게 해주시면 됩니다."}]'::jsonb, 'published', '2025-04-19T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'boulevardier' AND c.slug = 'boulevardier';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'espresso-martini', 'cocktail', '에스프레소 마티니 — 커피와 술이 동시에 필요할 때', '"정신이 번쩍 들게 해주고, 그러고 나서 제대로 취하게 만들어줘." 런던의 칵테일 킹 딕 브래드셀이 그 주문에 내놓은 대답.', '/articles/espresso-martini/00.webp',
  'https://blog.naver.com/shakinglikebartender/223823035796', false,
  '[{"kind":"figure","src":"/articles/espresso-martini/00.webp","width":966,"height":543},{"kind":"heading","text":"About the Cocktail"},{"kind":"paragraph","text":"「에스프레소 마티니」는 1980년대 후반에 런던의 ''프레드 바(Fred''s Bar)''에서 탄생했는데, 커피 칵테일 중 독보적인 인기를 끌고 있는 이 칵테일은 런던의 칵테일 킹이었던 딕 브래드셀(Dick Bradsell)에 의해 만들어졌습니다."},{"kind":"figure","src":"/articles/espresso-martini/01.webp","width":966,"height":1288},{"kind":"quote","text":"Wake me up, and then Fxxk me up"},{"kind":"quote","text":"정신이 번쩍 들게 해주고, 그러고 나서 제대로 취하게 만들어줘."},{"kind":"paragraph","text":"어느 날, 어린 모델(나중에는 유명해진)이 바에 들어와서는 \"정신이 번쩍 들게 해주고, 그러고 나서 제대로 취하게 만들어줘.\"라는 주문을 했다고 합니다."},{"kind":"paragraph","text":"이런 재밌는 요청에 브래드셀은 보드카, 커피 리큐르 그리고 갓 내린 에스프레소를 조합해서 칵테일을 만들어냈는데, 당시에 머신에서 갓 내린 에스프레소는 칵테일 재료로 거의 쓰이지 않았기 때문에 아주 담대한 선택이었죠."},{"kind":"paragraph","text":"에스프레소 마티니는 기주와 이름에서 당시 칵테일 트렌드를 아주 잘 보여주는데, 1980년대엔 보드카 칵테일들이 인기였고, 1990년대에는 마티니 잔(''V'' 모양)에 담긴 칵테일에 ''~마티니'' 같은 이름을 붙이는 것이 유행이었죠."},{"kind":"paragraph","text":"사실 브래드셀이 처음 칵테일을 만들었을 때는 「보드카 에스프레소(Vodka Espresso)」라는 이름을 붙였었는데, 1990년대 유행에 따라서 이름을 바꿨다고 합니다. 저는 지금의 이름이 좀 더 캐치한 것 같네요."},{"kind":"paragraph","text":"*''애플 마티니, 레몬 드롭 마티니'' 등처럼 이런 식으로 이름 붙은 마티니 칵테일이 많은데, 이런 칵테일들은 진과 드라이 버무스가 들어가는 클래식 마티니의 변형도 아니고, 잔의 모양 빼고는 아무런 관계가 없습니다."},{"kind":"figure","src":"/articles/espresso-martini/02.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"20ml 냉동한 보드카(Vodka)"},{"kind":"paragraph","text":"30ml 미스터 블랙(Mr Black)"},{"kind":"paragraph","text":"30ml 갓 내린 에스프레소(Espresso)"},{"kind":"paragraph","text":"10ml 리치 시럽 or  8g 데메라라 설탕"},{"kind":"paragraph","text":"*에스프레소 마티니는 재료에 따라서, 만드는 사람에 따라서 레시피가 천차 만별입니다. 이런저런 레시피를 많이 비교해 보시고 만드는 걸 추천드립니다."},{"kind":"paragraph","text":"다만, 깔루아로 만드는 경우에는 시럽(또는 설탕)을 빼고 재료를 1:1:1로 넣어서 만드는 게 가장 일반적인 레시피기도 합니다."},{"kind":"figure","src":"/articles/espresso-martini/03.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 쉐이커에 모든 재료를 넣어줍니다."},{"kind":"paragraph","text":"2. 쉐이커에 얼음을 채워줍니다."},{"kind":"paragraph","text":"3. 쉐이킹 후에 차갑게 식힌 칵테일 잔에 따라준다."},{"kind":"paragraph","text":"4. 거품층 위에 커피콩 3개를 얹어준다(옵션)."},{"kind":"heading","text":"에스프레소 마티니의 맛"},{"kind":"paragraph","text":"- 커피의 풍미에 리큐르와 설탕의 적당한 단맛."},{"kind":"paragraph","text":"- 에스프레소 마티니는 재료의 선택과 비율에 따라서 맛의 차이가 꽤 많이 나게 됩니다."},{"kind":"paragraph","text":"- 조합에 따라서는 더위사냥 같은 맛의 에스프레소 마티니가 만들어지기도 하죠."},{"kind":"heading","text":"쫀쫀하고 풍부한 거품층"},{"kind":"paragraph","text":"- 갓 내린 에스프레소를 사용하는 걸 추천하는데, 크레마가 칵테일의 거품층 형성에 아주 중요하기 때문."},{"kind":"paragraph","text":"- 개인적으로는 캡슐 커피 머신을 사용."},{"kind":"paragraph","text":"- 쉐이킹을 다소 강하게 해주기."},{"kind":"heading","text":"온도 조절"},{"kind":"paragraph","text":"- 갓 내린 에스프레소는 뜨겁기 때문에 보드카는 냉동실에서 차갑게 보관해 두기."},{"kind":"paragraph","text":"- 상온의 보드카를 사용하면 얼음이 원하는 것보다 더 녹게 되고, 칵테일의 맛이 좀 맹맹해질 수 있습니다."}]'::jsonb, 'published', '2025-04-05T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'espresso-martini' AND c.slug = 'espresso';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'kaikan-fizz', 'cocktail', '카이칸 피즈 — 우유로 변장한 진 피즈', '「카이칸 피즈」는 제2차 세계대전이 끝난 후에 일본 도쿄의 동경회관(도쿄카이칸/東京會舘)에서 만들어지게 됩니다.', '/articles/kaikan-fizz/00.webp',
  'https://blog.naver.com/shakinglikebartender/223761734109', false,
  '[{"kind":"figure","src":"/articles/kaikan-fizz/00.webp","width":966,"height":966},{"kind":"heading","text":"About the Cocktail"},{"kind":"paragraph","text":"「카이칸 피즈」는 제2차 세계대전이 끝난 후에 일본 도쿄의 동경회관(도쿄카이칸/東京會舘)에서 만들어지게 됩니다."},{"kind":"paragraph","text":"이 동경회관은 전쟁 전에는 서양식 건물의 사교장으로 이용되었으나, 전후에는 연합군 최고사령부(GHQ)에 의해 1945~1952의 기간 동안 「아메리칸 클럽 오브 도쿄」라는 이름의 장교들을 위한 장소(장교 클럽)으로 이용되었습니다."},{"kind":"paragraph","text":"카이칸 피즈는 이 기간 동안에 만들어지게 되었는데, 몇몇 설이 있지만 가장 유명한 것으로는 당시의 장교들이 낮부터 몰래 술을 마실 수 있도록 진피즈에 우유를 넣도록 요청하여, 마치 우유를 마시는 것처럼 위장하기 위해서 시작한 것이라 합니다."},{"kind":"paragraph","text":"몇 번의 재건축이 있었지만, 동경회관은 현재에도 계속해서 운영되고 있고, 이 안의 메인 바(Main Bar)에서는 현재에도 카이칸 피즈가 만들어지고 있다고 합니다. 이 바에서는 당시 최고사령관이었던 맥아더도 이 칵테일을 좋아했다고 소개하고 있습니다."},{"kind":"paragraph","text":"카이칸 피즈는 그 외에도 「진 피즈, 카이칸 스타일」 또는 「모닝 피즈」로도 불리고 있다고 하며, 우리나라에서는 인지도가 거의 없지만, 일본에서는 웬만한 바에서 주문해도 맛볼 수 있을 정도의 인지도를 가지고 있습니다."},{"kind":"figure","src":"/articles/kaikan-fizz/01.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"figure","src":"/articles/kaikan-fizz/02.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 탄산수를 제외한 재료를 쉐이커에 넣어줍니다."},{"kind":"paragraph","text":"2. 쉐이커에 얼음을 넣어주고,"},{"kind":"paragraph","text":"다소 길게 쉐이킹해줍니다."},{"kind":"paragraph","text":"3. 긴 잔에 얼음을 채우고, 쉐이커에서 부어줍니다."},{"kind":"paragraph","text":"4. 탄산을 살살 부어줍니다."},{"kind":"paragraph","text":"5. 얼음을 위아래로 2~3번 들었다 내려줍니다."},{"kind":"paragraph","text":"카이칸 피즈는 레시피 적으로는 단순히 ''우유가 들어간 진 피즈''로, 비주얼 적으로는 라모스 진 피즈의 그것을 떠올리게 합니다만, 맛 자체는 일반적인 진피즈에서 더 부드럽고, 실키한 느낌입니다."},{"kind":"paragraph","text":"약간은 칼피스 또는 밀키스를 살짝 떠올리게도 하는 맛."},{"kind":"paragraph","text":"칵테일에는 우유와 시트러스(레몬)이 들어가는 꽤나 특이한 조합을 하고 있는데, 이는 그닥 좋은 선택은 아닙니다. 레몬즙에는 산이 들어 있는데, 이 산이 우유 속 단백질을 응고시키게 되기 때문입니다."},{"kind":"paragraph","text":"게다가 만들어진 혼합물에 강한 탄산수를 확 부어버리면 거품이 순식간에 넘쳐버리기 때문에 탄산수를 따를 때에도 주의를 요해야 합니다."},{"kind":"paragraph","text":"이런 점들 때문에 카이칸 피즈는 꽤 만들기 까다로운 칵테일로 통하며, 개인적으로는 바텐더의 역량을 시험한다는 일반 진 피즈보다는 카이칸 피즈를 만드는 게 더 어렵다고 생각합니다."}]'::jsonb, 'published', '2025-02-15T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'kaikan-fizz' AND c.slug = 'kaikanfizz';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'sapporo-bar-farben', 'bar', '파벤 — 크래프트 칵테일을 즐길 수 있는 작고 소중한 바', '「바 파벤」은 삿포로 스스키노역 근처 한 빌딩의 6층에 위치한 바로, 오너 바텐더인 ''야자키 신(Yazaki Shin)'' 혼자서 운영하는 소규모의 바입니다.', '/articles/sapporo-bar-farben/00.webp',
  'https://blog.naver.com/shakinglikebartender/223752969062', false,
  '[{"kind":"figure","src":"/articles/sapporo-bar-farben/00.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/sapporo-bar-farben/01.webp","width":966,"height":1288},{"kind":"paragraph","text":"「바 파벤」은 삿포로 스스키노역 근처 한 빌딩의 6층에 위치한 바로, 오너 바텐더인 ''야자키 신(Yazaki Shin)'' 혼자서 운영하는 소규모의 바입니다."},{"kind":"paragraph","text":"''야자키 신''은 홋카이도 니세코의 ''바 규+(Bar Gyu+)'', 런던 등지에서 바텐더 생활을 한 후, 2024년 8월 6일 현재의 파벤을 오픈했다고 합니다. 제가 방문한 10월 말 기준으로는 오픈한 지 2달이 됐었네요."},{"kind":"paragraph","text":"저는 이전에 방문했던 ''아울&루스터(Bar Owl&Rooster)''에서 최근 생긴 괜찮은 바라고 추천받아서 방문하게 됐습니다."},{"kind":"figure","src":"/articles/sapporo-bar-farben/02.webp","width":966,"height":543},{"kind":"paragraph","text":"파벤은 메뉴나 백 바만 살짝 확인해도 위스키보다는 칵테일에 좀 더 중점을 둔 바이며, 진이나 오드비의 종류가 꽤 있는 바입니다. 추천해 줬던 아울&루스터처럼 믹솔로지적인 성향이 뚜렷한 느낌입니다."},{"kind":"figure","src":"/articles/sapporo-bar-farben/03.webp","width":966,"height":966},{"kind":"paragraph","text":"첫 잔은 역시 하이볼"},{"kind":"paragraph","text":"파벤에는 위스키의 종류가 그렇게 많은 편은 아닌데, 하이볼 기주로 주라 10년, 부나하벤 12년을 추천해 주셔서 주라로 한 잔 마셨습니다. 뭔들 맛없겠냐만, 개인적으로 주라 10년으로 만드는 하이볼을 꽤 좋아하는 편입니다."},{"kind":"figure","src":"/articles/sapporo-bar-farben/04.webp","width":966,"height":1288},{"kind":"paragraph","text":"파벤의 시그니처 칵테일들은 꽤 재미난 조합을 가지는 것들이 있는데, 그중 페어 앤 압생트 토닉(Pear and Absinthe Tonic)과 마스카포네 앤 커피 디저트 칵테일(Mascarpone and Coffee Dessert Cocktail)을 마셔봤습니다."},{"kind":"paragraph","text":"인상에 깊었던 「페어 앤 압생트 토닉」은 기주를 배로 만든 브랜디로 하고, 거기에 압생트·로즈 플라워 워터를 넣고, 토닉 워터에 탄산수를 넣는 소닉 스타일의 칵테일입니다."},{"kind":"paragraph","text":"아직 배로 만든 브랜디를 마셔본 적이 없어서 시켰는데, 호불호는 엄청나게 갈릴 것 같으면서도 아주 재미있는 맛으로, 플로럴 하면서도 상당히 섬세하다는 느낌을 받았습니다."},{"kind":"figure","src":"/articles/sapporo-bar-farben/05.webp","width":966,"height":1288},{"kind":"paragraph","text":"클래식 칵테일인 김렛도 마셔봤는데, 이전에 베키오에서 마셨던 것도 그렇고 확실히 삿포로의 칵테일은 다른 지역과는 맛이 다른 것 같습니다."},{"kind":"paragraph","text":"최근 몇 년간 유행해 온 하드 셰이킹을 하지 않고 만드는 것처럼 보이는데, 그래서 그런지 꽤나 쥬시하고, 맛이 강한 칵테일이 만들어집니다. 국내에서는 최근에 보기 힘든 스타일이라 오히려 신선한 느낌을 받았습니다."},{"kind":"paragraph","text":"백 바를 보다가 「닛카 코페이 진(Nikka Coffey Gin)」이 보였는데,  아무래도 홋카에도에 닛카의 증류소가 있기도 했고, 평소에 궁금하기도 해서 바로 진 토닉을 부탁드렸습니다."},{"kind":"paragraph","text":"이 닛카 코페이 진으로 만든 진 토닉도 정말 재밌었는데, 지금까지 제가 마셔봤던 진과는 꽤나 다른 유니크한 캐릭터를 가지고 있었고, 찌르는 듯한 시소 그리고 아마도 고수의 캐릭터가 꽤나 밝고 강렬하게 느껴지는 게 아주 상쾌한 진 토닉이었습니다."},{"kind":"figure","src":"/articles/sapporo-bar-farben/06.webp","width":966,"height":1288},{"kind":"paragraph","text":"저는 4박 5일의 일정 중에 3번을 파벤에 방문하면서 사장님이랑 친해지게 됐는데, 마지막 날이라 아쉬워하니 하쿠슈 미즈와리 한 잔과 타케츠루로 만든 롭로이(또는 맨하탄)의 변형을 서비스로 만들어주셨습니다. 조금 취했어서 한 잔만 서비스였나 기억이..."},{"kind":"paragraph","text":"타케츠루 마사타카가 지은 요이치 증류소가 있는 홋카이도에서 타케츠루로 만드는 칵테일이 작별 선물이라니, 정말이지 홋카이도의 바텐더라 할 수 있는 꽤나 운치 있는 선물이 아닐까 싶습니다."},{"kind":"figure","src":"/articles/sapporo-bar-farben/07.webp","width":966,"height":966},{"kind":"paragraph","text":"파벤에서의 좋았던 기억이 하나 더 있는데, 계산하고 나가기 전에 사장님이 바텐더스 핸드셰이크(Bartender''s Handshake)라고 하면서 페르넷 브랑카를 한 잔씩 꼭 주었던 점이었습니다."},{"kind":"paragraph","text":"이 바텐더스 헨드셰이크라는 게 일본에서는 잘 안 하는 서비스인데, 역시 서양 쪽 바 문화의 영향을 받았다는 걸 짐작해 볼 수 있네요."},{"kind":"paragraph","text":"파벤은 사장님 혼자서 운영하는 작은 바로, 처음 방문하더라도 은근하게 환영받는다는 느낌을 받았습니다. 아마 사장님이 영어도 가능하실 거라 일본어가 안되더라도 소통에 크게 문제는 없을 듯싶으니 가볍게 방문해서 한 잔 하는 것도 좋을 것 같습니다."}]'::jsonb, 'published', '2025-02-08T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'calvados-tonic', 'cocktail', '칼바도스 토닉 — 사과 캐릭터가 매력적인 간단한 탄산 칵테일', '「칼바도스 토닉」은 진 토닉처럼 이름 그대로 칼바도스라는 술에 토닉 워터를 넣어서 만들어주는 아주아주 간단한 칵테일입니다.', '/articles/calvados-tonic/00.webp',
  'https://blog.naver.com/shakinglikebartender/223750222811', false,
  '[{"kind":"figure","src":"/articles/calvados-tonic/00.webp","width":966,"height":966},{"kind":"heading","text":"About the Cocktail"},{"kind":"paragraph","text":"「칼바도스 토닉」은 진 토닉처럼 이름 그대로 칼바도스라는 술에 토닉 워터를 넣어서 만들어주는 아주아주 간단한 칵테일입니다."},{"kind":"paragraph","text":"여기서 ''칼바도스(Calvados)''란 브랜디의 일종으로, 사과(또는 배)를 발효해서 만든 시드르/사이더(Cidre/Cider)를 증류한 후 숙성을 해서 만들어지는 증류주입니다."},{"kind":"paragraph","text":"칼바도스는 프랑스 노르망디의 칼바도스라는 지역에서 수확하여 만들어져야 하는데, 「지역명 = 술 이름」이라는 점이 프랑스 꼬냑 지방의 브랜디인 ''꼬냑(Cognac)''과 비슷한 이치라 보면 되겠습니다."},{"kind":"paragraph","text":"칼바도스 또한 꼬냑처럼 AOC(원산지 명칭제)를 통하여 보호 및 관리 받고 있는데, 이를 바탕으로 「AOC 칼바도스(AOC Calvados)」, 「칼바도스 돔프롱테(calvados Domfrontais)」, 「칼바도스 페이도쥬(Calvados Pays d''Auge)」로 분류됩니다."},{"kind":"paragraph","text":"다시 칼바도스 토닉으로 돌아와서, 칼바도스는 꽤 달달한 사과의 캐릭터를 가지는 술로, 진토닉보다는 훨씬 달고 가볍게 마시기 좋은 칵테일입니다."},{"kind":"figure","src":"/articles/calvados-tonic/01.webp","width":966,"height":966},{"kind":"heading","text":"Recipe"},{"kind":"paragraph","text":"브랜드별로 다르겠지만, 토닉 워터는 생각보다 탄산감이 약합니다. 좀 더 탄산감을 원하신다면 소닉 스타일로 탄산수를 소량 추가해주는 걸 추천드립니다. 토닉 워터와 탄산수의 비율은 취향에 따라서 조절해주시면 되겠습니다."},{"kind":"figure","src":"/articles/calvados-tonic/02.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 긴 잔에 얼음을 채워줍니다."},{"kind":"paragraph","text":"2. 칼바도스(+비터)를 잔에 부어주고,"},{"kind":"paragraph","text":"살짝 스터해줍니다."},{"kind":"paragraph","text":"3. 토닉 워터(+탄산수)를 부어줍니다."},{"kind":"paragraph","text":"4. 바스푼으로 얼음을 살짝 들었다 놔줍니다."},{"kind":"paragraph","text":"5. 레몬 껍질에서 오일을 짜넣어주고,"},{"kind":"paragraph","text":"넣어줍니다."},{"kind":"paragraph","text":"칼바도스 토닉은 아주 간단한 칵테일이지만, 앙고스투라 비터를 넣어서 조금 더 풍부한 맛을 내게 하고, 토닉을 줄이고 탄산을 넣어서 탄산감을 높여준다거나 하는 식으로 디테일함을 더해 줄 수도 있습니다."},{"kind":"paragraph","text":"빈대로 칼바도스와 토닉 워터만 섞어서 간단하게 마시기에도 아주 훌륭한 칵테일입니다."},{"kind":"paragraph","text":"잔을 입으로 가져가면 먼저 향긋한 레몬과 달큰한 사과의 향이 나고, 맛은 보면 달달한 사과, 꿀, 토닉 워터의 약간은 쌉쌀함이 청량감 있게 느껴집니다."},{"kind":"paragraph","text":"칼바도스의 단맛과 토닉 워터의 쓴 맛이 절며하게 밸런스를 이루면서 청량감도 느껴지는 칵테일로, 개인적으로는 봄과 여름에 아주 잘 어울리는 칵테일이라 생각합니다."}]'::jsonb, 'published', '2025-02-06T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'calvados-tonic' AND c.slug = 'calvadostonic';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'sapporo-bar-atomic-age', 'bar', '아토믹 에이지 — 올드 보틀 위스키의 향연', '「바 아토믹 에이지」는 삿포로 스스키노역과 호스이스스키노역 근처에 위치한 바로, 유심히 찾아보지 않으면 입구를 놓치기 쉬운 특이한 구조의 바입니다. 저도 한참을 찾아 헤매다가 들어갔습니다.', '/articles/sapporo-bar-atomic-age/00.webp',
  'https://blog.naver.com/shakinglikebartender/223745150093', false,
  '[{"kind":"figure","src":"/articles/sapporo-bar-atomic-age/00.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/sapporo-bar-atomic-age/01.webp","width":966,"height":543},{"kind":"paragraph","text":"「바 아토믹 에이지」는 삿포로 스스키노역과 호스이스스키노역 근처에 위치한 바로, 유심히 찾아보지 않으면 입구를 놓치기 쉬운 특이한 구조의 바입니다. 저도 한참을 찾아 헤매다가 들어갔습니다."},{"kind":"figure","src":"/articles/sapporo-bar-atomic-age/02.webp","width":966,"height":543},{"kind":"paragraph","text":"아토믹 에이지는 백바에 올드 보틀이 줄지어 있는데, 위스키뿐만 아니라 럼·진·리큐르 등의 올드 보틀도 아주 많이 구비되어 있는 바입니다. 오히려 현행을 찾기가 힘든 느낌."},{"kind":"figure","src":"/articles/sapporo-bar-atomic-age/03.webp","width":966,"height":1287},{"kind":"figure","src":"/articles/sapporo-bar-atomic-age/04.webp","width":966,"height":1288},{"kind":"paragraph","text":"먼저 스카치의 올드 보틀을 마셨는데, 첫 잔은 추천을 부탁드렸는데 「80년대 링크우드 12년」을 추천해 주셨습니다. 아마도 무난하고 호불호가 안 갈릴 것 같은 캐릭터라 추천해 주신 듯. 맛도 모난 곳 없이 부드럽고 달큰했습니다."},{"kind":"paragraph","text":"다음으로 「모리슨 보모어 12년 덤피보틀」이 보이길래 가격을 여쭤보고 생각보다 싸서 주문을 했습니다. 개인적으로 현행 보모어와 비슷한 캐릭터가 많이 느껴진다고 하니 사장님도 현재의 모리슨이 이 시절의 맛을 따라가려 하고 있다고 맞장구를 치셨습니다."},{"kind":"paragraph","text":"마시면서 위스키 얘기를 하다가 로즈뱅크 이야기가 나오게 됐는데, 블렌디드 스카치인 「70년대의 하이랜드 넥타(Highland Nectar)」가 로즈뱅크와 탈리스커가 키몰트라고 하면서 추천해주시길래 바로 시켰습니다. 맛은 부드럽고 무난한 느낌."},{"kind":"figure","src":"/articles/sapporo-bar-atomic-age/05.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/sapporo-bar-atomic-age/06.webp","width":966,"height":1288},{"kind":"paragraph","text":"스카치를 마시는 중간에 사장님이 올드 버번이 그렇게 맛있다고 하시길래 하나 추천을 받았습니다. 「올드 크로우(Old Crow)」라는 버번인데 저는 처음 보는 버번이네요."},{"kind":"paragraph","text":"이 80년대의 올드 크로우는 힘이 많이 빠진 건지 원래 그런 맛인지는 모르겠지만 개인적으로 너무 맛이 비어있다고 생각되는 한 잔이었습니다. 이전에 80~90년대의 캐나디안 위스키를 마셨을 때 느꼈던 비는 맛..."},{"kind":"paragraph","text":"이것만 그런 건가 싶어서 도수가 높은 「올드 그랜드 대드 114」도 마셔봤는데, 현행과 꽤 비슷하지만 이것도 뭔가 힘이 빠졌달까 맛이 비었달까하는 굳이 싶은 맛이었습니다."},{"kind":"figure","src":"/articles/sapporo-bar-atomic-age/07.webp","width":966,"height":1288},{"kind":"paragraph","text":"위스키를 마시면서 백바를 보다가 적어도 80년대 이전에 유통된 「볼스(Bols)의 오렌지 큐라소」를 봐서 가격을 여쭤봤더니 조금 서비스를 주셔서 맛을 볼 기회가 있었습니다."},{"kind":"paragraph","text":"이 오렌지 큐라소가 현재의 오렌지 큐라소와는 전~혀 다른 느낌입니다. 훨씬 자연스러운 오렌지의 캐릭터에 더 당도가 있는 듯한 맛. 개인적으로 이건 니트로 마셔도 될 것 같은 맛이었습니다."},{"kind":"paragraph","text":"아토믹 에이지는 대부분의 보틀이 올드 보틀로, 올드 보틀을 좋아하시는 분이라면 꼭 한 번쯤은 삿포로에 가신다면 방문하는 걸 추천드릴만 한 바입니다."}]'::jsonb, 'published', '2025-02-02T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'sapporo-bar-the-hubris', 'bar', '휴브리스 — 한 잔 한 잔에 모든 정성을 다해서 만드는 칵테일', '「바 더 휴브리스」는 삿포로 스스키노역 근처 한 빌딩의 9층에 위치한 바로, 믹솔로지적인 성격이 아주 강한 바입니다.', '/articles/sapporo-bar-the-hubris/00.webp',
  'https://blog.naver.com/shakinglikebartender/223744357866', false,
  '[{"kind":"figure","src":"/articles/sapporo-bar-the-hubris/00.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/sapporo-bar-the-hubris/01.webp","width":966,"height":1288},{"kind":"paragraph","text":"「바 더 휴브리스」는 삿포로 스스키노역 근처 한 빌딩의 9층에 위치한 바로, 믹솔로지적인 성격이 아주 강한 바입니다. 저는 다른 바에서 추천을 받아서 알게 됐는데, 구글 리뷰에서 사진들을 보고 망설임 없이 찾아갔습니다."},{"kind":"figure","src":"/articles/sapporo-bar-the-hubris/02.webp","width":966,"height":543},{"kind":"paragraph","text":"백바에서도 바로 확인할 수 있듯이 진이 꽤 많이 갖춰져 있으며, 위스키가 어느 정도 있기는 하지만 아무래도 위스키를 좋아하는 분들을 만족시킬 정도의 가짓수는 아니라고 하겠습니다."},{"kind":"figure","src":"/articles/sapporo-bar-the-hubris/03.webp","width":966,"height":966},{"kind":"paragraph","text":"가장 먼저 메뉴에서 라벤더 진을 사용하는 칵테일이 보여서 바로 주문을 해봤습니다. 이 진은 홋카이도에서 생산되는 ''오호로(Ohoro)''라는 진의 한정판으로 나왔던 것으로, 현재에는 생산이 되지는 않아 구할 수 없다고 합니다."},{"kind":"paragraph","text":"칵테일의 이름은 「홋카이도 플로럴 사워(Hokkaido Floral Sour)」였는데, 이름에 걸맞게 플로럴함에 새콤달콤한 느낌으로 마시기에 부담스럽지 않은 칵테일이었습니다."},{"kind":"figure","src":"/articles/sapporo-bar-the-hubris/04.webp","width":966,"height":966},{"kind":"paragraph","text":"다음으로는 메뉴에서 타케츠루가 들어가는 에스프레소 마티니가 보여서 망설임 없이 주문했습니다. 아무래도 홋카이도다보니 닛카의 위스키를 사용하는 칵테일을 어렵지 않게 찾아볼 수 있습니다."},{"kind":"paragraph","text":"「타케츠루 에스프레소 마티니(Taketsuru Espresso Martini)」는 사실 에스프레소가 아니라 콜드브루를 쓰는데, 그래서 그런지 생각보다는 커피의 캐릭터가 엄청 강하지는 않습니다."},{"kind":"paragraph","text":"정확하게 맛이 기억이 나지는 않는데, 보드카로 만든 것 보다는 좀 더 복잡하고, 오렌지 비터로 인해서 살짝 시트러스한 캐릭터가 있었나....? 그치만 맛은 있었습니다."},{"kind":"paragraph","text":"제가 방문했을 때는 사장님 한 분만 계셨는데, 칵테일을 만들 때 한 잔 한 잔을 정말 정성스럽게 만든다는 느낌을 많이 받았고, 칵테일의 프레젠테이션이 꽤나 훌륭하다는 인상을 받았습니다."},{"kind":"paragraph","text":"앞서 얘기했듯이 위스키를 좋아하시는 분들보다는 칵테일을 좋아하는 분들에게 추천드릴 만 한 곳입니다."}]'::jsonb, 'published', '2025-02-01T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'negroni', 'cocktail', '네그로니 — 복잡하고 달콤쌉싸름한 매력', '1919년 피렌체에서 백작의 아메리카노를 진으로 바꿔 태어난 1:1:1의 클래식. 오렌지 껍질과 레몬 껍질 사이에서 표정이 바뀐다.', '/articles/negroni/00.webp',
  'https://blog.naver.com/shakinglikebartender/223742393163', false,
  '[{"kind":"figure","src":"/articles/negroni/00.webp","width":966,"height":966},{"kind":"heading","text":"About the Cocktail"},{"kind":"paragraph","text":"네그로니는 밀라노에서 탄생한 술인 ‘캄파리’와는 떼려야 뗄 수 없는 관계에 있으며, ‘밀라토-토리노 > 아메리카노 > 네그로니’와 같은 순서로 변형되어서 탄생되었다는 것이 가장 잘 알려져 있습니다."},{"kind":"paragraph","text":"1919년, 이탈리아 피렌체의 한 바에서 단골손님이었던 ‘네그로니 백작’이 자신의 아메리카노 칵테일(캄파리, 스윗 버무스, 탄산수)를 더 강하게 만들어 달라 요청하였고, 바텐더였던 포스코 스카셀리(Fosco Scarselli)는 탄산수를 진으로 변경하였습니다."},{"kind":"paragraph","text":"백작은 이를 매우 마음에 들어 했는데, 다른 손님들이 이후에 ‘네그로니 백작이 마신 술’을 주문하기 시작했고, 칵테일의 이름이 ‘네그로니’로 알려지게 되었습니다."},{"kind":"paragraph","text":"기본적으로 네그로니는 모든 재료를 1:1:1로 만드는 아주 간단한 구조로 이루어져 있으며, 이 때문인지 ‘불바디에(Boulevardier), 올드팔(Old Pal), 화이트 네그로니(White Negroni)’ 등의 변형이 상당히 많은 칵테일이고, 이러한 변형들을 통틀어서 네그로니 트리(Negroni Tree)라고 부르기도 합니다."},{"kind":"figure","src":"/articles/negroni/01.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"30ml 진(Gin)"},{"kind":"paragraph","text":"30ml 캄파리(Campari)"},{"kind":"paragraph","text":"30ml 스윗 버무스(Sweet Vermouth)"},{"kind":"paragraph","text":"가니시: 오렌지(또는 레몬) 껍질"},{"kind":"figure","src":"/articles/negroni/02.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 모든 재료를 락 잔에 넣어줍니다."},{"kind":"paragraph","text":"2. 얼음을 채우고, 스터를 해줍니다."},{"kind":"paragraph","text":"3. 잔 위로 오렌지 껍질을 짜서 오일을 뿌려줍니다."},{"kind":"paragraph","text":"4. 사용한 껍질을 다듬어서 잔에 넣어줍니다."},{"kind":"paragraph","text":"네그로니의 전통적인 비율은 1:1:1이지만, 최근에는 진을 늘리고 캄파리의 비율을 줄이는 등의 비율을 선호하는 바텐더들이 상당히 늘었습니다. 각자의 입맛에만 맞으면 되니, 맛을 봐가면서 각자의 비율을 찾아가는 재미도 있겠습니다."},{"kind":"figure","src":"/articles/negroni/03.webp","width":966,"height":966},{"kind":"paragraph","text":"잔을 입으로 가져다 대면 먼저 달큼한 오렌지의 향이 코에 닿고, 한 모금 마시게 되면 중심을 잡아주는 진과 함께 보타니컬함, 달큼한 오렌지와 와인 계열의 맛, 기분 좋을 정도의 캄파리의 쌉쌀함이 아주 복잡한 맛을 내게 됩니다."},{"kind":"paragraph","text":"가니시로 칵테일에 오일을 뿌려주는 시트러스로는 일반적으로 오렌지 껍질이 사용되지만, 레몬 껍질을 사용하기도 합니다."},{"kind":"paragraph","text":"이건 취향의 문제인데, 오렌지 껍질을 사용하면 캄파리에 있는 오렌지 캐릭터를 끌어올리면서도 묵직한 네그로니를 만들 수 있고, 레몬 껍질을 사용하면 화사한 캐릭터의 네그로니가 만들어집니다."},{"kind":"paragraph","text":"이런 특성에 따라서 취향껏 만들어 마실 수 있는데, 개인적으로는 더운 여름같이 묵직한 느낌은 부담스러우니 레몬 껍질을 이용한 네그로니를 선호하는 편입니다."}]'::jsonb, 'published', '2025-01-30T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'negroni' AND c.slug = 'negroni';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'sapporo-bar-owl-and-rooster', 'bar', '아울 앤 루스터 — 아마로, 진, 압생트 칵테일을 좋아한다면 여기로', '''바 아울 앤 루스터''는 삿포로 스스키노역 근처 한 빌딩의 6층에 위치한 바로, 위스키보다는 칵테일이 아주 집중한 바이며, 저처럼 칵테일 덕후들이라면 아주 환장을 할만한 바입니다.', '/articles/sapporo-bar-owl-and-rooster/00.webp',
  'https://blog.naver.com/shakinglikebartender/223740081893', false,
  '[{"kind":"figure","src":"/articles/sapporo-bar-owl-and-rooster/00.webp","width":966,"height":1288},{"kind":"paragraph","text":"''바 아울 앤 루스터''는 삿포로 스스키노역 근처 한 빌딩의 6층에 위치한 바로, 위스키보다는 칵테일이 아주 집중한 바이며, 저처럼 칵테일 덕후들이라면 아주 환장을 할만한 바입니다."},{"kind":"figure","src":"/articles/sapporo-bar-owl-and-rooster/01.webp","width":966,"height":543},{"kind":"figure","src":"/articles/sapporo-bar-owl-and-rooster/02.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/sapporo-bar-owl-and-rooster/03.webp","width":966,"height":1717},{"kind":"paragraph","text":"바는 바백에 진열되어 있는 보틀들을 보면 그 바의 성격을 유추할 수 있는데, 아울앤루스터에는 정말 많은 진과 아로마를 단번에 확인할 수 있고, 오른편으로 보면 압생트 분수 서브할 수 있는 유리병이 있습니다."},{"kind":"figure","src":"/articles/sapporo-bar-owl-and-rooster/04.webp","width":966,"height":1288},{"kind":"paragraph","text":"메뉴를 보면 바의 시그니처 메뉴들을 확인할 수 있는데, 이 메뉴들의 재료 설명만 봐도 칵테일 덕후들이 흥미로워할 만한 칵테일이 아주 많습니다."},{"kind":"figure","src":"/articles/sapporo-bar-owl-and-rooster/05.webp","width":966,"height":966},{"kind":"paragraph","text":"첫 번째 잔으로는 시그니처 중 하나인 압생트 초콜릿을 주문했습니다. 압생트와 초콜릿의 조합이라니 칵테일을 받기 전부터 떨리는 조합입니다."},{"kind":"paragraph","text":"의외로 압생트의 아니스, 허브 캐릭터가 초콜릿과 꽤 잘 어울린다는 느낌을 받았고, 압생트나 파스티스를 좋아하는 분들에게는 추천할 만한 한 잔입니다."},{"kind":"figure","src":"/articles/sapporo-bar-owl-and-rooster/06.webp","width":966,"height":966},{"kind":"paragraph","text":"다음 잔으로는 샘 로스의 유명 칵테일인 페니실린을 변형한 아크틱 페니실린(Arctic Peniciline)을 주문했는데, 재료만 봐서는 정말 이게 페니실린 싶은 생각이 듭니다."},{"kind":"paragraph","text":"홋카이도에 위치한 요이치 증류소의 위스키를 사용하는데, 아마 그런 이유로 이름을 이렇게 짓지 않았을까 싶습니다."},{"kind":"paragraph","text":"색깔부터 페니실린이라고는 믿기지 않는 비주얼인데, 맛을 보면 모든 사람들이 납득할 수 있을 정도로 페니실린이 맞습니다."},{"kind":"paragraph","text":"기본적인 페니실린 구조의 맛에 베리 등의 캐릭터가 추가된 느낌이며, 설명에 스파이시라고 쓰여 있긴 했는데, 저는 개인적으로 그 부분은 크게 느끼진 못했습니다."},{"kind":"figure","src":"/articles/sapporo-bar-owl-and-rooster/07.webp","width":966,"height":966},{"kind":"paragraph","text":"마지막으로는 평소에 궁금했었던 그랑 클라시코(Gran Classico Bitter)가 눈에 띄어서 이걸로 칵테일을 한 잔 만들어달라고 부탁드렸습니다."},{"kind":"paragraph","text":"네그로니 류의 칵테일을 만들어주셨는데, 아마 메뉴의 럼 네그로니를 만들어주신 것 같습니다. 아주 깊고, 초콜레틱한 느낌의 네그로니로 아주 맛있게 마셨습니다. 캄파리 네그로니보다 맛있는 듯"},{"kind":"paragraph","text":"아울 앤 루스터는 전형적인 일본의 오센틱 바라기보다는 좀 더 믹솔로지 스타일에 가까운 바로, 시그니처와 클래식 변형 칵테일이 아주 돋보입니다."},{"kind":"paragraph","text":"칵테일, 아마로, 압생트, 진 등에 관심이 있는 분들에게 아주아주 강추드리며, 개인적으로 이곳에서는 클래식 보다 시그니처 위주로 마셔보는 걸 추천드립니다."}]'::jsonb, 'published', '2025-01-27T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'sapporo-bar-proof', 'bar', '바 프루프 — 시간이 멈춰 있는 것만 같은, 올드 보틀을 이용한 칵테일', '''바 프루프''는 삿포로 스스키노역 근처 한 빌딩의 5층에 위치한 바로, 이전에 리뷰했던 나노 펨토(Bar nano femto)와 같은 건물에 위치해 있습니다.', '/articles/sapporo-bar-proof/00.webp',
  'https://blog.naver.com/shakinglikebartender/223734088668', false,
  '[{"kind":"figure","src":"/articles/sapporo-bar-proof/00.webp","width":966,"height":1718},{"kind":"figure","src":"/articles/sapporo-bar-proof/01.webp","width":966,"height":543},{"kind":"figure","src":"/articles/sapporo-bar-proof/02.webp","width":966,"height":543},{"kind":"paragraph","text":"''바 프루프''는 삿포로 스스키노역 근처 한 빌딩의 5층에 위치한 바로, 이전에 리뷰했던 나노 펨토(Bar nano femto)와 같은 건물에 위치해 있습니다. 이 날은 나노 펨토가 만석이여서 프루프를 방문했었습니다."},{"kind":"paragraph","text":"이 곳 프루프는 나이가 지긋한 사장님이 직접 메이킹을 해주시는데, 특이하게도 80~90년대의 올드 보틀으로 대부분의 칵테일을 만든다고 하십니다."},{"kind":"paragraph","text":"여담으로 일본에는 아직까지도 80~90년대의 위스키, 꼬냑, 리큐르들을 쉽게 찾을 수 있는 편인데, 아마 산토리의 존재와 일본의 버블 호황기로 인해 그러지 않을까 짐작해봅니다."},{"kind":"figure","src":"/articles/sapporo-bar-proof/03.webp","width":966,"height":1288},{"kind":"paragraph","text":"첫 잔은 하이볼"},{"kind":"paragraph","text":"대부분의 칵테일에 올드 보틀을 사용한다는 설명이 무색하게 하이볼은 현행 글렌리벳 12년으로 만들어주셨는데, 무난하게 맛있었습니다."},{"kind":"paragraph","text":"다음 잔으로는 여행 당시에 빠져 있었던 ''러스티 네일(Rusty Nail)''을 주문했는데, 이건 듀어스의 올드 보틀과 드람부이의 올드 보틀로 만들어주셨습니다."},{"kind":"paragraph","text":"듀어스인데도 불구하고 위스키의 캐릭터가 죽지 않고, 드람부이와 적절한 밸런스를 이뤘던 게 인상적이 었습니다."},{"kind":"figure","src":"/articles/sapporo-bar-proof/04.webp","width":966,"height":966},{"kind":"figure","src":"/articles/sapporo-bar-proof/05.webp","width":966,"height":966},{"kind":"paragraph","text":"다음 잔을 주문하려고 백바를 둘러보니 멀리서 서던 컴포트의 올드 보틀이 보이길래 바로 ''스칼렛 오하라(Scarlett O''Hara)''를 주문했습니다."},{"kind":"paragraph","text":"서던 컴포트는 원래 40도가 넘는 리큐르였는데, 세월이 지나면서 도수가 떨어지면서 맛이 변했다는 얘기가 있었어서 항상 궁금했었습니다. 현재에 국내에 35도의 제품이 일반적으로 들어오고 있습니다."},{"kind":"paragraph","text":"자극적이고 새콤달콤한 한 잔이라는 말로 정리될 수 있는데, 단 걸 그렇게 좋아하지 않는 저도 아주아주 맛있었습니다."},{"kind":"figure","src":"/articles/sapporo-bar-proof/06.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/sapporo-bar-proof/07.webp","width":966,"height":1288},{"kind":"paragraph","text":"올드 보틀로 마시는 김에 한 잔 더 마시자고 해서 시킨 ''사이드카(Sidecar)''. 코앵트로와 꼬냑 모두 80년대의 것이었는데, 특이한 건 프라팡 VSOP를 사용한다는 점이었습니다."},{"kind":"paragraph","text":"지금의 프라팡은 좀 섬세하고 여리여리한 면이 있어서 칵테일의 기주로 사용되는 경우를 본 적이 없는데, 80년대 프라팡을 니트로 마셔보지는 않았지만 현행과는 맛이 다른지 전혀 위화감이 없었습니다."},{"kind":"paragraph","text":"프루프는 올드 보틀으로 칵테일을 메이킹하는 것에 비해서 가격이 그닥 비싸지는 않은데, 올드 보틀 칵테일에 관심이 있는 분들에게는 꼭 추천해드리고 싶습니다."},{"kind":"paragraph","text":"다만, 접객에 있어서는 고객과 살짝 거리를 두는 듯한 이미지로, 딱 필요한 정도의 접객을 제공하는 곳이니 막 살갑게 말을 붙여주는 바를 선호하신다면 살짝 소외감을 느낄 수도 있겠습니다."}]'::jsonb, 'published', '2025-01-22T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'bar-yamazaki', 'bar', '바 야마자키 — 삿포로 칵테일이 태어난 노포', '1958년에 문을 연 스스키노의 노포. 1972년 동계 올림픽을 기념해 만든 시그니처 칵테일 "삿포로"가 아직 그 자리에 있다.', '/articles/bar-yamazaki/00.webp',
  'https://blog.naver.com/shakinglikebartender/223725716667', false,
  '[{"kind":"figure","src":"/articles/bar-yamazaki/00.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/bar-yamazaki/01.webp","width":966,"height":544},{"kind":"paragraph","text":"''바 야마자키''는 삿포로 스스키노역 근처 한 빌딩의 4층에 위치한 바로, 1958년에 창업하여 오픈한지 60년이 넘은 아주 오래된 노포입니다."},{"kind":"paragraph","text":"물론 일본의 유명한 동명의 위스키와는 관계 없으며, 바의 이름은 창업자인 ''야마자키 타츠로''님의 성에서 따온 것입니다. 90대까지 바에서 손님들을 맞았다고 하며, 2016년에 96세의 나이로 작고하셨다고 합니다."},{"kind":"paragraph","text":"이 곳에서는 ''삿포로''라는 이름의 시그니처 칵테일이 있는데, 1972년 삿포로 동계 올림픽을 기념하기 위해 개발됐으며, 이후 1981년에는 제네바에서 개최된 국제 칵테일 대회에서 특별상을 수상했다고 하는, 이 바의 아이덴티티와 같은 칵테일입니다."},{"kind":"figure","src":"/articles/bar-yamazaki/02.webp","width":966,"height":966},{"kind":"paragraph","text":"야마자키를 가기 전날에 하이볼만 계속 마셔서 이 날은 진 토닉을 주문했었습니다. 오센틱 바에서 이렇게 빨대와 함께 나오는 걸 처음 보는데, 이 바가 얼마나 오래 됐는지를 엿볼 수 있는 부분이 아닐까 싶습니다."},{"kind":"paragraph","text":"맛 자체는 스탠다드한 진토닉에서 살짝 라임맛이 좀 더 많이 나는 느낌이었습니다. 아마 라임 즙의 양이 좀 많은 느낌."},{"kind":"figure","src":"/articles/bar-yamazaki/03.webp","width":966,"height":966,"caption":"삿포로(Sapporo) 칵테일"},{"kind":"heading","text":"드디어 마셔보는 이 날의 목적"},{"kind":"paragraph","text":"삿포로 칵테일에는 보드카를 기주로 해서 아마레또, 그린 샤르트뢰즈, 드라이 베르무트가 들어가는 특이한 조합의 칵테일입니다."},{"kind":"paragraph","text":"개인적으로 샤르트뢰즈의 캐릭터가 너무 강해서 아마레또나 베르무트의 캐릭터는 잘 느껴지지 않았습니다. 샤르트뢰즈를 좋아하기는 하는데, 캐릭터가 너무 강하다보니 제가 받은 잔은 좀 실망스러웠습니다."},{"kind":"paragraph","text":"삿포로 칵테일에 대한 얘기를 직원 분들과 하다가 최근 샤르트뢰즈의 수급이 힘들지 않냐 물어봤는데, 본인들은 이 삿포로 칵테일의 존재 때문에 샤르트뢰즈 그린 수급에 대해서 전혀 걱정이 없다고 합니다. (아마 수입사에서 수급을 잘 해주는 듯?)"},{"kind":"paragraph","text":"여담으로 어느 바인지는 밝히지 못하지만, 야마자키가 최근 몇 년 사이에 좋지 못한 평을 받고 있다고 하는 얘기를 제가 갔던 삿포로의 몇몇 바에서 얘기해 주었습니다. 그 원인으로 많은 직원들이 이탈했다고..."},{"kind":"paragraph","text":"그래도 여전히 삿포로의 바를 대표하는 역사가 오래된 바 중 하나로, 이 삿포로 칵테일을 마셔보러 갈 만한 가치가 있다고 생각됩니다."}]'::jsonb, 'published', '2025-01-14T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'stay-up-late', 'cocktail', '스테이 업 레이트 — 화려한 느낌의 진 피즈', '''스테이 업 레이트''는 미국의 언론인이자 작가였던 루시우스 비비(Lucius Beebe)가 1946년에 집필한 저서인 ''스토크 클럽 바 북(The Stork Club Bar Book)''의 부록에 실린 칵테일입니다.', '/articles/stay-up-late/00.webp',
  'https://blog.naver.com/shakinglikebartender/223714417131', false,
  '[{"kind":"figure","src":"/articles/stay-up-late/00.webp","width":966,"height":966},{"kind":"heading","text":"About the Cocktail"},{"kind":"paragraph","text":"''스테이 업 레이트''는 미국의 언론인이자 작가였던 루시우스 비비(Lucius Beebe)가 1946년에 집필한 저서인 ''스토크 클럽 바 북(The Stork Club Bar Book)''의 부록에 실린 칵테일입니다."},{"kind":"paragraph","text":"이 ''스토크 클럽''은 1929~1965까지 운영되던 뉴욕 맨해튼의 유명했던 나이트클럽으로, 운영 당시 많은 유명인이 찾았던 클럽이라고 합니다."},{"kind":"paragraph","text":"재밌는 점은 이 ''스토크 클럽 바 북의 부록''은 스토크 클럽의 스태프들을 취재하여 추가한 칵테일 리스트로, 이 칵테일은 클럽의 모자 관리 부서의 ''베로니카 해롤드(Veronica Harrold)''에 의하여 추가되었다고 합니다."},{"kind":"paragraph","text":"그녀가 만든 칵테일인지는 알 수는 없지만, 나이트클럽과 정말 잘 어울리는 작명이라 할 수 있겠네요."},{"kind":"figure","src":"/articles/stay-up-late/01.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"왼쪽의 레시피는 제가 조정한 레시피이고, 원래 오리지널 레시피는 비율이 꽤 다른 편입니다. 혹시 비교해보실 분들을 위해 오리지널 레시피를 같이 첨부해두겠습니다."},{"kind":"figure","src":"/articles/stay-up-late/02.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 탄산수를 제외한 재료를 셰이커에 넣어줍니다."},{"kind":"paragraph","text":"2. 셰이커에 얼음을 채우고, 셰이킹해줍니다."},{"kind":"paragraph","text":"3. 긴 잔에 얼음을 채우고, 셰이커에서 부어줍니다."},{"kind":"paragraph","text":"4. 탄산수를 적당량 부어줍니다."},{"kind":"paragraph","text":"5. 얼음을 위아래로 살짝 들었다 놔줍니다."},{"kind":"paragraph","text":"6. 레몬 껍질에서 오일을 짜주고,"},{"kind":"paragraph","text":"잘 다듬어서 넣어줍니다."},{"kind":"paragraph","text":"스테이 업 레이트는 구조 자체는 진피즈에 꼬냑을 살짝 더해준 것인데, 마치 사이드카와 진 피즈를 매시업한 것 같은 맛으로, 꽤나 화려한 느낌의 진 피즈라 할 수 있을 것 같습니다."},{"kind":"paragraph","text":"서양에서는 톰 콜린스의 변형이라 보고 있는데, 아마 서양에서는 진 피즈에 계란 흰자를 사용하는 게 일반적이여서 그런 것 같습니다."},{"kind":"paragraph","text":"사용하는 주류의 종류가 꽤나 중요할 것 같은 맛인데, 제가 만든 건 레미 마틴의 시트러시함과 달달한 꼬냑의 카라멜 느낌이 도드라지고, 마지막에 탱커레이 넘버 텐의 후추 같은 향신료가 킥을 줍니다."},{"kind":"paragraph","text":"개인적으로 이 칵테일을 좋아하는 이유는 진과 꼬냑을 함께 사용하는 재밌는 조합도 있지만, 유자가 전혀 들어가진 않지만 뭔가 유자청 같은 맛을 만들어낸다는 점으로, 한 번쯤은 마셔보시는 걸 추천드립니다."}]'::jsonb, 'published', '2025-01-04T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'stay-up-late' AND c.slug = 'stayuplate';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'sapporo-bar-brora', 'bar', '브로라 — 얼큰하게 취한 사장님이 반겨주는 바', '''바 브로라''는 삿포로 스스키노역 근처 한 빌딩의 3층에 위치해 있는 바로, 사장님이 혼자서 운영하는 곳인데, 몇몇 블로그나 리뷰에서도 볼 수 있듯이 사장님이 기분이 좋으면 손님 응대를 하면서 술을 마셔 취하는 특이한 바입니다.', '/articles/sapporo-bar-brora/00.webp',
  'https://blog.naver.com/shakinglikebartender/223708461782', false,
  '[{"kind":"figure","src":"/articles/sapporo-bar-brora/00.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/sapporo-bar-brora/01.webp","width":966,"height":543},{"kind":"paragraph","text":"''바 브로라''는 삿포로 스스키노역 근처 한 빌딩의 3층에 위치해 있는 바로, 사장님이 혼자서 운영하는 곳인데, 몇몇 블로그나 리뷰에서도 볼 수 있듯이 사장님이 기분이 좋으면 손님 응대를 하면서 술을 마셔 취하는 특이한 바입니다."},{"kind":"figure","src":"/articles/sapporo-bar-brora/02.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/sapporo-bar-brora/03.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/sapporo-bar-brora/04.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/sapporo-bar-brora/05.webp","width":966,"height":1717},{"kind":"paragraph","text":"이곳 브로라는 백바가 꽤 볼만한데, 처음 보는 보틀이 정말 많았고, 특히 레이디번(Ladyburn)의 오피셜 보틀은 여기서 처음 봤습니다."},{"kind":"paragraph","text":"일단은 하이볼부터"},{"kind":"paragraph","text":"첫 잔으로 당연히(?) 하이볼을 부탁드렸는데, 아유 그러면 역시 벤로막이지 하고는 바로 앞에 있는 엄청 큰 사이즈의 벤로막(Benromach) 10년으로 만들어주셨습니다."},{"kind":"paragraph","text":"그렇게 크게 기억나는 맛은 아니었기는 한데, 무난무난하게 괜찮은 하이볼이었던 것 같습니다. 뭔가 이 보틀에 대해서 자랑을 하셨는데, 내용은 기억이 안나네요."},{"kind":"figure","src":"/articles/sapporo-bar-brora/06.webp","width":966,"height":1288},{"kind":"paragraph","text":"하이볼을 마시면서 사장님과 스코틀랜드에 갔다 온 얘기를 하다가 스프링뱅크 중에서는 헤이즐번을 좋아한다고 하니 헤이즐번(Hazelburn) 핸드필을 추천해주셨습니다."},{"kind":"paragraph","text":"맛은 이번 삿포로 여행 중에 가장 별로였던 위스키였던...이와 별개로 저는 개인적으로 스프링뱅크 증류소의 핸드필은 일본에서 잔에 2만원이 넘어간다면 그다지 추천드리지는 않을 것 같습니다."},{"kind":"paragraph","text":"일단 스프링뱅크 증류소에서의 가격에 비해서 너무 뻥튀기가 되어있는데다가, 증류소에 가보니 캐스크에서 바로 뽑아주는 핸드필이 아니라 여러 원액을 배팅한 것을 보틀링해주는 걸 봤어서 일정 가격 이상이면 굳이 싶습니다."},{"kind":"figure","src":"/articles/sapporo-bar-brora/07.webp","width":966,"height":1288},{"kind":"paragraph","text":"계속되는 나 홀로 아드벡 데이"},{"kind":"paragraph","text":"다음 잔으로는 무카와에서 보고 궁금했었던 아드벡(Ardbeg) 독립병입된 보틀을 마셔봤습니다. 이 시리즈는 일본의 위스키 수입사인 루더(The Ultimate Spirits Rudder Ltd)의 첫 독립병입 시리즈인 ''Art Session''의 첫 번째 릴리즈라 합니다."},{"kind":"paragraph","text":"타는 듯한 피트감이 꽤 강하고, 살짝의 달달함+시트러스의 캐릭터를 느낄 수 있었는데, 다른 캐릭터를 더 느끼기에는 피트감이 조금 거슬렸던 것 같습니다."},{"kind":"paragraph","text":"마시면서 사장님과 이런저런 얘기도 하고, 같이 짠도 하기도 하고, 꽤나 재미있게 즐겼습니다."},{"kind":"paragraph","text":"개인적으로 이 곳은 일본어 소통이 어느정도 되시는 분들이나, 위스키를 좋아하시고 가격에 대해서도 어느정도 파악이 쉬운 분들에게 추천을 드리고 싶습니다. 이 곳의 가격이 저렴한 편은 아니기도 하니까요."},{"kind":"paragraph","text":"※주의점?"},{"kind":"paragraph","text":"이 곳 리뷰를 보면서 ''혐한''이라는 리뷰를 하나 봤는데, 제가 한국인이라 밝히면서 한국 얘기도 조금 했는데 저는 그런 느낌은 못 받았던 것 같습니다."},{"kind":"paragraph","text":"다만, 본인이 일본어 소통이 어려우신 분들은 가게의 단골이 있을 때 가신다면 살짝 소외된 느낌을 느끼실 수는 있을 것 같습니다. 사장님이 취하시면 텐션이 올라가니 아무래도 접객에 갭 차이가 있을 수 밖에 없겠죠."},{"kind":"paragraph","text":"또한, 사장님이 술을 마시면서 접객을 하는 경우가 왕왕 있는 것 같은데, 그런 분위기를 선호하지 않는 분들에게는 그다지 추천드리지는 못하겠습니다."}]'::jsonb, 'published', '2024-12-29T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'sapporo-bar-brownie', 'bar', '브라우니 — 스스키노역 근처 지하에 숨어 있는 깔끔한 매력의 몰트바', '''바 브라우니''는 홋카이도의 오비히로에 본점을 둔 바로, 이곳 삿포로 스스키노역 근처에 있는 브라우니는 분점에 해당합니다.', '/articles/sapporo-bar-brownie/00.webp',
  'https://blog.naver.com/shakinglikebartender/223707726678', false,
  '[{"kind":"figure","src":"/articles/sapporo-bar-brownie/00.webp","width":966,"height":966},{"kind":"paragraph","text":"''바 브라우니''는 홋카이도의 오비히로에 본점을 둔 바로, 이곳 삿포로 스스키노역 근처에 있는 브라우니는 분점에 해당합니다. 제가 10월에 갔을 때는 오픈한 지 며칠 되지 않았다고 하며, 실제로 구글 맵에도 표시되지 않았던 걸로 기억합니다."},{"kind":"paragraph","text":"그런 곳을 어떻게 방문했냐하면, 근처의 샷 바 베키오(Shot Bar Vecchio)에서 추천을 받아서 방문했습니다."},{"kind":"paragraph","text":"사실 이번 삿포로 바 투어는 일단 찾아놓은 바를 갔다가 거기서 추천을 받고 즉흥적으로 갔던 곳이 꽤 있었는데, 브라우니는 그중 하나였습니다."},{"kind":"figure","src":"/articles/sapporo-bar-brownie/01.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/sapporo-bar-brownie/02.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/sapporo-bar-brownie/03.webp","width":966,"height":1717},{"kind":"paragraph","text":"브라우니의 특징은 우리가 흔하게 생각할 만한 아주 깔끔한 일본의 몰트바의 전형이라 할 수 있는데, 개인적으로 제가 일본에서 가 본 바들 중에서 가장 단정하고 깔끔한 인상을 받았습니다."},{"kind":"figure","src":"/articles/sapporo-bar-brownie/04.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/sapporo-bar-brownie/05.webp","width":966,"height":1288},{"kind":"paragraph","text":"일단 첫 잔으로 아묻따 하이볼."},{"kind":"paragraph","text":"개인적으로 하이볼은 와인류의 캐스크를 사용한 건 그렇게 좋아하지 않아서 버번 캐스크를 사용한 하이볼을 요청드렸는데, 글렌 알라키 버번캐스크로 만들어주셨습니다. 개인적으로 팥 같은 캐스크의 캐릭터가 좀 강해서 불호..."},{"kind":"figure","src":"/articles/sapporo-bar-brownie/06.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/sapporo-bar-brownie/07.webp","width":966,"height":1288},{"kind":"paragraph","text":"그리고 끝나지 않는 나 홀로 아드벡 데이."},{"kind":"paragraph","text":"이날 더 위스키 테이스팅 룸에서 아일라 스폰지를 못 사서 화풀이 마냥 세 곳의 바에서 아드벡을 엄청나게 마셨는데, 브라우니에서 마셨던 아드벡은 모두 맛있었습니다."},{"kind":"paragraph","text":"독립병입이었던 몰트만(Maltman)의 킬달튼 10년은 셰리캐스크였는데, 이거 가격도 괜찮고 모닥불같이 타는 듯한 피트감과 베리류, 크리미함, 베이컨과 같은 캐릭터로 맛도 아주 좋았어서 아드벡을 좋아하시는 분이라면 꼭 추천하고 싶습니다."},{"kind":"paragraph","text":"아드벡 싱글캐스크 같은 경우는 바테이블에 놓여있길래 ''싱글캐스크 + 세컨 필 꼬뜨 로띠 와인 캐스크''에 혹해 궁금해서 한 번 마셔봤는데, 정확한 맛까지는 기억이 안 나지만 우아한 캐릭터의 아드벡으로 한참 향을 맡았던 기억이 있습니다."},{"kind":"paragraph","text":"제가 갔던 날에는 점장님(?)의 아는 분들이 오셨는지 그렇게 얘기를 많이 나누지는 못했는데, 그래도 기본적으로 응대가 꽤 나이스했고, 위스키 라인업도 상당히 좋아서 일본에서 몰트바를 찾는 분들에게 특히 추천드립니다."}]'::jsonb, 'published', '2024-12-28T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'sapporo-shot-bar-vecchio', 'bar', '샷 바 베키오 — 더 위스키 테이스팅 룸에서 여기까지 왔다!', '''샷 바 베키오(Shot Bar Vecchio)''는 삿포로 시내 스스키노역 근처 빌딩의 7층에 위치한 바로, 이전에 소개한 바틀샵 ''더 위스키 테이스팅 룸(The Whisky Tasting Room)''의 점장이자, 일본의 주류 수입회사인 스카치 몰트', '/articles/sapporo-shot-bar-vecchio/00.webp',
  'https://blog.naver.com/shakinglikebartender/223706937101', false,
  '[{"kind":"figure","src":"/articles/sapporo-shot-bar-vecchio/00.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/sapporo-shot-bar-vecchio/01.webp","width":966,"height":544},{"kind":"figure","src":"/articles/sapporo-shot-bar-vecchio/02.webp","width":966,"height":1717},{"kind":"paragraph","text":"''샷 바 베키오(Shot Bar Vecchio)''는 삿포로 시내 스스키노역 근처 빌딩의 7층에 위치한 바로, 이전에 소개한 바틀샵 ''더 위스키 테이스팅 룸(The Whisky Tasting Room)''의 점장이자, 일본의 주류 수입회사인 스카치 몰트 판매 주식회사의 일원이자, 홋카이도 바텐더 협회의 회장님이 운영하는 바입니다."},{"kind":"paragraph","text":"워낙 겸임하는 게 많으셔서 이 분한테서 명함을 서너 장은 받은 것 같습니다."},{"kind":"paragraph","text":"메뉴는 따로 없는 것 같고, 역시 스카치 몰트 판매 주식회사에서 수입하는 위스키 스폰지(Whisky Sponge)의 시리즈라던가, 병입하는 더 테이스터(The Taster)의 시리즈 등이 눈에 띕니다."},{"kind":"figure","src":"/articles/sapporo-shot-bar-vecchio/03.webp","width":966,"height":1288},{"kind":"paragraph","text":"사실 더 위스키 테이스팅 룸을 거쳐서 여기까지, 아니 삿포로까지 오게 된 계기는 이 녀석입니다."},{"kind":"paragraph","text":"''아일라 스폰지 킬달튼(Islay Sponge Kildalton)''"},{"kind":"paragraph","text":"독립병입 위스키인 위스키 스폰지의 시리즈 중에 하나로, 독병으로는 일본에서도 드물게 아드벡 증류소의 원액 중에서도 셰리 캐스크에서 숙성한 제품입니다."},{"kind":"paragraph","text":"스코틀랜드에서 마시고 정말 맛있어서 여기저기 찾아보고 있다가 올해 7월(?)까지는 더 위스키 테이스팅 룸에 있다는 걸 확인하고, 재취업이 결정되자마자 삿포로행 티켓을 끊었는데...."},{"kind":"paragraph","text":"더 위스키 테이스팅 룸에서 수입하고 얼마 안 돼서 다 팔렸다는 얘기를 듣고, 지푸라기라도 잡는 심정으로 사실은 점장님의 바인 베키오를 찾아온 거였는데, 드디어 이렇게 만나게 됐습니다."},{"kind":"paragraph","text":"가격은 원가를 생각하면 너~~무 비싸니, 정말 궁금한 분들만 드시는 걸 추천드립니다. 저는 가격 때문에 하프로만 마신.... 그래도 맛은 확실합니다."},{"kind":"figure","src":"/articles/sapporo-shot-bar-vecchio/04.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/sapporo-shot-bar-vecchio/05.webp","width":966,"height":1288},{"kind":"paragraph","text":"일본 각지에서는 진(Gin), 럼 등을 생산하는 곳이 정말 많은데, 홋카이도에도 위스키 증류소 이외에 진 증류소가 꽤 있습니다."},{"kind":"paragraph","text":"그래서 홋카이도의 진으로 진 토닉을 추천해달라고 부탁드렸는데, 오호로(Ohoro)라는 진으로 토닉과 탄산수의 양을 반반으로 해서 만들어주셨습니다. 아마도 진의 캐릭터를 좀 더 느낄 수 있게 하려고 해서인 것 같습니다."},{"kind":"figure","src":"/articles/sapporo-shot-bar-vecchio/06.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/sapporo-shot-bar-vecchio/07.webp","width":966,"height":1288},{"kind":"paragraph","text":"그 외에도 사장님과 이런저런 얘기를 하다가 올해 스코틀랜드를 갔다 온 이후로 브룩라디를 좋아하게 됐다는 얘기를 하게 됐고, 의식의 흐름으로 하이볼 한 잔과 위스키 한 잔을 추천받아서 마셨습니다."},{"kind":"paragraph","text":"독립병입자인 엘리먼츠 오브 아일라(Elements of Islay) 시리즈 중에서 브룩라디의 다섯번째 배치로, 이 시리즈는 라벨을 보면 증류소의 이름을 유추할 수 있게 해두었습니다. 하이볼로 마시니 아주 기똥차네요."},{"kind":"paragraph","text":"마지막으로 일본 위스키 수입 회사인 스카치 몰트 판매 주식회사의 독립병입 시리즈인 더 테이스터(The Taster) 중에서도 브룩라디를 추천해 주셔서 한 잔 마셨습니다. 이건 향긋한 풀 내음+벌꿀의 캐릭터가 꽤나 인상적인 한 잔이었습니다."},{"kind":"paragraph","text":"이 테이스터 시리즈는 일본의 주류 애호가가 선택한 배럴을 보틀링 한 것으로, 일본에서는 꽤 인기가 있는 건지 찾아보면 대부분 품절이거나 물량을 찾기가 쉽지 않을 정도이니 눈에 띄면 한 번 정도는 마셔볼만합니다."},{"kind":"paragraph","text":"베키오는 칵테일보다는 위스키를 주로 드시는 분들께 추천드리고 싶은 바로, 더 위스키 테이스팅 룸에 들렀다가 가보는 건 어떨까 싶습니다."}]'::jsonb, 'published', '2024-12-27T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'springbank-distillery-tour', 'spirits', '스프링뱅크 증류소 투어 — 술 기행의 종착점', '회사를 그만두고 친구를 끌고 아일라를 거쳐 캠벨타운까지. 스코틀랜드 위스키 여행의 마지막 목적지에서 남긴 기록.', '/articles/springbank-distillery-tour/00.webp',
  'https://blog.naver.com/shakinglikebartender/223694261963', false,
  '[{"kind":"figure","src":"/articles/springbank-distillery-tour/00.webp","width":966,"height":1288},{"kind":"paragraph","text":"스프링뱅크 증류소 샵을 들렀다가 건너편의 워시백 바에서 위스키를 마시다보니 어느새 증류소 투어를 할 시간이 왔다. 증류소 투어는 꼭 홈페이지에서 예약하고 가자."},{"kind":"figure","src":"/articles/springbank-distillery-tour/01.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/springbank-distillery-tour/02.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/springbank-distillery-tour/03.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/springbank-distillery-tour/04.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/springbank-distillery-tour/05.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/springbank-distillery-tour/06.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/springbank-distillery-tour/07.webp","width":966,"height":1288},{"kind":"paragraph","text":"스프링뱅크의 증류소 투어는 몰팅하는 것부터 발효, 증류의 과정을 쭉 설명해주는 식으로 이루어지며, 제가 기억하기로는 특히 자사의 플로어 몰팅과 맥아에 대해서 꽤 공들여서 설명해주는 듯한 인상이었다."},{"kind":"paragraph","text":"사실 증류소를 방문한지 너무 오래됐기도 했고, 가이드를 해주신 직원의 억양이 상당히 강했어서 내용 자체는 그렇게 자세하게 기억나지는 않지만, 여느 증류소 투어에서나 나던 특유의 맥주향 비슷한 시큼한 발효향의 기억은 여전히 기억이 난다."},{"kind":"figure","src":"/articles/springbank-distillery-tour/08.webp","width":966,"height":544},{"kind":"figure","src":"/articles/springbank-distillery-tour/09.webp","width":966,"height":544},{"kind":"figure","src":"/articles/springbank-distillery-tour/10.webp","width":966,"height":1288},{"kind":"paragraph","text":"이후에는 작은 웨어하우스로 이동해서 숙성되고 있는 캐스크들을 구경할 수 있는데, 당연한 얘기지만 여기서는 캐스크에 정보가 적혀있지 않다. 다른 증류소는 그래도 몇몇은 캐스크 정보를 확인할 수 있었는데, 스프링뱅크 증류소는 완전히 캐스크 정보를 가리고 있더라."},{"kind":"figure","src":"/articles/springbank-distillery-tour/11.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/springbank-distillery-tour/12.webp","width":966,"height":1288},{"kind":"paragraph","text":"마지막으로 스프링뱅크 10년, 헤이즐번, 롱로우의 기본 엔트리 라인 중 하나를 선택해서 시음하고, 시음한 잔과 투어 기념 미니 바틀 하나를 받으면 증류소 투어는 끝이 난다."},{"kind":"paragraph","text":"투어 기념 미니 바틀은 물어보니 스프링뱅크 6년 숙성이라고 하며, 아마도 버번 캐스크라 했던 걸로 기억한다. 궁금하기는 한데, 이걸 오픈해서 마실 수나 있을지."},{"kind":"paragraph","text":"단지 아일라와 스프링뱅크의 위스키를 좋아해서 회사를 퇴사까지 해서 친구를 끌고 아일라를 거쳐 캠벨타운까지 갔는데, 이 마지막 글을 쓰면서 돌아보니 지금 봐도 정말 현실감이 없는 경험이었다."},{"kind":"figure","src":"/articles/springbank-distillery-tour/13.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/springbank-distillery-tour/14.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/springbank-distillery-tour/15.webp","width":966,"height":725},{"kind":"figure","src":"/articles/springbank-distillery-tour/16.webp","width":966,"height":543},{"kind":"paragraph","text":"증류소와 맛있는 위스키도 좋았지만, 그 사이사이의 사진으로는 온전히 담을 수 없는 자연의 풍경과 여유로움을 넋 놓고 즐겼던 것 같다. 음식은 대부분 맛없었지만."},{"kind":"paragraph","text":"같이 갔던 친구와 다시 스코틀랜드를 가자는 약속을 했는데, 언제가 될지는 모르겠지만 그 현실성 없고, 기약 없는 약속이 또 기다려진다."}]'::jsonb, 'published', '2024-12-15T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'miraon-very-young', 'spirits', '미라온 베리영 — 쌀의 즐거움', '''미라온''은 스코틀랜드 아일라 섬의 아드벡 증류소에서 바텐더로 근무했던 ''오수민 대표''가 운영하는 ''화심주조''에서 출시한 숙성된 증류식 소주입니다.', '/articles/miraon-very-young/00.webp',
  'https://blog.naver.com/shakinglikebartender/223681955688', false,
  '[{"kind":"figure","src":"/articles/miraon-very-young/00.webp","width":966,"height":966},{"kind":"paragraph","text":"About the Soju"},{"kind":"paragraph","text":"''미라온''은 스코틀랜드 아일라 섬의 아드벡 증류소에서 바텐더로 근무했던 ''오수민 대표''가 운영하는 ''화심주조''에서 출시한 숙성된 증류식 소주입니다."},{"kind":"paragraph","text":"다만, 일반적인 증류식 소주가 원료인 쌀을 불리고 찐 후에 누룩을 사용해서 발효하는 것과는 다르게, 쌀을 구운 후에 당화 과정을 거친 후, 위스키용 효모를 사용해서 발효를 하고 나서 2번의 증류를 한다고 합니다."},{"kind":"paragraph","text":"그러니 한국의 증류식 소주에 전통적인 스카치 위스키의 양조 방법을 대입한 것이라 할 수 있으며, 이 미라온 베리 영은 전통적인 의미의 증류식 소주라기보다는 그레인 위스키에 가깝지 않을까 싶습니다."},{"kind":"paragraph","text":"아드벡을 좋아하시는 분들이라면 ''베리 영(Very Young)''이라는 부분에 저처럼 눈이 갈 것 같은데, 맞습니다. 이 부분은 아드벡에 대한 오마주입니다."},{"kind":"paragraph","text":"아드벡은 1997년에 글렌모렌지에 인수된 후, 첫 번째 아드벡 10년(인트로듀싱 텐/Introducing Ten)을 출시하기 전, ''베리 영''>스틸 영(Still Young)>올모스트 데어(Almost There)>르네상스(Renaissance)로 이어지는 일련의 시리즈를 출시했습니다."},{"kind":"paragraph","text":"미라온은 아드벡처럼 이 시리즈를 완성시킬 예정이며, 베리영은 그 첫 번째 제품이라 할 수 있습니다. 여담으로 미라온의 보틀은 아드벡의 보틀과 셰입이 같은 점 또한 아드벡에 대한 오마주라 할 수 있습니다."},{"kind":"figure","src":"/articles/miraon-very-young/01.webp","width":966,"height":1288},{"kind":"quote","text":"증류소: 화심주조"},{"kind":"quote","text":"주류 타입: 증류식 소주"},{"kind":"quote","text":"캐스크 정보: 헤븐힐 버번 캐스크에서 1년 숙성"},{"kind":"quote","text":"도수: 58.3%"},{"kind":"figure","src":"/articles/miraon-very-young/02.webp","width":966,"height":966},{"kind":"paragraph","text":"향"},{"kind":"paragraph","text":"- 쌀, 대놓고 고소한 향"},{"kind":"paragraph","text":"- 증류식 소주에서 날만한 곡물의 향이 나기는 하지만, 그렇게 강하지는 않음"},{"kind":"paragraph","text":"- 약간의 바닐라, 참기름, 달달한 계피"},{"kind":"paragraph","text":"- 시간이 다소 지나고 난 후에는 초콜릿 캐릭터가 느껴짐"},{"kind":"heading","text":"맛"},{"kind":"paragraph","text":"- 곡식, 살짝의 달달함"},{"kind":"paragraph","text":"- 참기름"},{"kind":"paragraph","text":"- 혀에 남는 짭짤함과 약간의 쌉쌀함"},{"kind":"paragraph","text":"- 시간이 다소 지나고 난 후에는 향에서 나는 초콜릿 캐릭터가 살짝 느껴짐"},{"kind":"paragraph","text":"여운"},{"kind":"paragraph","text":"- 참기름"},{"kind":"paragraph","text":"- 고소하고 달달함"},{"kind":"paragraph","text":"미라온 베리 영의 가장 재미있는 점은 곡식의 고소함과 달달함에 더해 참기름 같은 캐릭터가 꽤나 직관적으로 느껴진다는 점인데, 위스키에서는 보기 어려운 독특한 캐릭터라 할 수 있겠습니다."},{"kind":"paragraph","text":"다른 증류식 소주들보다는 좀 더 위스키스러운 느낌으로, 버번 캐스크를 꽤나 멋들어지게 사용했다는 느낌이 개인적으로 크게 와닿았습니다."}]'::jsonb, 'published', '2024-12-04T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'bunnahabhain-feis-ile-2024', 'spirits', '부나하벤 페스 아일 2024 — 루비 포트 피니시', '아일라까지 가서 못 만난 축제 보틀을 싱가포르 창이 공항에서 만났다. 브리딩 후에 완전히 다른 위스키가 되는 14년 숙성.', '/articles/bunnahabhain-feis-ile-2024/00.webp',
  'https://blog.naver.com/shakinglikebartender/223670507851', false,
  '[{"kind":"figure","src":"/articles/bunnahabhain-feis-ile-2024/00.webp","width":966,"height":966},{"kind":"heading","text":"About the Whisky"},{"kind":"paragraph","text":"''부나하벤(Bunnahabhain)''은 스코틀랜드 아일라섬(Islay)의 북동쪽에 위치한 부나하벤 증류소에서 만들어지는 위스키로, 아일라 위스키지만 피트를 사용하지 않는다는 것이 특징인 위스키입니다."},{"kind":"paragraph","text":"이 아일라 섬에서는 해마다 5월 마지막 주에 옆의 주라 섬(Jura)과 함께 ''페스 아일(Feis Ile)''이라는 축제가 열리는데,  두 섬의 증류소들은 축제를 기념하기 위한 보틀을 출시합니다."},{"kind":"paragraph","text":"올해 열렸던 페스아일에서 부나하벤 증류소는 4가지 스펙의 제품을 출시하였는데, 이번에 리뷰하는 바틀은 14년 숙성의 루비 포트 피니시입니다."},{"kind":"paragraph","text":"올해 페스 아일 기간에 부나하벤의 오픈데이 당일 아일라 섬을 방문했었는데 일정상 부나하벤은 들리지 못했었습니다만, 가족 여행을 갔다 오면서 창이 공항에서 발견하고는 바로 확보했습니다."},{"kind":"paragraph","text":"아일라 섬까지 가서 구경도 못한 걸 싱가포르에서 만나다니 약간은 아이러니하네요."},{"kind":"quote","text":"증류소: 부나하벤 증류소"},{"kind":"quote","text":"위스키 타입: 싱글 몰트 위스키"},{"kind":"quote","text":"캐스크 정보: 버번 캐스크(Bourbon Cask) 11년 숙성 후, 루피 포트 혹스헤드(Ruby Port Hogshead)에서 3년 피니시"},{"kind":"quote","text":"도수: 58.7%"},{"kind":"quote","text":"시리즈: 페스 아일(Feis Ile)"},{"kind":"figure","src":"/articles/bunnahabhain-feis-ile-2024/01.webp","width":966,"height":966},{"kind":"heading","text":"Nose"},{"kind":"paragraph","text":"- 처음 오픈했을 때, 스파이시함이 강하고, 블루베리 요거트 같은 느낌. 어느정도 브리딩 후에는 전혀 달라짐."},{"kind":"paragraph","text":"- 어느정도 숙성된 그랑 샹파뉴 꼬냑의 란시오와 오렌지 캐릭터와 비슷한 느낌의 첫 향"},{"kind":"paragraph","text":"- 풍부한 어두운 계열의 베리류, 말린 망고"},{"kind":"paragraph","text":"- 오렌지 과육 위에서 카라멜라이즈된 설탕"},{"kind":"paragraph","text":"- 크리미함, 코코아의 캐릭터"},{"kind":"paragraph","text":"- 약간의 향신료와 스파이시함"},{"kind":"heading","text":"Palate"},{"kind":"paragraph","text":"- 스파이시함이 코를 탁 치지만, 전혀 거슬리지 않고 오히려 기분이 좋을 정도."},{"kind":"paragraph","text":"- 스파이시함 > 오크 캐릭터 > 단맛으로 이어짐"},{"kind":"paragraph","text":"- 단맛은 시럽 같은 단맛이 지배적임."},{"kind":"paragraph","text":"- 어딘가 꼬냑을 연상시키는 끝맛"},{"kind":"heading","text":"Finish"},{"kind":"paragraph","text":"- 달달함과 스파이시함의 절묘한 밸런스"},{"kind":"paragraph","text":"테이스팅 노트를 적다보니 ''꼬냑''에 대해서 꽤나 많이 적었는데, 그렇다고 꼬냑과 완전히 비슷하다! 이런 건 아니고, 그랑 샹파뉴 꼬냑의 뉘앙스가 어딘가 느껴지는 정도입니다."},{"kind":"paragraph","text":"처음 오픈했을 때는 스파이시함이 꽤 강하고, 블루베리 요거트 같은 캐릭터가 꽤나 강했는데, 브리딩 후에는 완전히 다른 위스키가 됐습니다. 아마 브리딩 하면서 스파이시 함이 좀 빠지면서 다른 캐릭터들이 올라온 탓이겠죠."},{"kind":"paragraph","text":"개인적으로는 브리딩 후에 정말 맛있게 마셨고, 포트 캐스크 피니시를 정말 잘했다고 느꼈습니다. 포트 캐스크를 활용한 위스키 중에서는 지금까지 마셔본 것 중에 가장 마음에 드네요."}]'::jsonb, 'published', '2024-11-23T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'between-the-sheets', 'cocktail', '비트윈 더 시츠 — 관능적인 이름과 그렇지 못한 맛', '''비트윈 더 시츠''는 1920~1930년대에 파리의 해리스 뉴욕 바(Harry''s New York Bar)에서 해리 맥켈혼(Harry MacElhone)에 의해서 만들어졌다는 설이 가장 많이 알려져 있습니다.', '/articles/between-the-sheets/00.webp',
  'https://blog.naver.com/shakinglikebartender/223662864531', false,
  '[{"kind":"figure","src":"/articles/between-the-sheets/00.webp","width":966,"height":966},{"kind":"heading","text":"About the Cocktail"},{"kind":"paragraph","text":"''비트윈 더 시츠''는 1920~1930년대에 파리의 해리스 뉴욕 바(Harry''s New York Bar)에서 해리 맥켈혼(Harry MacElhone)에 의해서 만들어졌다는 설이 가장 많이 알려져 있습니다."},{"kind":"paragraph","text":"다만, 1921년에 런던의 버클리 호텔(Berkeley Hotel)에서 매니저였던 폴리(Mr.Polly)에 의해서 만들어졌다는 설도 있으며, 해리 맥켈혼의 저서에서 실린 칵테일 중에서도 그가 만든 것이 아니지만 마치 그가 만들었다는 듯이 잘못 알려지는 경우도 다수 있어서 확실하지는 않습니다."},{"kind":"paragraph","text":"비트윈 더 시츠는 사이드카(Sidecar)의 변형으로 여겨지고 있으며, 실제로 사이드카에서 꼬냑의 양을 줄이고 그만큼 럼을 기주로 추가한 구조입니다."},{"kind":"paragraph","text":"다만, 어떠한 럼을 사용하느냐에 따라서 색과 맛이 달라지게 되며, 레시피도 꽤나 다양하게 있습니다. 이건 사실 원래 레시피로 하면 너무 맛이 없어서 그런... 예..."},{"kind":"paragraph","text":"이름 자체는 ''침대 안에서''이라는 뜻으로 관능적인 이름이며, 이름대로 나이트캡으로 마시는 칵테일이라고 합니다. 그렇지만 사실 이런 신맛의 칵테일은 나이트캡으로 잘 마시지 않는 걸 감안하면 이름 때문에 나이트캡 칵테일이라 하는 것 같습니다."},{"kind":"figure","src":"/articles/between-the-sheets/01.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"22.5ml 꼬냑 (VSOP Cognac)"},{"kind":"paragraph","text":"22.5ml 화이트럼 (White Rum)"},{"kind":"paragraph","text":"20ml 레몬즙 (Lemon Juice)"},{"kind":"paragraph","text":"15ml 코앵트로 (Cointreau or Orange Curacao)"},{"kind":"paragraph","text":"*이 레시피는 오리지널 레시피가 아니라 제가 조정한 레시피입니다."},{"kind":"paragraph","text":"**취향에 따라 숙성된 럼을 사용해도 무방합니다."},{"kind":"figure","src":"/articles/between-the-sheets/02.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 모든 재료를 셰이커에 넣어줍니다."},{"kind":"paragraph","text":"2. 셰이커에 얼음을 채우고, 셰이킹합니다."},{"kind":"paragraph","text":"3. 차게 해 둔 잔에 부어줍니다."},{"kind":"paragraph","text":"비트윈 더 시츠는 원형인 사이드카보다 오렌지 맛이나 알코올에서 오는 단맛이 좀 더 강하게 나는 칵테일이며, 다만 사이드카보다는 당연히 복합성 자체는 꽤나 많이 떨어집니다."},{"kind":"paragraph","text":"저 같은 경우는 오리지널 레시피보다 레몬즙을 꽤 많이 넣는 편인데, 오리지널 레시피는 알코올감이 너무 강해서 레몬즙을 좀 많이 넣게 됐습니다."},{"kind":"paragraph","text":"사이드카의 못난 형제 같은 느낌으로, 솔직히 왜 마시는지는 잘 모르겠는... 저한테는 그런 느낌의 칵테일입니다."}]'::jsonb, 'published', '2024-11-16T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'between-the-sheets' AND c.slug = 'betweenthesheets';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'sapporo-the-whisky-tasting-room', 'bar', '위스키 테이스팅 룸 — 많은 독립병입자 제품을 시음해보고 구매할 수 있는 리쿼샵', '''위스키 테이스팅룸''은 삿포로의 스스키노역 근처에 위치한 보틀샵이며, 일본의 주류회사인 ''스카치 몰트 판매 주식회사''에서 운영하고 있어서 독립병입자가 꽤나 많이 놓여져 있습니다.', '/articles/sapporo-the-whisky-tasting-room/00.webp',
  'https://blog.naver.com/shakinglikebartender/223659384518', false,
  '[{"kind":"figure","src":"/articles/sapporo-the-whisky-tasting-room/00.webp","width":966,"height":1288},{"kind":"paragraph","text":"''위스키 테이스팅룸''은 삿포로의 스스키노역 근처에 위치한 보틀샵이며, 일본의 주류회사인 ''스카치 몰트 판매 주식회사''에서 운영하고 있어서 독립병입자가 꽤나 많이 놓여져 있습니다."},{"kind":"paragraph","text":"독립병입자 위스키 외의 특이점이라면 보틀샵 내부에서 유료로 시음이 가능하며, 시음한 주류를 바틀로 구매하면 구매한 주류의 시음료를 빼준다는 점입니다."},{"kind":"paragraph","text":"독립병입자 같은 경우는 증류소 오피셜과 다른 경우가 꽤나 많고, 지뢰도 많은데 이렇게 시음 후 바틀을 구매할 수 있고, 한 잔 분량의 시음료를 빼준다는 게 장점이라 할 수 있죠."},{"kind":"figure","src":"/articles/sapporo-the-whisky-tasting-room/01.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/sapporo-the-whisky-tasting-room/02.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/sapporo-the-whisky-tasting-room/03.webp","width":966,"height":1717},{"kind":"paragraph","text":"스카치 몰트 판매 주식회사에서 운영하고 있는 만큼 해당 회사가 유통하는 독립병입자인 디스틸러리즈 콜렉션(Distilleries Collection), 더 몰트만(The Maltman), 쿠퍼스 초이스(Cooper''s Choice), 하트 브라더스(Heart Brothers), 더 테이스터(The Taster), 위스키 스폰지(Whisky Sponge) 등의 제품이 상당히 많습니다."},{"kind":"paragraph","text":"참고로 이 곳의 점장님이 삿포로 스스키노역 근처의 베키오(Shot Bar Vecchio)라는 바의 오너이신데, 그러다보니 이 바에도 독립병입자 제품이 많이 있습니다."},{"kind":"paragraph","text":"저는 사실 이전에 스코틀랜드에서 마셔본 아일라 스폰지 킬달튼이 있는 사진만 보고 간 거였는데, 그건 몇 달 전에 이미 다 팔렸다고....심지어 들어오자마자 거의 바로 팔렸었다고 해서 구하지는 못했습니다. 아드벡에 셰리 캐스크니 그러려니....."},{"kind":"paragraph","text":"그 외에 울프번(Wolfburn), 코츠월드(Cotswolds), 글렌파클라스(Glenfarclas)의 오피셜이나, 꼬냑, 럼, 보드카 등도 구비되어 있으며, 바로 옆에는 진 갤러리(The Gin Gallery)에서는 다양한 진을 경험할 수도 있습니다."},{"kind":"figure","src":"/articles/sapporo-the-whisky-tasting-room/04.webp","width":966,"height":1288},{"kind":"paragraph","text":"시음은 직원 분에게 얘기해서 자유롭게 할 수 있는데, 점포 내의 위스키는 거의 대부분 시음할 수 있으며, 이전에 판매하지만 보틀은 솔드아웃된 제품도 시음해볼 수 있습니다."},{"kind":"paragraph","text":"추천을 받아볼 수도 있는데 직원분들이 몇 가지 보틀을 가져와서 꽤 자세하게 설명해주시고, 그 중에서 하나 고르는 식으로 추천을 받았습니다. 직원분들이 위스키에 대해서 꽤나 잘 아시니 추천 받아보시길 바랍니다."},{"kind":"figure","src":"/articles/sapporo-the-whisky-tasting-room/05.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/sapporo-the-whisky-tasting-room/06.webp","width":966,"height":1288},{"kind":"paragraph","text":"저는 이틀에 걸쳐서 방문을 했었는데, 만족스러운 제품들이 꽤 있었습니다."},{"kind":"paragraph","text":"먼저 고양이와 물범이 그려진 바틀은 올해 홋카이도 위스키 페스티벌에서 출시된 것들인데, 고양이는 클라이넬리쉬(추정), 물범은 아드벡(추정)이라고 합니다. 꽤나 좋은 퀄리티들이여서 고민하다가 아드벡을 구매했습니다."},{"kind":"paragraph","text":"다음으로 아카이브(Archives)의 링크우드와 디스틸러리즈 콜렉션의 발메냑 이 둘 중에도 정말 고민을 많이 햇는데, 발메냑이 제가 딱 좋아하는 대추야자 캐릭터의 셰리 캐스크라서 발메냑을 구매했습니다."},{"kind":"figure","src":"/articles/sapporo-the-whisky-tasting-room/07.webp","width":966,"height":1288},{"kind":"paragraph","text":"구매하지는 않았지만, 디스틸러리즈 콜렉션의 윌리엄슨(Williamson) 13년 같은 경우는 아스팔트, 뜨거워진 고무타이어(...?) 같은 캐릭터가 나서 아주 재미있었습니다. 참고로 윌리엄슨은 라프로익의 티스푼 몰트입니다."},{"kind":"paragraph","text":"그 외에 브라운 슈거의 클라렌든(Clarendon Estate)은 럼을 좋아하시는 분이라면 꼭 시음해보는 걸 권해드리는데, 69.1%라는 엄청난 고도수의 강력함과 자메이칸 럼 특유의 펑키함이 아주아주 매력적인 럼입니다. 관세만 아니었으면 한 병 샀을텐데...."},{"kind":"paragraph","text":"사진에는 없지만 점포 내에서 숙성 중인 위스키도 볼 수 있는데, 하나는 시크릿 아일라, 하나는 시크릿 하이랜드라고 써져있습니다."},{"kind":"paragraph","text":"이 중 아일라는 스카치 몰트 판매 주식회사에서 병입하는 저숙성 아드벡을 미즈나라 캐스크에서 추가 숙성한 것으로, 이것도 한 번 경험해 보는 걸 추천드립니다."}]'::jsonb, 'published', '2024-11-13T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'old-pal', 'cocktail', '올드 팔 — 네그로니의 화사한 변형', '''올드 팔''은 수 많은 네그로니(Negroni)의 변형 중 하나로, 파리의 해리스 뉴욕 바(Harry''s New York Bar)에서 해리 맥켈혼(Harry MacElhone)의 저서 ''Barflies and Cocktails''에서 처음 등장합니다.', '/articles/old-pal/00.webp',
  'https://blog.naver.com/shakinglikebartender/223653506998', false,
  '[{"kind":"figure","src":"/articles/old-pal/00.webp","width":966,"height":966},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"''올드 팔''은 수 많은 네그로니(Negroni)의 변형 중 하나로, 파리의 해리스 뉴욕 바(Harry''s New York Bar)에서 해리 맥켈혼(Harry MacElhone)의 저서 ''Barflies and Cocktails''에서 처음 등장합니다."},{"kind":"paragraph","text":"이 저서의 마지막 부분에는 ''아서 모스(Arthur Moss)''가 쓴 에세이 ''Cocktails Round Town''가 있는데, 여기서 이 칵테일의 기원에 대해서 얘기하며, 이후 개정판에서는 누구의 레시피인지 자세하게 나오게 됩니다."},{"kind":"paragraph","text":"이에 따르면 칵테일을 만든 것은 ''윌리엄 로빈슨(William Sparrow Robinson)''이며, 오랜 친구인 ''저자(Writer)''를 위해 칵테일의 이름을 ''오랜 친구''라는 의미의 ''올드팔(정확히는 My Old Pal)''이라 명명했다고 합니다."},{"kind":"paragraph","text":"여기서 다소 혼동이 발생하는데, ''저자(Writer)''가 해리 맥켈혼을 의미하는지, 아서 모스를 의미하는지에 대해서 논란의 여지가 있기 때문입니다."},{"kind":"paragraph","text":"다만, 이 내용이 ''Barflies and Cocktails''의 메인 칵테일 리스트가 아니라, 아서 모스가 쓴 에세이 부분에 나온다는 점에서 이 ''올드 팔''이 아서 모스를 지칭한다고 보는 시각이 최근에는 설득력을 얻고 있는 것 같습니다."},{"kind":"paragraph","text":"레시피도 문제인게, 에세이에서는 캐나디안 클럽/이탈리안 버무스(Eyetalian Vermouth)/캄파리를 동률로 하는 레시피를 얘기하는데, 이 이탈리안 버무스가 단순히 이탈리아에서 만들어지는 버무스를 얘기하는 건지, 스윗 버무스를 얘기하는 건지는 알 수 없습니다."},{"kind":"paragraph","text":"전자도 후자도 문제가 되는 게, 전자는 스위트/드라이/비앙코 중 어떤 버무스인지 알 수도 없고, 후자는 올드 팔이 본래는 드라이 버무스로 만들어지는 게 아니라는 점입니다. 다만, 당시에는 이탈리안 버무스가 일반적으로 스윗 버무스를 의미하긴 합니다."},{"kind":"paragraph","text":"그러니 ''올드 팔''은 시간이 지나면서 원래의 레시피에서 꽤나 많은 변화를 겪은 칵테일이라 할 수 있겠습니다."},{"kind":"figure","src":"/articles/old-pal/01.webp","width":966,"height":966},{"kind":"paragraph","text":"Ingredietns"},{"kind":"paragraph","text":"20ml 라이 위스키 (Rye Whiskey)"},{"kind":"paragraph","text":"20ml 캄파리 (Campari)"},{"kind":"paragraph","text":"20ml 드라이 버무스 (Dry Vermouth)"},{"kind":"paragraph","text":"가니시: 레몬 껍질 (Lemon Peel)"},{"kind":"paragraph","text":"*저는 용량이 작은 잔을 써서 20ml를 기준으로 동량을 사용했으니, 잔의 용량에 따라 양을 조절해주시면 됩니다."},{"kind":"paragraph","text":"**동률의 레시피가 기본이긴 하지만, 2:1:1의 레시피도 있습니다."},{"kind":"figure","src":"/articles/old-pal/02.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 믹싱 글라스에 모든 재료를 넣어줍니다."},{"kind":"paragraph","text":"2. 믹싱 글라스에 얼음을 채워주고, 스터해줍니다."},{"kind":"paragraph","text":"3. 차게 해 둔 잔에 부어줍니다."},{"kind":"paragraph","text":"4. 레몬 껍질을 짜서 오일을 뿌려줍니다."},{"kind":"paragraph","text":"가니시는 오렌지 껍질과 레몬 껍질 중에 아무거나 사용하셔도 되지만, 저 같은 경우는 올드 팔의 화사함을 표현하기 위해서는 레몬 껍질이 더 잘 어울릴 것 같아서 레몬 껍질을 사용했습니다. 의외로 라이 위스키와 레몬 껍질의 궁합이 좋기도 하구요."},{"kind":"paragraph","text":"올드팔은 그 원형인 네그로니 특유의 묵직한 단맛 대신에 좀 더 가볍고 화사한 느낌이 있는 칵테일입니다. 그래서 조금은 허브감이 더 잘 느껴지는 것 같은 기분도 드네요."},{"kind":"paragraph","text":"전체적으로 쌉쌀함, 달달함, 허브감이 화사하게 느껴지는 칵테일이며, 여기에 약간의 바닐라 캐릭터가 느껴지기도 합니다. 물론, 바닐라 캐릭터의 경우는 사용하는 라이 위스키에 따라서 다르게 느껴질 수도 있습니다."}]'::jsonb, 'published', '2024-11-09T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'old-pal' AND c.slug = 'oldpal';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'sapporo-bar-nano-femto', 'bar', '나노 펨토 — 일본의 캐릭터를 더한 칵테일이 돋보이는 바', '''나노 펨토(Bar nano femto)''는 삿포로 시내 스스키노역 근처 빌딩의 7층에 위치한 바로, 근처의 ''나노 굴드(Bar nano gould)'' 및 ''파반(Bar Pavane)''은 이곳의 자매점입니다.', '/articles/sapporo-bar-nano-femto/00.webp',
  'https://blog.naver.com/shakinglikebartender/223645145610', false,
  '[{"kind":"figure","src":"/articles/sapporo-bar-nano-femto/00.webp","width":966,"height":1289},{"kind":"figure","src":"/articles/sapporo-bar-nano-femto/01.webp","width":966,"height":543},{"kind":"figure","src":"/articles/sapporo-bar-nano-femto/02.webp","width":966,"height":1288},{"kind":"paragraph","text":"''나노 펨토(Bar nano femto)''는 삿포로 시내 스스키노역 근처 빌딩의 7층에 위치한 바로, 근처의 ''나노 굴드(Bar nano gould)'' 및 ''파반(Bar Pavane)''은 이곳의 자매점입니다. 의외로 오너는 자매점인 나노 굴드에서 손님을 맞이하고 있다고 하네요."},{"kind":"figure","src":"/articles/sapporo-bar-nano-femto/03.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/sapporo-bar-nano-femto/04.webp","width":966,"height":1288},{"kind":"paragraph","text":"메뉴는 일본어와 영어 메뉴가 구비되어 있으니 영어 메뉴를 요청하시면 됩니다. 삿포로 시내의 바는 외국인이 많이 와서 그런지 메뉴가 있는 곳은 모두 영어 메뉴를 구비해놓은 것 같습니다."},{"kind":"paragraph","text":"이번 여행에서는 클래식 칵테일은 잘 안 마시고, 대부분 위스키와 바의 시그니처를 주로 마셨는데, 나노 펨토에서도 그런 느낌이었습니다. 일단 이곳 자체가 칵테일로 유명하기도 했고."},{"kind":"figure","src":"/articles/sapporo-bar-nano-femto/05.webp","width":966,"height":966},{"kind":"paragraph","text":"메뉴를 보다 보니 최근 많이 마셨던 러스티 네일을 일본 이모 쇼츄(고구마 쇼츄)를 기주로 해서 사쿠라 우드로 훈연을 해서 변형한 ''재패니즈 이모 쇼츄 러스티 네일''이 눈에 띄어 이것부터 주문했습니다."},{"kind":"paragraph","text":"첫 잔이어서 동영상을 못 찍었는데, 서브할 때 얼음만 채운 잔과 연기로 훈연 중인 칵테일을 담은 디캔터(?)를 같이 가지고 나오고, 손님이 보는 앞에서 따라줍니다."},{"kind":"paragraph","text":"이렇게 되면 서브할 때 칵테일과 연기가 같이 나오면서 연출적으로도 흥미롭고, 연기의 단 향이 코에 닿게 되는데 이게 또 참 향기롭습니다."},{"kind":"paragraph","text":"맛은 확실히 러스티 네일의 구조를 가지고 있는데, 기주를 이모 쇼츄로 하면서 좀 더 산뜻하고, 아마 드람부이의 양을 줄이면서 꿀을 넣은 건지 적절한 단맛과 허브감이 나며, 훈연으로 인해서 맛이 꽉 차있는 것에 더해 감칠맛이 상당합니다."},{"kind":"paragraph","text":"개인적으로 올해 마신 최고의 칵테일."},{"kind":"figure","src":"/articles/sapporo-bar-nano-femto/06.webp","width":966,"height":966},{"kind":"paragraph","text":"다음 잔을 위해서 메뉴를 보다가 ''마르티네즈''의 재료 조합이 눈에 확 들어와서 주문을 했습니다. 소테른 와인과 몽키47 진의 조합이라니... 정말 흥미롭고, 왜 이런 생각을 못 해봤을까라는 생각을 하면서 주문했습니다."},{"kind":"paragraph","text":"개인적으로는 마르티네즈보다는 마티니의 변형이 아닌가?라는 생각이 계속해서 드는 맛이었고, 마티니를 싫어하신다면 절대 비추입니다. 마티니를 좋아하신다면 추천할만하네요."},{"kind":"figure","src":"/articles/sapporo-bar-nano-femto/07.webp","width":966,"height":1288},{"kind":"paragraph","text":"자리 앞의 바 카운터를 둘러보다 보니 ''글렌파클라스 패밀리 리저브 1997 마데이라 캐스크''가 눈에 띄어서 주문했습니다. 예전에 봐뒀던 생년 빈티지인데다가 글렌파클라스에서 흔치 않은 마데이라 캐스크여서 한 번 마셔보고 싶었는데 여기서 만나니 꽤나 반가웠습니다."},{"kind":"paragraph","text":"맛은 정확히는 기억이 안 나는데, 엄청 인상 깊지는 않았지만 셰리 캐스크를 사용한 글렌파클라스들보다는 여리여리하게 단맛이었고, 입맛에 잘 맞았던 걸로 기억합니다."},{"kind":"paragraph","text":"직원분들이 아주 친절하고, 칵테일과 위스키를 마시면서 매니저님(아마도?)과 서로 스코틀랜드에 갔다 왔던 얘기를 하다 보니 시간 가는 줄 몰랐습니다."},{"kind":"paragraph","text":"칵테일이 정말 맛있었는데, 삿포로 마지막 날에 가서 이번 여행에서는 더 방문할 수 없는 데다가 자매점인 ''나노 굴드''를 못 가본 게 참 아쉬웠습니다. 나중에 나노 펨토에 다시 가고 싶어서라도 삿포로에 한 번쯤은 방문할 것 같습니다."}]'::jsonb, 'published', '2024-11-03T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'sapporo-vaisselle', 'bar', '와다가라스키텐 — 기무라 글라스, 우스하리, 빈티지 글라스를 찾는다면 여기로', '''와다가라스키텐(?)''은 삿포로 시내 니시주잇초메역 근처에 위치한 글라스 및 식기류 샵입니다.', '/articles/sapporo-vaisselle/00.webp',
  'https://blog.naver.com/shakinglikebartender/223643850303', false,
  '[{"kind":"figure","src":"/articles/sapporo-vaisselle/00.webp","width":966,"height":1288},{"kind":"paragraph","text":"''와다가라스키텐(?)''은 삿포로 시내 니시주잇초메역 근처에 위치한 글라스 및 식기류 샵입니다. 지도를 따라서 가면 ''아틀리에 모리히코''라는 큰 카페가 나오는데, 카페 정면에서 왼쪽으로 보면 사진처럼 와다가라스키텐을 방문할 수 있습니다."},{"kind":"figure","src":"/articles/sapporo-vaisselle/01.webp","width":966,"height":543},{"kind":"figure","src":"/articles/sapporo-vaisselle/02.webp","width":966,"height":543},{"kind":"paragraph","text":"내부에서는 다양한 종류의 글라스와 식기를 판매하고 있는데, 저는 글라스에만 관심이 있어서 글라스만 보고 왔습니다."},{"kind":"paragraph","text":"글라스는 전체적으로 기무라 글라스/기무라 유리점(Kimura Glass) 제품이 많으며, 우스하리도 사이즈별로 다수 놓여져 있고, 십 앤 거즐(Sip and Guzzle), 시도니오스(Sydonios), HTT, 일본 작가들의 글라스 등 다양한 브랜드의 제품이 놓여져 있습니다."},{"kind":"figure","src":"/articles/sapporo-vaisselle/03.webp","width":966,"height":1288},{"kind":"paragraph","text":"한 쪽에는 이렇게 빈티지 글라스들이 모여있는데, 주로 발 생 랑베르(Val Saint Lambert)의 제품이 놓여져있으며, 간혹 바카라(Baccarat Glass) 제품이 한 두 제품 놓여져 있습니다. 전 하나씩 구매했는데, 잔당 8,000~10,000 정도의 가격대로 놓여져 있는 것 같습니다."},{"kind":"paragraph","text":"포장을 꽤 꼼꼼하게 해주니 집에 가지고 오는 게 수월했으니, 캐리어에 넣지만 않는다면 그 부분은 걱정하지 않으셔도 될 것 같습니다. 만약 삿포로에 가신다면 구매하지 않더라도 한 번 쯤 들려보는 걸 추천드립니다."}]'::jsonb, 'published', '2024-11-02T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'china-blue', 'cocktail', '차이나 블루 — 달달한 리치 리큐르가 들어간 아름다운 칵테일', '"차이나 블루"라는 칵테일은 이름에서 ''차이나''는 중국이 아니라 도자기(China 또는 Chinaware)를 의미하며, 전체적으로 풀어보자면 "청색의 아름다운 도자기"를 본따 만든 칵테일이라 할 수 있습니다.', '/articles/china-blue/00.webp',
  'https://blog.naver.com/shakinglikebartender/223625072530', false,
  '[{"kind":"figure","src":"/articles/china-blue/00.webp","width":966,"height":966},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"\"차이나 블루\"라는 칵테일은 이름에서 ''차이나''는 중국이 아니라 도자기(China 또는 Chinaware)를 의미하며, 전체적으로 풀어보자면 \"청색의 아름다운 도자기\"를 본따 만든 칵테일이라 할 수 있습니다."},{"kind":"paragraph","text":"차이나 블루는 뭔가 이름 때문에 중국에서 만들어진 칵테일이 아닐까? 싶을 수도 있지만, 사실 일본에서 만들어진 칵테일입니다."},{"kind":"paragraph","text":"이 칵테일은 일본의 도야마현에 위치한 노포 바인 하쿠바칸(Bar Hakubakan)에서 \"우치다 테루히로\" 바텐더에 의해 만들어 졌다고 합니다."},{"kind":"paragraph","text":"바 하쿠바칸은 아직도 운영되고 있으며, 할아버지, 아버지, 아들이 3대에 걸쳐서 운영하고 있다고 합니다."},{"kind":"figure","src":"/articles/china-blue/01.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"30ml 리치 리큐르 (콰이페 or 디타)"},{"kind":"paragraph","text":"45ml 자몽즙 (Grapefruit Juice)"},{"kind":"paragraph","text":"60~75ml 토닉워터 (Tonic Water)"},{"kind":"paragraph","text":"10ml 블루 큐라소 (Blue Curacao)"},{"kind":"figure","src":"/articles/china-blue/02.webp","width":966,"height":966},{"kind":"figure","src":"/articles/china-blue/03.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 긴 잔에 얼음을 채워줍니다."},{"kind":"paragraph","text":"2. 리치 리큐르와 자몽즙을 넣고 잠시 스터해줍니다."},{"kind":"paragraph","text":"3. 토닉워터를 얼음에 닿지 않게 넣어줍니다."},{"kind":"paragraph","text":"4. 바스푼으로 얼음을 위아래로 들어줍니다."},{"kind":"paragraph","text":"5. 블루큐라소를 부어줍니다."},{"kind":"paragraph","text":"**마실 때는 다시 바스푼으로 얼음을 위아래로 들어주면서 블루 큐라소를 잘 섞은 후 마셔줍니다."},{"kind":"figure","src":"/articles/china-blue/04.webp","width":966,"height":966},{"kind":"paragraph","text":"차이나 블루는 리치의 달달하고 화려한 맛에 더해 자몽의 신맛, 블루 큐라소의 달달한 시트러스 등 간단하지만 복합적인 맛을 내는 칵테일이며, 비주얼이 정말 화려합니다."},{"kind":"paragraph","text":"원래 차이나 블루는 토닉이 들어가지 않고, 자몽즙이 더 많이 들어가는 쇼트 스타일의 칵테일이었다고 하지만 토닉이 첨가되는 롱 스타일의 칵테일이 더 대중적입니다."},{"kind":"paragraph","text":"차이나 블루는 바텐더마다 만드는 스타일이 다 다른데, 토닉 워터 이외의 재료를 셰이킹하고 토닉워터를 부어주는 경우도 있으며, 이렇게 만드는 편이 일체감은 오히려 좋습니다."},{"kind":"paragraph","text":"다만, 연한 핑크색에 파란색 블루 큐라소를 부어주면서 색이 변하는 연출을 할 수 있다는 점에서 개인적으로는 블루 큐라소를 따로 부어주는 방법을 더 좋아합니다."}]'::jsonb, 'published', '2024-10-19T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'china-blue' AND c.slug = 'chinablue';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'spumoni', 'cocktail', '스푸모니 — 부담 없이 마실 수 있는 캄파리와 자몽을 사용한 칵테일', '스푸모니는 어디에서, 누가 만들었는지 어떤 단서도 없을 정도로 기원이 불명확한 칵테일입니다.', '/articles/spumoni/00.webp',
  'https://blog.naver.com/shakinglikebartender/223622428420', false,
  '[{"kind":"figure","src":"/articles/spumoni/00.webp","width":966,"height":966},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"스푸모니는 어디에서, 누가 만들었는지 어떤 단서도 없을 정도로 기원이 불명확한 칵테일입니다."},{"kind":"paragraph","text":"우리나라나 일본에서는 스푸모니는 그 이름이 \"거품이 나다\"라는 뜻의 이탈리아어 [spumare]에서 유래한 이탈리아에서 탄생한 칵테일로 잘 알려져 있습니다."},{"kind":"paragraph","text":"그런데 재미있는 점은 서양에서는 오히려 이 스푸모니를 일본의 칵테일로 인식하고 있다는 점입니다. 한 이탈리아 음식 및 문화 전문가는 본인이 이탈리아에서 스푸모니라는 이름의 칵테일을 듣도보도 못했다고 할 정도입니다."},{"kind":"paragraph","text":"심지어 피셀리노(Pisellino)라는 바의 매니저 존 뮬렌(Jon Mullen)은 본인 버전의 스푸모니를 소개하면서 칵테일을 좋아한다면 알만한 ''바텐더''라는 이름의 일본 애니에서 스푸모니가 잠깐 언급된 것을 소개하기도 하였다고 합니다."},{"kind":"paragraph","text":"사실 이탈리아에서 ''Spumoni''라고 함은 전통적인 아이스크림을 이용한 디저트로 알려져 있으며, 스푸모니 칵테일과는 전혀 상관이 없는 것 같습니다."},{"kind":"paragraph","text":"결국 스푸모니 칵테일과 이탈리아의 연관점은 사실 캄파리라는 이탈리아에서 만들어지는 리큐르 밖에 없습니다."},{"kind":"paragraph","text":"그래서 개인적인 생각으로는 스푸모니의 이름이 \"이탈리아어 [spumare]에서 유래했다\"는 것이 와전되어 스푸모니 칵테일 자체가 이탈리아에서 유래했다고 받아들여지지 않았을까 싶습니다."},{"kind":"figure","src":"/articles/spumoni/01.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"30ml 캄파리 (Campari)"},{"kind":"paragraph","text":"45ml 자몽즙 (Grapefruit Juice)"},{"kind":"paragraph","text":"60~75ml 토닉워터 (Tonic Water)"},{"kind":"paragraph","text":"옵션 가니시: 자몽 조각"},{"kind":"figure","src":"/articles/spumoni/02.webp","width":966,"height":966},{"kind":"heading","text":"How to MIx"},{"kind":"paragraph","text":"1. 긴 잔에 얼음을 채워줍니다."},{"kind":"paragraph","text":"2. 잔에 캄파리와 자몽즙을 넣고 잠시 스터해줍니다."},{"kind":"paragraph","text":"3. 얼음에 닿지 않게 토닉워터를 따라줍니다."},{"kind":"paragraph","text":"4. 바스푼으로 얼음을 위아래로 들어줍니다."},{"kind":"paragraph","text":"5. 가니시로 장식해줍니다."},{"kind":"paragraph","text":"스푸모니는 캄파리의 쌉쌀하고 시트러시한 맛이 자몽과 정말 잘 어울리는 칵테일로, 사용하는 토닉워터에 따라 다르겠지만 과하게 달지는 않고, 약간은 쌉쌀한 칵테일입니다."},{"kind":"paragraph","text":"도수도 상당히 낮아 누구든 편하게 즐길 수 있으며, 특히 캄파리의 쌉쌀한 맛 때문에 캄파리를 싫어하시는 분들도 맛있게 마실 수 있을 것 같습니다."},{"kind":"paragraph","text":"개인적으로 캄파리를 정말 좋아하는 만큼 이 칵테일도 극호일 수 밖에 없네요."}]'::jsonb, 'published', '2024-10-17T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'spumoni' AND c.slug = 'spumoni';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'kilkerran-8cs-batch10', 'spirits', '킬커란 8cs 배치 10 — 캐스크 스트렝스 시음기', '형제의 분쟁에서 태어나 두 번 죽고 되살아난 글렌가일 증류소. 올로로소 캐스크 8년, 57.4%의 배치 10을 마셔봤다.', '/articles/kilkerran-8cs-batch10/00.webp',
  'https://blog.naver.com/shakinglikebartender/223618444164', false,
  '[{"kind":"figure","src":"/articles/kilkerran-8cs-batch10/00.webp","width":966,"height":966},{"kind":"heading","text":"About the Whisky"},{"kind":"paragraph","text":"킬커란은 캠벨타운의 글렌가일 증류소(Glengyle Distillery)에서 생산되는 위스키로, 스프링뱅크 증류소와 인연이 있는 증류소의 위스키입니다."},{"kind":"paragraph","text":"글렌가일 증류소는 윌리엄 미첼(William Mitchell)에 의해서 1872년에 설립되었는데, 윌리엄은 이전에 그의 형제인 존 미첼(John Mitchell)과 스프링뱅크 증류소를 운영하였는데, 둘 사이의 분쟁으로 인해 윌리엄이 독립하게 되었습니다."},{"kind":"paragraph","text":"20세기 초에 1차 세계대전 전후로 많은 증류소들이 그랬듯이 글렌가일 증류소는 경제적 어려움을 겪다가 결국 1919년 매각되어버리고, 이후 1925년에는 완전히 생산이 중단되어 버립니다."},{"kind":"paragraph","text":"2000년에는 글렌가일 증류는 미첼 가족의 후손인 헤들리 라이트(Hedley G Wright)가 이끄는 Mitchell''s Glengyle Ltd에 의해 인수되어 복구되기 시작했고, 2004년에는 첫 번째 원액이 증류되었습니다."},{"kind":"paragraph","text":"킬커란 8cs는 매년 1~2번 릴리즈 되며, 제가 구매한 것은 2024년 1월에 병입된 배치 10이며, 올로로소 캐스크에서 숙성되었습니다. 배치마다 캐스크가 동일하지 않으며, 이전에는 버번 캐스크, 포트 캐스크에서도 숙성한 배치가 있다고 합니다."},{"kind":"figure","src":"/articles/kilkerran-8cs-batch10/01.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/kilkerran-8cs-batch10/02.webp","width":966,"height":1288},{"kind":"quote","text":"증류소: 글렌가일 증류소"},{"kind":"quote","text":"위스키 타입: 싱글몰트 위스키"},{"kind":"quote","text":"캐스크 정보: 올로로소 셰리 캐스크"},{"kind":"quote","text":"도수: 57.4%"},{"kind":"figure","src":"/articles/kilkerran-8cs-batch10/03.webp","width":966,"height":966},{"kind":"heading","text":"Nose"},{"kind":"paragraph","text":"- 비릿하고, 강하지는 않은 피트향"},{"kind":"paragraph","text":"- 신문지(?)스러운 향, 건초"},{"kind":"paragraph","text":"- 그 아래로 부드럽게 느껴지는 약간의 땅콩 같은 견과류"},{"kind":"paragraph","text":"- 라즈베리, 체리, 신 딸기"},{"kind":"heading","text":"Palate"},{"kind":"paragraph","text":"- 고소한 몰트의 캐릭터, 우디함"},{"kind":"paragraph","text":"- 베리류의 캐릭터와 탄닌감"},{"kind":"paragraph","text":"- 약한 피트감"},{"kind":"paragraph","text":"- 혀에 남는 짭짤함과 쌉쌀함"},{"kind":"heading","text":"Finish"},{"kind":"paragraph","text":"-신 베리류 > 우디함 > 약간의 피트감 > 마지막에 남는 후추와 진저"},{"kind":"paragraph","text":"이런 순으로 변해가면서 얇고 길게 가는 느낌"},{"kind":"paragraph","text":"킬커란 8cs 배치10은 맛에서 전체적으로 뭔가 다양한 맛이 앞다투어 나는데, 깊이감 자체는 아쉬운 느낌입니다. 물론 8년 숙성이니만큼 깊이감을 바라기는 어렵고, 오히려 8년치고는 괜찮은 편이지 않을까 싶습니다."},{"kind":"paragraph","text":"또한 뭔가 조금 더티한 느낌이며, 달기도 하지만 그 후에 쓴맛이 꽤 올라오는 편입니다. 향·맛·피니시를 모두 합해보면 시고, 달고, 쓴 느낌을 강하게 받았습니다."},{"kind":"paragraph","text":"킬커란을 마셔본 적이 한두번 밖에 없었는데, 이번 보틀을 계기로 다른 킬커란이 보인다면 한 잔씩 마셔보고 싶어지네요."}]'::jsonb, 'published', '2024-10-14T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'rome-with-a-view', 'cocktail', '롬윗어뷰 — 로마의 오후의 풍경이 보이는 저도수 칵테일', '''롬 윗 어 뷰''는 2008년에 현대 칵테일계에 많은 영향을 미친 뉴욕의 밀크앤허니(Milk&Honey)라는 바에서 마이클 매킬로이(Michael McIlroy)에 의해서 만들어졌습니다.', '/articles/rome-with-a-view/00.webp',
  'https://blog.naver.com/shakinglikebartender/223617184701', false,
  '[{"kind":"figure","src":"/articles/rome-with-a-view/00.webp","width":966,"height":966},{"kind":"paragraph","text":"''롬 윗 어 뷰''는 2008년에 현대 칵테일계에 많은 영향을 미친 뉴욕의 밀크앤허니(Milk&Honey)라는 바에서 마이클 매킬로이(Michael McIlroy)에 의해서 만들어졌습니다."},{"kind":"paragraph","text":"당시에 미국에서는 쓴맛이 나는 아페리티프나 저도수 술에 대한 유행이 생기기 전이었고, 아직까지 캄파리나 네그로니 같은 쓴 맛의 술이 미국에서 큰 인기를 끌지도 못하는 시기였습니다."},{"kind":"paragraph","text":"이런 시기에 매킬로이는 밀크앤허니에 오는 손님들 중 쓴맛이 나는 칵테일을 싫어한다는 얘기를 듣고는 ''그럴리가요, 이것 한 번 드셔보세요.''라 하면서 롬윗어뷰를 만들어줬다고 합니다."},{"kind":"paragraph","text":"칵테일의 구조 자체는 피즈(Fizz) 류의 칵테일과 아메리카노(Americano) 칵테일을 매시업한 느낌이 드는 것 같습니다."},{"kind":"paragraph","text":"여담으로 매킬로이는 이후에 샘 로스(Sam Ross)와 밀크앤허니가 있던 자리에 아타보이(Attaboy)라는 바를 오픈했는데, 2015년 아타보이에서 댄 그린바움(Dan Greenbaum)에 의해서 롬윗어뷰의 변형 격인 세컨드 서브(Second Serve)가 만들어집니다."},{"kind":"figure","src":"/articles/rome-with-a-view/01.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"30ml 캄파리 (Campari)"},{"kind":"paragraph","text":"30ml 드라이 버무스 (Dry Vermouth)"},{"kind":"paragraph","text":"30ml 라임즙 (Lime Juice)"},{"kind":"paragraph","text":"15ml 설탕 시럽 (Simple Syrup)"},{"kind":"paragraph","text":"탄산수 탑 업"},{"kind":"paragraph","text":"가니시: 오렌지 휠"},{"kind":"figure","src":"/articles/rome-with-a-view/02.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 탄산수 이외의 재료를 셰이커에 넣어줍니다."},{"kind":"paragraph","text":"2. 셰이커에 얼음을 넣고, 셰이킹 해줍니다."},{"kind":"paragraph","text":"3. 셰이킹 후, 얼음을 채운 긴 잔에 부어줍니다."},{"kind":"paragraph","text":"4. 탄산수를 적당량 채워줍니다."},{"kind":"paragraph","text":"살짝 찌르는 듯한 상큼함에 쌉쌀하고 좋은 허브감이 살짝 느껴지는 것이 재미있는 칵테일이며, 캄파리로 인해서 약간은 자몽 같은 시트러스의 캐릭터가 느껴지기도 합니다."},{"kind":"paragraph","text":"캄파리와 라임 조합의 칵테일이 그렇게 많은 편은 아닌데, 이 칵테일만 마셔봐도 둘의 조합이 꽤나 잘 어울린다는 걸 알 수 있습니다."},{"kind":"paragraph","text":"저도수이기 때문에 아주아주 편하게 마실 수 있으며, 여름이나 초가을에 꽤나 잘 어울리는 칵테일이라 생각되며, 식전주로 마시기에도 부담스럽지 않을 것 같습니다."}]'::jsonb, 'published', '2024-10-13T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'rome-with-a-view' AND c.slug = 'romewithaview';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'pompier', 'cocktail', '폼피에 — 카시스 소다를 업그레이드해보자!', '폼피에는 프랑스어로 ''소방관''을 의미하며, 이 칵테일이 어떻게 생겨났는지, 왜 이런 이름이 붙었는지는 전혀 알려진 바가 없습니다.', '/articles/pompier/00.webp',
  'https://blog.naver.com/shakinglikebartender/223613692833', false,
  '[{"kind":"figure","src":"/articles/pompier/00.webp","width":966,"height":966},{"kind":"paragraph","text":"폼피에는 프랑스어로 ''소방관''을 의미하며, 이 칵테일이 어떻게 생겨났는지, 왜 이런 이름이 붙었는지는 전혀 알려진 바가 없습니다."},{"kind":"paragraph","text":"우리나라에서는 인지도가 없다시피 한 칵테일이며, 일본이나 서양에서나 조금 알려져 있는 것 같습니다. 저는 만화 ''바텐더 a tokyo''에서 처음 확인했습니다."},{"kind":"paragraph","text":"들어가는 재료는 아주 심플한데, 드라이 버무스와 크렘 드 카시스에 탄산이 들어가는 것으로, 어딘가 스프리츠 칵테일류를 생각나게 하는 조합입니다."},{"kind":"paragraph","text":"기주는 특이하게 드라이 버무스로, 버무스의 사용에 애를 먹는 홈텐더 분들에게 특히 추천할 만한 칵테일입니다."},{"kind":"figure","src":"/articles/pompier/01.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"45ml 드라이 버무스 (Dry Vermouth)"},{"kind":"paragraph","text":"15-20ml 크렘 드 카시스 (Creme de Cassis)"},{"kind":"paragraph","text":"100-120ml 탄산수 (Soda Water)"},{"kind":"figure","src":"/articles/pompier/02.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 긴 잔에 얼음을 채워줍니다."},{"kind":"paragraph","text":"2. 카시스와 버무스를 넣고 잘 섞이게 스터해줍니다."},{"kind":"paragraph","text":"3. 탄산수를 넣어주고, 얼음을 살짝 위아래로 움직여줍니다."},{"kind":"paragraph","text":"칵테일 자체는 덜 달지만 허브감과 와인스러움이 살짝 추가된 약간은 복잡한 카시스 소다 같은 느낌입니다. 그렇다고 복합미가 있는 칵테일은 아니고 맛 자체는 단순한 편입니다."},{"kind":"paragraph","text":"칵테일의 이름이 프랑스어인 만큼 재료를 모두 프랑스 재료로 사용하는 것도 센스 있는 선택이며, 이탈리안 버무스가 프렌치 버무스보다는 깔끔한 편이라 그냥 달고 밋밋한 술이 될 수 있으니 프랑스의 버무스를 추천하는 편입니다."},{"kind":"paragraph","text":"크렘 드 카시스는 제품마다 퀄리티 차이가 너무 극명하니 반드시 프랑스의 좋은 퀄리티의 제품을 사용하시는 걸 권장 드리는 편입니다."},{"kind":"paragraph","text":"저도수 칵테일인데다가 약간은 허브감이 있는 칵테일이라 식전주로도 꽤나 좋을 것 같네요."}]'::jsonb, 'published', '2024-10-10T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'pompier' AND c.slug = 'pompier';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'scotland-whisky-ep14', 'spirits', '스코틀랜드 위스키 여행 ep14 — 스프링뱅크 증류소 샵과 워시백 바', '스프링뱅크 증류소(Springbank Distillery)는 스코틀랜드의 캠벨타운에 위치해 있으며, 스프링뱅크·롱로우·헤이즐번을 생산하고 있는 증류소이다.', '/articles/scotland-whisky-ep14/00.webp',
  'https://blog.naver.com/shakinglikebartender/223612719499', false,
  '[{"kind":"figure","src":"/articles/scotland-whisky-ep14/00.webp","width":966,"height":1288},{"kind":"paragraph","text":"스프링뱅크 증류소(Springbank Distillery)는 스코틀랜드의 캠벨타운에 위치해 있으며, 스프링뱅크·롱로우·헤이즐번을 생산하고 있는 증류소이다. 증류소는 오전 10시부터 오픈하며, 일요일에는 문을 닫는다."},{"kind":"paragraph","text":"우리가 증류소를 방문한 날은 월요일이었는데, 월요일 아침 9시 40분 정도였는데도 우리 앞에 8명 정도가 줄을 서고 있었다."},{"kind":"paragraph","text":"사실 우리가 방문하기 약 2주 전에 캠벨타운에서 몰츠 페스티벌을 했어서 그 때 릴리즈된 바틀과 증류소에서만 구매할 수 있는 일명 ''케이지 바틀''을 구매하러 온 사람들이 대부분이었다."},{"kind":"paragraph","text":"케이지 바틀은 증류소 입구 바로 왼쪽의 증류소 샵에 들어가자마자 볼 수 있는데, 스프링뱅크 제품군을 아주 저렴한 가격으로 구매할 수 있어서 인기가 높은 제품이다. 가격은 숙성년도에 따라서 나뉘는데, 첫 번째 사진에서 볼 수 있듯이 꽤나 싼 편이다."},{"kind":"paragraph","text":"케이지 바틀은 1인당 일주일에 하나만 구매할 수 있다고 써져있으며, 한 번 들여놓은 바틀이 모두 판매되어야만 새로운 바틀을 채워준다. 우리가 있을 때는 한 번 다시 채워졌으니 아마 하루에 두 번 정도는 채워지지 않을까 싶다."},{"kind":"paragraph","text":"다만, 고숙성은 보기가 쉽지 않은 편인 듯. 우리가 갔을 때는 고숙성은 없었어서 나는 헤이즐번 셰리 캐스크 8년 숙성을 구매했고, 친구는 롱로우 버번 캐스크를 구매했다."},{"kind":"figure","src":"/articles/scotland-whisky-ep14/01.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep14/02.webp","width":966,"height":1288},{"kind":"paragraph","text":"케이지 바틀에서 왼쪽으로 가서 증류소 샵의 한쪽을 보면 완전히 하나의 작은 스프링뱅크 박물관이라 할 수 있다. 지금까지 출시했던 바틀들을 구경해 볼 수 있는데, 평생 한 번쯤은 마셔볼 수 있을까 싶은 바틀들이 즐비하다."},{"kind":"figure","src":"/articles/scotland-whisky-ep14/03.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep14/04.webp","width":966,"height":1288},{"kind":"paragraph","text":"반대편으로 가보면 증류소 관련 굳즈와 위스키를 판매하고 있다. 우리가 갔을 때는 고숙성은 없었고, 방문 전에 열렸던 캠벨타운 몰츠 페스티벌에서 릴리즈된 제품들을 볼 수 있었다. 그 중 롱로우 16년은 사서 여행 중에 마셨는데, 이게 정말 맛있었다."},{"kind":"paragraph","text":"둘러보다 보면 세 번째 사진처럼 스프링뱅크, 롱로우, 헤이즐번, 킬커란이 들어있는 큰 유리 디스펜서을 볼 수 있는데, 핸드필(?)이었던 걸로 기억한다."},{"kind":"paragraph","text":"설명으로는 한 병 용량에 못미쳐서 남는 원액들이나 미출시 원액을 계속해서 채워주는 것 같다. 이렇게 말하면 뭔가 남은 원액들 처리용 술인가 싶은데, 이 핸드필 제품들도 꽤나 맛있었다."},{"kind":"paragraph","text":"이 정도면 증류소 샵에서의 볼 일은 다 끝난다. 이제 샵에서 나와서 몇 발자국 직진하면 스프링뱅크 증류소에 딸려 있는 ''워시백 바(Washback Bar)''에 도착하게 된다."},{"kind":"quote","text":"워시백 바 (Washback Bar)"},{"kind":"paragraph","text":"워시백 바에서는 스프링뱅크 증류소의 제품군과 킬커란을 아주 저렴한 가격에 마셔볼 수 있다. 우리가 갔을 때는 많은 제품이 비워진 상태였는데, 마침 운나쁘게도 우리가 간 다음날에 메뉴를 개편한다고 하더라."},{"kind":"figure","src":"/articles/scotland-whisky-ep14/05.webp","width":966,"height":1288},{"kind":"paragraph","text":"먼저 마셔봤던 캠벨타운 몰츠 페스티벌 스프링뱅크 증류소 오픈데이의 헤이즐번 8년과 스프링뱅크 10년은 솔직히 그렇게 인상에 남는 맛은 아니었고, 나중에 바틀로 사서 마셔 본 롱로우 16년은 정말 맛있었다."},{"kind":"paragraph","text":"그 외에도 스프링뱅크 로컬발리 9년, 로컬 발리 8년, 팔로 코르타도 10년, 18년, 25년을 마셔봤는데, 친구와 공통적으로 말한 게 스프링뱅크는 저숙성과 버번 캐스크 위주가 맛있다는 점이었다. 둘 다 셰리 캐스크를 그렇게 선호하는 편이 아니기도 하고."},{"kind":"paragraph","text":"개인적으로는 로컬발리 8년, 9년과 팔로 코르타도가 이 중에는 제일 괜찮았고, 팔로 코르타도를 주문할 때 증류소 직원이 엑설런트 초이스라고 했던 게 기억에 남는다."},{"kind":"figure","src":"/articles/scotland-whisky-ep14/06.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep14/07.webp","width":966,"height":1288}]'::jsonb, 'published', '2024-10-09T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'scotland-whisky-ep13', 'spirits', '스코틀랜드 위스키 여행 ep13 — 캠벨타운의 근본 독립병입자, 카덴헤드의 위스키 샵과 테이스팅 룸', '카덴헤드(Wm Cadenhead''s Ltd)는 1842년에 설립된 가장 오래된 독립병입자로, 캠벨타운의 스프링뱅크 증류소와 글렌가일 증류소의 소유주인 제이앤에이 미첼앤코(J&A Mitchell & Co.', '/articles/scotland-whisky-ep13/00.webp',
  'https://blog.naver.com/shakinglikebartender/223611465006', false,
  '[{"kind":"figure","src":"/articles/scotland-whisky-ep13/00.webp","width":966,"height":1288},{"kind":"paragraph","text":"카덴헤드(Wm Cadenhead''s Ltd)는 1842년에 설립된 가장 오래된 독립병입자로, 캠벨타운의 스프링뱅크 증류소와 글렌가일 증류소의 소유주인 제이앤에이 미첼앤코(J&A Mitchell & Co. Ltd)에 1972년 인수되었다."},{"kind":"paragraph","text":"이 인수 이후로는 캠벨타운에 본사를 두고 있으며, 캠벨타운에서는 이 카덴헤드 위스키 샵과 테이스팅 룸이 있어 카덴헤드의 제품을 시음해 볼 수도 있다."},{"kind":"figure","src":"/articles/scotland-whisky-ep13/01.webp","width":966,"height":1288},{"kind":"paragraph","text":"먼저 테이스팅룸에 가기 앞서서 카덴헤드 위스키 샵에 들렀는데, 만약 여러분이 캐리어를 가지고 있으면 마음씨 좋은 직원들이 캐리어를 보관해줄까 물어봐준다. 원래는 스프링뱅크 증류소에 맡기려했는데, 어쩌다보니 여기 맡기게 되었다."},{"kind":"paragraph","text":"샵 내부 사진을 많이 찍지는 않았는데, 기본적으로 무료 시음이 가능한 4가지의 카덴헤드 위스키(아마 블렌디드 였던 걸로 기억함)와 럼을 마셔볼 수 있다. 이후에 테이스팅룸과 증류소 방문을 해야 해서 마셔보지는 않았지만."},{"kind":"paragraph","text":"판매하는 제품군이 아주 다양하게 있으며, 리틀밀(Little Mill)처럼 폐쇄증류소도 찾아볼 수 있다."},{"kind":"figure","src":"/articles/scotland-whisky-ep13/02.webp","width":966,"height":1288},{"kind":"paragraph","text":"카덴헤드 테이스팅 룸은 위스키 샵에서 조금 떨어져있는데, 아마 위스키 샵 내부에서 테이스팅 룸까지 이어지는 통로가 있던 것 같다. 증류소를 들렀다가 다시 오느라 이용하지는 않았지만."},{"kind":"figure","src":"/articles/scotland-whisky-ep13/03.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep13/04.webp","width":966,"height":1288},{"kind":"paragraph","text":"카덴헤드 테이스팅룸에서는 많은 카덴헤드 라인업을 아주 저렴한 가격에 경험해 볼 수 있다는 장점을 가지고 있다. 플라이트로 소량씩 마셔보는 것도 좋지만 따로 하나하나 마셔보는 것도 좋다."},{"kind":"figure","src":"/articles/scotland-whisky-ep13/05.webp","width":966,"height":543},{"kind":"figure","src":"/articles/scotland-whisky-ep13/06.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep13/07.webp","width":966,"height":1288},{"kind":"paragraph","text":"친구는 30파운드짜리 플라이트를 마셨는데, 여기에 카덴헤드에서 병입한 스프링뱅크 11년도 있었다. 스프링뱅크 증류소의 워시백 바 이외에 카덴헤드에도 스프링뱅크가 있으니 참고하시길."},{"kind":"paragraph","text":"나는 플라이트 말고 따로 하나씩 주문했는데, 스프링뱅크 26년, 번사이드 25년, 아드벡 29년을 한 잔씩 마셨고, 언제 이 가격에 이 증류소들의 고숙성을 마셔보겠어 하고 주문하게 되었다."},{"kind":"paragraph","text":"번사이드(Burnside)는 발베니(Balvenie) 99%에 글렌피딕(Glenfiddich) 1%를 섞은 티스푼 위스키(Teaspooned Whisky)인데, 발베니를 그렇게까지 좋아하는 편은 아니지만 25년 숙성된 게 15파운드라면 마실 수 밖에 없다."},{"kind":"paragraph","text":"이 바틀을 잘 보면 \"1 of 1 Bottle\"이라고 써져있는데, 그럼 이 테이스팅 룸에서만 마실 수 있겠다 싶었던 것도 주문한 이유 중 하나였고, 여기에 대해 재밌는 얘기를 들을 수 있었다."},{"kind":"paragraph","text":"위스키 바틀의 용량이 다르면 각각 1 of 1 bottle이라고 쓸 수 있다는 것. 그러니까 200ml, 350ml, 700ml를 한 바틀씩만 릴리즈한다면 각각 1 of 1 bottle이라고 표기할 수 있다고 한다."},{"kind":"paragraph","text":"스프링뱅크와 아드벡은 직원 추천을 받았던 건데, 메뉴에 없는 것들도 있으니 직원 추천을 받아보는 것도 좋은 선택이다. 그리고 고숙성이 이 가격이 맞나 싶을 정도로 싸니까 고숙성 마시자."}]'::jsonb, 'published', '2024-10-08T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'roku-gin', 'spirits', '로쿠 진 — 일본스러운, 특히 사쿠라·유자·차가 돋보이는 재패니즈 진', '''로쿠 진''은 일본의 산토리에서 생산하는 재패니즈 진으로, 일본의 4계절의 캐릭터를 낼 수 있는 6가지의 재료를 제철에 수확하여 증류·침지하여 만들어내며, 이 때 6가지의 일본의 재료를 바탕으로 로쿠(일본어로 6)라는 이름을 붙인 진입니다.', '/articles/roku-gin/00.webp',
  'https://blog.naver.com/shakinglikebartender/223607891549', false,
  '[{"kind":"figure","src":"/articles/roku-gin/00.webp","width":966,"height":966},{"kind":"paragraph","text":"About The Gin"},{"kind":"paragraph","text":"''로쿠 진''은 일본의 산토리에서 생산하는 재패니즈 진으로, 일본의 4계절의 캐릭터를 낼 수 있는 6가지의 재료를 제철에 수확하여 증류·침지하여 만들어내며, 이 때 6가지의 일본의 재료를 바탕으로 로쿠(일본어로 6)라는 이름을 붙인 진입니다."},{"kind":"paragraph","text":"이 6가지 재료는 ''벚꽃, 벚꽃잎, 센차, 옥로, 산초, 유자''이며, 그 외에도 진을 생산하는 데에 전통적으로 사용되는 재료들(주니퍼베리, 안젤리카, 카다멈 등) 8가지를 더해 총 14가지의 보태니컬로 진을 만들어내고 있습니다."},{"kind":"paragraph","text":"아쉽게도 아직까지 국내에는 수입되지 않고 있으며, 일본에서는 흔하게 볼 수 있습니다."},{"kind":"figure","src":"/articles/roku-gin/01.webp","width":966,"height":966},{"kind":"heading","text":"Nose"},{"kind":"paragraph","text":"- 압도적인 벚꽃, 유자, 차의 캐릭터"},{"kind":"paragraph","text":"- 은은한 주니퍼베리, 향신료"},{"kind":"paragraph","text":"- 향은 오일리한 느낌"},{"kind":"heading","text":"Palate"},{"kind":"paragraph","text":"- 깔끔한 벚꽃, 시트러스 캐릭터"},{"kind":"paragraph","text":"- 약간은 후추 같은 맛이 있음"},{"kind":"paragraph","text":"- 차를 마시는 느낌이 들기도 함"},{"kind":"figure","src":"/articles/roku-gin/02.webp","width":966,"height":966},{"kind":"paragraph","text":"진을 시음하려면 역시 진 토닉 또는 진 소다를 마셔봐야한다는 것이 제 지론이라 바로 만들어봤습니다."},{"kind":"paragraph","text":"잔을 입으로 가져가면서는 코에 차를 넣는 일본 진 특유의 향이 기분 좋게 올라옵니다. 맛은 살짝 달짝지근한 벚꽃, 유자에 깔끔한 차 같은 캐릭터가 있는 진토닉이 만들어졌습니다."},{"kind":"paragraph","text":"아주 깔끔하고 일본스러운 풍미가 가득한 느낌이네요."},{"kind":"paragraph","text":"개인적으로 로쿠 진이 국내에 수입이 되면 좋겠습니다만....가격적인 면에서 메리트가 있을지는 미지수입니다."}]'::jsonb, 'published', '2024-10-05T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'pegu-club', 'cocktail', '페구 클럽 — 미얀마에서 영국인들에 의해 시작되어 미국에서 꽃을 피운 칵테일', '''페구 클럽''은 영국이 미얀마를 식민 지배하던 시절이었던 20세기 초에 미얀마의 수도였던 양곤에 위치했던 사교 클럽(신사 클럽)으로, 이 곳에서 탄생하여 사교 클럽과 같은 이름을 가지게 되었습니다.', '/articles/pegu-club/00.webp',
  'https://blog.naver.com/shakinglikebartender/223605555360', false,
  '[{"kind":"figure","src":"/articles/pegu-club/00.webp","width":966,"height":966},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"''페구 클럽''은 영국이 미얀마를 식민 지배하던 시절이었던 20세기 초에 미얀마의 수도였던 양곤에 위치했던 사교 클럽(신사 클럽)으로, 이 곳에서 탄생하여 사교 클럽과 같은 이름을 가지게 되었습니다."},{"kind":"paragraph","text":"이후 1920년대에 파리의 해리스 뉴욕 바로 유명한 해리 맥켈혼(Harry MacElhone)의 저서(Harry''s ABC of Mixing Cocktails)에 기록되었습니다."},{"kind":"paragraph","text":"다만 해리 맥켈혼의 저서는 12번의 리뉴얼을 거쳤는데, 이름이 조금씩 바뀌게 되고, 여기서 페구 클럽이 몇 번째 인쇄본에서 기록된 것인지는 사람들마다 주장하는 것이 모두 다른 걸 보아 명확하지 않은 것 같습니다."},{"kind":"paragraph","text":"그 중 첫 번째 인쇄본인 Harry of Ciro''s ABC of Mixing Cocktails(1922), 일곱 번째 인쇄본인 Barflies and Cocktails(1927)로 갈리는 편인 것 같습니다."},{"kind":"paragraph","text":"페구 클럽은 그렇게 인기 있는 칵테일은 아니었고 서서히 잊혀져 가는 것처럼 보였습니다. 그러나 2000년대 초반 크래프트 칵테일 운동과 함께 오드리 손더스(Audrey Saunders)의 페구 클럽이 뉴욕에서 오픈하면서 다시 한 번 이름을 알리게 됩니다."},{"kind":"paragraph","text":"오드리 손더스는 당시 주류였던 보드카 대신 진(Gin)을 주류로 끌고 오기 위해 노력했으며, 그러한 일환으로 바의 이름을 페구 클럽으로 짓게 됩니다. 다만, 페구 클럽은 코로나의 여파로 2020년 문을 닫게 됩니다."},{"kind":"figure","src":"/articles/pegu-club/01.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"45ml 진 (London Dry Gin)"},{"kind":"paragraph","text":"20ml 라임즙 (Lime Juice)"},{"kind":"paragraph","text":"15ml 코앵트로 or 오렌지 큐라소"},{"kind":"paragraph","text":"(Cointreau or Orange Curacao)"},{"kind":"paragraph","text":"앙고스투라 비터 1대시"},{"kind":"paragraph","text":"(Angostura Aromatic Bitters 1dash)"},{"kind":"paragraph","text":"오렌지 비터 1대시"},{"kind":"paragraph","text":"(Orange Bitters 1dash)"},{"kind":"figure","src":"/articles/pegu-club/02.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 모든 재료를 셰이커에 넣어줍니다."},{"kind":"paragraph","text":"2. 셰이커에 얼음을 채우고, 셰이킹 해줍니다."},{"kind":"paragraph","text":"3. 차게 해 둔 칵테일 잔에 부어줍니다."},{"kind":"paragraph","text":"페구 클럽은 상큼하고, 오렌지스러운 시트러스에 더해 비터에서 오는 향신료의 캐릭터가 은은하게 더해지는 맛입니다. 거기에 진에서 나는 약간의 후추 캐릭터도 같이 느껴지는데 이건 아마 탱커레이라 그럴 수도 있습니다."},{"kind":"paragraph","text":"개인적으로 약간 슴슴한 느낌의 맛이라 생각되는데, 간이 약하다는 건 아니고, 비터의 캐릭터가 은은하게 나니까 슴슴하다 느끼는 걸 수도 있을 것 같습니다."},{"kind":"paragraph","text":"그러니까 맛있긴 한데 개인적으로 더 많은 자극을 원해!!라고 할 수 있겠네요. 저 같은 분들은 앙고스투라 비터를 조금만 더 넣어도 좋을 것 같습니다."}]'::jsonb, 'published', '2024-10-03T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'big-peat-the-smokehouse-edition-feis-ile-2023', 'spirits', '빅 피트 스모크하우스 에디션 페스 아일 2023', '''빅 피트''는 독립병입자인 더글라스 랭(Douglas Laing)에서 출시하는 지역 몰트 위스키 중 하나로 아일라 지역의 싱글 몰트 위스키를 블렌딩한 블렌디드 몰트 위스키입니다.', '/articles/big-peat-the-smokehouse-edition-feis-ile-2023/00.webp',
  'https://blog.naver.com/shakinglikebartender/223604449606', false,
  '[{"kind":"figure","src":"/articles/big-peat-the-smokehouse-edition-feis-ile-2023/00.webp","width":966,"height":966},{"kind":"heading","text":"About The Whisky"},{"kind":"paragraph","text":"''빅 피트''는 독립병입자인 더글라스 랭(Douglas Laing)에서 출시하는 지역 몰트 위스키 중 하나로 아일라 지역의 싱글 몰트 위스키를 블렌딩한 블렌디드 몰트 위스키입니다."},{"kind":"paragraph","text":"빅 피트에 사용되는 키 몰트로는 아일라 지역의 쿨일라(Caol Ila), 아드벡(Ardbeg), 보모어(Bowmore) 및 최근 재개장한 포트 엘런(Port Ellen)이 있습니다."},{"kind":"paragraph","text":"그 중에서 ''스모크하우스 에디션''은 매년 5월 마지막 주에 아일라(Islay) 섬과 주라(Jura) 섬에서 약 1~2주간에 걸친 위스키 관련 축제인 페스 아일(Feis Ile)을 기념하기 위해 2023년 페스 아일에 출시한 제품입니다."},{"kind":"paragraph","text":"특징으로는 빅피트 시리즈 중 최초로 레드 와인 캐스크로 피니시를 했다는 점입니다."},{"kind":"figure","src":"/articles/big-peat-the-smokehouse-edition-feis-ile-2023/01.webp","width":966,"height":1288},{"kind":"quote","text":"병입자: 더글라스 랭"},{"kind":"quote","text":"위스키 타입: 블렌디드 몰트 위스키"},{"kind":"quote","text":"캐스크 정보: 레드 와인 캐스크 피니시 / NAS"},{"kind":"quote","text":"도수: 48%"},{"kind":"quote","text":"시리즈: 페스 아일(Feis Ile)"},{"kind":"figure","src":"/articles/big-peat-the-smokehouse-edition-feis-ile-2023/02.webp","width":966,"height":966},{"kind":"heading","text":"Nose"},{"kind":"paragraph","text":"- 왁시하고 살짝 쌉쌀한 피트감, 어씨함(Earthy)"},{"kind":"paragraph","text":"- 곡식의 달달함과 살짝의 베이컨"},{"kind":"paragraph","text":"- 탄 것 같은 캬라멜"},{"kind":"paragraph","text":"- 스쳐지나가는 버터리함과 솔티함"},{"kind":"paragraph","text":"- 바닐라, 약간의 베리 같은 캐릭터"},{"kind":"paragraph","text":"- 쿨일라스러운 피트감이 지배적으로 느껴짐"},{"kind":"heading","text":"Palate"},{"kind":"paragraph","text":"- 왁시함, 달달한 곡식"},{"kind":"paragraph","text":"- 짭짤하고 쌉쌀함"},{"kind":"paragraph","text":"- 쓴맛이 꽤나 많이 나는 편"},{"kind":"paragraph","text":"- 태운 나무나 숯 같은 캐릭터"},{"kind":"paragraph","text":"- 후추"},{"kind":"heading","text":"Finish"},{"kind":"paragraph","text":"- 생각보다 길고 풍부한 피니시"},{"kind":"paragraph","text":"- 다크 초콜릿"},{"kind":"paragraph","text":"- 쌉쌀함, 후추의 캐릭터"},{"kind":"paragraph","text":"레드 와인 캐스크의 캐릭터는 꽤나 약하게 스쳐지나가서 솔직히 와인 캐스크의 장점이 크게 느껴지지는 않는다고 생각합니다. 다만, 제가 마지막 잔을 마셨어서 그런 걸 수도 있으니 참고해주세요."},{"kind":"paragraph","text":"제일 특이했던 점은 끝맛이 꽤나 쓴 편이며, 맛과 피니시에서 후추의 캐릭터가 꽤 강하게 느껴진다는 점입니다. 고기와의 궁합이 좋을 것 같네요."}]'::jsonb, 'published', '2024-10-02T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'vieux-carre', 'cocktail', '뷰 카레 — 뉴올리언스에서 탄생한 맨하탄의 허브감 있는 변형', '"뷰 카레"는 1938년 뉴올리언스(New Orleans)의 호텔 몬텔레온(Hotel Monteleone)에 있는 바의 헤드 바텐더 월터 버저론(Walter Bergeron)에 의해 만들어졌습니다.', '/articles/vieux-carre/00.webp',
  'https://blog.naver.com/shakinglikebartender/223603174986', false,
  '[{"kind":"figure","src":"/articles/vieux-carre/00.webp","width":966,"height":966},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"\"뷰 카레\"는 1938년 뉴올리언스(New Orleans)의 호텔 몬텔레온(Hotel Monteleone)에 있는 바의 헤드 바텐더 월터 버저론(Walter Bergeron)에 의해 만들어졌습니다."},{"kind":"paragraph","text":"뷰 카레는 프랑스어로 ''오래된 광장''을 의미하며, 뉴올리언스의 프렌치 쿼터(French Quarter) 지역을 지칭하기도 합니다."},{"kind":"paragraph","text":"이 칵테일은 맨하탄과 보비 번스라는 칵테일을 뉴올리언스 식으로 매시업한 느낌의 칵테일이며, 미국에 위치한 프랑스어로 된 지명의 이름을 기리기 위해서인지 기주를 라이 위스키와 꼬냑을 반반으로 만드는 특이한 레시피를 가지고 있습니다."},{"kind":"paragraph","text":"뉴올리언스에서는 사제락(Sazerac)이나 라모스 진 피즈(Ramos Gin Fizz) 같이 현재에도 사랑 받는 클래식 칵테일이 만들어졌는데, 뷰 카레는 클래식 칵테일이라 하기에는 그만큼의 인지도를 얻지는 못했습니다."},{"kind":"figure","src":"/articles/vieux-carre/01.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"22.5ml 라이 위스키 (Rye Whiskey)"},{"kind":"paragraph","text":"22.5ml 꼬냑 (Cognac)"},{"kind":"paragraph","text":"22.5ml 스윗 버무스 (Sweet Vermouth)"},{"kind":"paragraph","text":"7.5-10ml 베네딕틴 돔 (Benedictine DOM)"},{"kind":"paragraph","text":"앙고스투라 비터 2대시"},{"kind":"paragraph","text":"(Angostura Aromatic Bitters)"},{"kind":"paragraph","text":"페이쇼드 비터 2대시"},{"kind":"paragraph","text":"(Peychaud''s Bitters)"},{"kind":"paragraph","text":"가니시: 레몬 껍질, 마라스키노 체리(옵션)"},{"kind":"figure","src":"/articles/vieux-carre/02.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 가니시 이외의 재료를 믹싱 글라스에 넣어줍니다."},{"kind":"paragraph","text":"2. 믹싱 글라스에 얼음을 채우고, 스터 해줍니다."},{"kind":"paragraph","text":"3. 차게 해 둔 온더락 잔에 얼음을 채우고, 칵테일을 부어줍니다."},{"kind":"paragraph","text":"4. 레몬 껍질을 짜서 오일을 뿌려줍니다."},{"kind":"paragraph","text":"5. 마라스키노 체리를 하나 넣어줍니다(옵션)."},{"kind":"paragraph","text":"뷰 카레는 체리 맛 술은 들어가지 않지만 어딘가 마라스키노 체리나 포도 껍질 같은 달달한 맛이은은한 허브의 캐릭터와 함께 납니다. 아마 재료의 조합에서 나오는 맛이겠죠."},{"kind":"paragraph","text":"베네딕틴의 허브감과 달달함이 은은하게 느껴지면서 스윗 버무스의 달달함, 꼬냑의 화사함과 라이 위스키의 스파이시함이 입체적으로 느껴집니다."},{"kind":"paragraph","text":"시럽 없이 술만 들어갔지만, 높은 도수감을 잊을 정도로 생각보다 달달하기도 합니다."},{"kind":"paragraph","text":"꽤나 맨하탄이 생각나는 맛이기도 한데 구조적으로 맨하탄에 베네딕틴이 들어간 것이라고 볼 수도 있을 것 같습니다."},{"kind":"paragraph","text":"칵테일의 밸런스는 칼끝을 타는 것처럼 아슬아슬할 정도로 절묘하다고 생각합니다만, 사람에 따라서는 밸런스가 좋지 않다고 할 수도 있을 것 같은 칵테일입니다."}]'::jsonb, 'published', '2024-10-01T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'japanese-slipper', 'cocktail', '재패니즈 슬리퍼 — 미도리를 사용한 초록색 네온사인 같이 강렬한 색감의 칵테일', '"재패니즈 슬리퍼"는 1984년 멜버른에서 미에타스 레스토랑(Mietta''s Restaurant)에서 장 폴 부르기뇽(Jean-Paul Bourguignon)에 의해 만들어진 칵테일입니다.', '/articles/japanese-slipper/00.webp',
  'https://blog.naver.com/shakinglikebartender/223602035796', false,
  '[{"kind":"figure","src":"/articles/japanese-slipper/00.webp","width":966,"height":966},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"\"재패니즈 슬리퍼\"는 1984년 멜버른에서 미에타스 레스토랑(Mietta''s Restaurant)에서 장 폴 부르기뇽(Jean-Paul Bourguignon)에 의해 만들어진 칵테일입니다."},{"kind":"paragraph","text":"자극적인 캐릭터의 칵테일이 만들어지던 흔히 칵테일 암흑기라 부르는 시기에 만들어진 것을 한눈에 알 수 있는데, 초록색 네온사인 같은 비비드한 색감이 특징인 칵테일입니다."},{"kind":"paragraph","text":"칵테일 암흑기라는 좋지 않은 어감의 시대입니다만, 이건 서양의 바텐더들, 특히 칵테일 르네상스 시기를 강하게 주장하는 사람들이 만들어낸 것일 뿐입니다."},{"kind":"paragraph","text":"사실 이 시기에 코스모폴리탄, 롱아일랜드 아이스티, 에스프레소 마티니 등과 같은 현재에도 많은 사랑을 받는 칵테일들이 탄생하기도 했던 시기이기도 합니다."},{"kind":"paragraph","text":"재패니즈 슬리퍼는 기주(멜론 리큐르), 큐라소, 레몬즙이 들어가는 것이 얼핏 데이지 스타일로 보이기도 하는데, 이건 사람마다 다르게 느낄 수도 있겠네요."},{"kind":"figure","src":"/articles/japanese-slipper/01.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"30ml 미도리 / 멜론 리큐르"},{"kind":"paragraph","text":"(Midori / Melon Liqueur)"},{"kind":"paragraph","text":"30ml 코앵트로 / 트리플 섹"},{"kind":"paragraph","text":"(Cointreau / Triple Sec)"},{"kind":"paragraph","text":"30ml 레몬즙 (Lemon Juice)"},{"kind":"paragraph","text":"가니시: 체리 (옵션)"},{"kind":"figure","src":"/articles/japanese-slipper/02.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 가니시 이외의 재료를 셰이커에 넣어줍니다."},{"kind":"paragraph","text":"2. 셰이커에 얼음을 채우고, 셰이킹 해줍니다."},{"kind":"paragraph","text":"3. 차게 해둔 잔에 부어줍니다."},{"kind":"paragraph","text":"4. 체리 한 알을 넣어줍니다(옵션)."},{"kind":"paragraph","text":"재패니즈 슬리퍼는 초록색 네온사인 같은 겉모습에 걸맞게 아주 자극적인 맛의 칵테일로, 달고 살짝 신맛의 칵테일입니다."},{"kind":"paragraph","text":"개인적으로는 죠스바의 남색부분에 오렌지맛을 더한 것 같은 살짝은 유치한 불량식품 같은 맛입니다. 오랜만에 이런 맛의 칵테일을 마셨는데, 생각보다 꽤나 맛있었습니다."},{"kind":"paragraph","text":"칵테일에 대해서 잘 모르거나, 달달한 칵테일을 좋아하시는 분들에게는 추천할만한 칵테일입니다."}]'::jsonb, 'published', '2024-09-30T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'attaboy', 'bar', '모던 클래식 칵테일의 아이콘, 아타보이의 샘 로스를 찰스 H에서 만나다', '샘 로스는 호주 출신의 바텐더로, 이후 뉴욕의 밀크 앤 허니(Milk & Honey), 리틀 브랜치(Little Branch) 등을 거치며 페이퍼 플레인(Paper Plane)과 페니실린(Penicillin)과 같은 모던 클래식 칵테일 중에서도 아이코', '/articles/attaboy/00.webp',
  'https://blog.naver.com/shakinglikebartender/223597381823', false,
  '[{"kind":"figure","src":"/articles/attaboy/00.webp","width":966,"height":1288},{"kind":"paragraph","text":"샘 로스는 호주 출신의 바텐더로, 이후 뉴욕의 밀크 앤 허니(Milk & Honey), 리틀 브랜치(Little Branch) 등을 거치며 페이퍼 플레인(Paper Plane)과 페니실린(Penicillin)과 같은 모던 클래식 칵테일 중에서도 아이코닉한 불후의 명작을 만들어낸 장본인입니다."},{"kind":"paragraph","text":"샘 로스를 얘기할 때 지금은 고인이 된 그의 멘토인 사샤 페트라스케(Sasha Petraske)를 빼놓을 수 없는데, 샘 로스가 밀크 앤 허니에서 근무할 때 오너인 사샤 페트라스케에게서 많은 영향을 받게 되었습니다."},{"kind":"paragraph","text":"사샤 페트라스케는 1999년 밀크 앤 허니를 오픈하면서 스피크이지(Speakeasy) 스타일의 바를 유행시켰고, 크래프트 칵테일 운동(Craft Cocktail Movement, AKA 칵테일 르네상스)에 큰 영향을 미친 사람 중 한 명입니다."},{"kind":"paragraph","text":"샘 로스는 현재 이전의 밀크 앤 허니가 있었던 자리에 아타보이(Attaboy)를 오픈하여 이 곳을 본거지로 활동하고 있으며, 현대 칵테일계의 아이콘, 바텐더들의 바텐더라 할 수 있습니다."},{"kind":"paragraph","text":"이번에 포시즌스에 위치한 바인 찰스 H에서 샘 로스의 게스트 바텐딩이 있어서 방문했습니다."},{"kind":"figure","src":"/articles/attaboy/01.webp","width":966,"height":1288},{"kind":"paragraph","text":"이번 게스트 바텐딩에서는 그레이트 밤비노, 드래프트 데이, 페이퍼 플레인, 페어뱅크스의 4가지 메뉴에 페니실린까지 더해서 5종의 칵테일을 마셔볼 수 있었습니다."},{"kind":"paragraph","text":"먼저 페니실린은 기주로 피트감이 없는 블렌디드 몰트 위스키를 사용하면서 아일라 위스키를 소량 플로팅했기 때문에 맛에서는 피트 캐릭터가 그렇게 많이 나지는 않습니다. 샘 로스는 애초에 기주로 너무 피트 캐릭터가 강한 위스키를 사용하면 안된다고 이야기합니다."},{"kind":"figure","src":"/articles/attaboy/02.webp","width":966,"height":966},{"kind":"figure","src":"/articles/attaboy/03.webp","width":966,"height":966},{"kind":"figure","src":"/articles/attaboy/04.webp","width":966,"height":966},{"kind":"figure","src":"/articles/attaboy/05.webp","width":966,"height":966,"caption":"페니실린 / 페이퍼 플레인 / 드래프트 데이 페어뱅크스 / 그레이트 밤비노"},{"kind":"paragraph","text":"페이퍼 플레인은 생각했던 것보다 아마로의 진득하고 무거운 캐릭터가 많이 느껴져서 놀랐는데, 페이퍼 플레인을 어떻게 만들려고 의도했는지 드디어 알 수 있는 한 잔이었습니다."},{"kind":"paragraph","text":"드래프트 데이는 기주로 라이 위스키와 자메이칸 럼을 블렌딩하는 독특한 칵테일인데, 이게 또 바나나 리큐르와 압생트의 캐릭터와 절묘한 조합을 만들어내며 아주 재미있는 맛이었습니다."},{"kind":"paragraph","text":"페어뱅크스는 올드패션드에서 재료 중 당에 아프리콧 리큐르를 추가한 것으로, 맛은 솔직히 딱 그 재료들이 낼 수 있는 맛이었고, 팬시 프리라는 칵테일과 비슷한 인상을 받았습니다."},{"kind":"paragraph","text":"그레이트 밤비노는 버번 위스키, 퍼넷 브랑카, 배 거기에 오르쟈(아몬드 시럽)이 들어가는 독특한 조합의 칵테일인데 배와 퍼넷 브랑카의 캐릭터가 생각보다 잘 어울리며, 단맛과 쓴맛의 밸런스가 좋은, 꽤나 매력적인 칵테일이었습니다."},{"kind":"paragraph","text":"전체적으로 칵테일의 온도감이 생각보다 낮았다고 느껴졌는데, 일부로 의도한 것인지가 궁금했습니다만 너무 붐벼서 물어보지는 못했네요."},{"kind":"figure","src":"/articles/attaboy/06.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/attaboy/07.webp","width":966,"height":1288},{"kind":"paragraph","text":"전체적으로 아주 붐비는 분위기였지만 칵테일이 본인의 바가 아닌 게스트 바텐딩에서 이런 맛을 낸다고? 싶을 정도로 아주 맛있었습니다. 개인적으로 게스트 바텐딩을 몇 번 가봤지만 이렇게까지 만족스러웠던 적은 처음이네요."},{"kind":"paragraph","text":"칵테일을 좋아하는 저로서는 글과 사진으로만 접하던 사람과 칵테일을 만나니 약간 위인전의 인물을 보는 것 같은 느낌이었습니다. 너무 들떠서 책에 사인까지 받아왔네요."},{"kind":"paragraph","text":"나중에 뉴욕을 간다면 아타보이는 꼭 방문해보고 싶습니다."}]'::jsonb, 'published', '2024-09-26T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'blood-and-sand', 'cocktail', '블러드 앤 샌드 — 체리, 오렌지 그리고 스파이스의 콤비네이션', '"블러드 앤 샌드"는 1930년에 해리 크래독(Harry Craddock)의 저서 사보이 칵테일 북(The Savoy Cocktail Book)에 처음 기록으로 등장했습니다.', '/articles/blood-and-sand/00.webp',
  'https://blog.naver.com/shakinglikebartender/223589936245', false,
  '[{"kind":"figure","src":"/articles/blood-and-sand/00.webp","width":966,"height":966},{"kind":"heading","text":"About the Cocktail"},{"kind":"paragraph","text":"\"블러드 앤 샌드\"는 1930년에 해리 크래독(Harry Craddock)의 저서 사보이 칵테일 북(The Savoy Cocktail Book)에 처음 기록으로 등장했습니다."},{"kind":"paragraph","text":"누가 무슨 의도로 만들었는지에 대한 정보는 전혀 없으며, 해리 크래독이 만든 것인지, 그가 단순히 기록만 한 것인지도 알 수 없습니다."},{"kind":"paragraph","text":"다만, 1922년에 개봉한 동명의 무성 영화에서 이름을 따온 것으로 추정하고 있지만 그마저도 확실하지 않은 아주 미스터리한 칵테일입니다."},{"kind":"paragraph","text":"해당 영화는 한 스타 투우사의 몰락과 죽음에 관한 영화라 하는데, 사실 칵테일 자체는 꽤나 달달한 칵테일이기 때문에 개인적으로 색감 이외에는 이름과 매치가 잘 안된다고 생각됩니다."},{"kind":"figure","src":"/articles/blood-and-sand/01.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"22.5ml 블렌디드 스카치 위스키"},{"kind":"paragraph","text":"(Blended Scotch Whisky)"},{"kind":"paragraph","text":"22.5ml 체리 히링 (Cherry Heering)"},{"kind":"paragraph","text":"22.5ml 스윗 버무스 (Sweet Vermouth)"},{"kind":"paragraph","text":"22.5ml 오렌지즙 (Orange Juice)"},{"kind":"paragraph","text":"가니시: 오렌지 껍질 (Orange Peel)"},{"kind":"figure","src":"/articles/blood-and-sand/02.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 가니시 이외의 모든 재료를 셰이커에 넣어줍니다."},{"kind":"paragraph","text":"2. 셰이커에 얼음을 채우고, 셰이킹 합니다."},{"kind":"paragraph","text":"3. 차게 해 둔 칵테일 잔에 부어줍니다."},{"kind":"paragraph","text":"4. 오렌지 껍질에서 오일을 짜내고, 장식해 줍니다."},{"kind":"paragraph","text":"전체적으로 확실한 오렌지 캐릭터에 신맛의 생 체리 맛이 더해지며, 올스파이스나 시나몬 같은 스파이스가 달달하게 다가옵니다. 살짝 신맛이 있지만 확실히 달달하네요."},{"kind":"paragraph","text":"체리 히링과 스윗 버무스의 콤비네이션을 오렌지와 함께 느낄 수 있는 칵테일입니다."},{"kind":"paragraph","text":"블러드 앤 샌드는 재료에서부터 느낄 수 있지만, 꽤나 달달한 칵테일입니다. 이런 점 때문에 밸런스가 안 좋은 칵테일이라는 예기를 많이 듣기도 하죠."},{"kind":"paragraph","text":"따라서 몇몇 바텐더들은 레몬즙이나 라임즙을 소량 첨가하기도 하며, 아예 오렌지즙을 넣는 것이 아니라 껍질을 위스키에 인퓨징해서 만들기도 합니다."},{"kind":"paragraph","text":"개인적으로도 원래 레시피 자체가 그렇게 밸런스 좋은 칵테일이라 생각되지는 않지만, 재료가 갖춰져 있다면 한 번쯤은 만들어보는 걸 추천드립니다."}]'::jsonb, 'published', '2024-09-20T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'oaxaca-old-fashioned', 'cocktail', '와하카 올드패션드 — 클래식과 새로움의 만남', '"와하카 올드 패션드"는 2007년 필 워드(Phil Ward)가 뉴욕의 바 데스앤코(Death&Co)에서 만들어낸 칵테일로, 특이하게도 아가베 증류주를 기주로 사용한 올드 패션드의 변형입니다.', '/articles/oaxaca-old-fashioned/00.webp',
  'https://blog.naver.com/shakinglikebartender/223588722581', false,
  '[{"kind":"figure","src":"/articles/oaxaca-old-fashioned/00.webp","width":966,"height":966},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"\"와하카 올드 패션드\"는 2007년 필 워드(Phil Ward)가 뉴욕의 바 데스앤코(Death&Co)에서 만들어낸 칵테일로, 특이하게도 아가베 증류주를 기주로 사용한 올드 패션드의 변형입니다."},{"kind":"paragraph","text":"''와하카''는 메즈칼의 최대 생산지 중 하나로, 메즈칼을 강조하기 위해서 붙은 이름이라 할 수 있습니다."},{"kind":"paragraph","text":"와하카 올드 패션드는 모던 클래식 칵테일을 뽑을 때 반드시 손에 꼽히는 칵테일로, 최근의 아가베 증류주 붐이라는 트렌드를 이끌어내는데 큰 역할을 했다 할 수 있습니다."},{"kind":"paragraph","text":"칵테일이 만들어질 당시는 한창 크래프트 칵테일 운동으로 인해 클래식 칵테일이나 새로운 재료에 대한 관심이 컸던 데다가, 메즈칼이 미국에 소개되기 시작했었고, 클래식 칵테일에 대한 소비자들의 관심 또한 커져갔습니다."},{"kind":"paragraph","text":"그러니 이 칵테일은 당시 시대적 상황에 따라서 필연적으로 만들어질 수밖에 없었던 칵테일이라 할 수 있습니다."},{"kind":"figure","src":"/articles/oaxaca-old-fashioned/01.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"45ml 레포사도 테킬라 (Reposado Tequila)"},{"kind":"paragraph","text":"15ml 메즈칼 (Mezcal)"},{"kind":"paragraph","text":"7.5ml 아가베 넥타 (Agave Nectar)"},{"kind":"paragraph","text":"앙고스투라 비터 2대시"},{"kind":"paragraph","text":"(Angostura Aromatic Bitters 2dashes)"},{"kind":"paragraph","text":"가니시: 불에 그을린 오렌지 껍질"},{"kind":"figure","src":"/articles/oaxaca-old-fashioned/02.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 가니시 이외의 모든 재료를 온더락 잔에 넣어줍니다."},{"kind":"paragraph","text":"2. 잔에 얼음을 채워주고 스터 해줍니다."},{"kind":"paragraph","text":"3. 성냥 등으로 오렌지 껍질 바깥 부분을 살짝 데운 후,"},{"kind":"paragraph","text":"칵테일을 향해 성냥 불을 두고 오렌지 껍질을 짜서 오일을 뿌려줍니다."},{"kind":"figure","src":"/articles/oaxaca-old-fashioned/03.webp","width":966,"height":966},{"kind":"paragraph","text":"이 칵테일은 기주로 데킬라 45ml에 메즈칼 15ml를 사용하는데, 그럼에도 불구하고 메즈칼 특유의 스모키한 캐릭터가 꽤나 치고 나오는 독특한 캐릭터를 보여줍니다."},{"kind":"paragraph","text":"이렇게 메즈칼을 단독 기주로 사용하는 것이 아니라 데킬라를 블렌딩한 것이 정말 좋은 선택이라 생각하는 것이 메즈칼에 익숙하지 않은 사람들이 좀 더 메즈칼에 편하게 접할 수 있기 때문입니다."},{"kind":"paragraph","text":"메즈칼은 사실 특유의 스모키한 캐릭터가 꽤나 강해 처음 접하게 된다면 다소 버거울 수 있지만, 이 칵테일이라면 메즈칼의 캐릭터를 기분 좋게 경험해 볼 수 있겠습니다."},{"kind":"paragraph","text":"칵테일은 전체적으로 캔디드 오렌지, 달달한 아가베, 약간의 스모키함에 더해 살짝의 향신료와 초콜릿(또는 카카오)의 캐릭터가 함께 느껴집니다."},{"kind":"paragraph","text":"바를 방문했을 때 메즈칼이 보이신다면 주저 않고 주문해 보시는 걸 추천드립니다."}]'::jsonb, 'published', '2024-09-19T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'brandy-alexander', 'cocktail', '브랜디 알렉산더 — 꼬냑, 크리미한 초콜릿, 완벽한 디저트 칵테일', '"브랜디 알렉산더"는 진, 크렘 드 카카오, 생크림으로 만들어지는 "알렉산더"라는 칵테일의 변형이며, 그 기원이 명확하지는 않으나 확실한 건 정복자 알렉산더 대왕(알렉산드로스)과는 전혀 상관이 없다는 것입니다.', '/articles/brandy-alexander/00.webp',
  'https://blog.naver.com/shakinglikebartender/223584032606', false,
  '[{"kind":"figure","src":"/articles/brandy-alexander/00.webp","width":966,"height":966},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"\"브랜디 알렉산더\"는 진, 크렘 드 카카오, 생크림으로 만들어지는 \"알렉산더\"라는 칵테일의 변형이며, 그 기원이 명확하지는 않으나 확실한 건 정복자 알렉산더 대왕(알렉산드로스)과는 전혀 상관이 없다는 것입니다."},{"kind":"paragraph","text":"진으로 만드는 알렉산더는 금주법 이전에 만들어진 칵테일이며, 1916년 휴고 엔슬린(Hugo Ensslin)의 저서 Recipes for Mixed Drinls에 처음 기록으로 등장했습니다(그가 만들었다는 게 아님)."},{"kind":"paragraph","text":"브랜디 알렉산더는 누가 만들었는지는 알 수 없지만, 1930년 해리 크래독(Harry Craddock)의 저서 사보이 칵테일 북(The Savoy Cocktail Book)에서 처음 기록으로 등장하게 됩니다."},{"kind":"paragraph","text":"다만, 이때의 이름은 브랜디 알렉산더가 아닌 \"알렉산더 칵테일 넘버 2(Alexander Cocktail No.2)\"라는 이름으로 등장하며, 모든 재료가 동일한 비율로 소개됩니다."},{"kind":"paragraph","text":"이후 1937년에는 좀 더 최근의 레시피로 조정된 브랜디 알렉산더가 윌리엄 탈링(W.J Tarling)의 저서인 카페 로얄 칵테일 북(Cafe Royal Cocktail Book)에서 소개되기도 합니다."},{"kind":"paragraph","text":"브랜디 알렉산더는 많은 대중매체에서도 꾸준하게 등장하며 많은 사랑을 받아왔는데, 반대로 원형인 진으로 만드는 알렉산더는 그 유명세에 밀리게 되었습니다."},{"kind":"paragraph","text":"우리나라에서도 알렉산더 칵테일은 브랜디 알렉산더를 지칭할 확률이 아주아주아주 높습니다."},{"kind":"figure","src":"/articles/brandy-alexander/01.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"30ml 꼬냑 (Cognac)"},{"kind":"paragraph","text":"20ml 크렘 드 카카오 (Creme de Cacao)"},{"kind":"paragraph","text":"20ml 생크림 (Heavy Cream)"},{"kind":"paragraph","text":"가니시: 육두구"},{"kind":"figure","src":"/articles/brandy-alexander/02.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 가니시 이외의 재료를 셰이커에 넣어줍니다."},{"kind":"paragraph","text":"2. 셰이커에 얼음을 채우고, 셰이킹 해줍니다."},{"kind":"paragraph","text":"3. 차게 해 둔 칵테일 잔에 따라줍니다."},{"kind":"paragraph","text":"4. 칵테일 위에 육두구를 소량 갈아줍니다."},{"kind":"paragraph","text":"레시피는 다양하게 있는데, 좀 더 단 맛을 좋아한다고 하시면 1:1:1의 레시피를, 꼬냑의 캐릭터를 크리미한 초콜릿 캐릭터와 같이 즐기고 싶다고 하신다면 3:2:2의 레시피를 추천드립니다."},{"kind":"paragraph","text":"2:1:1의 레시피도 있긴 한데, 이 레시피는 도수가 높은 꼬냑으로 인해 알콜감이 튈 확률이 좀 높기 때문에 추천드리지는 않습니다. 만약 XO급 이상으로 만든다면 2:1:1도 괜찮겠네요."},{"kind":"paragraph","text":"개인적으로 브랜디 알렉산더에 추천드리는 꼬냑은 헤네시 VSOP로, 특유의 묵직한 단맛과 바닐라, 스파이스(향신료)의 캐릭터가 꽤나 잘 어울립니다."},{"kind":"paragraph","text":"브랜디 알렉산더는 크림과 카카오의 맛으로 인해 술맛도 별로 안 나고, 부드럽고 달달하며, 거기에 꼬냑 뉘앙스가 같이 나게 됩니다."},{"kind":"paragraph","text":"그렇기 때문에 술을 잘 못 마시는 사람이더라도 충분히 맛있게 한 잔을 다 마칠 수 있을 만한 디저트 칵테일입니다."}]'::jsonb, 'published', '2024-09-14T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'glen-scotia-exclusive-cask-for-korea-2024-tawny-port', 'spirits', '글렌스코시아 익스클루시브 캐스크 포 코리아 2024', '"글렌 스코시아"는 스코틀랜드 캠벨타운(Campbeltown)에 위치한 글렌 스코시아 증류소에서 만들어지는 위스키로, 게일어로 ''스코틀랜드의 계곡(Valley of the Scots)''이라는 뜻을 가지고 있다고 합니다.', '/articles/glen-scotia-exclusive-cask-for-korea-2024-tawny-port/00.webp',
  'https://blog.naver.com/shakinglikebartender/223582856831', false,
  '[{"kind":"figure","src":"/articles/glen-scotia-exclusive-cask-for-korea-2024-tawny-port/00.webp","width":966,"height":966},{"kind":"heading","text":"About The Whisky"},{"kind":"paragraph","text":"\"글렌 스코시아\"는 스코틀랜드 캠벨타운(Campbeltown)에 위치한 글렌 스코시아 증류소에서 만들어지는 위스키로, 게일어로 ''스코틀랜드의 계곡(Valley of the Scots)''이라는 뜻을 가지고 있다고 합니다."},{"kind":"paragraph","text":"글렌 스코시아 증류소는 1832년에 문을 열어 현재까지 운영되고 있는데, 이 당시에 캠벨타운에는 약 20~30여 개의 위스키 증류소가 존재했다고 합니다."},{"kind":"paragraph","text":"당시 스코틀랜드 전역에 약 130개의 증류소가 있었던 점을 고려하면 이 작은 마을이 빅토리아 시대 당시에 \"세계 위스키의 수도\"라 불렸다는 것에 고개가 끄덕여집니다."},{"kind":"paragraph","text":"이후 미국의 대공황, 금주령 및 세계대전 등으로 위스키 자체에 대한 수요가 줄어들면서 캠벨타운의 많은 증류소도 문을 닫게 되었는데, 글렌 스코시아는 현재까지 자리를 지키고 있습니다."},{"kind":"paragraph","text":"현재 캠벨타운에는 2000년에 글렌가일 증류소가 오픈하면서 스프링뱅크 증류소까지 3곳의 증류소가 가동되고 있으며, 최근에는 신생 증류소가 지어지고 있습니다."},{"kind":"paragraph","text":"글렌스코시아 익스클루시브 캐스크 포 코리아 2024는 세 가지 바틀로 나온 것으로 아는데, 제가 마셔본 것은 토니 포트 혹스헤드로, 그 외에 자메이카 럼 배럴, 올로로소 셰리 캐스크가 있다고 합니다."},{"kind":"figure","src":"/articles/glen-scotia-exclusive-cask-for-korea-2024-tawny-port/01.webp","width":966,"height":966},{"kind":"quote","text":"증류소: 글렌 스코시아"},{"kind":"quote","text":"위스키 타입: 싱글 몰트 위스키"},{"kind":"quote","text":"캐스크 정보: 토니 포트 혹스헤드, 8년 숙성"},{"kind":"quote","text":"도수: 56.8%"},{"kind":"figure","src":"/articles/glen-scotia-exclusive-cask-for-korea-2024-tawny-port/02.webp","width":966,"height":966},{"kind":"heading","text":"Nose"},{"kind":"paragraph","text":"- 포도 껍질, 말린 대추, 바닐라"},{"kind":"paragraph","text":"- 조금 뒤에 향이 급변함"},{"kind":"paragraph","text":"> 치즈 비스킷, 건포도"},{"kind":"paragraph","text":"- 향이 일반적인 포트 캐스크와는 좀 다르고, 향이 계속해서 변함"},{"kind":"heading","text":"Palate"},{"kind":"paragraph","text":"- 드라이한데 맛 자체는 꽤나 달다"},{"kind":"paragraph","text":"- 캐러멜, 바닐라, 우디함, 그래시(Grassy)"},{"kind":"paragraph","text":"- 탄닌감"},{"kind":"heading","text":"Finish"},{"kind":"paragraph","text":"- 화한 느낌(아마도 진저?)"},{"kind":"paragraph","text":"- 바닐라"},{"kind":"paragraph","text":"이 바틀이 정말 웃겼던 게 시간을 좀 두고 마시면 계속해서 향이 왔다 갔다 합니다. 처음에는 포트 캐스크의 캐릭터가 났다가 갑자기 아메리칸 캐스크의 캐릭터로 급변합니다."},{"kind":"paragraph","text":"그리고 향 중에 치즈 비스킷을 적어두었는데, 이 부분이 정말 인상 깊었습니다(바 사장님은 뽀또라 하심.... 근데 맞음....)."},{"kind":"paragraph","text":"최근 마신 바틀 중에 가장 재미있는 바틀 중 하나였으며, 저숙성 한정 바틀을 만들려면 안정적인 것보다는 이렇게 도파민 터지는 바틀을 만드는 게 좋을 것 같다는 생각이 드는 한 잔이었습니다."}]'::jsonb, 'published', '2024-09-13T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'pierre-de-segonzac-tres-vieille-reserve-extra', 'spirits', '피에르 드 세공작 트레뷰 리저브 엑스트라', '"피에르 드 세공작"은 라벨에 그려진 할아버지 "피에르 페랑(Pierre Ferrand)"에 의해서 2000년경에 만들어진 꼬냑 브랜드로 얼마 되지 않은 것 같지만, 사실 페랑 가문의 꼬냑 역사는 1702년 자크 페랑(Jacques Ferrand)에', '/articles/pierre-de-segonzac-tres-vieille-reserve-extra/00.webp',
  'https://blog.naver.com/shakinglikebartender/223581931252', false,
  '[{"kind":"figure","src":"/articles/pierre-de-segonzac-tres-vieille-reserve-extra/00.webp","width":966,"height":966},{"kind":"paragraph","text":"About The Cognac"},{"kind":"paragraph","text":"\"피에르 드 세공작\"은 라벨에 그려진 할아버지 \"피에르 페랑(Pierre Ferrand)\"에 의해서 2000년경에 만들어진 꼬냑 브랜드로 얼마 되지 않은 것 같지만, 사실 페랑 가문의 꼬냑 역사는 1702년 자크 페랑(Jacques Ferrand)에 의해 시작됩니다."},{"kind":"paragraph","text":"가문의 꼬냑을 생산하는 역사가 오래되었는데, 다만 많은 양을 큰 꼬냑 기업들에게 납품을 하고 소량만을 판매하였고, ''피에르 드 세공작''이라는 브랜드를 만든 지가 오래되지 않은 것뿐이라 할 수 있겠습니다."},{"kind":"paragraph","text":"꼬냑을 좋아하시는 분들이라면, 어디선가 피에르 페랑이라는 이름을 들어보셨을 텐데, 메종 페랑(Maison Ferrand)에서 나오는 꼬냑으로 동명의 ''피에르 페랑''이 있습니다."},{"kind":"paragraph","text":"사실 이 ''메종 페랑의 꼬냑 피에르 페랑''은 앞서 말씀드린 피에르 드 세공작의 창업주 할아버지의 이름을 딴 것이 맞기는 합니다. 이게 참 복잡한 사연인데 얘기하게 되면 너무 길어지니 시음기 이후에 적어두겠습니다."},{"kind":"paragraph","text":"여하튼 피에르 드 세공작은 꼬냑의 그랑 샹파뉴(Grande Champagne) 지역의 중심부인 세공작(Segonzac) 지역에 위치해있습니다."},{"kind":"paragraph","text":"피에르 드 세공작은 우니 블랑(Uni-Blanc)이라는 포도 품종을 단일으로 사용하고, 자체 포도원에서 수확한 포도만을 사용해서 자가증류하는 몇 안되는 부이이외르 드 크뤼(bouilleur de cru) 가문입니다."},{"kind":"paragraph","text":"피에르 드 세공작의 ''트레뷰 리저브 엑스트라''는 구매할 때 물어보니 평균 숙성 50년의 원액을 블렌딩한 것이라 하는데, 바틀 하단의 Lot.50을 확인하실 수 있습니다."},{"kind":"paragraph","text":"사실 이 Lot라는 표기는 평균 블렌딩된 원액의 숙성 연수, 증류 연대, 숙성 시작 연대 등 정립되지 않은 용어이기 때문에 판매자나 생산자의 얘기가 가장 정확합니다."},{"kind":"paragraph","text":"또한 꼬냑은 오크 숙성을 끝내고 유리병이나 항아리에 원액을 담아내더라도 후숙(또는 병숙)을 인정하기 때문에 적힌 연수 대로 오크 숙성을 했구나!라고 단정할 수 없기도 합니다."},{"kind":"figure","src":"/articles/pierre-de-segonzac-tres-vieille-reserve-extra/01.webp","width":966,"height":966},{"kind":"quote","text":"생산자: 피에르 드 세공작"},{"kind":"quote","text":"아펠라시옹: 그랑 샹파뉴"},{"kind":"quote","text":"포도 품종: 우니 블랑 100%"},{"kind":"quote","text":"캐스크: 리무쟁 오크"},{"kind":"quote","text":"숙성: 평균 50년 숙성된 원액의 블렌딩"},{"kind":"figure","src":"/articles/pierre-de-segonzac-tres-vieille-reserve-extra/02.webp","width":966,"height":966},{"kind":"heading","text":"Nose"},{"kind":"paragraph","text":"- 크루아상 같은 버터리함"},{"kind":"paragraph","text":"- 약간은 묵직한 달달함"},{"kind":"paragraph","text":"- 미묘하게 나는 오래 후숙된 과일 or 설탕에 졸인 핵과류 과일"},{"kind":"paragraph","text":"- 올스파이스 따위의 향신료"},{"kind":"heading","text":"Palate"},{"kind":"paragraph","text":"- 달달하고, 깔끔하고, 생각보다는 가벼운 맛"},{"kind":"paragraph","text":"- 건과일"},{"kind":"paragraph","text":"- 복잡하고도 다채로운 풍미 (이걸 설명하기 어렵다...)"},{"kind":"paragraph","text":"- 마지막에는 홍차의 쌉쌀한 끝 맛을 연상시키는 쌉쌀하고 우디한 맛이 입에 남음"},{"kind":"heading","text":"Finish"},{"kind":"paragraph","text":"-무겁지는 않지만 다소 복잡하며, 달큰 쌉쌀한 피니시"},{"kind":"paragraph","text":"장기 숙성된 (과하게 숙성되지 않은) 코냑은 란시오로 인해 아주 복합적인 캐릭터를 내는데, 개인적으로 이런 복합성을 좋아하면서도 사실 이걸 하나하나 캐릭터를 집으면서 글로 풀어내기는 상당히 어렵다고 생각됩니다."},{"kind":"paragraph","text":"그나마 가장 잘 느껴지는 점은 볼드체로 했으니 참고해 주세요."},{"kind":"paragraph","text":"피에르 페랑 할아버지는 왜 본인의 이름으로 꼬냑을 판매하지 않을까?에 대한 간략한(?) 정리"},{"kind":"paragraph","text":"피에르 드 세공작의 창업주 할아버지는 초기 메종 페랑(꼬냑 페랑)의 창업주들과 동업(또는 고용) 관계였으며, 이 과정에서 이들은 회사를 설립하고 \"피에르 페랑\"을 브랜드로 하여 꼬냑을 판매하였습니다."},{"kind":"paragraph","text":"이후 모종의 이유로 이들 간에 불화가 생기며 결별했고, 피에르 페랑(세공작)은 전 파트너들의 회사의 브랜드인 본인의 이름으로 꼬냑을 판매하기 시작합니다."},{"kind":"paragraph","text":"메종 페랑은 이에 위조 혐의로 소송을 제기하게 되었고, 결국 2000년에 법원은 메종 페랑의 손을 들어줬습니다."},{"kind":"paragraph","text":"정확하지는 않지만 어찌 됐건 피에르 페랑은 정당하게 메종 페랑의 브랜드이고, 회사 설립 전에 ''피에르 페랑''이라는 이름이나 명칭이 꼬냑 업계에서 유명했던 것이 아니었기 때문에 상표적으로 사용했다 볼 수 없어서 그런 것 같습니다."},{"kind":"paragraph","text":"결국 본인의 이름을 뺏긴 격이 된 피에르 페랑(세공작)은 피에르 드 세공작이라는 새로운 이름으로 꼬냑을 판매하게 되었고, 메종 페랑은 \"엘리 페랑(Elie Ferrand)\" 가문의 유산을 인수하여 꼬냑을 생산하고 있습니다."},{"kind":"paragraph","text":"두 페랑에 대한 자세한 이야기는 다른 글로 다시 풀어보겠습니다."}]'::jsonb, 'published', '2024-09-12T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'rusty-nail', 'cocktail', '러스티 네일 — 매력적인 스카치위스키와 드람부이의 콤비네이션', '"러스티 네일"은 직역하면 ''낡은 못''으로 칵테일의 색이 낡은 못과 비슷하다', '/articles/rusty-nail/00.webp',
  'https://blog.naver.com/shakinglikebartender/223580334379', false,
  '[{"kind":"figure","src":"/articles/rusty-nail/00.webp","width":966,"height":966},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"\"러스티 네일\"은 직역하면 ''낡은 못''으로 칵테일의 색이 낡은 못과 비슷하다 하여 붙은 이름이라는 설이 있으며, 영국 속어로 ''예스러운 것''이라는 뜻을 가지며 칵테일의 재료나 맛이 예스럽다는 점에서 이름이 붙었다는 설이 있습니다."},{"kind":"paragraph","text":"러스티 네일의 탄생 자체는 꽤 모호하지만, 드람부이가 상업화되었다고 하는 1910년대 이후에나 탄생한 것이 명확하며, 두 명의 칵테일 역사가 및 전문가에 의해 두 가지 설이 주류가 되고 있습니다."},{"kind":"figure","src":"/articles/rusty-nail/01.webp","width":966,"height":966},{"kind":"paragraph","text":"① 데이비드 원드리치 (David Wondrich)"},{"kind":"paragraph","text":"원드리치는 러스티 네일이 1937년 소개된 BIF라는 칵테일에서 시작되었다고 주장합니다."},{"kind":"paragraph","text":"이 BIF라는 칵테일은 1937년 영국 산업 박람회(British Industries Fair)에서 그 이름을 따서 베니먼(F. Benniman)이라는 사람에 의해 만들어졌으며, 현재 흔하게 알려진 러스티 네일에 비터가 소량 첨가된 칵테일입니다."},{"kind":"paragraph","text":"원드리치는 BIF에서 시작하여 이후 D&S, Little Club No.1, Mig-21 등의 이름으로 러스티 네일과 비슷한 칵테일이 존재했고, 결국에 출처는 확실하지는 않지만 현재의 레시피와 이름이 최종적으로 살아남았다고 주장합니다."},{"kind":"paragraph","text":"② 데일 데그로프 (Dale DeGroff)"},{"kind":"paragraph","text":"데그로프는 러스티 네일이 1960년대 초에 뉴욕 맨해튼에 위치한 21 클럽(21 Club)이라는 레스토랑에서 일하던 한 바텐더가 만들어낸 것이 좀 더 설득력 있다고 주장합니다."},{"kind":"paragraph","text":"그러한 근거는 당시에 미국에서 러스티 네일이 유행하기도 했고, 21 Club에서는 브랜디와 베네딕틴으로 만드는 B&B를 만들어냈는데, 러스티 네일은 B&B와 꽤나 유사한 형식의 칵테일이기 때문이라는 것입니다."},{"kind":"paragraph","text":"다만, 데그로프 자신 또한 이 근거를 입증할 수 있는 자료나 증거를 찾아내지는 못하였다고 합니다."},{"kind":"paragraph","text":"1963년 드람부이 회사의 회장은 뉴욕 타임즈에서 러스티 네일이 21 Club에서 만들어졌다는 주장을 지지했는데, 이것도 곧이곧대로 믿기 어렵긴 합니다."},{"kind":"paragraph","text":"21 Club은 많은 유명 인사들이 다니던 곳으로 유명했는데, 드람부이 회사의 입장에서는 21 Club의 유명세를 바탕으로 러스티 네일과 드람부이를 광고할 스토리를 하나 얻을 수 있으니 손해 볼 것이 없었겠죠."},{"kind":"figure","src":"/articles/rusty-nail/02.webp","width":966,"height":427},{"kind":"figure","src":"/articles/rusty-nail/03.webp","width":966,"height":419},{"kind":"paragraph","text":"여담으로 \"러스티 네일\"은 상표로 등록된 몇 안 되는 칵테일 중 하나로, 1960년대에 미국에서 상표등록이 되었으며, 우리나라에서도 1990년대 후반에 등록된 바 있습니다."},{"kind":"figure","src":"/articles/rusty-nail/04.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"45ml 싱글몰트 또는 블렌디드 스카치 위스키 (Scotch Whisky)"},{"kind":"paragraph","text":"15ml 드람부이 (Drambuie)"},{"kind":"paragraph","text":"옵션 가니시: 레몬 껍질 (Lemon Peel)"},{"kind":"figure","src":"/articles/rusty-nail/05.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 모든 재료를 온더락 잔에 넣어줍니다."},{"kind":"paragraph","text":"2. 얼음을 채워주고, 가볍게 스터 해줍니다."},{"kind":"paragraph","text":"3. **레몬 껍질에서 오일을 짜넣어줍니다(옵션)."},{"kind":"paragraph","text":"러스티 네일은 꿀과 허브 캐릭터의 드람부이와 다양한 캐릭터의 여러 스카치 위스키의 콤비네이션이 돋보이는 칵테일입니다."},{"kind":"paragraph","text":"러스티 네일의 골자는 물론 드람부이의 꿀과 허브감이지만, 어떤 스카치 위스키를 사용하냐에 따라 맛이 다양하게 바뀝니다."},{"kind":"paragraph","text":"피트가 없는 스카치를 사용한다면 좀 더 달달한 느낌의 러스티 네일이 만들어지며, 강한 피트 캐릭터가 있는 스카치를 사용하더라도 생각보다 피트감이 강하지 않으며, 피트·꿀·허브감이 멋들어진 삼박자를 이룹니다."},{"kind":"paragraph","text":"개인적으로는 라가불린 16년으로 만드는 러스티 네일을 좋아하는데, 드람부이의 꿀과 허브 캐릭터가 라가불린 특유의 피트와 곡식의 달달한 캐릭터가 절묘한 밸런스를 이루며, 마시고 난 후에는 살짝 쌈쌀함이 입안에 남습니다."},{"kind":"paragraph","text":"다만, 라가불린 16년을 기주로 해서 바에서 마시기에는 너무 비싸지게 됩니다. 그럴 때는 드람부이가 탄생한 스카이(Skye)섬에서 생산되는 탈리스커(Talisker) 10년을 기주로 하는 것도 센스 있는 주문이겠네요."},{"kind":"paragraph","text":"더 저렴하게는 피트 캐릭터가 특징인 조니워커 블랙 또는 더블 블랙을 추천드립니다."},{"kind":"paragraph","text":"러스티 네일은 스카치와 드람부이의 비율이 최근에는 3:1이 일반적인데, 2:1 ~ 4:1까지 입맛 또는 사용하는 스카치의 종류에 따라 조정하면 되겠습니다."}]'::jsonb, 'published', '2024-09-11T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'octomore-15-series', 'spirits', '브룩라디 증류소, 옥토모어 15 시리즈 공개 — 시리즈 사상 두 번째로 높은 ppm을 기록', '옥토모어(Octomore)는 브룩라디(Bruichladdich)와 포트샬롯(Port Charlotte)과 함께 "브룩라디 증류소"의 코어 라인 중 하나로, 일반적으로 매년 xx.1 / xx.2 / xx.3 (+xx.4/없는 해도 있음)의 번호를 달고', '/articles/octomore-15-series/00.webp',
  'https://blog.naver.com/shakinglikebartender/223580412866', false,
  '[{"kind":"figure","src":"/articles/octomore-15-series/00.webp","width":966,"height":966,"caption":"사진 출처: 브룩라디 홈페이지"},{"kind":"paragraph","text":"옥토모어(Octomore)는 브룩라디(Bruichladdich)와 포트샬롯(Port Charlotte)과 함께 \"브룩라디 증류소\"의 코어 라인 중 하나로, 일반적으로 매년 xx.1 / xx.2 / xx.3 (+xx.4/없는 해도 있음)의 번호를 달고 출시되는 매번이 일종의 한정판인 특이한 위스키입니다."},{"kind":"paragraph","text":"옥토모어는 수퍼 헤빌리 피티드(Super Heavily Peated)가 가장 큰 특징인 위스키로, 페놀 수치가 보통 100ppm을 넘기는 게 일반적이며, 페놀 수치가 높은 편에 속하는 아드벡이 일반적으로 50~60ppm인 것에 비해서도 엄청나게 높은 걸 알 수 있죠."},{"kind":"paragraph","text":"브룩라디 증류소에서는 올해 릴리스 되는 옥토모어 15 시리즈에 대한 정보를 공개했습니다."},{"kind":"paragraph","text":"옥토모어 15 시리즈에 대한 정보를 정리해 보자면 다음과 같습니다."},{"kind":"paragraph","text":"옥토모어 15.1"},{"kind":"paragraph","text":"- 보리 정보: 100% Scottish Mainland Concerto barley"},{"kind":"paragraph","text":"- 캐스크 정보: 퍼스트필 버번 배럴과 리차링한 엑스 버번 캐스크, 5년 숙성"},{"kind":"paragraph","text":"(First-fill bourbon barrels with re-charred ex-bourbon casks)"},{"kind":"paragraph","text":"- 증류: 2017년 보리 수확 후 2018년 증류"},{"kind":"paragraph","text":"- 페놀 수치: 108.2 ppm"},{"kind":"paragraph","text":"- 도수: 59.1%"},{"kind":"paragraph","text":"- 출시 가격: 140 파운드"},{"kind":"paragraph","text":"옥토모어 15.2"},{"kind":"paragraph","text":"- 보리 정보: 100% Scottish Mainland Concerto barley"},{"kind":"paragraph","text":"- 캐스크 정보: 세컨필 와인 캐스크와 세컨필 버번 캐스크에서 숙성한 원액을 섞고, 2023년 퍼스트필 꼬냑 캐스크에 담아 피니시함, 5년 숙성"},{"kind":"paragraph","text":"(Originally filled into a combination of second fill wine casks and second fill bourbon casks. In 2023 the spirit was recasked into first fill Cognac casks for the remainder of its maturation.)"},{"kind":"paragraph","text":"- 증류: 2017년 보리 수확 후 2018년 증류"},{"kind":"paragraph","text":"- 페놀 수치: 108.2 ppm"},{"kind":"paragraph","text":"- 도수: 57.9%"},{"kind":"paragraph","text":"- 출시 가격: 155 파운드"},{"kind":"paragraph","text":"옥토모어 15.3"},{"kind":"paragraph","text":"- 보리 정보: 100% Islay grown Concerto barley from Octomore Farm"},{"kind":"paragraph","text":"- 캐스크 정보: 퍼스트필 버번 캐스크와 스페인 헤레스 지방의 페르난도 데 카스티야의 퍼스트필 올로로소 혹스헤드에서 풀 숙성, 5년 숙성"},{"kind":"paragraph","text":"(Full term maturation in first fill bourbon casks and first fill Oloroso hogsheads from Fernando de Castilla, Jerez, Spain.)"},{"kind":"paragraph","text":"- 증류: 2017년 보리 수확 후 2018년 증류"},{"kind":"paragraph","text":"- 페놀 수치: 307.2 ppm"},{"kind":"paragraph","text":"- 도수: 61.3%"},{"kind":"paragraph","text":"- 출시 가격: 195 파운드"},{"kind":"paragraph","text":"옥토모어 15 시리즈에서 가장 주목할 만한 점은 옥토모어 시리즈 사상 두 번째로 높은 ppm의 옥토모어가 출시된다는 점입니다."},{"kind":"paragraph","text":"시리즈 사상 가장 높은 ppm의 옥토모어는 08.3으로 ppm이 309.1이었으며, 이번 시리즈의 15.3은 그 뒤를 잇는 307.2 ppm이라는 높은 수치를 기록하게 되었습니다."},{"kind":"paragraph","text":"물론 ppm이 높다고 숙성 후의 위스키가 피트감이 무조건 강하다 할 수는 없지만, 15.3은 5년 밖에 숙성하지 않았고, 이전에 마셔본 08.3의 피트감이 상당히 강했기 때문에 피트 러버로서는 기대가 될 수밖에 없네요."},{"kind":"paragraph","text":"개인적으로 나중에 일본에 출시될 때 한 병 정도 집어와서 리뷰해보고 싶습니다."}]'::jsonb, 'published', '2024-09-11T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'scotland-whisky-ep12', 'spirits', '스코틀랜드 위스키 여행 ep12 — 아일라에서 캠벨타운으로', '아일라섬에서 페리를 타고 나오면 케나크레이그(Kennacraig) 페리 터미널에 도착을 하게 된다. 캠벨타운이나 그 반대편인 글래스고로 가는 버스는 여기서 타면 된다.', '/articles/scotland-whisky-ep12/00.webp',
  'https://blog.naver.com/shakinglikebartender/223579235249', false,
  '[{"kind":"figure","src":"/articles/scotland-whisky-ep12/00.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep12/01.webp","width":966,"height":1288},{"kind":"paragraph","text":"아일라섬에서 페리를 타고 나오면 케나크레이그(Kennacraig) 페리 터미널에 도착을 하게 된다. 캠벨타운이나 그 반대편인 글래스고로 가는 버스는 여기서 타면 된다."},{"kind":"paragraph","text":"사실 페리 도착 시간과 버스 도착 시간이 진짜 이상하다. 몇 분 차로 버스가 먼저 도착해서 출발하는 시간대 거나, 약 20분 차이로 페리가 먼저 도착하는 빡빡한 시간대 거나. 그렇지 않으면 몇 시간이나 차이가 나버린다."},{"kind":"paragraph","text":"그렇기 때문에 시간 계산을 잘해서 예약을 하자. 우린 한 20분 페리가 먼저 도착하는 걸 예약했는데 페리가 생각보다 늦게 도착하는 바람에 버스 시간이 지나서 내리게 되었다."},{"kind":"paragraph","text":"내리자마자 달려서 버스를 찾는데, 터미널 직원에게 물어보니 아직 안 왔다고 하더라.... 페리 도착이 늦고, 버스 도착도 덩달아 늦어서 시간이 맞아버리는 이상한 상황."},{"kind":"paragraph","text":"결국 버스 잘 탔고, 몇 시간을 걸려서 캠벨타운에 도착했다. 일요일은 스프링뱅크 증류소나 카덴헤드 샵이 오픈을 안 해서 밖에서만 둘러보고 다음날을 기약했다."},{"kind":"figure","src":"/articles/scotland-whisky-ep12/02.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep12/03.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep12/04.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep12/05.webp","width":966,"height":1288},{"kind":"paragraph","text":"캠벨타운에서 오래 있지는 않았지만, 음식을 추천하자면 \"홈 웍(Home Wok)\"이라는 포장 전문 중국집을 강력하게 추천한다."},{"kind":"figure","src":"/articles/scotland-whisky-ep12/06.webp","width":966,"height":966},{"kind":"paragraph","text":"구글 평점을 기준으로 4.6점으로 다른 캠벨타운 음식점들보다 높은 편인데다가, 일단 가격이 싸면서도 양이 정말 많다. 가게 주인이 아시아인인데 우릴 보고 같은 아시아인이라 반가워 해줬어서 양을 더 많이 준 걸지도 모르겠다."},{"kind":"paragraph","text":"맛도 한국인 입맛에 맞는 데다가 정말 맛있었다. 딱 서양 스타일의 중국 음식 같은 느낌."},{"kind":"paragraph","text":"웬만해서는 식당 추천은 안 하는 편인데, 맛있고 가성비 좋은 음식점이 없는 캠벨타운 여행자들을 위해서 꼭 추천하고 싶은 식당이다."}]'::jsonb, 'published', '2024-09-10T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'long-island-iced-tea', 'cocktail', '롱아일랜드 아이스티 — 칵테일계의 원기옥', '"롱아일랜드 아이스티"는 서양에서는 1970~1980년대(특히 미국)에 큰 인기를 끌었으며, 우리나라에서도 예전부터 바 뿐만 아니라 펍에서도 흔하게 볼 수 있을 정도로 잘 알려진 칵테일입니다.', '/articles/long-island-iced-tea/00.webp',
  'https://blog.naver.com/shakinglikebartender/223577739711', false,
  '[{"kind":"figure","src":"/articles/long-island-iced-tea/00.webp","width":966,"height":966},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"\"롱아일랜드 아이스티\"는 서양에서는 1970~1980년대(특히 미국)에 큰 인기를 끌었으며, 우리나라에서도 예전부터 바 뿐만 아니라 펍에서도 흔하게 볼 수 있을 정도로 잘 알려진 칵테일입니다."},{"kind":"paragraph","text":"1972년 뉴욕 주의 롱아일랜드에 위치한 오크 비치 인(Oak Beach Inn/OBI)에서 칵테일 콘테스트가 열렸고, 칵테일에 트리플 섹을 넣을 것을 요구했다고 합니다."},{"kind":"paragraph","text":"당시에 OBI에서 일하던 로버트 \"로즈버드\" 버트(Robert \"Rosebud\" Butt)는 이 콘테스트에 참가하기 위해 이 칵테일을 만들었다고 합니다."},{"kind":"paragraph","text":"로버트 버트가 회상하기로는 \"만들고 나서 5년이 지나고는 어디에서든 이 칵테일을 판매했다.\"라고 하며, 1985년 뉴욕 타임스는 롱아일랜드 아이스티라는 독한 칵테일이 전국의 술집을 휩쓸고 있다고 보도하기도 할 정도였다고 합니다."},{"kind":"paragraph","text":"롱아일랜드 아이스티는 기주라 할 게 없고, 5개의 높은 도수의 술이 동률로 들어가 칵테일로서는 \"근본 없는\" 조합으로 이루어져 있는데 사실 이게 인기의 포인트라 할 수 있습니다."},{"kind":"paragraph","text":"들어가는 술을 모두 싸게 구할 수 있어 700미리 병 기준으로 40잔 이상 만들 수 있는 데다가, 잔에 얼음 채우고 대충 넣어서 쉽게 만들 수도 있어서 캐주얼하고, 도수가 높아 가격에 비해 가성비가 좋은 등 친구들이 삼삼오오 모여서 간단하게 기분 내며 마실 수 있는 칵테일이기 때문입니다."},{"kind":"paragraph","text":"\"롱아일랜드 아이스티\"라는 이름에서 립톤 사의 아이스티 같은 복숭아 티 같은 맛이 날 거라 생각하기 쉬운데, 사실 그런 맛이 나지는 않고 색깔이 아이스티와 비슷해서 붙은 이름입니다."},{"kind":"figure","src":"/articles/long-island-iced-tea/01.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"15ml 진 (Gin)"},{"kind":"paragraph","text":"15ml 화이트 럼 (White Rum)"},{"kind":"paragraph","text":"15ml 블랑코 데킬라 (Blanco Tequila)"},{"kind":"paragraph","text":"15ml 보드카 (Vodka)"},{"kind":"paragraph","text":"15ml 코앵트로 (Cointreau)"},{"kind":"paragraph","text":"30ml 레몬즙 (Lemon Juice)"},{"kind":"paragraph","text":"10ml 설탕 시럽 (Simple Syrup)"},{"kind":"paragraph","text":"**콜라 소량"},{"kind":"paragraph","text":"가니시: 레몬 웨지 or 레몬 휠"},{"kind":"paragraph","text":"**콜라는 양을 너무 많이 넣지 않도록 해줍니다(약 30-45ml)."},{"kind":"paragraph","text":"칵테일의 제작자인 로버트 버트는 \"색을 내기 위해 콜라를 소량 넣는다(a little Coke just to make the color).\"라고 한 걸 보면 콜라는 맛보다는 그저 아이스티 같은 색을 내기 위해서 넣는 것에 불과합니다."},{"kind":"figure","src":"/articles/long-island-iced-tea/02.webp","width":966,"height":966},{"kind":"figure","src":"/articles/long-island-iced-tea/03.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 콜라를 제외한 모든 재료를 셰이커에 넣어줍니다."},{"kind":"paragraph","text":"2. 셰이커에 얼음을 채우고, 셰이킹 해줍니다."},{"kind":"paragraph","text":"3. 얼음을 채운 긴 잔에 부어줍니다."},{"kind":"paragraph","text":"4. 색을 내기 위해 콜라를 소량 부어줍니다."},{"kind":"paragraph","text":"5. 레몬으로 가니시해줍니다."},{"kind":"figure","src":"/articles/long-island-iced-tea/04.webp","width":966,"height":966},{"kind":"paragraph","text":"롱아일랜드 아이스티는 대학 시절에 누구나 한 번쯤은 마셔봤을 법한 칵테일로, 펍에서도 아주 쉽게 찾아볼 수 있습니다."},{"kind":"paragraph","text":"개인적인 입맛으로는 그렇게 맛있는 칵테일이라 생각하지는 않지만, 우리나라 바텐더들 중에서는 롱아일랜드 아이스티를 좋아해 이를 개량한 사람들도 종종 있습니다."},{"kind":"paragraph","text":"롱아일랜드 아이스티는 레시피가 사람마다 달라서 너무 종류가 많은데, 잔의 용량이나 만드는 방법에 따라서 술을 얼마나 넣을지를 정해야 합니다."},{"kind":"paragraph","text":"예를 들어 제가 사용한 잔은 용량이 360ml로 크지 않은 편이고, 셰이킹 해서 다일루션이 더 생겼기 때문에 술을 15ml씩 사용했습니다."},{"kind":"paragraph","text":"롱아일랜드 아이스티는 40도의 술을 기준으로 적어도 두 잔 반 이상의 용량이 술로 들어가기 때문에 마실 때에는 취하지 않도록 조심해야 합니다."}]'::jsonb, 'published', '2024-09-09T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'americano', 'cocktail', '아메리카노 — 커피가 아니라 칵테일, 미국인이 아니라 이탈리아인입니다!!', '흔히 커피로 오해받기 쉬운 "아메리카노 칵테일"은 그 이름과는 다르게 커피나 미국적인 요소가 하나도 들어가지 않은, 이탈리아에서 탄생한 칵테일입니다.', '/articles/americano/00.webp',
  'https://blog.naver.com/shakinglikebartender/223574457761', false,
  '[{"kind":"figure","src":"/articles/americano/00.webp","width":500,"height":500},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"흔히 커피로 오해받기 쉬운 \"아메리카노 칵테일\"은 그 이름과는 다르게 커피나 미국적인 요소가 하나도 들어가지 않은, 이탈리아에서 탄생한 칵테일입니다."},{"kind":"paragraph","text":"아메리카노 칵테일의 기원에 대해서는 두 가지 이야기가 있습니다."},{"kind":"paragraph","text":"① 1860년대에 가스파레 캄파리(Gaspare Campari)가 아메리카노 칵테일에 들어가는 재료인 캄파리라는 술을 만들었고, 자신의 바에서 캄파리를 사용한 칵테일을 제공하였습니다."},{"kind":"paragraph","text":"이 바에서는 캄파리와 스윗 버무스가 동량으로 들어가는 ''밀라노-토리노(Milano-Torino)''라는 칵테일을 탄산수로 희석한 칵테일을 제공하였는데, 이 칵테일이 아메리카노입니다."},{"kind":"paragraph","text":"다만, 아메리카노라는 이름이 붙은 건 금주법 시대 당시에 미국 관광객의 인기를 얻으면서 붙게 되었다고 합니다."},{"kind":"paragraph","text":"② 1920년대 미국 금주법 시대에 미국 관광객들이 이탈리아에서 ''밀라노-토리노''의 쌉쌀한 맛을 좀 더 편하게 즐기기 위해서 탄산수를 넣었고, 이게 미국 관광객들의 인기를 끌어서 ''아메리카노''라 이름을 붙인 칵테일이 탄생했다고 합니다."},{"kind":"paragraph","text":"시기에 차이가 있지만, 중요한 건 아메리카노 칵테일이 ''밀라노-토리노''라는 칵테일에서 시작된 것이고, 후에 ''네그로니(Negroni)''라는 칵테일에도 영향을 미치게 된다는 점입니다."},{"kind":"paragraph","text":"여담으로, 소설 제임스 본드 시리즈의 첫 번째 작품인 카지노 로얄에서 애주가인 제임스 본드가 가장 첫 번째로 주문한 칵테일이 아메리카노입니다."},{"kind":"figure","src":"/articles/americano/01.webp","width":499,"height":499},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"30ml 캄파리 (Campari)"},{"kind":"paragraph","text":"30ml 스윗 버무스 (Sweet Vermouth, Italian)"},{"kind":"paragraph","text":"탄산수 적당량"},{"kind":"paragraph","text":"가니시: 오렌지 껍질 or 오렌지 휠 반쪽"},{"kind":"figure","src":"/articles/americano/02.webp","width":500,"height":500},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 얼음을 채운 긴 잔에 캄파리와 버무스를 넣어줍니다."},{"kind":"paragraph","text":"2. 바스푼으로 살짝 스터해서 온도를 낮춰줍니다."},{"kind":"paragraph","text":"3. 탄산수를 넣어줍니다."},{"kind":"paragraph","text":"4. 오렌지 껍질을 쓰는 경우, 칵테일에 오일을 짜고 넣어줍니다."},{"kind":"paragraph","text":"or"},{"kind":"paragraph","text":"오렌지 휠 반 쪽을 쓰는 경우 그냥 넣어줍니다."},{"kind":"figure","src":"/articles/americano/03.webp","width":500,"height":500},{"kind":"paragraph","text":"아메리카노는 유럽에서 식전주로 아주 인기가 많은 칵테일로, 달큰쌉쌀하고 허브감이 탄산과 함께 상쾌하게 다가오는 것이 입맛을 돋구기 딱 좋은 칵테일입니다."},{"kind":"paragraph","text":"오렌지 껍질을 가니시로 쓰는 경우에는 쌉쌀한 오렌지 캐릭터가, 오렌지 휠을 가니시로 쓰는 경우에는 묵직하게 달큰한 오렌지의 캐릭터가 좀 더 두드러집니다."},{"kind":"paragraph","text":"확실히 식전주로 아주 좋은 칵테일이며, 식후에도 입을 싹 씻어줄만한 칵테일이기도 합니다."},{"kind":"paragraph","text":"참고로 저는 작은 용량의 잔을 사용해서 30미리씩 넣었으니, 사용하시는 잔에 따라 용량을 맞춰서 드시면 되겠습니다."}]'::jsonb, 'published', '2024-09-06T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'belle-aile', 'cocktail', '벨 에르 — 산토리 칵테일 어워드 1996 대회 우승작', '"벨 에르"는 1996년 산토리 칵테일 어워드 대회 우승작으로, 당시 오사카에 위치한 바 알폰테(Bar Alponte)에서 근무하던 일본의 후지타 토시아키 바텐더가 만들어낸 칵테일입니다.', '/articles/belle-aile/00.webp',
  'https://blog.naver.com/shakinglikebartender/223573457961', false,
  '[{"kind":"figure","src":"/articles/belle-aile/00.webp","width":966,"height":966},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"\"벨 에르\"는 1996년 산토리 칵테일 어워드 대회 우승작으로, 당시 오사카에 위치한 바 알폰테(Bar Alponte)에서 근무하던 일본의 후지타 토시아키 바텐더가 만들어낸 칵테일입니다."},{"kind":"paragraph","text":"후지타 토시아키씨는 1997년에는 독립을 하여 오사카의 우메다에 하버 인(Bar Habour Inn)이라는 바를 차리게 되며, 현재에도 바의 메뉴에 한 자리를 차지하고 있다고 합니다."},{"kind":"paragraph","text":"하버 인이라는 이름은 아일라섬의 도시 보모어에서 보모어 증류소 근처에 있는 숙소인 하버 인(Harbour Inn)에서 이름을 따온 것으로, 후지타씨가 아일라 여행을 할 때 묵은 숙소라 합니다."},{"kind":"paragraph","text":"칵테일의 이름인 \"벨 에르 (Belle Aile)\"라는 단어는 프랑스어로, \"아름다운 날개\"라는 의미라 합니다."},{"kind":"figure","src":"/articles/belle-aile/01.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"30ml  VSOP급 꼬냑 (Cognac VSOP)"},{"kind":"paragraph","text":"20ml 크렘 드 피치 (Creme de Peche)"},{"kind":"paragraph","text":"10ml 레몬즙 (Lemon Juice)"},{"kind":"paragraph","text":"5ml 블루 큐라소 (Blue Curacao)"},{"kind":"figure","src":"/articles/belle-aile/02.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 셰이커에 모든 재료를 넣어줍니다."},{"kind":"paragraph","text":"2. 셰이커에 얼음을 채우고, 셰이킹해줍니다."},{"kind":"paragraph","text":"3. 차게 해둔 잔에 따라줍니다."},{"kind":"paragraph","text":"벨 에르는 꼬냑, 크렘 드 피치, 블루큐라소, 레몬이라는 좀처럼 보기 드문 조합의 칵테일로, 재료 조합이나 색깔이나 어딘가모르게 킹스 밸리(King''s Valley)를 떠오르게 하기도 합니다."},{"kind":"paragraph","text":"맛은 꽤나 달달한 편인데, 꼬냑과 복숭아, 시트러스의 캐릭터가 아주 잘 어울리며, 이 맛들이 어우러지면서 약간은 리치 같은 캐릭터로도 느껴집니다. 약간 과일맛이 들어간 플레이버드 티 같기도 하네요."},{"kind":"paragraph","text":"도수 자체는 그렇게 낮은 편은 아님에도 술을 잘 못마시는 사람들에게 추천하고 싶습니다."},{"kind":"paragraph","text":"원 레시피는 꼬냑을 크루보아제(Courvoisier)를 사용했는데, 개인적으로 헤네시 VSOP는 우디함이 강한 편이라 어울리지 않는다고 생각됩니다."},{"kind":"paragraph","text":"피치 리큐르의 경우도 원래는 다른 브랜드를 사용하는데, 피치트리를 사용하는 경우에는 레시피 조정이 필요해보입니다."}]'::jsonb, 'published', '2024-09-05T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'pimms-cup', 'cocktail', '핌스 컵 — 오이, 여름, 제철과일을 더한 윔블던의 칵테일', '"핌스컵"은 영국의 전통적인 칵테일로, 과일컵(Fruit Cup)의 일종입니다.', '/articles/pimms-cup/00.webp',
  'https://blog.naver.com/shakinglikebartender/223572075568', false,
  '[{"kind":"figure","src":"/articles/pimms-cup/00.webp","width":966,"height":966},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"\"핌스컵\"은 영국의 전통적인 칵테일로, 과일컵(Fruit Cup)의 일종입니다. 과일컵이란 과일, 기주, 향신료나 허브(또는 향신료나 허브가 들어간 주류), 탄산음료로 만들어지는 칵테일입니다. 일종의 펀치라고 볼 수도 있죠."},{"kind":"paragraph","text":"19세기 영국에서는 이 과일컵이 인기가 있었는데, 식당마다 저마다의 레시피대로 과일컵을 판매하였으며, 이 칵테일들을 작은 No.1 사이즈의 탱커드 잔(Tankard)에 담아서 서브했다고 합니다."},{"kind":"paragraph","text":"1840년에는 제임스 핌(James Pimm)이라는 사람이 런던에 위치한 본인의 식당인 핌스 오이스터 웨어하우스(Pimm''s Oyster Warehouse)의 바에서 과일컵을 제공하였습니다."},{"kind":"paragraph","text":"이 과일컵이 후에 핌스 넘버 원 컵(Pimm''s No.1 Cup)이라 불리게 되었고, 탄산음료와 과일, 허브를 더해서 간단하게 만들 수 있도록 핌스 넘버 원(Pimm''s No.1)이라는 진을 기반으로 하는 리큐르를 판매하게 됩니다."},{"kind":"paragraph","text":"1971년에는 최초의 핌스 바(Pimm''s Bar)가 윔블던 테니스 토너먼트에서 오픈하였으며, 켄터키 더비와 민트 줄렙처럼 핌스 컵은 윔블던 테니스 토너먼트를 상징하는 주류가 되었다고 할 정도로 인기를 끌었다고 합니다."},{"kind":"paragraph","text":"얼마나 인기가 많았는지 영국에서 여름의 핌스 컵의 수요가 오이의 수요를 늘릴 정도였다고 합니다."},{"kind":"figure","src":"/articles/pimms-cup/01.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"45ml 핌스 넘버 원 (Pimm''s No.1)"},{"kind":"paragraph","text":"7.5ml 레몬즙 (Lemon Juice)"},{"kind":"paragraph","text":"진저에일 적당량"},{"kind":"paragraph","text":"가니시: 민트, 오이, 시트러스(레몬, 오렌지 등)"},{"kind":"paragraph","text":"옵션 가니시: 딸기, 기타 제철과일"},{"kind":"figure","src":"/articles/pimms-cup/02.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 긴 잔에 얼음을 채워줍니다."},{"kind":"paragraph","text":"2. 모든 재료를 넣고 살짝 저어줍니다."},{"kind":"paragraph","text":"3. 가니시로 장식해줍니다."},{"kind":"paragraph","text":"핌스 컵은 핌스의 살짝 쌉쌀하고 달달한 맛에 과일의 달달함, 오이의 시원함, 생강의 알싸함에 약간의 탄산까지 나는 아주 복합적인 캐릭터이지만 마시기 쉬운 칵테일입니다."},{"kind":"paragraph","text":"핌스 컵은 여름에 마시는 칵테일이라는 인식이 강한데, 그 맛을 보면 동의히지 않을 수가 없습니다."},{"kind":"paragraph","text":"영국에서는 딸기를 넣는 것이 일반적인 거 같은데, 영국의 딸기는 3월부터 12월까지 재배되지만 우리나라는 제철이 겨울이라 굳이 넣지는 않았습니다. 다른 제철 과일을 넣어도 괜찮구요."},{"kind":"paragraph","text":"오이는 웬만하면 넣는 걸 추천드리는 것이, 오이의 시원한 맛이 아주 상쾌하게 다가옵니다."}]'::jsonb, 'published', '2024-09-04T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'shirley-temple', 'cocktail', '셜리 템플 — 쉬어가는 타이밍에 마시는 논알콜 칵테일', '"셜리 템플"은 1930~1940년대 할리우드의 전설적인 아역배우인 셜리 템플(Shirley Jane Temple)의 이름을 딴 무알콜 칵테일로, 무알콜 칵테일 중 가장 인지도가 높은 칵테일입니다.', '/articles/shirley-temple/00.webp',
  'https://blog.naver.com/shakinglikebartender/223570716549', false,
  '[{"kind":"figure","src":"/articles/shirley-temple/00.webp","width":966,"height":966},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"\"셜리 템플\"은 1930~1940년대 할리우드의 전설적인 아역배우인 셜리 템플(Shirley Jane Temple)의 이름을 딴 무알콜 칵테일로, 무알콜 칵테일 중 가장 인지도가 높은 칵테일입니다."},{"kind":"paragraph","text":"그 기원에 관련된 설이 정말 다양한데, 기본적인 골조는 레스토랑에서 미성년자였던 셜리 템플이 술을 마시지 못해 그녀를 위해 바텐더가 만들어준 무알콜 칵테일이라는 점입니다."},{"kind":"paragraph","text":"기본적으로는 그레나딘 시럽에 진저에일을 더하는 칵테일인데, 이후에 레몬즙이나 라임즙을 소량 추가한다거나, 진저에일을 레모네이드, 레몬라임소다(ex. 스프라이트), 콜라 등으로 변경하는 식으로 개인 기호에 따라 만들어지게 되었습니다."},{"kind":"paragraph","text":"셜리 템플에 술을 소량 넣어서 \"더티 셜리(Dirty Shirley)\"라는 칵테일으로 마신다고도 합니다만, 굳이 시도할 것 같지는 않네요."},{"kind":"figure","src":"/articles/shirley-temple/01.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"10ml 그레나딘 시럽 (Grenadine)"},{"kind":"paragraph","text":"진저에일/진저비어/스프라이트/콜라"},{"kind":"figure","src":"/articles/shirley-temple/02.webp","width":966,"height":966},{"kind":"figure","src":"/articles/shirley-temple/03.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 긴 잔에 얼음을 채워주고, 그레나딘을 부어줍니다."},{"kind":"paragraph","text":"2. **탄산음료를 살짝 부어주고, 잘 섞어줍니다."},{"kind":"paragraph","text":"3. 탄산음료를 더 부어주고,"},{"kind":"paragraph","text":"바스푼으로 얼음을 한두 번 위아래로 들어올려줍니다."},{"kind":"paragraph","text":"**그레나딘은 당도가 높아 가라앉아있기 때문에 탄산음료를 모두 부어 준 후에 섞으려면 잘 섞이지 않고, 탄산이 많이 빠지게 됩니다."},{"kind":"paragraph","text":"그러니 그레나딘이 바닥에 가라앉아있지 않게 탄산음료를 소량 넣어서 잘 섞어주고, 나머지 탄산음료를 따라서 잘 섞이면서 탄산이 최대한 남게 만들어주는 것이 좋습니다."},{"kind":"figure","src":"/articles/shirley-temple/04.webp","width":966,"height":966},{"kind":"paragraph","text":"셜리 템플의 재밌는 점은 본인 입맛에 맞춰서 탄산음료를 넣으면 된다는 점입니다. 저는 진저비어가 남아있어서 진저비어를 썼는데, 생강의 캐릭터가 다소 강하네요."},{"kind":"paragraph","text":"거기에 더해서 레몬즙이나 라임즙을 소량 넣으면 좀 더 입체감 있는 맛을 낼 수도 있습니다."},{"kind":"paragraph","text":"술을 마시다가 쉬어가거나, 다른 사람들과 바에 갔지만 술을 마시기 어려운 상황에 마시기 딱 좋은 칵테일입니다."}]'::jsonb, 'published', '2024-09-03T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'longrow-16yo-campbeltown-malts-festival-2024', 'spirits', '롱로우 16년 캠벨타운 몰츠 페스티벌 2024', '"캠벨타운 몰츠 페스티벌(Campbeltown Malts Festival)"은 캠벨타운의 스프링뱅크 증류소, 글렌가일 증류소, 글렌스코시아 증류소, 카덴헤드가 중심이 되어 열리는 위스키 관련 축제입니다.', '/articles/longrow-16yo-campbeltown-malts-festival-2024/00.webp',
  'https://blog.naver.com/shakinglikebartender/223569207842', false,
  '[{"kind":"figure","src":"/articles/longrow-16yo-campbeltown-malts-festival-2024/00.webp","width":966,"height":966},{"kind":"figure","src":"/articles/longrow-16yo-campbeltown-malts-festival-2024/01.webp","width":966,"height":966},{"kind":"heading","text":"About The Whisky"},{"kind":"paragraph","text":"\"캠벨타운 몰츠 페스티벌(Campbeltown Malts Festival)\"은 캠벨타운의 스프링뱅크 증류소, 글렌가일 증류소, 글렌스코시아 증류소, 카덴헤드가 중심이 되어 열리는 위스키 관련 축제입니다."},{"kind":"paragraph","text":"올해의 캠벨타운 몰츠 페스티벌의 주인공은 킬커란이었다고 할 수 있는데, 킬커란은 현 스프링뱅크의 소유주인 J&A 미첼이 글렌가일 증류소를 인수하고 처음으로 증류한 2004년으로부터 올해로 20년이 되었습니다."},{"kind":"paragraph","text":"이를 기념하기 위해서도 글렌가일 증류소에서는 올해 축제의 오픈 데이 바틀로 2004년 증류해 20년 동안 숙성한 킬커란을 출시하기도 하였습니다."},{"kind":"paragraph","text":"\"롱로우\"는 스프링뱅크 증류소에서 출시되는 세 가지 싱글몰트 위스키의 코어 라인 중 하나로, 세 위스키 중 가장 피트감이 강한 위스키입니다."},{"kind":"paragraph","text":"스프링뱅크는 올해 오픈 데이에서 아래의 스펙으로 세 가지 위스키를 출시했습니다."},{"kind":"paragraph","text":"스프링뱅크"},{"kind":"paragraph","text":"-피지 럼 캐스크 (Fijian Rum Casks) 10년, 57.1%"},{"kind":"paragraph","text":"헤이즐번"},{"kind":"paragraph","text":"-버번 & 올로로소 캐스크 (Bourbon & Oloroso Casks) 8년, 52.8%"},{"kind":"paragraph","text":"롱로우"},{"kind":"paragraph","text":"-루비 포트 캐스크 (Ruby Port Casks) 16년, 54.7%"},{"kind":"figure","src":"/articles/longrow-16yo-campbeltown-malts-festival-2024/02.webp","width":966,"height":966},{"kind":"figure","src":"/articles/longrow-16yo-campbeltown-malts-festival-2024/03.webp","width":966,"height":966},{"kind":"quote","text":"증류소: 스프링뱅크 증류소"},{"kind":"quote","text":"위스키 타입: 싱글 몰트 위스키"},{"kind":"quote","text":"캐스크 정보: 루비 포트 캐스크 (Ruby Port Casks), 16년"},{"kind":"quote","text":"도수: 54.7%"},{"kind":"quote","text":"시리즈: 캠벨타운 몰츠 페스티벌 오픈 데이"},{"kind":"figure","src":"/articles/longrow-16yo-campbeltown-malts-festival-2024/04.webp","width":966,"height":966},{"kind":"heading","text":"Nose"},{"kind":"paragraph","text":"- 묵직한 달달함"},{"kind":"paragraph","text":"- 포도, 말린 대추야자, 베리류의 건과일"},{"kind":"paragraph","text":"- 약간의 피트"},{"kind":"heading","text":"Palate"},{"kind":"paragraph","text":"- 향에서 크게 변하지 않으며, 롱로우 특유의 캐릭터에서 좀 더 달달하고 우디함"},{"kind":"paragraph","text":"- 달달한 피트에서 갑작스럽게 우디함으로 변함"},{"kind":"paragraph","text":"- 혀 끝에 남는 꿀의 캐릭터"},{"kind":"heading","text":"Finish"},{"kind":"paragraph","text":"- 달달한 포도나 살짝의 우디함이 꽤 길게 느껴짐"},{"kind":"paragraph","text":"- 기분 좋을 정도의 피트"},{"kind":"paragraph","text":"개인적으로 스프링뱅크에서 출시되는 세 가지의 위스키를 모두 좋아하는데, 올해의 오픈 데이에 출시된 것들 중에서는 롱로우가 가장 맛있었습니다."},{"kind":"paragraph","text":"오픈 데이 스프링뱅크와 헤이즐번은 증류소의 워시백 바에서 마셔봤는데, 개인적으로 엔트리에 비해서 그렇게 특별함을 느끼지는 못했습니다."},{"kind":"paragraph","text":"워시백 바에서 못마셨던 오픈 데이 롱로우가 용량이 350ml로 작아서 한 병 사들고 유럽 여행 내내 친구와 나눠마셨는데, 이건 정말 맛있게 마셨네요."},{"kind":"paragraph","text":"350ml에 아마 60파운드(?)였었는데, 이 가격이면 몇 병이라도 쟁여두고 마시고 싶을 정도였습니다."},{"kind":"paragraph","text":"무카와에는 28,800엔으로 재고가 2개 있던데, 스프링뱅크 증류소 제품 + 숙성년수 + 용량을 총합해서 비교해보면 그렇게 비싸지 않은 것 같기도 한 것 같고...."}]'::jsonb, 'published', '2024-09-02T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'lagavulin-10yo-feis-ile-2024', 'spirits', '라가불린 10년 페스 아일 2024', '페스 아일(Feis Ile)은 매년 5월 마지막 주에 아일라(Islay) 섬과 주라(Jura) 섬에서 약 1~2주간에 걸친 위스키 관련 축제입니다.', '/articles/lagavulin-10yo-feis-ile-2024/00.webp',
  'https://blog.naver.com/shakinglikebartender/223563873221', false,
  '[{"kind":"figure","src":"/articles/lagavulin-10yo-feis-ile-2024/00.webp","width":966,"height":644},{"kind":"heading","text":"About The Whisky"},{"kind":"paragraph","text":"페스 아일(Feis Ile)은 매년 5월 마지막 주에 아일라(Islay) 섬과 주라(Jura) 섬에서 약 1~2주간에 걸친 위스키 관련 축제입니다."},{"kind":"paragraph","text":"증류소에서는 해마다 페스 아일을 기념하기 위해서 위스키를 출시하는데, 라가불린 증류소에서는 올해 페스아일에 10년 숙성과 29년 숙성을 출시하였습니다."},{"kind":"paragraph","text":"그 중 29년은 말도 안 되는 가격 때문에 바틀만 구경해 봤고, 10년은 라가불린 증류소 투어 중 테이스팅을 하다가 남은 것을 담아왔습니다."},{"kind":"paragraph","text":"테이스팅을 하면서 들은 것 중에 기억에 남는 건 이번 10년 페스 아일 바틀은 기존의 라가불린보다 피트감이 더 강하다는 점이었습니다."},{"kind":"paragraph","text":"라가불린 10년 페스 아일 2024는 1,800병이 출시되었으며, 소매가는 175파운드였다고 합니다. 10년 숙성치고는 가격대가 꽤 나가는 편이죠."},{"kind":"figure","src":"/articles/lagavulin-10yo-feis-ile-2024/01.webp","width":966,"height":966},{"kind":"figure","src":"/articles/lagavulin-10yo-feis-ile-2024/02.webp","width":966,"height":966,"caption":"가운데가 10년 페스 아일 2024 29년 페스 아일 2024의 소매가는 2,500파운드"},{"kind":"quote","text":"증류소: 라가불린 증류소"},{"kind":"quote","text":"위스키 타입: 싱글 몰트 위스키"},{"kind":"quote","text":"캐스크 정보: 리필 헤빌리 차드 캐스크(Refill, Heavily Charred Cask), 퍼스트 필 엑스 버번 아메리칸 오크 혹스헤드 캐스크(1st fill ex-Bourbon American Oak Hogshead Cask) / 10년 숙성"},{"kind":"quote","text":"도수: 56.7%"},{"kind":"quote","text":"시리즈: 페스 아일 (Feis Ile)"},{"kind":"figure","src":"/articles/lagavulin-10yo-feis-ile-2024/03.webp","width":966,"height":966},{"kind":"figure","src":"/articles/lagavulin-10yo-feis-ile-2024/04.webp","width":966,"height":966},{"kind":"heading","text":"Nose"},{"kind":"paragraph","text":"- 타고 남은 재 같은 피트감으로, 확실히 기존 라가불린보다는 강함"},{"kind":"paragraph","text":"- 라가불린 특유의 고소한 곡식"},{"kind":"paragraph","text":"- 버터리한 크루아상이 달달하게 다가옴"},{"kind":"paragraph","text":"- 짠 느낌, 약간은 해초스러움"},{"kind":"paragraph","text":"- 시트러스"},{"kind":"paragraph","text":"- 달달하지만 오일리 하지는 않고, 오히려 살짝 드라이함"},{"kind":"heading","text":"Palate"},{"kind":"paragraph","text":"- 라가불린 특유의 고소한 곡식"},{"kind":"paragraph","text":"- 지나가고 나면 다크초콜릿과 카카오닙"},{"kind":"paragraph","text":"- 약간의 견과류와 생강"},{"kind":"paragraph","text":"- 날카롭고 강한 피트감"},{"kind":"paragraph","text":"- 맛은 달지 않고 약간 쌉쌀한 정도"},{"kind":"heading","text":"Finish"},{"kind":"paragraph","text":"- 생각보다 긴 피니시"},{"kind":"paragraph","text":"- 달달한 피트감"},{"kind":"paragraph","text":"- 일반적인 라가불린보다는 좀 더 재 같은 캐릭터가 있음"},{"kind":"paragraph","text":"다 마시고 난 뒤에 라가불린의 고소한 곡식의 캐릭터에 더해 재 같은 피트 캐릭터가 코와 입안에 아주 오래 남게 됩니다."},{"kind":"paragraph","text":"라가불린 10년 페스 아일 2024는 기본적으로 라가불린 특유의 고소한 곡식의 캐릭터가 구조감을 잡아주고, 타고 남은 재 같은 피트감에 더해 짭짤하고 버터리한 빵 같은 향이 매력적인 위스키입니다."},{"kind":"paragraph","text":"꽤나 재미있는 라가불린으로, 숙성년수에 비해서 가격이 다소 비싼 감은 있지만, 개인적으로 향과 맛을 봤을 때 한 병 사두고 싶을 정도입니다."}]'::jsonb, 'published', '2024-08-28T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'bramble', 'cocktail', '브램블 — 베리류 칵테일 최강자', '"브램블"은 1980년대 중반에 런던 소호의 프레드스 클럽(Fred''s Club)에서 당시 바 매니저였던 딕 브래드셀(Dick Bradsell)에 의해 만들어졌습니다.', '/articles/bramble/00.webp',
  'https://blog.naver.com/shakinglikebartender/223562540663', false,
  '[{"kind":"figure","src":"/articles/bramble/00.webp","width":966,"height":966},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"\"브램블\"은 1980년대 중반에 런던 소호의 프레드스 클럽(Fred''s Club)에서 당시 바 매니저였던 딕 브래드셀(Dick Bradsell)에 의해 만들어졌습니다."},{"kind":"paragraph","text":"딕 브래드셀은 브램블 이외에도 에스프레소 마티니 등의 칵테일을 만들어낸 바텐더로도 유명합니다."},{"kind":"paragraph","text":"브램블이라는 이름은 블랙베리가 자라는 덤불에서 따온 것으로, 브래드셀 본인이 어린 시절에 자랐던 와이트 섬(Isle of Wight)에서 블랙베리를 따먹다가 덤불에 긁혔던 추억을 바탕으로 만든 것이라 합니다."},{"kind":"paragraph","text":"기본적으로 이 칵테일의 구조는 진 사워(Gin Sour)에 베리류의 리큐르를 더한 꽤나 간단한 칵테일이지만, 진 사워라는 완성된 칵테일에 다시 무언가를 더한다는 점에서 당시에 발상의 전환 같은 칵테일이었을 수도 있겠습니다."},{"kind":"paragraph","text":"그 외에 사보이 스타일의 싱가폴 슬링(진, 레몬즙, 체리 브랜디, 설탕 시럽, 탄산수)과도 연관점을 찾는 사람들도 있습니다."},{"kind":"figure","src":"/articles/bramble/01.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"45ml 진 (Gin)"},{"kind":"paragraph","text":"20ml 레몬즙 (Lemon Juice)"},{"kind":"paragraph","text":"10ml 설탕 시럽 (Simple Syrup)"},{"kind":"paragraph","text":"10-15ml **크렘 드 뮬 (Creme de Mure)"},{"kind":"paragraph","text":"가니시: 레몬 휠 + 베리류(옵션)"},{"kind":"paragraph","text":"**크렘 드 뮬이 없다면, 크렘 드 카시스(Creme de Cassis), 크렘 드 프람보아즈(Creme de Framboise), 샴보드(Chambord) 등과 같은 베리 리큐르를 사용해도 괜찮습니다."},{"kind":"paragraph","text":"저는 같이 칵테일 동아리를 하는 동생이 만든 크렘 드 뮬을 선물로 받아서 사용했습니다."},{"kind":"figure","src":"/articles/bramble/02.webp","width":966,"height":966},{"kind":"figure","src":"/articles/bramble/03.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 크렘 드 뮬을 제외한 재료를 셰이커에 넣어준다."},{"kind":"paragraph","text":"2. 셰이커에 얼음을 채우고 셰이킹 한다."},{"kind":"paragraph","text":"3. 온더락 잔에 잔얼음을 채워준다."},{"kind":"paragraph","text":"4. 잔에 셰이킹 한 걸 부어준다."},{"kind":"paragraph","text":"5. 크렘 드 뮬을 부어주고, 얼음을 더 채워준다."},{"kind":"paragraph","text":"6. 가니시를 해주고, 짧은 빨대를 꽂아준다."},{"kind":"figure","src":"/articles/bramble/04.webp","width":966,"height":966},{"kind":"paragraph","text":"브램블은 진 사워의 신맛에 베리류의 묵직한 달달함이 더해지는 새콤달달한 칵테일입니다. 어떤 베리 리큐르를 사용하냐에 따라서 맛이 조금씩 다른 것도 하나의 재미이기도 합니다."},{"kind":"paragraph","text":"브램블의 묘미는 베리 리큐르를 부어줄 때 잔얼음 사이사이로 아름답게 흘러내리는 점입니다. 플로팅 하는 칵테일이 아니고서야 이렇게 칵테일을 만들어놓고 무거운 리큐르를 따르는 연출은 그렇게 많지 않기도 하니 더 특별하죠."},{"kind":"paragraph","text":"잔얼음 같은 경우는 한 잔 기준으로 편의점에서 플라스틱 잔에 든 큰 사이즈의 잔 얼음 하나면 충분합니다."},{"kind":"paragraph","text":"진 같은 경우는 일부러 비피터를 사용했는데, 비피터가 시트러스 캐릭터를 가지고 있어서 브램블에 잘 어울릴 거라 생각해서 사용했습니다. 탱커레이 넘버텐도 나쁘지 않겠네요."},{"kind":"paragraph","text":"베리 리큐르는 15ml를 넘지 않게 부어주시는 걸 추천하는데, 아무래도 리큐르다 보니 너무 많이 넣게되면 알콜감이 튀게되기 때문입니다."}]'::jsonb, 'published', '2024-08-27T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'scotland-whisky-ep11', 'spirits', '스코틀랜드 위스키 여행 ep11 — 굿바이, 아일라', '이틀간의 짧은 시간이 지나고 아일라섬에서 떠나야 하는 시간이 왔다. 이틀 동안 다섯 곳의 증류소를 다니면서 멋진 자연 풍경도 보고, 위스키도 정말 원 없이 마신 것 같다.', '/articles/scotland-whisky-ep11/00.webp',
  'https://blog.naver.com/shakinglikebartender/223561180329', false,
  '[{"kind":"figure","src":"/articles/scotland-whisky-ep11/00.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep11/01.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep11/02.webp","width":966,"height":1288},{"kind":"paragraph","text":"이틀간의 짧은 시간이 지나고 아일라섬에서 떠나야 하는 시간이 왔다. 이틀 동안 다섯 곳의 증류소를 다니면서 멋진 자연 풍경도 보고, 위스키도 정말 원 없이 마신 것 같다."},{"kind":"paragraph","text":"아일라에서 음식은 그다지였고 커피는 맛이 없었지만, 사람들이 친절하고 정말 유쾌했다. 처음 아일라 사람들을 보면 살짝 차갑다거나 무뚝뚝하다는 이미지를 가질지도 모르지만, 한두마디 나눠보면 그들의 친절함과 유쾌함을 바로 느낄 수 있다."},{"kind":"figure","src":"/articles/scotland-whisky-ep11/03.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep11/04.webp","width":966,"height":725},{"kind":"paragraph","text":"아일라섬에 들어올 때는 경비행기를 이용했지만, 나갈 때는 페리를 예약해서 택시를 타고 포트 엘런으로 향했다. 아일라섬은 일요일에 버스가 없으니 주의하자."},{"kind":"paragraph","text":"정확히는 기억이 안나는데 보모어에서 포트 엘런까지 택시비가 한 30파운드 했던 것 같다. 카드 계산기가 안될 가능성이 높으니 카드보다는 현금을 준비해두자."},{"kind":"paragraph","text":"역시 페스 아일이 끝난 다음날이라 그런지 사람들이 정말 많구나라고만 생각했는데, 알고보니 경비행기가 날씨 때문에 결항해서 사람들이 다 페리로 몰린 거 였더라."},{"kind":"figure","src":"/articles/scotland-whisky-ep11/05.webp","width":966,"height":1288},{"kind":"paragraph","text":"페리의 내부는 꽤 큰 편이고, 간단한 음식을 구입할 수도 있고, 윗층의 레스토랑에서 음식을 먹을 수도 있다. 아침을 먹기도 했지만 일단 사람이 너무 많아서 이용할 엄두가 나지는 않았다."},{"kind":"paragraph","text":"이렇게 아일라섬에서의 술 기행이 끝났고, 다음 술 기행 도시인 캠벨타운으로 향하게 됐다."},{"kind":"figure","src":"/articles/scotland-whisky-ep11/06.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep11/07.webp","width":966,"height":1288}]'::jsonb, 'published', '2024-08-26T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'gin-fizz', 'cocktail', '진 피즈 — 덥거나 비오는 날에 첫 잔으로 마시기 완벽한 한 잔', '"진 피즈"는 그 기원이 모호한 칵테일 중에 하나인데, 그도 그럴 것이 아주 오래된 칵테일이기 때문입니다. 그중 유력하다고 여겨지는 설이 두 가지가 있습니다.', '/articles/gin-fizz/00.webp',
  'https://blog.naver.com/shakinglikebartender/223561330867', false,
  '[{"kind":"figure","src":"/articles/gin-fizz/00.webp","width":500,"height":500},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"\"진 피즈\"는 그 기원이 모호한 칵테일 중에 하나인데, 그도 그럴 것이 아주 오래된 칵테일이기 때문입니다. 그중 유력하다고 여겨지는 설이 두 가지가 있습니다."},{"kind":"paragraph","text":"첫 번째 설은 진피즈가 처음으로 등장한 기록은 제리 토마스(Jerry Thomas)의 저서인 바텐더스 가이드(The Bar-tenders Guide)의 재판(再版, 1876년)의 부록이었다는 것이며, 이건 서양에서 정설로 여겨지는 것 같습니다."},{"kind":"paragraph","text":"두 번째 설은 1888년 뉴올리언스의 임페리얼 캐비닛 살롱(Imperial Cabinet Saloon)의 오너인 헨리 라모스(Henry Carl Ramos)에 의해 만들어졌다는 설인데, 주로 일본에서 정설로 여겨집니다."},{"kind":"paragraph","text":"개인적으로 이런 형태의 기주, 산(시트러스), 당(설탕)에 탄산을 더하는 식의 칵테일은 훨씬 이전부터 존재했을 것이고, 두 번째 설은 일반적인 진피즈와 다른 \"라모스 진 피즈\"의 기원을 얘기하는 것이라 생각합니다."},{"kind":"paragraph","text":"즉, 진 피즈라는 칵테일과 명칭이 이미 존재한 상태에서 라모스가 본인 스타일대로 만들어낸 라모스 진 피즈를 \"라모스씨의 진 피즈\"로 지칭하다가 그가 진 피즈를 만들어냈다고 잘못 알려진 게 아닐까 싶습니다."},{"kind":"paragraph","text":"진 피즈는 \"톰 콜린스(Tom Collins)\"라는 형제 칵테일이 있는데, 톰 콜린스는 진 피즈와 같은 재료를 빌드로 만들어 내는 칵테일이며, 진의 종류가 다르고, 다일루션 차이로 탄산감이 다른 등의 차이가 있습니다."},{"kind":"figure","src":"/articles/gin-fizz/01.webp","width":500,"height":500},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"45ml 진 (Gin)"},{"kind":"paragraph","text":"20ml 레몬즙 (Lemon Juice)"},{"kind":"paragraph","text":"7.5~10ml 설탕 시럽 (Simple Syrup)"},{"kind":"paragraph","text":"탄산수"},{"kind":"paragraph","text":"가니시: 레몬 필(Lemon Peel)"},{"kind":"figure","src":"/articles/gin-fizz/02.webp","width":500,"height":500},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 탄산수 외에 모든 재료를 셰이커에 넣어줍니다."},{"kind":"paragraph","text":"2. 셰이커에 얼음을 채우고 셰이킹 해줍니다."},{"kind":"paragraph","text":"3. 얼음을 채운 긴 잔에 부어줍니다."},{"kind":"paragraph","text":"4. 탄산수를 적당량 채워줍니다."},{"kind":"paragraph","text":"5. 레몬 필에서 오일을 짜주고,"},{"kind":"paragraph","text":"잘 다듬어서 넣어줍니다."},{"kind":"paragraph","text":"진 피즈는 상큼하고 산뜻한 칵테일로, 더운 날씨나 비 내리는 날에 첫 잔으로 마시기 아주 좋은 칵테일입니다."},{"kind":"paragraph","text":"진 피즈에서 가장 중요하다고 생각되는 건 당과 산의 조화입니다. 너무 달아져버리면 레모네이드 같은 느낌이 될 수 있으니 어느 정도 산과 당을 조절하면서 진의 캐릭터도 다소는 느껴질 수 있어야겠습니다."},{"kind":"paragraph","text":"또, 탄산을 너무 많이 넣어버리면 맛이 밍밍해져 버릴 수 있습니다. ''적당량''이라고 하면 참 애매한데, 저는 개인적으로 45-60ml 정도 넣는 것 같습니다."},{"kind":"paragraph","text":"여담으로 만화 바텐더의 영향 때문에 진 피즈가 바텐더의 전투력 측정기라고 여기는 경우가 꽤 많습니다만, 그건 만화일 뿐이니 너무 그대로 받아들이지 않는 편이 좋지 않을까 싶습니다."}]'::jsonb, 'published', '2024-08-26T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'scotland-whisky-ep10', 'spirits', '스코틀랜드 위스키 여행 ep10 — 직접 핸드필로 위스키를 담아 온 라가불린 증류소 투어', '아드벡 데이의 경험이 너무 즐거웠지만, 사실 이번 스코틀랜드 여행은 계획할 때만 해도 라가불린이 하이라이트였다.', '/articles/scotland-whisky-ep10/00.webp',
  'https://blog.naver.com/shakinglikebartender/223559164258', false,
  '[{"kind":"figure","src":"/articles/scotland-whisky-ep10/00.webp","width":966,"height":1288},{"kind":"paragraph","text":"아드벡 데이의 경험이 너무 즐거웠지만, 사실 이번 스코틀랜드 여행은 계획할 때만 해도 라가불린이 하이라이트였다."},{"kind":"paragraph","text":"우리 둘 다 라가불린을 좋아하기도 하고, 이왕 가는 거 하나 정도는 비싼 투어를 체험하자고 해서 라가불린 증류소 익스클루시브 익스피리언스 투어(Lagavulin Distillery Exclusive Experience)를 예약했다."},{"kind":"figure","src":"/articles/scotland-whisky-ep10/01.webp","width":966,"height":1288},{"kind":"paragraph","text":"투어는 라가불린 생산 과정을 일부 보여주는 것부터 시작하는데, 투어 시작부터 피트가 반겨준다. 투어 내용 자체는 반절 좀 넘게 이해한 것 같은데, 영어를 좀 더 잘하면...."},{"kind":"paragraph","text":"생산 과정에 대한 섹션이 끝나면 밖으로 나와서 증류소 내부 해안가에서 잠시 시간을 가지게 되는데, 개인적으로는 날씨가 좋아서 이 시간이 좀 더 마음에 들었다."},{"kind":"figure","src":"/articles/scotland-whisky-ep10/02.webp","width":966,"height":966},{"kind":"figure","src":"/articles/scotland-whisky-ep10/03.webp","width":966,"height":644},{"kind":"paragraph","text":"이 해안선을 보다 보면 투어를 안내하는 스태프가 이런저런 얘기를 하다가 던우베이그 성(Dunyvaig Castle)의 유적에 대한 얘기를 해주기도 한다(두 번째 사진)."},{"kind":"paragraph","text":"여담으로, 라가불린은 독립병입자가 라가불린 명칭을 쓰는 걸 지양하는 증류소 중에 하나인데, 이러한 점 때문에 독립병입자들은 라가불린 원액의 경우 던우베이그 성의 유적을 라벨에 종종 그려 넣고는 한다."},{"kind":"paragraph","text":"이렇게 해안선 구경까지 끝나게 되면 매키 테이스팅 룸(Mackie Tasting Room)이라는 증류소 내의 프라이빗 한 테이스팅 룸으로 향한다."},{"kind":"figure","src":"/articles/scotland-whisky-ep10/04.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep10/05.webp","width":966,"height":966},{"kind":"paragraph","text":"테이스팅 룸에서는 총 6가지를 마셔봤는데, 그중 하나는 라가불린 뉴메이크 스피릿(NMS)이었다. 지금까지 로즈뱅크, 클라이드사이드의 뉴메이크는 마셔봤는데, 피트 처리된 뉴메이크는 처음이어서 아주 기대됐다."},{"kind":"paragraph","text":"라가불린 뉴메이크 스피릿 (Lagavulin NMS)"},{"kind":"paragraph","text":"라가불린 디아지오 SR 2021 (Lagavulin Diageo SR 2021, 26yo)"},{"kind":"paragraph","text":"라가불린 아일라 재즈 페스티벌 2022 (Lagavulin Islay Jazz Festival 2022, 14yo)"},{"kind":"paragraph","text":"라가불린 페스 아일 2023 (Lagavulin Feis Ile 2023, 14yo)"},{"kind":"paragraph","text":"라가불린 페스 아일 2024 (Lagavulin Feis Ile 2024, 10yo)"},{"kind":"paragraph","text":"라가불린 8년 퍼스트필 엑스-버번 혹스헤드 (Lagavulin 1st fill ex-Bourbon Hogshead, 8yo)"},{"kind":"paragraph","text":"가장 먼저 뉴메이크를 마셔봤는데, 라가불린은 이미 뉴메이크부터 특유의 고소한 곡식+피트감이 나타난다. 거기에 핵과류의 달달함이 같이 나는데, 이거 정말 맛있었다."},{"kind":"paragraph","text":"다음으로 라가불린 디아지오 SR 2021의 차례였는데, 향만큼은 이번 아일라 여행에서 맡은 위스키 중에 top3에서도 1, 2위를 차지할 정도였다. 맛에서는 향만큼의 퍼포먼스를 보여주지 못한 건 아쉽지만."},{"kind":"paragraph","text":"재즈 페스티벌과 페스 아일 2023 바틀은 사실 정확히 맛이 기억은 안 난다. 라가불린의 캐릭터가 있던 것 정도만 기억났고, 페스 아일 2024는 기존 라가불린보다 피트감이 높은 게 인상적이었다."},{"kind":"paragraph","text":"마지막 라가불린 8년은 이날 투어의 마지막으로 우리가 핸드필해서 가져갈 위스키였다. 8년 숙성인 건 조금 아쉽지만 그래도 라가불린 핸드필을 받은 것만으로도 만족스럽다."},{"kind":"figure","src":"/articles/scotland-whisky-ep10/06.webp","width":540,"height":720},{"kind":"figure","src":"/articles/scotland-whisky-ep10/07.webp","width":966,"height":1288,"caption":"라벨 작업하는 곳에는 올드 라가불린과 뗄래야 뗄 수 없는 관계인화이트 홀스도 보인다."},{"kind":"paragraph","text":"핸드필하는 원액의 정보를 꽤 잘 알려주는 편이고, 핸드필 할 때는 병의 라벨 정보를 본인이 쓴 후에 직접 붙이게 되는데, 이 작업이 또 재미있다. 200미리를 받아왔는데, 이거 오픈할 수 있을지나 모르겠다."},{"kind":"paragraph","text":"아일라섬의 증류소 투어를 알아보다 보면 100~200미리 핸드필을 받아갈 수 있는 투어가 꽤 있는데, 강력하게 추천한다."}]'::jsonb, 'published', '2024-08-24T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'scotland-whisky-ep9', 'spirits', '스코틀랜드 위스키 여행 ep9 — 아름다운 자연과 어우러진 라프로익 증류소', '라프로익 증류소는 다른 킬달튼 형제(아드벡, 라가불린)들과는 다르게 가로수길(?)을 거친 후에야 나타나는데, 우리는 날씨가 정말 좋았을 때 갔어서 이 가로수길이 아주 아름다웠다.', '/articles/scotland-whisky-ep9/00.webp',
  'https://blog.naver.com/shakinglikebartender/223558193281', false,
  '[{"kind":"figure","src":"/articles/scotland-whisky-ep9/00.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep9/01.webp","width":966,"height":1288},{"kind":"paragraph","text":"라프로익 증류소는 다른 킬달튼 형제(아드벡, 라가불린)들과는 다르게 가로수길(?)을 거친 후에야 나타나는데, 우리는 날씨가 정말 좋았을 때 갔어서 이 가로수길이 아주 아름다웠다."},{"kind":"paragraph","text":"라프로익 증류소에는 단순히 몇몇 라프로익 위스키를 찍먹해보려고 갔던지라 친구와 곧바로 비지터 센터 너머의 바로 직행했다."},{"kind":"figure","src":"/articles/scotland-whisky-ep9/02.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep9/03.webp","width":966,"height":1288},{"kind":"paragraph","text":"라프로익 비지터 센터의 바에 가면 우선 주문하기도 전에 위스키를 한 잔 준다. 받은 건 올해 페스 아일 바틀인 카디어스(Cairdeas)였는데, 솔직히 올해 축제 바틀을 웰컴 위스키로 내줄 줄은 몰랐다."},{"kind":"paragraph","text":"라프로익 카디어스는 2008년부터 페스 아일을 위해 릴리즈된 시리즈로, 카디어스(Cairdeas)는 게일어로 우정(Friendship)을 의미한다."},{"kind":"paragraph","text":"아마 여기에 착안한 것인지, 아니면 그 반대인지 라프로익이 운영하는 멤버십의 이름은 라프로익의 친구들(Friends of Laphroaig)이기도 하다."},{"kind":"figure","src":"/articles/scotland-whisky-ep9/04.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep9/05.webp","width":966,"height":1288},{"kind":"paragraph","text":"비지터 바에서는 올드 & 레어와 캐스크 스트렝스 10 테이스팅 플라이트를 마시게 되었는데, 가격면에서 지금까지 방문했던 증류소 중에서 제일 저렴했던 것 같다."},{"kind":"paragraph","text":"문제는 맛인데....나도 친구도 라프로익을 그다지 좋아하는 편은 아니여서 그렇게 큰 감상은 없었다. 더 큰 문제는 마신 것들 중에 비매품인 핸드필 제품이 있었는데, 이게 정말 별로였다."},{"kind":"paragraph","text":"위스키에서 처음 맛보는 이상한 맛이 났는데, 나만 그랬으면 내 혀가 이상하구나 하고 끝냈겠지만, 친구도 맛이 이상하다고 한 거 보니 뭔가 바틀이 오염됐거나, 잘못 보관된 건가 싶다."},{"kind":"paragraph","text":"비지터 내부 바에서 마시다보면 자연스럽게 창문으로 눈길이 가는데, 그 너머로 보이는 광경은 아직도 잊히지 않을 정도로 아름다웠다."},{"kind":"figure","src":"/articles/scotland-whisky-ep9/06.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep9/07.webp","width":966,"height":1288}]'::jsonb, 'published', '2024-08-23T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'scotland-whisky-ep8', 'spirits', '스코틀랜드 위스키 여행 ep8 — 페스 아일의 피날레, 스펙타귤러한 아드벡 증류소의 서커스', '올해 페스 아일(Feis Ile)의 마지막 오픈 데이는 아드벡 데이(Ardbeg Day)로, 아드벡 증류소에서는 서커스를 주제로 축제를 진행했고, 한국에서도 아드벡 스펙타큘러 행사를 진행하기도 했다.', '/articles/scotland-whisky-ep8/00.webp',
  'https://blog.naver.com/shakinglikebartender/223557978077', false,
  '[{"kind":"figure","src":"/articles/scotland-whisky-ep8/00.webp","width":966,"height":644},{"kind":"paragraph","text":"올해 페스 아일(Feis Ile)의 마지막 오픈 데이는 아드벡 데이(Ardbeg Day)로, 아드벡 증류소에서는 서커스를 주제로 축제를 진행했고, 한국에서도 아드벡 스펙타큘러 행사를 진행하기도 했다."},{"kind":"paragraph","text":"오전 10시에 오픈이라 9시 반 정도까지 갔는데, 이미 줄이 엄청 서있었다. 코스튬을 입고 온 사람들, 방송국 카메라의 등장, 긴 오픈런 줄임에도 즐거워하는 사람들까지 축제는 축제였다."},{"kind":"paragraph","text":"10시를 조금 넘긴 시간에 서커스 단원들이 길게 늘어선 줄을 지나 아드벡 증류소 입구를 거쳐 들어가면서 축제는 막을 올렸다."},{"kind":"figure","src":"/articles/scotland-whisky-ep8/01.webp","width":966,"height":966},{"kind":"paragraph","text":"먼저 정문에서 사전 예약을 확인하고 나서 티켓과 작은 잔을 하나 챙겨주는데, 아드벡 스펙타큘러나 코어 레인지 한 잔과 아드벡 하이볼 한 잔을 공짜로 제공해 주는 티켓이었다."},{"kind":"paragraph","text":"아드벡의 마스코트인 강아지가 묘기를 부리고 있는 티켓이라니, 이번 아드벡 데이의 컨셉을 귀엽고도 확실하게 보여준다."},{"kind":"figure","src":"/articles/scotland-whisky-ep8/02.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep8/03.webp","width":966,"height":1288},{"kind":"paragraph","text":"술쟁이로서 아드벡 데이에서 가장 좋았던 점은 로스트 앤 파운드 드램이라 해서 단종된 아드벡들을 잔 당 아주 싼 가격에 판매한다는 점이었다."},{"kind":"paragraph","text":"여기서 아일라에 들어가는 분들에게 드리고 싶은 팁은 **섬에 들어가기 전에 반드시 파운드 현금을 어느 정도 찾아 놓으라는 점이다."},{"kind":"paragraph","text":"당일 저 아드벡 바에서는 현금만을 받았는데, 우리가 가지고 있는 건 80파운드가 전부였고, 결국 마셔 볼 위스키를 취사선택할 수밖에 없었다. 그렇게 마신 게 아래의 리스트"},{"kind":"paragraph","text":"아드벡 스틸영(Ardbeg Still Young, 2006)"},{"kind":"paragraph","text":"아드벡 투엔티썸띵(Ardbeg Twenty Something) - 22년"},{"kind":"paragraph","text":"아드벡 수퍼노바(Ardbeg Supernova, 2014)"},{"kind":"paragraph","text":"아드벡 다크코어(Ardbeg Dark Core, 2016)"},{"kind":"paragraph","text":"아드벡 킬달튼(Ardbeg Kildalton, 2014)"},{"kind":"paragraph","text":"아드벡 데이(Ardbeg day, 2012)"},{"kind":"paragraph","text":"아드벡 르네상스(Ardbeg Renaissance, 2008)"},{"kind":"paragraph","text":"80파운드가 넘지 않나? 싶지만, 아드벡 르네상스는 사실 축제에서 만나서 얘기 나누던 영국인 형님이랑 킬달튼을 바꿔마셨다."},{"kind":"paragraph","text":"개인적으로 제일 맛있었던 건 스틸영과 수퍼노바로, 올해 마신 위스키 top5에 들어갈만했다. 이 두 위스키를 마실 기회가 있다면 꼭 한 번씩은 드셔보시길."},{"kind":"figure","src":"/articles/scotland-whisky-ep8/04.webp","width":966,"height":1288},{"kind":"paragraph","text":"서커스가 컨셉인만큼 대형 미끄럼틀 같은 서커스 관련 콘텐츠에 더해 락 밴드의 노래, 간단한 음식들까지 올해 아드벡 데이는 위스키나 칵테일 외에도 즐길 게 다양했다. 그냥 그 공간 안에 있는 자체로 텐션이 올라갔다."},{"kind":"figure","src":"/articles/scotland-whisky-ep8/05.webp","width":966,"height":966},{"kind":"figure","src":"/articles/scotland-whisky-ep8/06.webp","width":966,"height":966},{"kind":"paragraph","text":"증류소샵도 이용 가능했고, 여기서 아드벡 증류소의 마스코트도 만나볼 수 있다. 이 날은 아드벡 싱글 캐스크도 판매하고 있었는데, 이걸 구매하려는 사람들이 많아 줄을 설 정도였다. 가격이 너무 비싸 구매하지는 않았지만"},{"kind":"paragraph","text":"외부에서는 카드 결제가 안됐지만, 증류소샵에서는 카드 결제가 가능하다."},{"kind":"paragraph","text":"분위기도 신나고, 날씨도 너무 좋아서 축제를 더 즐기고 싶었지만, 킬달튼 3형제를 모두 들러보기 위해서 축제를 뒤로하고 라프로익 증류소로 이동했다."},{"kind":"paragraph","text":"아드벡 증류소에 마신 마지막 잔은 친구의 로망. 우가달을 좋아하는 친구가 증류소에서 꼭 우가달을 마셔보고 싶다는 얘기에 로망 한 잔을 나눠마셨다."},{"kind":"figure","src":"/articles/scotland-whisky-ep8/07.webp","width":966,"height":966}]'::jsonb, 'published', '2024-08-23T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'shandy-gaff', 'cocktail', '샌디 가프 — 저도수 생강 맛 맥주의 매력', '"샌디 가프"는 쉽게 얘기해서 진저비어와 맥주를 동량으로 섞는 칵테일로, 집에서도 만들기 아주 간단하지만 생강의 달달한 알싸함에 맥주를 더한 매력적인 칵테일입니다.', '/articles/shandy-gaff/00.webp',
  'https://blog.naver.com/shakinglikebartender/223555778355', false,
  '[{"kind":"figure","src":"/articles/shandy-gaff/00.webp","width":524,"height":524},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"\"샌디 가프\"는 쉽게 얘기해서 진저비어와 맥주를 동량으로 섞는 칵테일로, 집에서도 만들기 아주 간단하지만 생강의 달달한 알싸함에 맥주를 더한 매력적인 칵테일입니다."},{"kind":"paragraph","text":"샌디 가프는 그 유래가 투명하지는 않은데, 영국에서 시작됐을 거라고 보는 것이 주된 설입니다. 그럴만한 게 진저비어가 처음 만들어진 건 18세기 중반 영국의 요크셔에서 였기 때문입니다."},{"kind":"paragraph","text":"그러다 보니 누군가가 맥주와 진저비어를 섞어서 마신 것이 샌디가프의 시작이었을 것이고, 만들기도 쉬우니 일반 술집에서도 간단하게 팔기 시작하면서 유행을 타지 않았을까 싶습니다."},{"kind":"paragraph","text":"현재에는 영국에서는 샌디가프를 줄여서 샌디라고 부르며, 진저비어가 아닌 레모네이드를 맥주에 섞는 것이 일반적이라 합니다."},{"kind":"paragraph","text":"이걸 프랑스에서는 파나셰(Panache), 독일에서는 라들러(Radler)라고 부르고 있습니다."},{"kind":"paragraph","text":"일본의 이자카야를 가면 진저에일을 사용하는 샌디가프를 심심찮게 볼 수 있는데, 다른 술들을 마시다가 저도수로 체이서를 마시고 싶다 했을 때 딱 좋은 칵테일입니다."},{"kind":"figure","src":"/articles/shandy-gaff/01.webp","width":501,"height":501},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"진저비어"},{"kind":"paragraph","text":"좋아하는 맥주"},{"kind":"figure","src":"/articles/shandy-gaff/02.webp","width":500,"height":500},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 차갑게 해둔 잔에 맥주를 따른다."},{"kind":"paragraph","text":"2. 진저비어를 동량 따라준다."},{"kind":"paragraph","text":"진저비어와 맥주를 동량 따르는 레시피이지만, 굳이 동량을 맞추지 않아도 상관없습니다. 두 재료가 모두 탄산을 가지고 있어서 지거를 사용한다면 탄산이 많이 빠지겠죠."},{"kind":"paragraph","text":"그것보다는 눈대중으로 어느 정도 동량을 맞춰도 되며, 입맛에 따라서 양을 조절하셔도 전혀 상관없습니다."},{"kind":"paragraph","text":"맥주의 경우 본래는 에일을 썼다고 합니다만, 이것도 굳이 신경 쓰지 말고 좋아하는 맥주를 사용하시면 됩니다(다만, 흑맥주는 제외)."},{"kind":"paragraph","text":"저도수이니만큼 마시기 아주 쉬우며, 진저비어의 단맛과 알싸한 맛이 맥주 특유의 쓴맛을 가려주기 때문에 맥주의 쓴맛이 싫어하시는 분들도 가볍게 마시기 좋습니다."},{"kind":"paragraph","text":"진저에일을 사용해도 되기는 하지만, 진저비어가 생강의 맛이 좀 더 뚜렷하기 때문에 진저비어로 만드는 걸 추천드리는 편입니다."}]'::jsonb, 'published', '2024-08-21T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'scotland-whisky-ep7', 'spirits', '스코틀랜드 위스키 여행 ep7 — 포트 엘런의 굴뚝에서는 연기가 나고 있다', '포트 엘런(Port Ellen)은 보모어와 더불어 아일라 섬에서 가장 큰 도시로, 포트 애스케이크(Port Askaig)와 더불어 스코틀랜드 내륙과 이어지는 페리 노선이 운영되는 마을이다.', '/articles/scotland-whisky-ep7/00.webp',
  'https://blog.naver.com/shakinglikebartender/223555650827', false,
  '[{"kind":"figure","src":"/articles/scotland-whisky-ep7/00.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/scotland-whisky-ep7/01.webp","width":966,"height":725},{"kind":"paragraph","text":"포트 엘런(Port Ellen)은 보모어와 더불어 아일라 섬에서 가장 큰 도시로, 포트 애스케이크(Port Askaig)와 더불어 스코틀랜드 내륙과 이어지는 페리 노선이 운영되는 마을이다."},{"kind":"paragraph","text":"이곳에는 보모어보다 B&B 숙소가 많이 위치해있어 많은 여행자가 포트 엘런을 거점으로 아일라 섬을 여행하기도 한다."},{"kind":"paragraph","text":"마을에서부터 포트 엘런 증류소까지 이어지는 해안선이 아주 아름다우며, 후에 방문할 킬달튼 3형제(라프로익, 라가불린, 아드벡)을 만나기 위해서는 반드시 거쳐야 하는 도시이다."},{"kind":"paragraph","text":"보모어에서부터 킬달튼으로 가는 거라면 물론 포트 엘런을 방문하지 않고 지나갈 수 있지만, 아침 일찍부터 아드벡 증류소를 가야 해서 아침도 해결하고, 포트 엘런 증류소도 볼 겸 방문했다."},{"kind":"figure","src":"/articles/scotland-whisky-ep7/02.webp","width":966,"height":966},{"kind":"figure","src":"/articles/scotland-whisky-ep7/03.webp","width":966,"height":966},{"kind":"figure","src":"/articles/scotland-whisky-ep7/04.webp","width":966,"height":966},{"kind":"paragraph","text":"포트 엘런은 설립 후 몇 번의 고비를 겪다가 결국 1983년에 결국 문을 닫아버린 증류소로, 이후 증류는 하지 않고 맥아 제조를 위한 몰팅(Malting) 작업만을 하게 되었다."},{"kind":"paragraph","text":"자가 몰팅을 하지 않는 아일라 증류소는 대부분 포트 엘런의 몰트를 사용하며, 아일라 섬 이외에도 몰트를 공급하기도 한다."},{"kind":"paragraph","text":"이렇게 포트 엘런 증류소는 유령 증류소가 되었고, 남아 있는 원액들은 간간이 디아지오에 의해서 레어 몰츠 셀렉션(Rare Malts Selection)이나 독립병입자들에 의해서 소량 출시되었다."},{"kind":"paragraph","text":"다만, 가격이 매우 높은 데다가 소량만 출시되기 때문에 컬렉터가 아닌 이상에야 구매하기는 상당히 어렵다. 일본에서는 종종 바에서 볼 수 있기도 하지만 역시나 가격이 높다."},{"kind":"paragraph","text":"이후 소유주인 디아지오는 서덜랜드 지역의 브로라(Brora) 증류소와 함께 재개장할 계획을 발표하고, 2024년 3월 19일 마침내 포트 엘런 증류소를 재개장하기에 이른다."},{"kind":"paragraph","text":"우리가 가서 포트 엘런을 보았을 때는 이른 시간이라 아직 문을 열지 않았는데, 비지터 센터가 있는지, 일반 방문객이 방문할 수 있는지는 잘 모르겠다."},{"kind":"paragraph","text":"다만, 디아지오 사이트인 malts.com에서 투어를 예약할 수 있는 걸 보면 아마 방문이 가능할 것 같기는 하다. 단순 방문에서 포트 엘런을 마셔볼 수 있을지는 모르지만."},{"kind":"paragraph","text":"포트 엘런은 간단하게 둘러보고, 아침을 해결하고 아드벡으로 발걸음을 옮겼다."},{"kind":"figure","src":"/articles/scotland-whisky-ep7/05.webp","width":966,"height":644},{"kind":"figure","src":"/articles/scotland-whisky-ep7/06.webp","width":966,"height":966},{"kind":"figure","src":"/articles/scotland-whisky-ep7/07.webp","width":966,"height":966,"caption":"커피는 여기도 여전히 맛없다"}]'::jsonb, 'published', '2024-08-21T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'scotland-whisky-ep6', 'spirits', '스코틀랜드 위스키 여행 ep6 — 보모어 호텔의 루치스 위스키 바의 엄청난 아일라 위스키 컬렉션 / Lucci''s Whisky Bar', '우리가 숙박한 보모어 호텔의 내부에는 루치스 바가 있었는데, 여기가 또 아일라 여행객들에게는 성지 중 하나로 통한다.', '/articles/scotland-whisky-ep6/00.webp',
  'https://blog.naver.com/shakinglikebartender/223554418634', false,
  '[{"kind":"figure","src":"/articles/scotland-whisky-ep6/00.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep6/01.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep6/02.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/scotland-whisky-ep6/03.webp","width":966,"height":1288},{"kind":"paragraph","text":"우리가 숙박한 보모어 호텔의 내부에는 루치스 바가 있었는데, 여기가 또 아일라 여행객들에게는 성지 중 하나로 통한다."},{"kind":"paragraph","text":"바 내부에만 위스키가 있는 게 아니라, 호텔 내부 곳곳에 위스키가 있는데, 킬호만의 경우는 우리가 머문 방 바로 옆에 위치해 있어서 매일 아침저녁으로 바틀을 구경하기도 했다."},{"kind":"paragraph","text":"루치스 바의 컬렉션은 정말 입을 떡 벌어지게 할만한데, 직접 보고 있어도 현실감이 떨어진다. 그건 말도 안 되게 높은 가격 때문...."},{"kind":"paragraph","text":"아마 대부분이 마실 수 있는 바틀들 중에서도 아주 희귀한 바틀이 있음에도 불구하고 텐션이 그렇게 오르지 않았던 건 가격 때문이었다. 아무리 위스키를 좋아하고, 돈을 쓸 각오를 하고 와도 가격이 익숙해지질 않는다."},{"kind":"figure","src":"/articles/scotland-whisky-ep6/04.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep6/05.webp","width":966,"height":1288},{"kind":"paragraph","text":"루치스 바의 메뉴를 친구가 몇 쪽 찍어왔는데, 엄청난 컬렉션에 한 번 놀라고, 가격에 두 번 놀라게 된다. 저 사진이 진짜 일부에 불과하다."},{"kind":"paragraph","text":"브룩라디 웨어하우스 투어를 안내해 준 스태프가 자신이 마신 위스키 중 최고였다고 극찬한 옥토모어 이벤트 호라이즌을 마셔보고 싶었는데, 100파운드라 고민 끝에 포기해버렸다."},{"kind":"paragraph","text":"어디선가 얼핏 본 바로는 보모어에서 멀리 떨어지지 않은 곳에 \"더 아일라 위스키 볼트(The Islay Whisky Vault)\"라는 곳이 여기보다 더 합리적인 가격으로 위스키를 맛볼 수 있다고 하니, 보모어 호텔에 숙박하는 거 아니면 거기로 하자."},{"kind":"figure","src":"/articles/scotland-whisky-ep6/06.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep6/07.webp","width":966,"height":1288,"caption":"브룩라디 블랙아트(Bruichladdich Black Art 03.1) / 라가불린 12년 CS (Lagavulin 12yo CS, 2016)"},{"kind":"paragraph","text":"그렇게 나는 브룩라디 블랙아트 03.1을 마셨는데, 이게 얼마 남아있지 않은 상태에서 오래 보관돼서 그런지 솔직히 힘이 너~무 빠져있었다. 향이나 맛이나 힘이 너무 빠진...."},{"kind":"paragraph","text":"그나마 합리적인 가격 찾다가 주문했지만 이것도 비싼 걸로 기억하는데, 적잖이 실망했다."},{"kind":"paragraph","text":"개인적으로 물론 희귀한 바틀도 있지만, 굳이 여기서보다는 증류소에서 이것저것 더 합리적인 가격에 마셔보거나, 더 비싼 증류소 투어를 하는 게 더 나을 것 같다는 생각이 들었다."}]'::jsonb, 'published', '2024-08-20T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'gin-gin-mule', 'cocktail', '진진뮬 — 모히또와 모스코뮬이 만난 칵테일, 근데 이제 진을 곁들인', '"진 진 뮬"은 2000년 오드리 손더스(Audrey Saunders)가 뉴욕의 바 비콘(Beacon)에서 만들어낸 칵테일입니다.', '/articles/gin-gin-mule/00.webp',
  'https://blog.naver.com/shakinglikebartender/223554367690', false,
  '[{"kind":"figure","src":"/articles/gin-gin-mule/00.webp","width":500,"height":500},{"kind":"heading","text":"About the Cocktail"},{"kind":"paragraph","text":"\"진 진 뮬\"은 2000년 오드리 손더스(Audrey Saunders)가 뉴욕의 바 비콘(Beacon)에서 만들어낸 칵테일입니다."},{"kind":"paragraph","text":"어느 날 오드리 손더스의 스승인 데일 데그로프(Dale Degroff)는 그녀에게 신선한 허브(민트)를 사용해서 만드는 클래식한 모히또를 만드는 방법을 보여주었습니다."},{"kind":"paragraph","text":"이게 무슨 대수냐라고 할 수 있지만, 당시만 하더라도 칵테일에 신선한 재료를 사용하는 경우가 많지 않았고, 크래프트 칵테일 운동의 선구적인 역할을 했던 데일 데그로프 정도였으니 관심을 가졌을 겁니다."},{"kind":"paragraph","text":"오드리 손더스는 보드카가 주류인 시절에 진에 많은 관심을 두고 있었는데, 모히또(Mojito)에 모스코 뮬(Moscow Mule)을 더하고, 기주를 진으로 바꿔서 이 칵테일을 만들어냈습니다."},{"kind":"paragraph","text":"당시 주류가 아닌 기주에 신선한 재료를 사용한 것뿐만 아니라, 진저비어까지 수제로 만들어서 이 칵테일을 만들어냈는데, 이러한 점이 시간이 지나면서 이 칵테일을 모던 클래식 칵테일에서 중요한 자리를 차지하게 해줍니다."},{"kind":"paragraph","text":"이후 오드리 손더스는 2005년 뉴욕에 페구 클럽(Pegu Club)이라는 바를 오픈했는데, 진진뮬은 2020년 이 바가 문을 닫을 때까지 당당하게 주요 메뉴의 하나로 자리 잡았습니다."},{"kind":"figure","src":"/articles/gin-gin-mule/01.webp","width":436,"height":436},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"45ml 진 (Gin)"},{"kind":"paragraph","text":"20ml 라임즙 (Lime Juice)"},{"kind":"paragraph","text":"10ml 설탕 시럽 (Simple Syrup)"},{"kind":"paragraph","text":"민트 잎 6~8개"},{"kind":"paragraph","text":"진저비어 (Ginger Beer)"},{"kind":"paragraph","text":"가니시: 민트 다발 (Mint Bouquet)"},{"kind":"figure","src":"/articles/gin-gin-mule/02.webp","width":500,"height":500},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 진저비어를 제외한 재료를 셰이커에 넣어줍니다."},{"kind":"paragraph","text":"2. 머들러로 민트 입을 너무 강하지 않게 눌러줍니다."},{"kind":"paragraph","text":"3. 셰이커에 얼음을 채운 후, 셰이킹 해줍니다."},{"kind":"paragraph","text":"4. 얼음을 채운 잔에 **더블스트레이닝해줍니다."},{"kind":"paragraph","text":"5. 진저비어를 채워줍니다."},{"kind":"paragraph","text":"6. 민트 다발로 가니 시 해줍니다."},{"kind":"figure","src":"/articles/gin-gin-mule/03.webp","width":448,"height":448},{"kind":"paragraph","text":"진진뮬을 마시려고 잔을 입으로 가져다 대면, 먼저 코에 민트 다발의 향이 상쾌하고 기분 좋게 다가옵니다."},{"kind":"paragraph","text":"맛을 보면 민트의 상쾌함과 생강의 알싸함이 아주 상쾌하게 다가오며, 라임의 상큼함에 약간의 탄산감까지 있어서 산뜻한 느낌까지 줍니다."},{"kind":"paragraph","text":"모히또나와 모스코뮬의 장점만을 가져와 합친 것 같은 느낌으로, 역시 여름에 마시기에 좋은 칵테일이라는 생각이 듭니다."},{"kind":"paragraph","text":"다른 레시피들에서는 시럽을 30ml 넣으라고 하고 있지만, 진저비어에도 당도가 있기 때문에 그대로 다 넣으면 너무 달아지게 되니 아무리 많이 넣더라도 15ml를 넘지 않는 걸 추천드립니다."}]'::jsonb, 'published', '2024-08-20T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'scotland-whisky-ep5', 'spirits', '스코틀랜드 위스키 여행 ep5 — 보모어 시내와 피트제리아', '보모어는 아일라 섬의 주도이긴 하지만 기본적으로 증류소를 빼면 시골이다. 증류소가 닫고 난 저녁 시간에는 산책 말고는 딱히 놀 거리가 많지 않다.', '/articles/scotland-whisky-ep5/00.webp',
  'https://blog.naver.com/shakinglikebartender/223553107152', false,
  '[{"kind":"figure","src":"/articles/scotland-whisky-ep5/00.webp","width":966,"height":725},{"kind":"figure","src":"/articles/scotland-whisky-ep5/01.webp","width":966,"height":543},{"kind":"figure","src":"/articles/scotland-whisky-ep5/02.webp","width":966,"height":543},{"kind":"figure","src":"/articles/scotland-whisky-ep5/03.webp","width":966,"height":543},{"kind":"figure","src":"/articles/scotland-whisky-ep5/04.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/scotland-whisky-ep5/05.webp","width":966,"height":1288},{"kind":"paragraph","text":"보모어는 아일라 섬의 주도이긴 하지만 기본적으로 증류소를 빼면 시골이다. 증류소가 닫고 난 저녁 시간에는 산책 말고는 딱히 놀 거리가 많지 않다. 그나마 호텔에 딸려있는 바에서 한 잔 하는 정도."},{"kind":"paragraph","text":"저녁을 먹을 수 있는 식당도 대부분 호텔에 딸려있는 경우가 많은데, 입맛에 안맞는 경우가 있을 수 있다. 맛이 없을 수도 있고...."},{"kind":"paragraph","text":"만약 그런 불상사가 발생한다면 피트-제리아에서 피자를 먹는 걸 추천한다. 엄청 맛있고 그런 건 아니고, 좀 자극적이고 강하다. 하지만 맛없는 영국 음식에 데여봤다면 아주 맛있게 먹을 수 있을 것이다."},{"kind":"paragraph","text":"아일라 위스키에서 빠질 수 없는 요소인 피트(Peat)와 피자 전문점인 피제리아(Pizzeria)를 합쳐서 피트제리아(Peatzeria)인데, 이름에 걸맞게 메뉴 중에 수제 피트 소금(?)을 쓴 메뉴가 있다."},{"kind":"paragraph","text":"보모어 내에서 음식 선택권이 많지 않은 와중에도 그래도 맛있게 먹을 수 있는 피자이니 아일라에 간다면 지도에 저장해두자."}]'::jsonb, 'published', '2024-08-19T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'port-charlotte-rockndaal-03-2-feis-ile-2024', 'spirits', '포트 샬롯 로큰달 03.2 페스 아일 2024', '"포트샬롯(Port Charlotte)" 위스키는 "브룩라디 증류소"의 코어 위스키 라인업 3종 중 하나로, 브룩라디 증류소에서 남서쪽으로 3km 떨어진 마을인 포트 샬롯의 이름을 딴 것입니다.', '/articles/port-charlotte-rockndaal-03-2-feis-ile-2024/00.webp',
  'https://blog.naver.com/shakinglikebartender/223553186100', false,
  '[{"kind":"figure","src":"/articles/port-charlotte-rockndaal-03-2-feis-ile-2024/00.webp","width":540,"height":720},{"kind":"figure","src":"/articles/port-charlotte-rockndaal-03-2-feis-ile-2024/01.webp","width":522,"height":696},{"kind":"heading","text":"About The Whisky"},{"kind":"paragraph","text":"\"포트샬롯(Port Charlotte)\" 위스키는 \"브룩라디 증류소\"의 코어 위스키 라인업 3종 중 하나로, 브룩라디 증류소에서 남서쪽으로 3km 떨어진 마을인 포트 샬롯의 이름을 딴 것입니다."},{"kind":"paragraph","text":"원래 포트 샬롯 마을 내에는 1829년 문을 연 \"로킨달(Lochindaal) 증류소\"가 존재했는데, 여러 차례 주인이 바뀌고, 폐쇄했다가 재개장하는 등의 고난을 겪다가 1929년 문을 닫게 됩니다."},{"kind":"paragraph","text":"2007년, 브룩라디 증류소는 이 로킨달 증류소의 건물들을 사들였고, 포트 샬롯이라는 이름의 증류소를 세울 계획을 발표했습니다만, 2008년 금융위기로 보류하게 되었습니다."},{"kind":"paragraph","text":"대신 2007년부터 남아있는 로킨달 증류소 창고에 포트샬롯 원액을 숙성하기 시작하였습니다."},{"kind":"paragraph","text":"포트샬롯은 헤빌리 피티드(Heavily Peated)로 출시되며, 페놀 수치는 40ppm입니다. 이는 킬달튼 3형제(라프로익, 라가불린, 아드벡)와 비슷한 수치입니다."},{"kind":"paragraph","text":"현대에 아드벡과 브룩라디의 슈퍼 헤빌리 피티드 경쟁에서 탄생한 아드벡의 슈퍼노바나 브룩라디의 옥토모어 등으로 인해 이 정도 ppm이 낮다고 생각할 수는 있지만, 40ppm도 충분히 높은 수치입니다."},{"kind":"paragraph","text":"포트 샬롯 로큰달 03.2은 올해 페스 아일을 기념하여 출시된 것으로, 브룩라디 증류소의 페스 아일 오픈 데이 이벤트인 로큰달 축제(ROCK''NDAAL Festival)의 이름을 따온 바틀입니다."},{"kind":"paragraph","text":"이 축제는 2022년부터 시작되어 이때부터 01번이 붙게 되었고, 00.1은 브룩라디 바틀을, 00.2는 포트 샬롯 바틀을 지칭합니다."},{"kind":"quote","text":"증류소: 브룩라디 증류소"},{"kind":"quote","text":"위스키 타입: 싱글 몰트 위스키"},{"kind":"quote","text":"캐스크 정보: 버번 캐스크 풀 숙성(Bourbon Cask 70%) + 퍼스트필 소테른 캐스크(1st fill Sauternes Cask 30%)를 배팅 / 20년 숙성"},{"kind":"quote","text":"보리 정보: 100% 스코틀랜드산 보리 (Scottish Barley)"},{"kind":"quote","text":"페놀 수치: 40ppm"},{"kind":"quote","text":"도수: 54%"},{"kind":"quote","text":"시리즈: 로큰달 (ROCK''NDAAL)"},{"kind":"figure","src":"/articles/port-charlotte-rockndaal-03-2-feis-ile-2024/02.webp","width":500,"height":500},{"kind":"heading","text":"Nose"},{"kind":"paragraph","text":"-디저트 와인 같은 달큰한 향"},{"kind":"paragraph","text":"-복숭아, 살구 등과 같은 달달한 핵과류의 향"},{"kind":"paragraph","text":"-바닐라와 견과류"},{"kind":"paragraph","text":"-허브의 터치"},{"kind":"paragraph","text":"-생각보다 강하지 않은 피트감"},{"kind":"heading","text":"Palate"},{"kind":"paragraph","text":"-향에 비해서는 약간 드라이함"},{"kind":"paragraph","text":"-바닐라, 과실감"},{"kind":"paragraph","text":"-가죽, 우디함"},{"kind":"paragraph","text":"-어딘가 화이트, 디저트 와인 같은 느낌"},{"kind":"paragraph","text":"-강하지는 않지만 존재감 있는 피트"},{"kind":"paragraph","text":"-혀끝에 남는 꿀의 느낌"},{"kind":"heading","text":"Finish"},{"kind":"paragraph","text":"-꽤나 긴 피니시"},{"kind":"paragraph","text":"-시트러스, 허니콤, 살짝의 피트"},{"kind":"paragraph","text":"포트 샬롯 로큰달 03.2는 전체적으로 핵과류, 바닐라, 화이트/디저트 와인스러운 캐릭터가 주가 되며, 피트감이 튀지 않고, 크게 흠잡을 곳 없이 아주 밸런스가 좋은 느낌입니다."},{"kind":"paragraph","text":"브룩라디 증류소의 위스키 중 소테른 캐스크를 사용하는 브룩라디, 옥토모어, 포트샬롯을 모두 마셔봤는데 확실히 다른 증류소들보다 와인 캐스크를 잘 사용하는 인상을 다시 한번 받았습니다."},{"kind":"paragraph","text":"또한 포트 샬롯 로큰달 03.2은 제가 알기로 브룩라디 증류소가 출시한 오피셜 포트샬롯 중 가장 숙성 연수가 긴 걸로 알고 있는데, 길고 우아한 피니시로 고숙성의 기대감을 채워주기도 했습니다."},{"kind":"paragraph","text":"함께 아일라 여행을 갔던 친구가 사 온 바틀인데, 개인적으로 아주 맛있게 마셨네요."}]'::jsonb, 'published', '2024-08-19T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'scotland-whisky-ep4', 'spirits', '스코틀랜드 위스키 여행 ep4 — 짧은 시간이었지만 아름다웠던 보모어 증류소', '아일라 첫째 날 마지막을 장식한 증류소는 보모어 증류소(Bowmore Distillery)였다.', '/articles/scotland-whisky-ep4/00.webp',
  'https://blog.naver.com/shakinglikebartender/223550901536', false,
  '[{"kind":"figure","src":"/articles/scotland-whisky-ep4/00.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep4/01.webp","width":966,"height":1288},{"kind":"paragraph","text":"아일라 첫째 날 마지막을 장식한 증류소는 보모어 증류소(Bowmore Distillery)였다. 그날 투어가 있기는 했지만 스케줄이 브룩라디 웨어하우스 투어와 같은 날에 하는 건 물리적으로 불가능해 비지터 센터에서 위스키만 마시게 됐다."},{"kind":"paragraph","text":"보모어 증류소는 아일라 섬의 주도인 보모어에 위치해 있는데, 호텔이 마침 근처에 있어서 비지터 센터가 닫기 직전까지 내부 바에서 위스키를 마실 수 있었다."},{"kind":"figure","src":"/articles/scotland-whisky-ep4/02.webp","width":966,"height":725},{"kind":"figure","src":"/articles/scotland-whisky-ep4/03.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep4/04.webp","width":966,"height":1288},{"kind":"paragraph","text":"지금 와서 생각해보자면 보모어 증류소는 다른 곳들보다 비지터 센터가 볼 거리도 많고, 잘돼있다는 느낌이 있다. 위스키를 마시느라 사진으로 찍는 걸 깜빡했는데, 바다 뷰로 경치도 끝내준다."},{"kind":"paragraph","text":"덤으로 여러 전설적인 바틀과 보모어 관련 굿즈들도 볼 수 있는데, 이 정도면 작은 박물관이라 해도 되겠다. 물론 마실 수는 없지만."},{"kind":"figure","src":"/articles/scotland-whisky-ep4/05.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep4/06.webp","width":966,"height":1263},{"kind":"paragraph","text":"보모어에서는 작년과 올해의 페스 아일 바틀들, 애스턴 마틴 3번째 릴리즈, 2013년에 릴리스된 보모어 23년, 27년 숙성의 보모어 핸드필 1996, 타임리스 시리즈의 27년을 마셨었다."},{"kind":"paragraph","text":"맛이 정확히 기억은 안나는데, 대부분 보모어의 향기롭고 우아한 약피트가 매력적으로 다가왔던 것은 기억에 남는다."},{"kind":"paragraph","text":"브룩라디에서 만났던 인도인 형님(?)을 다시 만났는데, 본인이 마시던 타임리스 시리즈의 31년을 건네줘서 살짝 마셔보기도 했고."},{"kind":"paragraph","text":"보모어 타임리스 시리즈를 시키면 저 작은 모래시계가 다 떨어지고 나서 마시라고 하는데, 바틀을 처음 땄더니 저 모래시계를 선물로 챙겨줬다. 모래시계는 용케 유럽여행 중에 깨지지 않고 집까지 무사히 도착했다."},{"kind":"paragraph","text":"하나 아쉬웠던 점운 브룩라디 증류소에서 옥토모어를 마시고 온 후에 보모어를 갔다는 점이다. 이미 너무 자극적인 걸 마시기도 했고, 브룩라디 증류소에서 시음도 많이 해서 혀와 코가 많이 무뎌졌었다."},{"kind":"paragraph","text":"짧은 시간 내에 많이 즐겨야하니 어쩔 수 없었지만....."},{"kind":"figure","src":"/articles/scotland-whisky-ep4/07.webp","width":966,"height":1288}]'::jsonb, 'published', '2024-08-17T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'regarding-cocktails', 'cocktail', '칵테일에 관하여 — 사샤 페트라스케를 기리며', '"Regarding Cocktails"는 현대 칵테일과 바 트렌드에 많은 영향을 미친 바인 밀크 앤 허니(Milk&Honey)를 오픈한 "사샤 페트라스케(Sasha Petraske)"와 관련된 칵테일 북입니다.', '/articles/regarding-cocktails/00.webp',
  'https://blog.naver.com/shakinglikebartender/223550948729', false,
  '[{"kind":"figure","src":"/articles/regarding-cocktails/00.webp","width":500,"height":500},{"kind":"paragraph","text":"\"Regarding Cocktails\"는 현대 칵테일과 바 트렌드에 많은 영향을 미친 바인 밀크 앤 허니(Milk&Honey)를 오픈한 \"사샤 페트라스케(Sasha Petraske)\"와 관련된 칵테일 북입니다."},{"kind":"paragraph","text":"그의 저서가 아닌 ''관련된''이라 표현했는데, 이 칵테일 북은 사샤 페트라스케의 유작으로 알려져 있지만 사실 그의 아내(Georgette Moger-Petraske)가 남편의 글을 모아 정리하고, 동업자인 바텐더들의 도움을 받아 집필한 책이기 때문입니다."},{"kind":"figure","src":"/articles/regarding-cocktails/01.webp","width":966,"height":557,"caption":"사진: Daniel Krieger / 출처: Punch Drink"},{"kind":"paragraph","text":"사샤 페트라스케는 1999년 밀크 앤 허니를 오픈하면서 스피크이지(Speakeasy) 스타일의 바를 유행시켰고, 크래프트 칵테일 운동(Craft Cocktail Movement, AKA 칵테일 르네상스)에 큰 영향을 미친 사람 중 한 명입니다."},{"kind":"paragraph","text":"당시 칵테일은 저급의 술과 재료 및 너무 단 기성품 시럽 등으로 만들어졌으며, 달고 외견만 화려한 칵테일이 주가 되었던 시대였습니다."},{"kind":"paragraph","text":"사샤 페트라스케를 포함한 몇몇 바텐더 및 음료 관계자들은 크래프트 칵테일 운동을 통해서 전통으로의 회귀, 좋은 퀄리티와 신선한 재료, 잊힌 주류의 재발견, 크래프트 재료의 사용 등으로 당시의 ‘칵테일은 저질의 것을 그나마 맛있게 만드는 것’이라는 인식을 타파하려 노력했습니다."},{"kind":"paragraph","text":"그 결과 클래식 칵테일들이 다시금 주목 받게 되었고, 잊혔던 칵테일과 주류들이 다시 발굴되었으며, 신선하고 좋은 재료와 수제 재료를 사용하여 칵테일의 맛을 높이게 되었습니다."},{"kind":"paragraph","text":"클래식 칵테일이 계속해서 인기를 누리며, 많은 변형이 나오는 것도 크래프트 칵테일 운동이 없었다면 불가능했겠죠."},{"kind":"paragraph","text":"2015년 8월 21일 사샤 페트라스케는 안타깝게도 42세의 이른 나이로 사망하게 됩니다. 밀크 앤 허니의 첫 번째 매장 위치(한 번 이사함)에는 현재 그의 제자 샘 로스(Sam Ross)의 바인 아타보이(Attaboy)가 자리 잡게 되었습니다."},{"kind":"paragraph","text":"2020년 9월 26일 밀크 앤 허니는 런던 소호에 위치한 지점이 문을 닫게 되면서 그 역사의 끝을 맞이하게 됩니다."},{"kind":"figure","src":"/articles/regarding-cocktails/02.webp","width":720,"height":540},{"kind":"paragraph","text":"다시 책 이야기로 돌아와서 Regarding Cocktails라는 책은 바텐더들보다는 홈바, 홈텐더들에게 초점이 맞춰져 있는 책입니다."},{"kind":"paragraph","text":"홈바에 필요한 바웨어, 글라스웨어에 대한 정보는 기본이고, 밀크 앤 허니에서 쓰던 시럽이나 홈 칵테일 파티를 위한 유의점 등과 같은 정보가 실려 있는 걸 보면 더욱 홈바에 적절한 책이죠."},{"kind":"figure","src":"/articles/regarding-cocktails/03.webp","width":606,"height":454},{"kind":"figure","src":"/articles/regarding-cocktails/04.webp","width":897,"height":673},{"kind":"paragraph","text":"칵테일 레시피 소개 같은 경우에는 재료를 아주 센스 있게 표현했고, 메이킹 과정에 더해 사샤 페트라스케와 관련 있는 사람들의 소회가 주로 적혀 있습니다. 여기서는 메이킹보다는 관련인들의 소회가 좀 더 주가 되는 느낌을 받았습니다."},{"kind":"paragraph","text":"화려하지 않고, 디테일한 메이킹 정보 등이 실려있지는 않지만 필요한 내용을 알차고 담담하게 소개하고 있다는 인상이 마치 사샤 페트라스케 그 자체를 간접적으로 보여주는 것 같네요."},{"kind":"paragraph","text":"여기에 더해 밀크 앤 허니의 칵테일 레시피도 실려있으니 홈바에 반드시 한 권쯤 두는 걸 강력하게 추천드립니다."}]'::jsonb, 'published', '2024-08-17T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'scotland-whisky-ep3', 'spirits', '스코틀랜드 위스키 여행 ep3 — 낭만 넘치는 브룩라디 증류소 웨어하우스 테이스팅 투어', '보모어에서 브룩라디 증류소(Bruichladdich Distilley)까지는 버스로 약 20분가량이 소요되는데, 해안선을 따라 달리는 버스에서 바깥 풍경과 건너편에서 작게나마 보이는 브룩라디 증류소를 보고 있으면 두근거리기 마련이다.', '/articles/scotland-whisky-ep3/00.webp',
  'https://blog.naver.com/shakinglikebartender/223550131652', false,
  '[{"kind":"figure","src":"/articles/scotland-whisky-ep3/00.webp","width":966,"height":1288},{"kind":"paragraph","text":"보모어에서 브룩라디 증류소(Bruichladdich Distilley)까지는 버스로 약 20분가량이 소요되는데, 해안선을 따라 달리는 버스에서 바깥 풍경과 건너편에서 작게나마 보이는 브룩라디 증류소를 보고 있으면 두근거리기 마련이다."},{"kind":"paragraph","text":"우리가 탔던 버스는 브룩라디까지 아무도 타지 않았고, 기사님은 \"오늘 너네가 버스 전세 냈네!\"라며 너스레를 떨었고, 지나치는 사람들은 손을 흔들며 환호했다. 이른 아침부터 다들 축제로 들뜬 분위기."},{"kind":"figure","src":"/articles/scotland-whisky-ep3/01.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep3/02.webp","width":966,"height":1288},{"kind":"paragraph","text":"브룩라디에 도착하기 전에 식사를 하지 않았다면 증류소 옆의 미니 마켓에서 때우는 걸 추천한다. 영국 커피는 정말 맛없었는데, 샌드위치는 꽤 맛있더라."},{"kind":"paragraph","text":"이날의 첫 끼를 빠르게 해치우고 브룩라디 투어 전에 증류소 샵을 보러 갔다."},{"kind":"figure","src":"/articles/scotland-whisky-ep3/03.webp","width":966,"height":543},{"kind":"paragraph","text":"증류소 샵은 이것저것 판매하고 있었고, 하이라이트는 역시 올해 축제 바틀이었다. 축제 바틀로는 브룩라디, 포트샬롯, 옥토모어, 발린치가 각각 나왔는데, 옥토모어는 500미리 325파운드라는 가격으로 말문을 막히게 했다."},{"kind":"paragraph","text":"물론 올해 옥토모어 페스 아일 바틀은 쉬라 캐스크에서 12년을 숙성한 것으로, 아마 현재까지 나온 증류소 오피셜 옥토모어 중에서 가장 숙성이 길기는 하다. 그렇지만 500미리에 325파운드...."},{"kind":"paragraph","text":"옥토모어는 깔끔하게 포기하고, 발린치가 세컨 필 셰리 벗 17년 숙성인데 80파운드였고(이것도 500미리....), 시음해 보고 이걸 샀는데 정말 맛있어서 후회는 없다."},{"kind":"figure","src":"/articles/scotland-whisky-ep3/04.webp","width":966,"height":725},{"kind":"paragraph","text":"증류소 샵에서 투어 시간이 되면 코피타 잔을 주면서 본격적인 투어가 시작된다. 우리는 웨어하우스 투어를 신청했는데, 꼭 반드시 이 투어를 하는 걸 추천한다. 웨어하우스에서 릴리즈되지 않는 브룩라디, 포트 샬롯, 옥토모어를 한 잔씩 맛볼 수 있는 투어기 때문이다."},{"kind":"paragraph","text":"위스키는 이런 식으로 캐스크에서 바로바로 빼서 잔에 따라준다."},{"kind":"figure","src":"/articles/scotland-whisky-ep3/05.webp","width":966,"height":1288,"caption":"바이알은 요청하면 무료로 준다."},{"kind":"paragraph","text":"이날의 베스트는 옥토모어였는데, 14년 소테른 캐스크 숙성이었다. ppm은 110이었나 했는데, 피트감이 전혀 강하지 않고, 달달한 소테른 캐스크의 캐릭터와 고소한 보리의 캐릭터와 함께 느껴지는 것이 지금까지 마신 위스키 top3에 들었다."},{"kind":"paragraph","text":"물론 아일라 섬에서, 증류소의 웨어하우스에서 마셨다는 점과 증류소 스태프의 낭만 넘치는 대사를 들은 것도 영향이 있었을 것 같다."},{"kind":"quote","text":"이 세 위스키를 좋아하되, 사랑에 빠지지는 마세요."},{"kind":"quote","text":"지금 여기서만 마실 수 있으니"},{"kind":"paragraph","text":"이러는데 맛이 없을 수가 있을까? 듣는 순간 투어에 참여한 모든 사람이 감탄을 내뱉었고, 그 순간부터는 낭만에 취하는 느낌이었다."},{"kind":"paragraph","text":"여담으로, 투어 안내를 해준 스태프는 ''루비''라는 분이었는데, 우리가 한국에서 왔다고 하니 이 분이 이전에 아드벡에서 일했었다면서 화심주조의 오수민 대표님이 잘 있냐며 보고 싶다고 하더라."},{"kind":"paragraph","text":"마지막으로 시음과 관련한 팁을 하나 공유하자면, 기본적으로 브룩라디 증류소에는 테이스팅 공간이 없다."},{"kind":"paragraph","text":"다만, 증류소 샵의 계산대 쪽에서 직원에게 뒤편의 위스키들을 시음해 볼 수 있는지 물어보면 시음을 도와준다. 딱히 제한도 없어서 이것저것 꼭 마셔보시길(무한으로 즐겨요)."},{"kind":"figure","src":"/articles/scotland-whisky-ep3/06.webp","width":966,"height":1287},{"kind":"figure","src":"/articles/scotland-whisky-ep3/07.webp","width":966,"height":1288,"caption":"주섬주섬 꺼내든 건 발린치아름다운 하늘색의 브룩라디를 추억하며"}]'::jsonb, 'published', '2024-08-16T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'scotland-whisky-ep2', 'spirits', '스코틀랜드 위스키 여행 ep2 — 드디어 꿈에 그리던 아일라로', '글래스고에서 아일라로 가는 방법은 크게 두 가지가 있다.', '/articles/scotland-whisky-ep2/00.webp',
  'https://blog.naver.com/shakinglikebartender/223549995582', false,
  '[{"kind":"figure","src":"/articles/scotland-whisky-ep2/00.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep2/01.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep2/02.webp","width":966,"height":1288},{"kind":"paragraph","text":"글래스고에서 아일라로 가는 방법은 크게 두 가지가 있다."},{"kind":"paragraph","text":"1. 글래스고 공항에서 경비행기 타기"},{"kind":"paragraph","text":"2. 버스나 렌터카를 통해 케나크레이그로 이동 후 페리 타기."},{"kind":"paragraph","text":"**좀 더 자세한 내용은 ep0 참고!!!"},{"kind":"paragraph","text":"이번에는 2박 3일이라는 짧은 기간에서 되도록 시간을 잘 쓰기 위해 경비행기를 타고 아침 일찍 아일라로 이동했다. 참고로 글래스고 시내에서 공항까지는 500 Airport Express 버스로 이동이 편하고, 구글 맵에서도 쉽게 찾아볼 수 있다."},{"kind":"figure","src":"/articles/scotland-whisky-ep2/03.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep2/04.webp","width":966,"height":1288,"caption":"멀리서 보이는 포트 엘런과 아일라 공항"},{"kind":"paragraph","text":"경비행기 자체는 내부가 엄청 시끄럽기는 했지만 비행시간 자체가 짧아서 강력하게 추천한다. 다만, 날씨라는 변수에 따라 결항될 확률도 있긴 하다. 아일라 공항에서는 와이파이나 데이터가 잘 안 터지는데 전화는 또 잘 된다."},{"kind":"paragraph","text":"택시를 타고 예약한 호텔로 향하던 중에 논두렁에 차가 한 대 빠져있는 걸 보고선 택시 운전수가 \"아일라에 온 걸 환영해, 저렇게까지 마시진 말라구.\"라고 농담하는 걸 듣고 친구와 빵 터졌고, 아일라에 왔다는 걸 새삼 실감하게 되었다."},{"kind":"paragraph","text":"보모어에 도착해서 호텔에 짐을 맡기고, 버스를 타고 브룩라디 증류소로 향했다."},{"kind":"figure","src":"/articles/scotland-whisky-ep2/05.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep2/06.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep2/07.webp","width":966,"height":1289}]'::jsonb, 'published', '2024-08-16T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'scotland-whisky-ep1', 'spirits', '스코틀랜드 위스키 여행 ep1 — 글래스고, 이곳에도 위스키와 증류소가 있어', '아일라나 스코틀랜드의 다른 위스키 지역을 가기 위해서는 글래스고와 에든버러 둘 중에 웬만하면 한 곳은 들러야 한다.', '/articles/scotland-whisky-ep1/00.webp',
  'https://blog.naver.com/shakinglikebartender/223546645087', false,
  '[{"kind":"paragraph","text":"아일라나 스코틀랜드의 다른 위스키 지역을 가기 위해서는 글래스고와 에든버러 둘 중에 웬만하면 한 곳은 들러야 한다."},{"kind":"paragraph","text":"개인적으로 글래스고를 선택한 이유는 에든버러보다는 조금 더 아일라가 가까웠기 때문이고, 위스키 성지인 팟스틸(Pot Still)이 있기 때문이었다. 그런데 시내에 증류소도 있더라."},{"kind":"figure","src":"/articles/scotland-whisky-ep1/00.webp","width":966,"height":1288},{"kind":"paragraph","text":"처음 도착한 글래스고는 도시 자체가 너무나 이뻤다. 술과는 전혀 상관없지만, 그냥 찍었던 사진을 넣고 싶어서..."},{"kind":"quote","text":"클라이드사이드 증류소"},{"kind":"quote","text":"Clydeside Distillery"},{"kind":"figure","src":"/articles/scotland-whisky-ep1/01.webp","width":966,"height":1288},{"kind":"paragraph","text":"\"클라이드사이드 증류소\"는 글래스고 시내에 위치한 증류소로, 2017년에 오픈한 신생 증류소이며, 2021년 첫 번째 싱글몰트 위스키를 출시했다. 지역적으로 로우랜드(Lowland) 싱글몰트 위스키."},{"kind":"paragraph","text":"재밌는 점은 빔 산토리가 보모어 증류소를 인수하기 전까지 보모어 증류소를 소유하고 있던 모리슨 패밀리가 이 증류소를 소유하고 있다는 점이다."},{"kind":"paragraph","text":"증류소에서는 투어를 즐길 수도 있으며, 내부의 카페에서 간단한 음식을 먹거나 위스키 시음이 가능하다. 글래스고 여행자들이 라이트 하게 접하기 좋은 투어이며, 학생이면 할인도 된다."},{"kind":"figure","src":"/articles/scotland-whisky-ep1/02.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/scotland-whisky-ep1/03.webp","width":966,"height":1717},{"kind":"paragraph","text":"증류소는 ''클라이드 강'' 바로 옆에 있는데, 투어 중 증류소 스태프가 투어 참가자들에게 질문을 해온다."},{"kind":"paragraph","text":"\"위스키를 만드는 데 있어서 좋은 물은 필수입니다. 우리 증류소는 어디에서 물을 길어올까요?\""},{"kind":"paragraph","text":"강을 옆에 두고 이런 질문을 하는 데는 다 이유가 있다. 참가자 대부분은 당연히 옆에 있는 강이라고 답변하는데, 스태프는 낚시에 성공했다는 듯이 웃으며 카트린 호(Loch Katrine)가 수원이라고 한다. 관광객이 어떻게 아냐고....ㅋㅋㅋㅋ"},{"kind":"figure","src":"/articles/scotland-whisky-ep1/04.webp","width":966,"height":1288},{"kind":"paragraph","text":"투어에는 위스키 테이스팅이 포함되는데, 클라이드사이드의 뉴메이크 스피릿(NMS)과 미출시 바틀들을 시음할 수 있다. 이 뉴메이크 스피릿이 꽤 맛있었던 기억이 있었는데, 사실 뉴메이크 스피릿을 시음할 수 있는 증류소 투어는 많지 않다."},{"kind":"paragraph","text":"물론, 나중에 라가불린에서 가격대가 좀 있는 투어를 했을 때는 뉴메이크 스피릿을 마셔봤지만, 저렴한 가격의 투어라면 굳이 뉴메이크 스피릿을 제공하지 않는다. 아마 클라이드 사이드가 신생 증류소라 제공해 주지 않았을까 싶긴 하다."},{"kind":"quote","text":"바 팟 스틸"},{"kind":"quote","text":"Bar Pot Still"},{"kind":"paragraph","text":"\"팟 스틸\"은 글래스고 시내에 위치한 바로, 위스키 러버들에게는 스코틀랜드 위스키 성지 취급을 받으며, 우리나라 방송에도 노출된 적이 있을 정도로 꽤나 유명한 곳이다. 일찍부터 오픈하니 낮술 하기에도 딱 좋다."},{"kind":"figure","src":"/articles/scotland-whisky-ep1/05.webp","width":966,"height":1717},{"kind":"paragraph","text":"백바에는 수많은 위스키가 있으며, 당연히 우리나라에서 볼 수 없는 위스키들도 많다. 다만, 특이한 점은 대부분의 손님이 꽤 나이가 지긋했고, 대부분 맥주를 마신다는 점이었다. 위스키를 마시는 건 관광객 정도."},{"kind":"figure","src":"/articles/scotland-whisky-ep1/06.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/scotland-whisky-ep1/07.webp","width":966,"height":1717,"caption":"첫 번째 사진처럼 푸어하는 건팟 스틸의 시그니처"},{"kind":"paragraph","text":"이날 위스키를 다양하게 마시긴 했지만, 병을 바로바로 치우는 바람에 사진을 많이 찍지는 못했다. 그중 이날의 베스트는 위스키 스펀지의 킬달튼(이라 쓰고 아드벡이라 읽음)이었다."},{"kind":"paragraph","text":"출시할 때부터 마셔보고 싶었는데, 마침 선반에 있길래 바로 주문했고, 지금에 와서는 구체적인 맛까지는 기억이 안 나지만 마시자마자 감탄했던 기억이 있다."},{"kind":"paragraph","text":"주문에 관해서 팟 스틸에는 메뉴가 따로 없어서 백바를 확인하고 종업원에게 부탁을 하거나, 잘 모르겠다 싶으면 추천을 해달라고 할 수도 있다. 예를 들어, \"몇 잔을 몇 파운드까지의 예산으로 ~~캐릭터의 위스키로 추천해 주세요.\" 정도로 물어볼 수도 있다."},{"kind":"paragraph","text":"어디까지 예시이니 편하게 물어보면 되겠다. 몇몇 분들은 가격을 물어봐도 될까?라는 생각을 하실 수 있는데, 가격 물어보는 게 전혀 실례는 아니니 마음껏 물어보시라."},{"kind":"paragraph","text":"다만, 되도록이면 구체적으로 추천해달라고 문의하는 것이 좋은 게, 직원들이 되도록이면 증류소의 오피셜 라인 중에서도 코어 라인을 위주로 추천하는 경향이 있는 것 같다."},{"kind":"paragraph","text":"그 와중에 오큰토션은 여기서도 찬밥 신세....(아메리칸 오크가 단돈 3파운드!)"}]'::jsonb, 'published', '2024-08-13T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'scotland-whisky-ep0-5', 'spirits', '스코틀랜드 위스키 여행 ep0.5 — 아일라 섬에서 열리는 위스키 축제, 페스 아일에 대해서 알아보자', '페스 아일(Feis Ile)은 매년 5월 마지막 주에 아일라(Islay) 섬과 주라(Jura) 섬에서 약 1~2주간에 걸친 위스키 관련 축제입니다.', '/articles/scotland-whisky-ep0-5/00.webp',
  'https://blog.naver.com/shakinglikebartender/223546572556', false,
  '[{"kind":"figure","src":"/articles/scotland-whisky-ep0-5/00.webp","width":966,"height":966},{"kind":"figure","src":"/articles/scotland-whisky-ep0-5/01.webp","width":966,"height":966},{"kind":"paragraph","text":"페스 아일(Feis Ile)은 매년 5월 마지막 주에 아일라(Islay) 섬과 주라(Jura) 섬에서 약 1~2주간에 걸친 위스키 관련 축제입니다."},{"kind":"paragraph","text":"1985년, 아일라 섬에서는 관광객을 유치하고, 사라져가는 게일어를 지키기 위하는 등의 목적으로 지역 위원회가 구성되었고, 1986년에 첫 번째 페스 아일(Feis Isle)이 개최되었습니다."},{"kind":"paragraph","text":"다만, 처음부터 오늘날과 같이 위스키에 초점을 맞춘 축제는 아니었고, 아일라의 아름다운 자연 풍경과 더불어 게일어 연극이나 음악과 관련된 콘텐츠나 지역 커뮤니티 연계 콘텐츠가 주였다고 합니다."},{"kind":"paragraph","text":"2000년에 들어서야 아일라 섬의 증류소들이 마스터 클래스나 오픈 데이(Open Day)를 여는 등 축제에 참여하기 시작했고, 축제 기념 위스키를 출시하게 되기에 이릅니다. 여기에 더해 독립병입자들 또한 축제 한정 바틀을 출시하기도 합니다."},{"kind":"paragraph","text":"이 아일라 섬에서 열리는 축제는 지역민의 자원봉사로 이루어지는 것으로 알고 있는데, 그래서인지 업데이트가 다소 느린 편이고, 지역민이 운영하던 가게나 B&B를 축제 기간에 문을 닫기도 하는 경우도 왕왕 있습니다."},{"kind":"figure","src":"/articles/scotland-whisky-ep0-5/02.webp","width":966,"height":966},{"kind":"figure","src":"/articles/scotland-whisky-ep0-5/03.webp","width":966,"height":966},{"kind":"paragraph","text":"페스 아일 기간에 증류소는 각각 오픈 데이를 가지면서 증류소 한정 제품을 선보이거나, 록 밴드를 불러 공연을 하는 등의 각종 엔터테인먼트 거리를 제공합니다. 예를 들어, 올해 아드벡 데이에는 서커스를 테마로 했고, 그 외에 록 밴드의 공연이 있었습니다."},{"kind":"paragraph","text":"페스 아일 일정과 티켓에 관한 정보는 여기에서 확인할 수 있습니다."},{"kind":"paragraph","text":"참고로, 각 증류소의 오픈 데이가 아니라 하더라도 해당 증류소 투어나 비지터 센터 이용이 가능합니다. 다만, 투어 예약은 각 증류소 사이트에서 해야합니다."},{"kind":"figure","src":"/articles/scotland-whisky-ep0-5/04.webp","width":966,"height":966},{"kind":"figure","src":"/articles/scotland-whisky-ep0-5/05.webp","width":966,"height":966},{"kind":"figure","src":"/articles/scotland-whisky-ep0-5/06.webp","width":966,"height":966},{"kind":"figure","src":"/articles/scotland-whisky-ep0-5/07.webp","width":966,"height":966},{"kind":"paragraph","text":"증류소마다 출시하는 축제 바틀은 매년 다른 스펙으로 출시되며, 기본적으로 정보가 공개되지만 증류소에 따라서 공개하지 않는 경우도 있습니다."},{"kind":"paragraph","text":"예를 들어서 브룩라디 증류소는 브룩라디와 포트샬롯에 대해서는 사전예약을 통한 판매를 했었는데, 옥토모어와 발린치에 대해서는 따로 공개를 하지 않았던 걸로 기억합니다."},{"kind":"paragraph","text":"축제 한정 위스키들은 축제 기간에 대부분 증류소에서 맛볼 수 있으며, 증류소가 없는 독립병입자들 같은 경우는 레스토랑 등에서 시음회를 열기도 합니다. 이 티켓들은 공식 축제 홈페이지에서 확인할 수 있습니다."},{"kind":"paragraph","text":"아래는 올해 페스 아일을 기념해 출시한 바틀들이니 참고해 주세요."},{"kind":"paragraph","text":"**페스 아일 2024 출시 바틀 정보"},{"kind":"paragraph","text":"보모어 (Bowmore)"},{"kind":"paragraph","text":"- 19년"},{"kind":"paragraph","text":"- 버진 아메리칸 오크에서 더블 메추어드"},{"kind":"paragraph","text":"- 54.8%"},{"kind":"paragraph","text":"브룩라디"},{"kind":"paragraph","text":"1. 브룩라디 록앤달 03.1 (Bruichladdich ROCK‘NDAAL 03.1)"},{"kind":"paragraph","text":"- 100% 스코틀랜드 보리(Scottish Barley)"},{"kind":"paragraph","text":"- 소테른 캐스크(Sauterne Cask, 12.5%), 오스트리아 디저트 와인 캐스크(Austrian Dessert Wine Cask, 12.5%), PX 셰리를 숙성한 후 스페인 브랜디(페르난도 드 카스티야/Fernando de Castilla)를 숙성한 엑스 브랜디 캐스크(ex-Brandy Cask, 75%)의 원액을 엑스 버번 캐스크(ex-Bourbon Cask)에서 2017년~2023년 숙성"},{"kind":"paragraph","text":"- 10년"},{"kind":"paragraph","text":"-50%, 논피트"},{"kind":"paragraph","text":"2. 포트샬롯 (Port Charlotte)"},{"kind":"paragraph","text":"- 100% 스코틀랜드 보리(Scottish Barley)"},{"kind":"paragraph","text":"- 20년"},{"kind":"paragraph","text":"- 버번 캐스크(Bourbon Cask, 70%), 퍼스트 필 소테른 캐스크(First fill Sauterne Cask, 30%)"},{"kind":"paragraph","text":"- 54%, 40ppm"},{"kind":"paragraph","text":"3. 옥토모어 발린치 0.3 (Octomore Valinch 0.3)"},{"kind":"paragraph","text":"- 12년"},{"kind":"paragraph","text":"- 세컨 필 시라 캐스크(2nd fill Syrah Cask)"},{"kind":"paragraph","text":"- 싱글 캐스크"},{"kind":"paragraph","text":"- 58.2%, 150.2ppm, 500ml"},{"kind":"paragraph","text":"4. 발린치 (Valinch)"},{"kind":"paragraph","text":"- 17년"},{"kind":"paragraph","text":"- 세컨 필 셰리 벗(2nd fill Sherry Butt)"},{"kind":"paragraph","text":"- 57.1%, 논피트, 500ml"},{"kind":"paragraph","text":"라가불린"},{"kind":"paragraph","text":"1. 라가불린 10년 (Lagavulin 10yo feis ile 2024)"},{"kind":"paragraph","text":"- 10년"},{"kind":"paragraph","text":"- 리필 헤빌리 차드 캐스크(Refill, Heavili Charred Cask), 퍼스트 필 엑스 버번 아메리칸 오크 혹스헤드 캐스크(1st fill ex-Bourbon American Oak Hogshead Cask)"},{"kind":"paragraph","text":"- 56.7%, 기존의 라가불린보다 강한 피트감이 특징"},{"kind":"paragraph","text":"2. 라가불린 스카이 오브 페스 아일(Lagavulin Skies of Feis ile)"},{"kind":"paragraph","text":"- 엑스 보데가 셰리 캐스크(ex-Bodega Sherry Cask)에서 1995년 5월부터 약 20년 숙성 후, 아모로소 세리 와인으로 시즌된 아메리칸 오크를 헤빌리 차드한 베럴(heavily charred barrel of American oak treated with Amoroso)에서 8년 숙성"},{"kind":"paragraph","text":"- 52.4%"},{"kind":"paragraph","text":"아드벡 스펙타큘러 (Ardbeg Spectacular)"},{"kind":"paragraph","text":"- 포트 캐스크(Port Cask), 엑스 버번 캐스크(ex-Bourbon Cask)"},{"kind":"paragraph","text":"- 46%"},{"kind":"paragraph","text":"라프로익 카데어스 (Laphroaig Cairdeas)"},{"kind":"paragraph","text":"- 10년"},{"kind":"paragraph","text":"- 엑스 버번 캐스크 + 쿼터 캐스크를 PX 셰리 캐스크에서 피니시 (ex-bourbon + Quarter Cask finished in PX)"},{"kind":"paragraph","text":"- 52.4%"},{"kind":"paragraph","text":"부나하벤"},{"kind":"paragraph","text":"1. 27년"},{"kind":"paragraph","text":"- 모스카텔 캐스크에서 9년간 피니시(Moscatel Cask Finish)"},{"kind":"paragraph","text":"- 46.4"},{"kind":"paragraph","text":"2. 23년"},{"kind":"paragraph","text":"- 트리플 셰리 우드 피니시(Triple Sherry Wood Finish)"},{"kind":"paragraph","text":"- 아몬티야도(Amontillado), 만자니야(Manzanilla), 올로로소(Olorosso)의"},{"kind":"paragraph","text":"- 53.3%, 캐스크 스트렝스"},{"kind":"paragraph","text":"3. 14년"},{"kind":"paragraph","text":"- 버번 캐스크(Bourbon Cask) 11년 숙성 후, 루피 포트 혹스헤드(Ruby Port Hogshead)에서 3년 피니시"},{"kind":"paragraph","text":"- 58.7%"},{"kind":"paragraph","text":"4. 19년"},{"kind":"paragraph","text":"- 버번 캐스크(Bourbon Cask)에서 12년 숙성 후, 마데이라 혹스헤드(Madeira Hogshead)에서 7년 피니시"},{"kind":"paragraph","text":"- 51.2%, 피티드"},{"kind":"paragraph","text":"킬호만 (Kilchoman)"},{"kind":"paragraph","text":"- 2011년 증류한 두 개의 버번 캐스크를 배팅한 것(Vatting of two fresh Bourbon Barrels)"},{"kind":"paragraph","text":"- 53%, 논피티드"},{"kind":"paragraph","text":"쿨일라 (Caol Ila)"},{"kind":"paragraph","text":"- 13년"},{"kind":"paragraph","text":"- 루비 포트 프렌치 오크(Ruby Port French Oak)"},{"kind":"paragraph","text":"- 54.5%"},{"kind":"paragraph","text":"아드나호 (Ardnahoe)"},{"kind":"paragraph","text":"- 5년"},{"kind":"paragraph","text":"- 퍼스트필 & 리필 버번 캐스크(1st Fill & Refill Bourbon Barrel)"},{"kind":"paragraph","text":"- 59.3%"},{"kind":"paragraph","text":"주라 (Jura)"},{"kind":"paragraph","text":"- 15년"},{"kind":"paragraph","text":"- 퍼스트필 버번 캐스크(1st fill Bourbon Cask)"},{"kind":"paragraph","text":"- 55.5%, 캐스크 스트렝스"},{"kind":"paragraph","text":"빅피트 (Big Peat)"},{"kind":"paragraph","text":"- 럼 캐스크 피니시(Rum Finish)"},{"kind":"paragraph","text":"- 48%"},{"kind":"paragraph","text":"엘리먼트 오브 아일라 (Elements of Islay)"},{"kind":"paragraph","text":"- 쿨일라 & 부나하벤 블렌디드"},{"kind":"paragraph","text":"- 헤빌리 리-차드 혹스헤드(Heavily re-charred Hogshead), 아메리칸 오크 올로로소 셰리 혹스헤드(American Oak Oloroso Sherry Hogshead), 유로피안 오크 올로로소 셰리 벗(European Oak Oloroso Sherry Butt)"},{"kind":"paragraph","text":"- 54.5%"},{"kind":"paragraph","text":"막탈라 (Mac-Talla)"},{"kind":"paragraph","text":"- 15년"},{"kind":"paragraph","text":"- 혹스헤드(Hogshea) 10년 숙성 후, 크루잔 럼 캐스크(Cruzan Rum Cask) 5년 숙성"},{"kind":"paragraph","text":"- 53.7%"},{"kind":"paragraph","text":"스카치 몰트 오브 스코틀랜드 (SMWS)"},{"kind":"paragraph","text":"1. Sm''oak!"},{"kind":"paragraph","text":"- 증류소 코드: 29"},{"kind":"paragraph","text":"- 25년"},{"kind":"paragraph","text":"- 리필 혹스헤드(Refill hogsheads), 퍼스트필 올로로소 바리끄 STR(1st-fill Oloroso barriques STR)"},{"kind":"paragraph","text":"- 56.3%, 헤빌리 피티드"},{"kind":"paragraph","text":"2. Winter''s green"},{"kind":"paragraph","text":"- 증류소 코드: 53"},{"kind":"paragraph","text":"- 12년"},{"kind":"paragraph","text":"- 리필 혹스헤드(Refill hogsheads)"},{"kind":"paragraph","text":"- 57.6%"},{"kind":"paragraph","text":"드램풀 리키 라디 (Dramfool Leaky Laddie)"},{"kind":"paragraph","text":"- 브룩라디 15년"},{"kind":"paragraph","text":"- 퍼스트필 버번 캐스크(1st fill Bourbon cask) 숙성 중 리필 셰리 옥타브로 리랙킹(re-racked into a refill sherry octave)"},{"kind":"paragraph","text":"- 58%, 캐스크 스트렝스"},{"kind":"paragraph","text":"- 200ml로 77병 출시"},{"kind":"paragraph","text":"더 싱글 캐스크 (The Single Cask/TSC)"},{"kind":"paragraph","text":"- 린스(rhinns) > 브룩라디 증류소"},{"kind":"paragraph","text":"- 12년"},{"kind":"paragraph","text":"- 버번 캐스크(Fresh Bourbon Barrel)"},{"kind":"paragraph","text":"- 60.4%"},{"kind":"paragraph","text":"핀라간 (Finlaggan)"},{"kind":"paragraph","text":"- 템프라니요 바리끄(Tempranillo Barrique)"},{"kind":"paragraph","text":"- 50%"},{"kind":"paragraph","text":"아일라 미스트 (Islay Mist)"},{"kind":"paragraph","text":"- 17년"},{"kind":"paragraph","text":"- 40%"}]'::jsonb, 'published', '2024-08-13T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'scotland-whisky-ep0', 'spirits', '스코틀랜드 위스키 여행 ep0 — 아일라, 피트 위스키 축제가 열리는 아일라로 가자', '아일라 여행은 너무나도 급작스럽게도 장난삼아 한 말이 발단으로 시작됐다.', '/articles/scotland-whisky-ep0/00.webp',
  'https://blog.naver.com/shakinglikebartender/223545245219', false,
  '[{"kind":"quote","text":"오, 아일라에서는 위스키 축제를 한다는데, 유럽 여행 함 가실?"},{"kind":"paragraph","text":"아일라 여행은 너무나도 급작스럽게도 장난삼아 한 말이 발단으로 시작됐다. 2023년 3월 즈음에 아일라에서는 5월 마지막 주 ~ 6월 첫째 주에 열리는 위스키 축제가 있다는 걸 알게 됐고, 조금씩 위스키에 관심을 갖게 된 친구에게 물어본 것이 시작."},{"kind":"paragraph","text":"그렇게 2024년 아일라에서 열리는 페스 아일(Feis Ile) 기간을 알아보고, 비행기표를 속전속결로 예약했다. 중간 과정을 뛴 것 같지만 놀랍게도 중간 과정은 없었는걸...."},{"kind":"paragraph","text":"그러고 나서 곧바로 숙소를 예약하지 않은 걸 아직까지도 후회한다."},{"kind":"paragraph","text":"아일라에서 숙박을 해결할 수 있는 방법은 아주 다양하다. 호텔, 코티지, 도미토리, B&B, 캠핑카, 텐트가 그 방법들인데, 먼저 캠핑카와 텐트는 일단 제외하고, 코티지는 단체로 갈 거 아니면 너무 비싸니 다른 것을 찾아보자."},{"kind":"figure","src":"/articles/scotland-whisky-ep0/00.webp","width":837,"height":837,"caption":"아일라 섬 / 출처: Google Map"},{"kind":"paragraph","text":"일단 아일라에서 그래도 큰 마을은 보모어와 포트 엘런 지역이다. 여기서 호텔과 B&B를 찾아볼 수 있고, 생각보다 숙소가 많은 편이다. 그 외에 포트 샬롯 지역에는 유스호스텔이 있는데, 여기가 제일 가격적으로는 싸다."},{"kind":"paragraph","text":"가격은 코티지>>호텔>B&B>유스호스텔 순"},{"kind":"paragraph","text":"숙소를 여기저기 알아보면서 아직 가기까지 1년 넘게 남았네~하고 여유 부리고 있었는데, 가기 10개월 전에야 가는 날짜 세기가 지루해서 숙소에 예약 가능 여부를 물어봤다."},{"kind":"paragraph","text":"대강 열 곳이 넘는 곳에 메일을 보냈는데, 충격적이게도 축제 기간에는 B&B를 운영하지 않는 곳도 있거니와 이미 방이 다 찼다는 답변만 받았다. 축제 기간이라는 것과 전 세계 술쟁이들이 모이는 축제인 걸 간과한 탓에 아일라 가서 텐트 치고 자게 생긴 것이다."},{"kind":"paragraph","text":"여담으로 축제 기간에는 아일라 주민들이 축제 준비를 도와주거나 스태프로 참여하는 경우가 있어서 B&B를 축제 기간 동안 운영하지 않는 경우가 많다."},{"kind":"figure","src":"/articles/scotland-whisky-ep0/01.webp","width":966,"height":966},{"kind":"paragraph","text":"''숙소를 예약 못했더니 아일라 섬에서 텐트 치기라는 이색 경험을 하게 됐네!''라는 원영적 사고를 친구와 하고 있던 참에, 다행히도 보모어에 위치한 보모어 호텔에서 2박 3일은 가능하다고 해서 원래 계획에서 하루를 줄이게 되었다."},{"kind":"paragraph","text":"남자 두 명이서 바다가 보이는 스위트룸을 1박에 230파운드로 사용하게 됐고.... 아직까지도 3박 4일 일정을 계획했는데 하루가 줄어든 게 너무 아쉽다."},{"kind":"paragraph","text":"혹시라도 페스 아일 기간에 아일라를 방문하려고 계획하는 분들은 이 글을 보자마자 숙소를 알아보시길...."},{"kind":"figure","src":"/articles/scotland-whisky-ep0/02.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/scotland-whisky-ep0/03.webp","width":966,"height":1288},{"kind":"paragraph","text":"아일라 섬을 들어가는 방법으로는 글래스고 공항에서 출발하는 로건에어(Logan Air)의 경비행기와 케나크레이그(Kennacraig)와 포트 에스케이그(Port Askaig) / 포트 엘런(Port Ellen)을 연결해 주는 페리가 있다."},{"kind":"paragraph","text":"1. 경비행기"},{"kind":"paragraph","text":"- 빠르게 갈 수 있음 (약 30분)"},{"kind":"paragraph","text":"- 이른 시간에 섬에 들어가서 하나라도 더 증류소 체험이 가능함"},{"kind":"paragraph","text":"- 경비행기를 경험할 수 있음(?)"},{"kind":"paragraph","text":"- 날씨에 따라서 결항될 위험이 높음"},{"kind":"paragraph","text":"2. 페리"},{"kind":"paragraph","text":"- 저렴함"},{"kind":"paragraph","text":"- 글래스고(뷰캐넌 버스터미널)에서 케나크레이그까지 가서 페리로 갈아타야 함"},{"kind":"paragraph","text":"- 버스와 페리 시간을 잘 맞춰야 함"},{"kind":"paragraph","text":"- 입항 당일에는 증류소 체험할 시간이 안될 수 있음"},{"kind":"paragraph","text":"- 페리 스케줄 사이트"},{"kind":"paragraph","text":"개인적으로 섬에 들어갈 때는 경비행기를, 섬에서 나갈 때는 페리를 이용하는 게 좋은 것 같다. 어차피 마지막 날에는 페리 시간 맞추느라 증류소 방문하기가 좀 어렵기 때문에."},{"kind":"figure","src":"/articles/scotland-whisky-ep0/04.webp","width":966,"height":1288},{"kind":"paragraph","text":"아일라 내부에서 이동할 때는 생각보다 많은 이동 수단이 존재하니 시간과 예산에 맞춰서 이용하는 걸 추천한다."},{"kind":"paragraph","text":"1. 버스"},{"kind":"paragraph","text":"- 아일라 섬 내 버스 스케줄"},{"kind":"paragraph","text":"- 버스가 적고, 시간대마다 코스나 정류장이 다를 수 있으니 주의"},{"kind":"paragraph","text":"- 꽤 이른 시간부터 있고, 막차가 오후 5~6시 즈음이니 주의"},{"kind":"paragraph","text":"- 4월 경에 스케줄이 변경되니 주의"},{"kind":"paragraph","text":"2. 택시"},{"kind":"paragraph","text":"- 비싸지만 가장 편한 이동 수단"},{"kind":"paragraph","text":"- 공항 갈 때나 부나하벤 같은 버스가 안 가는 증류소들 방문 시 추천"},{"kind":"paragraph","text":"- 메일이나 전화로 예약해서 이용해야 함"},{"kind":"paragraph","text":"- 아예 위스키 투어를 해주는 경우도 있음"},{"kind":"paragraph","text":"3. 자전거"},{"kind":"paragraph","text":"- 가장 맘 편한 이동 수단"},{"kind":"paragraph","text":"- 금액이 합리적인 편"},{"kind":"paragraph","text":"- 방문하려는 코스에 따라서 배터리가 다르니 주의"},{"kind":"paragraph","text":"4. 히치하이킹"},{"kind":"paragraph","text":"- 축제 기간에는 차가 많아서 가능할지도?"},{"kind":"paragraph","text":"5. 렌터카"},{"kind":"paragraph","text":"- 안 해봐서 잘 모르지만, 아마 글래스고나 에든버러에서 렌트해서 페리 타고 입항해야 하는 걸로 알고 있음"}]'::jsonb, 'published', '2024-08-12T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'starward-solera', 'spirits', '스타워드 솔레라', '"스타워드"는 호주에서 생산되는 위스키로, "스타워드 증류소"는 2007년 호주의 국영 항공사인 콴타스(Qantas)의 격납고에서 처음 설립되었습니다.', '/articles/starward-solera/00.webp',
  'https://blog.naver.com/shakinglikebartender/223544208786', false,
  '[{"kind":"figure","src":"/articles/starward-solera/00.webp","width":533,"height":533},{"kind":"heading","text":"About The Whisky"},{"kind":"paragraph","text":"\"스타워드\"는 호주에서 생산되는 위스키로, \"스타워드 증류소\"는 2007년 호주의 국영 항공사인 콴타스(Qantas)의 격납고에서 처음 설립되었습니다."},{"kind":"paragraph","text":"스타워드 위스키는 변덕스러운 멜버른의 날씨로 인해서 증발량이 많고, 비교적 짧은 시간의 숙성에도 풍부한 풍미를 가지게 되었습니다."},{"kind":"paragraph","text":"\"스타워드 솔레라\"는 호주의 주정강화 와인인 아페라(Apera) 와인을 숙성했던 캐스크에서 숙성된 위스키인데, 이 아페라 와인은 호주 버전의 셰리 와인이라 할 수 있습니다."},{"kind":"paragraph","text":"다만, 2000년대 중반부터 세계적으로 유럽 연합이 무역 협정 협상에서 샴페인, 스카치, 꼬냑 등과 같은 지리적 표시의 보호를 강력하게 요구하면서 호주의 셰리 와인 또한 영향을 받게 되었습니다."},{"kind":"paragraph","text":"셰리 와인은 스페인의 헤레스(Jerez) 지역에서 생산되는 주정강화 와인으로, 원산지 증명과 지리적 표시 보호를 받아 이 지역에서 생산된 것이 아니면 ''셰리''라는 이름을 사용하지 못합니다. 이로 인해 호주의 셰리 와인은 이름을 아페라 와인으로 변경하게 되었다고 합니다."},{"kind":"paragraph","text":"아페라 와인 캐스크를 사용해서 셰리 위스키 숙성 방식인 ''솔레라 방식''으로 위스키를 숙성한다고 하며, 간략히 얘기해서 가장 오래 숙성된 캐스크에서 위스키를 일정량 병입하고, 그만큼을 덜 숙성된 캐스크에서 채워 넣는 식의 일종의 계단식 숙성 시스템입니다."},{"kind":"paragraph","text":"이런 숙성 방법으로 인해 스타워드에서는 \"오늘날 만들어진 모든 병에는 여전히 최초의 통이 약간 들어 있다는 것\"이라 이야기하고 있습니다."},{"kind":"figure","src":"/articles/starward-solera/01.webp","width":540,"height":540},{"kind":"quote","text":"증류소: 스타워드 증류소"},{"kind":"quote","text":"위스키 타입: 오스트레일리아 싱글 몰트"},{"kind":"quote","text":"캐스크 정보: 아페라 와인 배럴(Apera Wine Barrel)"},{"kind":"quote","text":"보리 정보: 100% 호주산 보리"},{"kind":"quote","text":"도수: 43%"},{"kind":"figure","src":"/articles/starward-solera/02.webp","width":501,"height":501},{"kind":"heading","text":"Nose"},{"kind":"paragraph","text":"-시나몬이나 정향 같은 향신료"},{"kind":"paragraph","text":"-달달한 건과일, 건포도"},{"kind":"paragraph","text":"-바닐라"},{"kind":"heading","text":"Palate"},{"kind":"paragraph","text":"-건과일"},{"kind":"paragraph","text":"-살짝 달달한 카카오닙"},{"kind":"paragraph","text":"-약간의 바닐라빈"},{"kind":"paragraph","text":"-혀 끝에 남는 카라멜"},{"kind":"heading","text":"Finish"},{"kind":"paragraph","text":"-건과일"},{"kind":"paragraph","text":"-향신료"},{"kind":"paragraph","text":"-흑설탕{?} 또는 카라멜"},{"kind":"paragraph","text":"스타워드 노바보다는 좀 더 복잡하고, 달큰한 느낌입니다. 어딘가 셰리 캐스크를 사용한 스카치와 비슷한 인상이 드는 것이 스카치 위스키를 좋아하는 분들에게는 이 쪽이 좀 더 익숙한 맛이지 않을까 싶습니다."},{"kind":"paragraph","text":"마실 당시에는 느끼지 못했는데, 테이스팅 노트를 보니 어느 정도 크리스마스 시즌의 슈톨렌을 연상시키기도 할 것 같습니다."}]'::jsonb, 'published', '2024-08-11T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'starward-nova', 'spirits', '스타워드 노바', '"스타워드"는 호주에서 생산되는 위스키로, "스타워드 증류소"는 2007년 호주의 국영 항공사인 콴타스(Qantas)의 격납고에서 처음 설립되었습니다.', '/articles/starward-nova/00.webp',
  'https://blog.naver.com/shakinglikebartender/223543055543', false,
  '[{"kind":"figure","src":"/articles/starward-nova/00.webp","width":522,"height":522},{"kind":"heading","text":"About The Whisky"},{"kind":"paragraph","text":"\"스타워드\"는 호주에서 생산되는 위스키로, \"스타워드 증류소\"는 2007년 호주의 국영 항공사인 콴타스(Qantas)의 격납고에서 처음 설립되었습니다."},{"kind":"paragraph","text":"2015년에는 디아지오의 주류 스타트업 자금 조달 프로젝트인 ''디스틸 벤처스(Distill Ventures)''의 지원을 받으면서 증류소를 확장할 수 있었고, 2016년에는 현재 위치인 멜버른(Melbourne)으로 이주하게 되었습니다."},{"kind":"paragraph","text":"스타워드 위스키는 변덕스러운 멜버른의 날씨로 인해서 증발량이 많고, 비교적 짧은 시간의 숙성에도 풍부한 풍미를 가지게 되었습니다. 호주에서 생산되는 와인을 담았던 캐스크를 사용하면서 많은 주목을 받았으며, 이후에는 진저비어 캐스크, 라가불린 캐스크 등 재미있는 시도를 하기도 하였습니다."},{"kind":"paragraph","text":"2022년에는 샌프란시스코 월드 스피릿 대회(San Francisco World Spirits Competition)에서 참가한 수 많은 증류소 중 가장 많은 상을 수상한 증류소가 되기도 하였습니다."},{"kind":"paragraph","text":"\"스타워드 노바\"는 호주산 레드 와인 통에서 숙성된 것으로, 숙성 년수는 표기되지 않았습니다. \"스타워드 솔레라\"와 함께 국내에 수입되는 스타워드의 싱글 몰트 프로파일 중 코어 라인이라 할 수 있겠습니다."},{"kind":"figure","src":"/articles/starward-nova/01.webp","width":540,"height":540},{"kind":"quote","text":"증류소: 스타워드 증류소"},{"kind":"quote","text":"위스키 타입: 오스트레일리아 싱글몰트"},{"kind":"quote","text":"캐스크 정보: 호주산 레드 와인 통 (Australian Red Wine Barrel)"},{"kind":"quote","text":"도수: 41%"},{"kind":"figure","src":"/articles/starward-nova/02.webp","width":540,"height":540},{"kind":"heading","text":"Nose"},{"kind":"paragraph","text":"- 달달한 붉은 베리, 약간의 검붉은 포도 껍질"},{"kind":"paragraph","text":"- 약간의 진저 캐릭터"},{"kind":"paragraph","text":"- 약간의 우디함"},{"kind":"paragraph","text":"- 요구르트(?)"},{"kind":"heading","text":"Palate"},{"kind":"paragraph","text":"- 바닐라, 흑설탕 내지는 캬라멜"},{"kind":"paragraph","text":"- 라즈베리처럼 느껴질 수도 있는 약간의 탄닌감"},{"kind":"paragraph","text":"- 살짝 크리미한 질감"},{"kind":"heading","text":"Finish"},{"kind":"paragraph","text":"- 처음 맡던 향과 거의 동일함"},{"kind":"paragraph","text":"- 와인스러운 캐릭터"},{"kind":"paragraph","text":"- 꽤 짧은 편임"},{"kind":"paragraph","text":"스타워드 위스키는 국내에서는 아직까지 많이 알려지지 않은 위스키이지만, 개인적으로 뉴 월드 위스키에 대한 편견을 깨준 위스키로, 아주 좋아하는 브랜드입니다."},{"kind":"paragraph","text":"스타워드 노바는 향에서는 생각보다 숙성감이 느껴지며, 전체적으로 저숙성임에도 레드 와인 캐스크의 특징이 나름대로 잘 갈무리된 위스키라 생각됩니다."}]'::jsonb, 'published', '2024-08-10T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'grinchhopper', 'cocktail', '그린치호퍼 — 어른스러운 입맛의 민초단을 위한 칵테일', '"그린치호퍼"는 크리미한 민트초코맛이 나는 "그래스호퍼(Grasshopper)"라는 칵테일의 변형으로, 어른스러운 입맛의 민초단을 위한 칵테일이라 할 수 있습니다.', '/articles/grinchhopper/00.webp',
  'https://blog.naver.com/shakinglikebartender/223542145727', false,
  '[{"kind":"figure","src":"/articles/grinchhopper/00.webp","width":500,"height":500},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"\"그린치호퍼\"는 크리미한 민트초코맛이 나는 \"그래스호퍼(Grasshopper)\"라는 칵테일의 변형으로, 어른스러운 입맛의 민초단을 위한 칵테일이라 할 수 있습니다."},{"kind":"paragraph","text":"이 칵테일은 라스 베이거스의 더 코스모폴리탄 호텔(The Cosmopolitan of Las Vegas)의 \"스키 롯지(Ski Lodge)\"라는 바에서 \"니코 노빅(Niko Novick)\"에 의해 만들어졌으며, 2022년 크리스마스 시즌을 위해 만들어진 칵테일로 보입니다."},{"kind":"paragraph","text":"''Las Vegas Magazine''에 2022년 12월 16일 처음으로 미야사토 키코에 의해 기록됐으며(추정), 이후 2022년 12월 19일 ''임바이브 매거진(Imbibe Magazine)''에 자세한 레시피가 공개됐습니다."},{"kind":"paragraph","text":"기존의 그래스호퍼 칵테일에 ''페르넷 브랑카''라는 복잡하고도 쓴 약초맛이 특징인 아마로를 추가해 좀 더 복잡한 맛을 내는 그래스호퍼라 할 수 있습니다."},{"kind":"figure","src":"/articles/grinchhopper/01.webp","width":500,"height":500},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"22.5ml 크렘 드 카카오 화이트"},{"kind":"paragraph","text":"(Creme de Cacao White)"},{"kind":"paragraph","text":"15ml 크렘 드 망트 그린"},{"kind":"paragraph","text":"(Creme de Menthe Green)"},{"kind":"paragraph","text":"15ml 페르넷 브랑카"},{"kind":"paragraph","text":"(Fernet Branca)"},{"kind":"paragraph","text":"30ml 생크림"},{"kind":"paragraph","text":"민트 잎 3개"},{"kind":"paragraph","text":"가니시: 민트 잎 1개"},{"kind":"figure","src":"/articles/grinchhopper/02.webp","width":403,"height":403},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 모든 재료를 셰이커에 넣어줍니다."},{"kind":"paragraph","text":"2. 셰이커에 얼음을 채워줍니다."},{"kind":"paragraph","text":"3. 셰이킹 후 차갑게 해 둔 칵테일 잔에 부어줍니다."},{"kind":"paragraph","text":"4. 가니시로 장식해줍니다."},{"kind":"figure","src":"/articles/grinchhopper/03.webp","width":500,"height":500},{"kind":"paragraph","text":"페르넷 브랑카는 꽤나 쓴 약초의 캐릭터가 아주 복잡하게 나는 매력적인 술로, 개인적으로 쌉쌀한 다크 초콜릿이나 민트의 화한 캐릭터도 가지고 있다고 느껴집니다."},{"kind":"paragraph","text":"그린치호퍼는 이런 페르넷 브랑카를 단순한 그래스호퍼에 넣어서 일반적인 그래스호퍼보다 당도는 살짝 낮추고, 복합성을 더해주는 아주 재밌는 변형이라 할 수 있죠."},{"kind":"paragraph","text":"화한 민트의 느낌이라기 보다는 약간은 묵직하고 쌉쌀한 느낌의 허브 캐릭터가 나는 민트초코의 맛이랄까요. 어른스러운 입맛의 민초단을 위한 한 잔입니다."},{"kind":"paragraph","text":"추가적으로, 페르넷 브랑카에서 민트 캐릭터가 부각된 ''브랑카 멘타''를 사용하는 것도 아주 잘 어울릴 것 같습니다."}]'::jsonb, 'published', '2024-08-09T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'mojito', 'cocktail', '모히또 — 이걸 마시지 않으면 여름이 아니지!', '"모히또"는 16세기에 탄생한 "드라케(Draque)"라는 칵테일에서 파생된 칵테일이라 합니다.', '/articles/mojito/00.webp',
  'https://blog.naver.com/shakinglikebartender/223540829379', false,
  '[{"kind":"figure","src":"/articles/mojito/00.webp","width":520,"height":520},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"\"모히또\"는 16세기에 탄생한 \"드라케(Draque)\"라는 칵테일에서 파생된 칵테일이라 합니다. 이 드라케라는 칵테일은 럼의 전신격인 아과르디엔테(Aguardiente)와 설탕, 라임, 민트로 만들어진 것으로, 나중에 아과르디엔테를 럼으로 바꾼 것이 \"모히또\"가 되었다고 합니다."},{"kind":"paragraph","text":"모히또 하면 \"모히또에서 몰디브 한 잔\"과 \"나의 모히또는 라 보데기타에, 나의 다이키리는 엘 플로리디타에\"라는 두 문장으로 아주 유명한 칵테일입니다."},{"kind":"paragraph","text":"\"모히또에서 몰디브 한 잔\"은 영화 내부자들에서 이병헌 배우의 애드리브로, 국내에 모히또라는 칵테일을 일반인에게도 각인시키는 대사가 되었죠."},{"kind":"paragraph","text":"\"나의 모히또는 라 보데기타에, 나의 다이키리는 엘 플로리디타에\"라는 대사는 소설가 어니스트 헤밍웨이가 \"라 보데기타 델 메디오(La Bodeguita del Medio)\"라는 쿠바의 바에 써놓은 메모로, 모히또와 관련된 가장 유명한 명문입니다."},{"kind":"paragraph","text":"다만, 이 역사적인 명문은 마케팅용으로 조작된 것으로, 헤밍웨이가 쓴 것이 아니라고 보는 견해도 있습니다."},{"kind":"paragraph","text":"애주가로서 본인의 저서에 여러번 다른 바와 칵테일을 적었던 헤밍웨이가 본인의 책에서 모히또나 라 보데기타를 기록한 적이 없으며, 무엇보다 당뇨에 시달려 시럽 대신에 마라스키노 리큐르를 넣는 \"헤밍웨이 다이키리\"라는 칵테일을 주문한 장본인이기 때문이죠."},{"kind":"figure","src":"/articles/mojito/01.webp","width":540,"height":540},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"45ml 화이트 럼 (White Rum)"},{"kind":"paragraph","text":"민트 잎 12~15개 (되도록이면 스피아민트)"},{"kind":"paragraph","text":"라임 반 개 (깍둑 썰기로 4등분 커트)"},{"kind":"paragraph","text":"설탕 시럽 또는 사탕수수 시럽 10ml"},{"kind":"paragraph","text":"15-30ml 탄산수"},{"kind":"paragraph","text":"*잔얼음 / 크러시드 아이스"},{"kind":"paragraph","text":"옵션 가니시: 민트 부케"},{"kind":"paragraph","text":"(줄기 있는 민트를 여러 개 합한 것)"},{"kind":"figure","src":"/articles/mojito/02.webp","width":502,"height":502},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 긴 잔에 민트, 라임, 시럽, 럼을 넣어줍니다."},{"kind":"paragraph","text":"2. 머들러로 머들링해줍니다(누르면서 살짝 비틀기)."},{"kind":"paragraph","text":"3. 잔얼음을 액면보다 좀 더 위에 오게 채워줍니다."},{"kind":"paragraph","text":"4. 바스푼을 가장 아래로 찔러 넣고,"},{"kind":"paragraph","text":"위아래로 강하게 저어줍니다."},{"kind":"paragraph","text":"5. 얼음을 더 채우고, 탄산수를 부어주고,"},{"kind":"paragraph","text":"다시 바스푼으로 위아래로 저어줍니다."},{"kind":"paragraph","text":"6. 얼음을 잔 끝까지 채워주고,"},{"kind":"paragraph","text":"빨대와 가니시로 장식해줍니다."},{"kind":"figure","src":"/articles/mojito/03.webp","width":511,"height":511},{"kind":"paragraph","text":"모히또는 역시 시각적으로부터 아주 시원합니다. 맛은 다 알만한 그 상큼하고 달달하고 시원한 그 맛입니다. 역시 여름에는 모히또 만한 칵테일이 없네요."},{"kind":"paragraph","text":"모히또를 집에서 만들어 마실 때 가장 큰 애로사항은 신선한 민트와 잔얼음이 아닐까 싶습니다. 민트를 오프라인에서 사자니 마땅히 살 곳도 없고, 얼음을 깨서 잔얼음을 만들자니 귀찮죠."},{"kind":"paragraph","text":"민트는 웬만하면 시장, 쿠팡이나 당일배송되는 곳에서 구매하시는 게 좋습니다. 대형마트에서 몇 번 사봤는데 잎이 작은데다 맛과 향이 약한 편이고, 딱히 신선하지도 않아 절반을 버린 적도 허다합니다."},{"kind":"paragraph","text":"만약 민트의 상태가 별로여서 맛과 향이 약하다 싶으면 민트를 더 많이 넣어주셔도 됩니다."},{"kind":"paragraph","text":"잔얼음은 쿠팡에서 같이 시키거나, 편의점 컵 얼음을 추천드립니다. 얼음의 퀄리티 자체가 중요한 칵테일은 아닌데다가 일단 편리하니까요...."}]'::jsonb, 'published', '2024-08-08T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'mojito' AND c.slug = 'mojito';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'grasshopper', 'cocktail', '그래스호퍼 — 주의)민초단 이외에는 보지마세요', '"그래스호퍼"는 민트 리큐르와 카카오 리큐르가 들어가 민트초코맛이 나는 칵테일로, 민초단을 위한 칵테일이라 할 수 있습니다.', '/articles/grasshopper/00.webp',
  'https://blog.naver.com/shakinglikebartender/223539574029', false,
  '[{"kind":"figure","src":"/articles/grasshopper/00.webp","width":500,"height":500},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"\"그래스호퍼\"는 민트 리큐르와 카카오 리큐르가 들어가 민트초코맛이 나는 칵테일로, 민초단을 위한 칵테일이라 할 수 있습니다."},{"kind":"paragraph","text":"그래스호퍼는 필립 기셰(Philip Guichet)가 1918년 뉴욕에서 열린 칵테일 대회에서 만들어낸 칵테일로, 당시 대회에서 2위를 차지하였으며, 이후 뉴올리언스에 있는 자신의 가게인 Tujague''s Restaurant에 이 칵테일을 선보이면서 가게 간판 메뉴 같은 존재가 되었다고 합니다."},{"kind":"paragraph","text":"이 Tujague''s Restaurant라는 레스토랑은 1856년에 오픈해 아직도 영업을 하고 있으며(한 번 이사를 했지만), 2018년에는 그래스호퍼 탄생 100주년을 기념하여 반값에 판매하는 이벤트를 하였다고 합니다."},{"kind":"paragraph","text":"민초 논쟁이 있는 우리나라에서는 아주 호불호가 극명하게 갈릴 수 밖에 없는 칵테일이지만, 개인적으로는 크리미한 민트초코의 맛은 거부할 수가 없네요."},{"kind":"figure","src":"/articles/grasshopper/01.webp","width":540,"height":540},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"20ml 크렘 드 카카오 화이트 (Creme de Cacao White)"},{"kind":"paragraph","text":"20ml 크렘 드 망트 (Creme de Menthe)"},{"kind":"paragraph","text":"20ml 생크림 (Heavy Cream)"},{"kind":"paragraph","text":"가니시: 민트 잎 1개 or 갈아둔 초콜릿"},{"kind":"paragraph","text":"(옵션)"},{"kind":"paragraph","text":"*모든 재료를 같은 양으로 넣는다고 생각하자!"},{"kind":"figure","src":"/articles/grasshopper/02.webp","width":500,"height":500},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 모든 재료를 셰이커 안에 넣어줍니다."},{"kind":"paragraph","text":"2. 셰이커에 얼음을 채워줍니다."},{"kind":"paragraph","text":"3. 셰이킹 후 차갑게 해둔 칵테일 잔에 부어줍니다."},{"kind":"paragraph","text":"4. 가니시로 장식해줍니다."},{"kind":"figure","src":"/articles/grasshopper/03.webp","width":500,"height":500},{"kind":"paragraph","text":"\"그래스호퍼\"는 들어가는 재료들이 아주 직관적이게 느껴지는 단순한 칵테일로, 재료가 재료다보니 딱히 복잡한 맛을 느끼기는 어렵습니다."},{"kind":"paragraph","text":"당연히 민초단인 분들은 좋아하시겠지만, 민트초코를 싫어하시는 분들은 모르고 바에서 시켰다가 한 입만 마시고 후회하는 불상사가 일어나게 되겠죠."},{"kind":"paragraph","text":"개인적으로는 민트초코에 대해서 거부감이 없기 때문에 훌륭한 디저트 칵테일이라 생각합니다."},{"kind":"paragraph","text":"다만, Tujague''s Restaurant의 오리지널 레시피는 오늘날 잘 알려진 1:1:1의 비율과 재료와는 좀 다른 면이 있고, 브랜디가 들어가기도 하니, 나중에 그 레시피도 소개하도록 하겠습니다."}]'::jsonb, 'published', '2024-08-07T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'gin-rickey', 'cocktail', '진 리키 — 무더운 여름 갈증을 날려줄 상쾌한 한 잔', '"진 리키"는 아주 오래된 칵테일임에도 불구하고 그 기원이 상당히 명확한데, 19세기 후반 워싱턴 DC에서 민주당의 로비스트로 활동하던 "조 리키(Joe Rickey)"의 이름을 딴 것이며, 1880년 워싱턴 DC의 "슈메이커스 바(Shoomaker’', '/articles/gin-rickey/00.webp',
  'https://blog.naver.com/shakinglikebartender/223538391938', false,
  '[{"kind":"figure","src":"/articles/gin-rickey/00.webp","width":382,"height":382},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"\"진 리키\"는 아주 오래된 칵테일임에도 불구하고 그 기원이 상당히 명확한데, 19세기 후반 워싱턴 DC에서 민주당의 로비스트로 활동하던 \"조 리키(Joe Rickey)\"의 이름을 딴 것이며, 1880년 워싱턴 DC의 \"슈메이커스 바(Shoomaker’s bar)\"에서 \"조지 A. 윌리엄슨(George A. Williamson)\"이라는 바텐더에 의해 만들어졌다 합니다."},{"kind":"paragraph","text":"이 \"조 리키\"라는 인물은 버번 위스키&소다를 즐겨 마셨는데, 하루는 바텐더에게 라임을 조금 추가해 줄 것을 요청하였고, 그렇게 버번 리키(Bourbon Rickey)가 탄생하게 되었습니다."},{"kind":"paragraph","text":"이후에 버번은 진으로 대체되면서 진 리키가 유행하게 되었고, 1900년 즈음에는 리키 스타일의 칵테일은 진 리키가 기본적인 레시피로 자리잡았다고 합니다."},{"kind":"paragraph","text":"다만, 이러한 스토리는 각 문헌마다 차이가 있는데, 리키 스타일의 칵테일의 탄생이 버번 위스키인지 라이 위스키 베이스인지 확실하지 않다는 설, 라임이 아닌 레몬이 원조라는 설, 탄생 계기가 조금씩 다른 설 등 다양하게 있습니다."},{"kind":"paragraph","text":"리키 스타일의 칵테일이 위스키 하이볼에서 파생된 것이니, \"진 리키\"를 가장 심플하게 표현하자면 \"라임즙이 소량 들어간 진 하이볼\"이라 할 수 있겠네요."},{"kind":"figure","src":"/articles/gin-rickey/01.webp","width":500,"height":500},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"40ml 진 (Gin)"},{"kind":"paragraph","text":"8ml 라임즙 (Lime Juice)"},{"kind":"paragraph","text":"100 ~ 120ml 탄산수 (Soda Water)"},{"kind":"paragraph","text":"가니시: 라임 웨지"},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 차갑게 해둔 긴 잔에 얼음을 채워줍니다."},{"kind":"paragraph","text":"2. 라임즙과 진을 부어준 후, 살짝 스터해줍니다."},{"kind":"paragraph","text":"3. 탄산수를 얼음에 닿지 않게 부어줍니다."},{"kind":"paragraph","text":"4. 바스푼으로 얼음을 살짝 들어줍니다."},{"kind":"paragraph","text":"5. 라임 웨지로 가니시해줍니다."},{"kind":"figure","src":"/articles/gin-rickey/02.webp","width":500,"height":500},{"kind":"paragraph","text":"\"진 리키\"는 라임과 진의 허브감에 탄산이 더해져 아주 상큼하고, 깔끔하게 맛이 딱 떨어지는 칵테일로, 갈증나는 여름에 딱 어울리죠."},{"kind":"paragraph","text":"사실 진 하이볼에 라임즙을 살짝 더한 것인데, 이 때 진의 선택과 라임즙의 양이 맛에 꽤 큰 영향을 줍니다. 아무래도 들어가는 재료가 적으니까요."},{"kind":"paragraph","text":"진은 개인적으로 탱커레이, 고든스, 비피터와 같이 스탠다드한 것들이나 카다멈 같이 시원하고 상쾌한 향이 메인인 진(ex. 포필라스 네이비 스트렝스를 소량 블렌딩)을 사용하는 걸 추천드립니다. 아무래도 진 리키의 상큼하고 깔끔한 캐릭터를 잘 살릴 수 있는 기주가 좋습니다."},{"kind":"paragraph","text":"다만, 이 또한 제 개인적인 취향이니 개인의 취향에 잘 맞는 진을 사용해도 전혀 상관 없습니다."}]'::jsonb, 'published', '2024-08-06T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'matador', 'cocktail', '마타도르 — 무더운 여름, 간단하게 음식과 곁들여 마시기 좋은 칵테일', '"마타도르"는 투우에서 소에게 최후의 일격을 가하는 투우사라는 뜻을 가지는데, 사실 칵테일 자체는 생각보다 달큰한 감이 있어서 약간은 이름과 이미지가 미스매치인 듯한 칵테일입니다.', '/articles/matador/00.webp',
  'https://blog.naver.com/shakinglikebartender/223537145044', false,
  '[{"kind":"figure","src":"/articles/matador/00.webp","width":473,"height":473},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"\"마타도르\"는 투우에서 소에게 최후의 일격을 가하는 투우사라는 뜻을 가지는데, 사실 칵테일 자체는 생각보다 달큰한 감이 있어서 약간은 이름과 이미지가 미스매치인 듯한 칵테일입니다."},{"kind":"paragraph","text":"다소 오래된 칵테일로, 그 기원 자체는 명확하지는 않습니다. 다만, 1972년 빅터 버거론(Victor Jules Bergeron)의 저서인 \"Trader Vic''s Bartender''s Guide\"에서 \"데킬라 마타도르(Tequila Matador)\"라는 이름으로 소개된 것이 가장 오래된 기록이라 합니다."},{"kind":"paragraph","text":"물론 그 이전부터 칵테일 자체는 존재하기는 했다고 합니다. 가장 오래된 기록이 빅터 버거론의 저서에서 발견됐다 정도로 이해하면 될 것 같습니다(빅터 버거론의 비율은 2:4:1)."},{"kind":"paragraph","text":"제가 알기로 서양에서는 거의 사장되다 싶이 한 칵테일이고, 찾아보더라도 좀 다른 레시피가 많습니다. 우리나라 바에서는 간혹 볼 수 있는데, 이건 우리나라 바가 일본 바의 영향을 많이 받아서 그런 것으로 보입니다."},{"kind":"figure","src":"/articles/matador/01.webp","width":540,"height":540},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"30ml 블랑코 데킬라 (Blanco Tequila)"},{"kind":"paragraph","text":"45ml 파인애플 주스 (Pineapple Juice)"},{"kind":"paragraph","text":"15ml 라임즙 또는 레몬즙 (Lime/Lemon Juice)"},{"kind":"figure","src":"/articles/matador/02.webp","width":390,"height":390},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 모든 재료를 셰이커에 넣어줍니다."},{"kind":"paragraph","text":"2. 셰이커에 얼음을 채워줍니다."},{"kind":"paragraph","text":"3. 셰이킹 후, 얼음을 채운 락글라스에 부어줍니다."},{"kind":"figure","src":"/articles/matador/03.webp","width":449,"height":449},{"kind":"paragraph","text":"\"마타도르\"는 트로피컬한 단맛과 상큼한 신맛이 적절히 어우러지면서도 데킬라의 캐릭터가 뼈대를 잡아주는 칵테일입니다. 달큰한 맛 뒤에 오는 데킬라의 맛이 마타도르를 이미지화한 것이라고 생각할 수도 있겠네요."},{"kind":"paragraph","text":"아직 데킬라의 특유의 맛과 향에 익숙하지 않은 분들도 부담 없이 즐길만한 칵테일이며, 간이 세거나 매운 음식과 궁합이 꽤 좋을 것 같습니다. 트로피컬한 칵테일이니 만큼 여름에 마시기에 좋은 칵테일이죠."},{"kind":"paragraph","text":"원래 레시피에는 라임을 사용하나, 좀 더 상큼한 캐릭터를 내고 싶으시다면 레몬즙을 사용하는 것도 좋은 선택입니다."},{"kind":"paragraph","text":"원래 가니시는 없지만, 마타도르의 상징이 붉은 천인 만큼 붉은 색의 체리로 간단하게 가니시해주는 것도 칵테일의 매력을 높이는 방법이겠네요."}]'::jsonb, 'published', '2024-08-05T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'mars-the-lucky-cat-double-individuals-hana-and-choco', 'spirits', '마르스 럭키 캣 하나 & 초코', '"마르스 럭캐 캣" 시리즈는 일본의 "마르스(Mars) 위스키"의 리미티드 에디션으로, 블렌디드 위스키로 릴리즈되며, 사랑스러운 고양이 라벨이 특징인 냥스키입니다.', '/articles/mars-the-lucky-cat-double-individuals-hana-and-choco/00.webp',
  'https://blog.naver.com/shakinglikebartender/223531891910', false,
  '[{"kind":"figure","src":"/articles/mars-the-lucky-cat-double-individuals-hana-and-choco/00.webp","width":526,"height":526},{"kind":"heading","text":"About The Whisky"},{"kind":"paragraph","text":"\"마르스 럭캐 캣\" 시리즈는 일본의 \"마르스(Mars) 위스키\"의 리미티드 에디션으로, 블렌디드 위스키로 릴리즈되며, 사랑스러운 고양이 라벨이 특징인 냥스키입니다."},{"kind":"paragraph","text":"그 중에서 \"하나 & 초코\"는 시리즈의 9번째 위스키로, 라벨에 그러진 응석받이인 하나와 말괄량이인 초코라는 자매 고양이를 모티브로 해서 만들어졌다고 합니다."},{"kind":"paragraph","text":"올로로소 셰리 캐스크, 와인 캐스크, 스패니시 오크 캐스크를 사용해 스패니시 오크가 구조를 탄탄하게 받혀주며, 올로로소 셰리 및 와인 캐스크로 부드러운 단맛과 과실 캐릭터를 부여하려 했다고 합니다."},{"kind":"paragraph","text":"2024년 5월에 병입되어 7,920병이 출시되었으며, 한국에는 210병이 들어왔다고 합니다. 이전 럭키 캣 시리즈가 소량만 들어온 것에 비해서는 꽤 많은 바틀이 들어왔네요."},{"kind":"figure","src":"/articles/mars-the-lucky-cat-double-individuals-hana-and-choco/01.webp","width":540,"height":720},{"kind":"figure","src":"/articles/mars-the-lucky-cat-double-individuals-hana-and-choco/02.webp","width":507,"height":676},{"kind":"quote","text":"증류소: 마르스 코마가타케 증류소"},{"kind":"quote","text":"시리즈: 럭키 캣"},{"kind":"quote","text":"위스키 타입: 블렌디드 위스키"},{"kind":"quote","text":"캐스크 정보: Oloroso Sherry Cask, Wine Cask, Spanish Oak Cask"},{"kind":"quote","text":"생산량: 7,920병"},{"kind":"quote","text":"도수: 43%"},{"kind":"figure","src":"/articles/mars-the-lucky-cat-double-individuals-hana-and-choco/03.webp","width":540,"height":540},{"kind":"heading","text":"Nose"},{"kind":"paragraph","text":"- 말린 무화과, 바닐라(?), 복숭아나 살구같은 과실의 달달함"},{"kind":"paragraph","text":"- 약간의 스파이스(향신료)"},{"kind":"paragraph","text":"- 알콜감이 튀어 약간은 거칠지만 달달함이 있음"},{"kind":"paragraph","text":"- 시간이 지날수록 알콜감이 적어지고, 달달함이 더 올라옴"},{"kind":"paragraph","text":"- 약간은 크리미 또는 밀키함"},{"kind":"heading","text":"Palate"},{"kind":"paragraph","text":"- 단맛, 뭔지 모를 향신료(아마 시나몬?), 우디함"},{"kind":"paragraph","text":"- 다만, 맛이 너무 약해 캐릭터를 캐치하기 어려움"},{"kind":"paragraph","text":"- 약간은 저숙성 럼 같은 느낌도 듬"},{"kind":"heading","text":"Finish"},{"kind":"paragraph","text":"- 달달함과 우디함이 쓱 지나감"},{"kind":"paragraph","text":"- 구체적인 캐릭터보다는 어떤 느낌이 난다 정도"},{"kind":"paragraph","text":"향은 괜찮았던 것에 비해 맛과 피니시가 다소 아쉬웠으며, 어느정도 단순한 캐릭터였던 것 같으나 라벨이 정말 맛있습니다."},{"kind":"paragraph","text":"사실 라벨이 너무 마음에 들어서 구입한 것도 있는데, 냥스키 오우너가 되고 싶거나 시리즈를 모으지 않는 한 굳이 살 것 같지는 않습니다."},{"kind":"paragraph","text":"한국에서 출시하면 10만원대인 걸로 알고 있는데, 좀 비싸다고 생각하고, 저는 5월에 후쿠오카에서 우연히 발견해서 7~8천엔에 구입했던 것 같습니다."},{"kind":"paragraph","text":"라벨은 참 이쁜데...."}]'::jsonb, 'published', '2024-07-31T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'mary-pickford', 'cocktail', '메리 픽포드 — 아름다운 아메리칸 스윗하트를 위한 칵테일', '"메리 픽포드"는 1920년대 초 쿠바에서 만들어진 칵테일로, 당시 ''미국의 연인(America''s Sweetheart)''이라는 애칭을 처음으로 받은 여배우의 이름이 붙여진 것입니다.', '/articles/mary-pickford/00.webp',
  'https://blog.naver.com/shakinglikebartender/223529434771', false,
  '[{"kind":"figure","src":"/articles/mary-pickford/00.webp","width":515,"height":515},{"kind":"paragraph","text":"\"메리 픽포드\"는 1920년대 초 쿠바에서 만들어진 칵테일로, 당시 ''미국의 연인(America''s Sweetheart)''이라는 애칭을 처음으로 받은 여배우의 이름이 붙여진 것입니다."},{"kind":"paragraph","text":"오래된 칵테일이 종종 그렇듯 그 탄생이 명확하지 않은데, 가장 유력한 설은 1920년대 초 메리 픽포드가 영화 촬영을 위해 배우자인 더글러스 페어뱅크스와 그의 절친인 찰리 채플린과 함께 쿠바에 방문했을 때, 나시오날 호텔(Nacional Hotel)의 바텐더가 그녀를 위해 만들었고, 그녀의 이름을 붙였다고 합니다."},{"kind":"paragraph","text":"다만, 그 바텐더가 누구였는지에 대해 논란이 있는데, 에디 웰케(Eddie Woelke)와 프레드 카우프먼(Fred Kaufman)이 유력한 후보이며, 후자가 좀 더 신빙성이 있다고 보는 것이 대세라 합니다."},{"kind":"paragraph","text":"그러나 이후에 1920년대에 메리 픽포드가 영화 촬영을 위해 쿠바를 방문한 적이 없으며, 더욱이 결혼 생활 동안 쿠바에서 영화 촬영을 한 적이 없다는 것이 밝혀지면서 이 가설은 힘을 잃게 됩니다."},{"kind":"paragraph","text":"이후 1928년에 바질 운(Basil Woon)의 저서인 \"When It’s Cocktail Time in Cuba\"에서 처음 기록되었으며, 1930년에는 해리 크래독(Harry Craddock)의 저서인 \"The Savoy Cocktail Book\"에 등장하였습니다."},{"kind":"figure","src":"/articles/mary-pickford/01.webp","width":540,"height":540},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"40ml 화이트 럼 (White Rum)"},{"kind":"paragraph","text":"40ml 파인애플 주스 (Pineapple Juice)"},{"kind":"paragraph","text":"10ml 그레나딘 시럽 (Grenadine Syrup)"},{"kind":"paragraph","text":"3ml 마라스키노 리큐르 (Maraschino Liqueur)"},{"kind":"figure","src":"/articles/mary-pickford/02.webp","width":430,"height":430},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 모든 재료를 쉐이커 안에 넣어줍니다."},{"kind":"paragraph","text":"2. 셰이커에 얼음을 채워줍니다."},{"kind":"paragraph","text":"3. 셰이킹 후, 차게 해 둔 칵테일 잔에 부어줍니다."},{"kind":"figure","src":"/articles/mary-pickford/03.webp","width":516,"height":516},{"kind":"paragraph","text":"\"메리 픽포드\"는 트로피컬한 과실의 단맛이 장점인 칵테일로, 상큼하고 달달한 느낌이 나며, 거기에 마라스키노 리큐르의 체리 캐릭터가 살짝 더해져 칵테일의 맛을 좀 더 풍부하게 해줍니다."},{"kind":"paragraph","text":"숏 칵테일임에도 불구하고 파인애플 주스가 기주와 동량으로 꽤 많이 들어가게 되는 것이 특징인데, 이 파인애플 주스의 양을 조절하는 게 이 칵테일의 핵심이 아닐까 싶습니다. 너무 적게 넣으면 럼의 알콜감이 튀고, 너무 많이 넣으면 럼의 풍미가 죽어버리게 됩니다."},{"kind":"paragraph","text":"금주법 시대에 만들어진 아주 오래된 칵테일이니 만큼 레시피가 딱 정해져 있는 것이 아닌, 정말 많은 레시피가 존재합니다. 다른 레시피들을 참고하면서 본인의 입맛에 맞춰가는 재미가 있는 칵테일이죠."},{"kind":"paragraph","text":"저 같은 경우는 그레나딘을 늘리고, 마라스키노를 줄였습니다. 그레나딘은 파인애플 주스의 캐릭터가 과하지 않게 좀 눌러주기 위해서, 마라스키노는 캐릭터가 강한 걸 개인적으로 좋아하지 않아서 은은하게 날 수 있게 조정을 햇습니다."}]'::jsonb, 'published', '2024-07-29T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'ardbeg-bizarrebq', 'spirits', '아드벡 비자르비큐 — 위스키와 바베큐의 만남', '"아드벡 비자르비큐"는 아일라 섬의 피트 위스키로 유명한 ''아드벡 증류소''에서 2023년 ''아드벡 커미티(Ardbeg Committee)'' 한정으로 출시한 바틀로, 특이하게도 "바베큐"에서 영감을 받은 위스키입니다.', '/articles/ardbeg-bizarrebq/00.webp',
  'https://blog.naver.com/shakinglikebartender/223527447243', false,
  '[{"kind":"figure","src":"/articles/ardbeg-bizarrebq/00.webp","width":524,"height":524},{"kind":"heading","text":"About The Whisky"},{"kind":"paragraph","text":"\"아드벡 비자르비큐\"는 아일라 섬의 피트 위스키로 유명한 ''아드벡 증류소''에서 2023년 ''아드벡 커미티(Ardbeg Committee)'' 한정으로 출시한 바틀로, 특이하게도 \"바베큐\"에서 영감을 받은 위스키입니다."},{"kind":"paragraph","text":"''아드벡 증류소''에서는 이따금씩 일종의 아드벡 커뮤니티/팬클럽인 ''아드벡 커미티'' 한정의 특이한 바틀을 출시하는데, 그 중 하나입니다."},{"kind":"paragraph","text":"마스터 디스틸러인 빌 럼스덴 박사(Dr. Bill Lumsden)과 그릴 전문가 크리스찬 스티븐슨(일명 DJ BBQ)이 협업하여 만든 바틀로, 강렬한 고기맛 · 피트감이 어우러지는 독특한 캐릭터를 가지게 됩니다."},{"kind":"paragraph","text":"캐스크는 이중으로 태운 오크 캐스크(Double Charred Oak Cask), 페드로 히메네스 캐스크(Pedro Ximenez Sherry Cask)와 \"BBQ 캐스크(BBQ Cask)\"를 사용했다고 하는데, 이 \"BBQ 캐스크\"가 뭔지는 수수께끼네요."},{"kind":"quote","text":"증류소: 아드벡 증류소"},{"kind":"quote","text":"위스키 타입: 싱글 몰트"},{"kind":"quote","text":"캐스크 정보: Double Charred Oak Cask, PX Sherry Cask, BBQ Cask"},{"kind":"quote","text":"도수: 50.9%"},{"kind":"figure","src":"/articles/ardbeg-bizarrebq/01.webp","width":540,"height":540},{"kind":"heading","text":"Nose"},{"kind":"paragraph","text":"- 달달하고 다소 무거운 피트감"},{"kind":"paragraph","text":"- 훈제향, 구수한 곡식, 훈제향에 숨은 건포도"},{"kind":"paragraph","text":"- 커피 찌꺼기"},{"kind":"heading","text":"Palate"},{"kind":"paragraph","text":"- 달달한 스모키함, 구수한 곡식"},{"kind":"paragraph","text":"- 스파이스, 약간의 생강, 가죽"},{"kind":"paragraph","text":"- 혀에 남는 탄 설탕의 느낌"},{"kind":"heading","text":"Finish"},{"kind":"paragraph","text":"- 그렇게 강하지 않은 적당히 기분 좋은 피트감"},{"kind":"paragraph","text":"- 훈제향, 약간의 스파이스"},{"kind":"paragraph","text":"- 피트가 지나가면 달달함이 올라옴"},{"kind":"paragraph","text":"''아드벡 비자르비큐''는 국내에서는 두 번째로 정식 출시된 아드벡 커미티 바틀로, 159,000원이라는 아주아주 합리적인 가격으로 출시되어 저도 무지성으로 일단 한 병 구입을 했었습니다."},{"kind":"paragraph","text":"오픈한지 얼마 안됐을 때는 훈제 베이컨, 고기 같은 캐릭터가 강했던 걸로 기억하는데, 얼마 남지 않은 상태로 오래 브리딩이 되고 나니 베이컨보다는 훈제+건과일 같은 달달함이 부각되는 것 같습니다."},{"kind":"paragraph","text":"제가 올린 테이스팅 노트는 반 이상 마신 후에 거의 1년 정도가 지난 상태니 이 점도 참고해주시면 좋을 것 같습니다."},{"kind":"paragraph","text":"''아드벡 비자르비큐''는 합리적인 가격에 비해 아주 잘 만들어진 바틀이라 생각되며, 마실 기회가 있다면 반드시 한 번 정도는 맛보시는 걸 추천드립니다."}]'::jsonb, 'published', '2024-07-27T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'bruichladdich-bere-barley', 'spirits', '브룩라디 비어발리 2012', '"브룩라디 비어 발리"는 원액이 증류된 연도를 달고 해마다 나오는 ''브룩라디 증류소''의 위스키 라인 중 하나로, 10년 숙성 · 논피트 · 50%의 도수로 출시됩니다.', '/articles/bruichladdich-bere-barley/00.webp',
  'https://blog.naver.com/shakinglikebartender/223526188695', false,
  '[{"kind":"figure","src":"/articles/bruichladdich-bere-barley/00.webp","width":540,"height":540},{"kind":"heading","text":"About The Whisky"},{"kind":"paragraph","text":"\"브룩라디 비어 발리\"는 원액이 증류된 연도를 달고 해마다 나오는 ''브룩라디 증류소''의 위스키 라인 중 하나로, 10년 숙성 · 논피트 · 50%의 도수로 출시됩니다."},{"kind":"paragraph","text":"독특하게 현재 위스키 산업에서는 거의 사용되지 않는 \"비어 발리(Bere Barley)\"라는 보리 품종을 사용하는데, 20세기에 효율성 및 수익성으로 인해 다른 품종의 보리를 사용하게 되면서 외면받게 되었다고 합니다."},{"kind":"paragraph","text":"브룩라디 증류소는 2005년부터 하이랜드 앤 아일랜드 대학(UHI)의 농경학 연구소와 협력하여 비어 발리가 다시금 위스키 생산에 쓰일 수 있도록 노력했으며, 이 비어 발리 라인업이 그 결과라 할 수 있습니다."},{"kind":"quote","text":"증류소 정보: 브룩라디 증류소"},{"kind":"quote","text":"위스키 타입: 싱글 몰트"},{"kind":"quote","text":"캐스크 정보: 퍼스트필 버번 캐스크(1st Fill Bourbon) 10년"},{"kind":"quote","text":"보리 정보: 오크니 대학(UHI)의 농경학 연구소에서 재배한 비어 발리 / 2011년 수확"},{"kind":"quote","text":"도수: 50%"},{"kind":"figure","src":"/articles/bruichladdich-bere-barley/01.webp","width":540,"height":540},{"kind":"heading","text":"Nose"},{"kind":"paragraph","text":"- 달달한 과실, 참외 속 부분, 오크, 꿀, 샤프한 시트러스?"},{"kind":"paragraph","text":"- 약간의 화사한 플로럴함"},{"kind":"heading","text":"Palate"},{"kind":"paragraph","text":"- 아주 달달한 과실감, 약간의 복숭아와 망고"},{"kind":"paragraph","text":"- 약간의 짭짤함, 끝에 살짝 남는 쌉쌀함"},{"kind":"heading","text":"Finish"},{"kind":"paragraph","text":"- 달달한 생강, 오크, 짭짤함, 약간의 후추"},{"kind":"paragraph","text":"- 10년 숙성치고는 약간은 아쉬운 피니시"},{"kind":"paragraph","text":"브룩라디 비어 발리 2012는 과실의 달달함의 캐릭터가 빛이 나는 한 잔으로, 처음 오픈했을 때는 오크의 캐릭터가 강해 셰리 캐스크를 썼나? 싶었던 기억이 있습니다. 다만, 비교군이 적어 비어 발리라는 보리 품종의 특징까지는 잘 모르겠네요."},{"kind":"paragraph","text":"브룩라디 비어 발리 시리즈는 국내에서는 찾아보기 어렵지만, 일본에서는 쉽게 찾아볼 수 있으며, 가격이 현지보다 오히려 쌉니다. 저는 올해 7월 후쿠오카에서 10만 원 안되는 가격으로 구입을 했습니다."},{"kind":"paragraph","text":"가격 대비 만족도가 괜찮았으며, 브룩라디 증류소의 팬이거나, 가성비 좋은 바틀을 일본에서 구입하시는 분들에게는 추천드릴만 하네요."}]'::jsonb, 'published', '2024-07-26T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'kings-valley', 'cocktail', '킹스 밸리 — 스카치 위스키의 색깔놀이', '"킹스 밸리(King''s Valley)"는 도쿄의 긴자에 위치한 바 ''텐더(Tender)''의 일본 칵테일 씬의 전설인 "우에다', '/articles/kings-valley/00.webp',
  'https://blog.naver.com/shakinglikebartender/223524202319', false,
  '[{"kind":"figure","src":"/articles/kings-valley/00.webp","width":501,"height":501},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"\"킹스 밸리(King''s Valley)\"는 도쿄의 긴자에 위치한 바 ''텐더(Tender)''의 일본 칵테일 씬의 전설인 \"우에다 카즈오\"에 의해 만들어진 칵테일로, 1986년에 개최된 제1회 스카치 위스키 칵테일 콩쿨 우승작입니다."},{"kind":"paragraph","text":"우리나라에서는 잘 알려져 있지 않지만, 일본에서는 인지도 있는 칵테일이며, ''유키구니(Yukiguni)''와 함께 일본에서 탄생한 칵테일 중 가장 사랑 받는 칵테일 중 하나입니다."},{"kind":"paragraph","text":"스카치 위스키의 산지인 스코틀랜드의 산의 깊은 계곡을 이미지한 칵테일이며, 재료 중 녹색을 띄는 것이 없음에도 불구하고, 재료의 조합으로 녹색을 띄는 것이 특징입니다."},{"kind":"figure","src":"/articles/kings-valley/01.webp","width":526,"height":526},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"40ml 스카치 위스키(Scotch Whisky)"},{"kind":"paragraph","text":"10ml 화이트 큐라소(White Curacao)"},{"kind":"paragraph","text":"10ml 라임즙(Lime Juice)"},{"kind":"paragraph","text":"5ml 블루 큐라소(Blue Curacao)"},{"kind":"figure","src":"/articles/kings-valley/02.webp","width":420,"height":420},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 모든 재료를 셰이커에 넣어줍니다."},{"kind":"paragraph","text":"2. 셰이커에 얼음을 채우고, 셰이킹해줍니다."},{"kind":"paragraph","text":"3. 차게 해둔 칵테일 잔에 부어줍니다."},{"kind":"figure","src":"/articles/kings-valley/03.webp","width":529,"height":529},{"kind":"paragraph","text":"\"킹스 밸리\"는 꽤 간단한 재료에 비해서 아주 화려한 색을 낼 수 있는 칵테일입니다. 제가 만든 건 청록색에 가까운 색이며, 기주인 스카치 위스키의 종류나 비율, 잔의 종류 등에 따라서 색이 다르게 나올 수 있습니다. 그에 따라서 맛도 달라지겠죠."},{"kind":"paragraph","text":"\"우에다 카즈오\"님의 저서인 ''칵테일 테크닉''에서는 ''그란츠''나 ''화이트 앤 맥케이''를 사용했던 걸로 보아, 어느 하나 특징이 튀지 않고 부드러운 블렌디드 위스키를 사용하는 걸 선호했던 것으로 보입니다. 또한, 위스키를 좋아하는 손님을 위해서는 ''올드파''를 사용했다고 하네요."},{"kind":"paragraph","text":"다만, 이 저서는 꽤 오래된 저서라서 최근에는 사용하는 기주가 바뀌었을 수도 있겠네요. 개인적으로는 ''페이머스 그라우스''가 기주에 적합하다고 느꼈습니다."},{"kind":"paragraph","text":"맛 자체는 요즘 만들어지는 칵테일에 비해서는 무난하다고 할 수 있지만 안정감이 있는 맛으로, 밸런스가 아주 좋습니다. 레시피 자체는 ''사일런트 서드(Silent Third)의 변형처럼도 보이네요."}]'::jsonb, 'published', '2024-07-24T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'bar-kurayoshi-daimyo', 'bar', '쿠라요시 다이묘점 — 칵테일로 마시는 가을의 아름다움', '"쿠라요시(Bar Kurayoshi)"는 다이묘와 나카스에 2개의 점포가 운영되고 있는 바로, 이번 글은 다이묘에 위치한 지점에 대한 글입니다.', '/articles/bar-kurayoshi-daimyo/00.webp',
  'https://blog.naver.com/shakinglikebartender/223522532652', false,
  '[{"kind":"figure","src":"/articles/bar-kurayoshi-daimyo/00.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/bar-kurayoshi-daimyo/01.webp","width":966,"height":1288,"caption":"아키우라라 (秋麗/Akiurara)"},{"kind":"paragraph","text":"\"쿠라요시(Bar Kurayoshi)\"는 다이묘와 나카스에 2개의 점포가 운영되고 있는 바로, 이번 글은 다이묘에 위치한 지점에 대한 글입니다. \"쿠라요시 다이묘점\"은 위스키 라인업도 꽤 괜찮지만, 칵테일을 아주 잘한다는 인상을 받은 곳입니다."},{"kind":"paragraph","text":"특히나 올해 2월에 일본에서 열린 ''제6회 본격 쇼츄&아와모리 칵테일 대회''에서 우승한 ''나가하마 유타로''씨의 ''아키우라라''는 이모쇼츄(고구마쇼츄)를 기주로하여 일본의 가을의 풍경과 열매를 이미지화한 것으로, 마셔볼만한 가치가 있는 한 잔이었습니다."},{"kind":"figure","src":"/articles/bar-kurayoshi-daimyo/02.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/bar-kurayoshi-daimyo/03.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/bar-kurayoshi-daimyo/04.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/bar-kurayoshi-daimyo/05.webp","width":966,"height":1288,"caption":"독립병입자 쿨일라 하이볼 / 에두라두어 10년 미즈와리 / 진 토닉 / 블랙 벨벳"},{"kind":"paragraph","text":"그외에 하이볼의 추천을 부탁드렸는데, 이 독립병입자 쿨일라로 만든 하이볼이 정말 맛있었던 기억이 있습니다. 다만, 바틀을 들여다보지 않아서 어떤 독립병입자였는지는 기억이 나질 않네요. 진 토닉의 경우는 다른 곳들과는 다르게 구리 잔으로 서브를 했는데, 좀 더 차갑게 마실 수 있도록 하기 위해서라 합니다."},{"kind":"paragraph","text":"일본의 바에서는 샴페인으로 칵테일을 만들어주는 곳이 꽤 많은데, \"쿠라요시\" 또한 샴페인 칵테일을 판매합니다. 국내에서는 샴페인 칵테일을 바에서 좀처럼 시킬 수 없으니, 샴페인을 사용한 칵테일을 주문하는 것도 하나의 재미입니다."},{"kind":"paragraph","text":"저 같은 경우에는 흑맥주(기네스)와 샴페인을 반반씩 섞어서 만드는 블랙 벨벳(Black Velvet)을 부탁드렸는데, 만화처럼 동시에 두 가지 술을 따르지는 못한다고 장난스럽게 얘기하시는 걸 보면 이전에 바텐더 만화를 보시고 주문한 분이 있는가 봅니다."}]'::jsonb, 'published', '2024-07-23T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'octomore-14-1', 'spirits', '옥토모어 14.1', '옥토모어는 브룩라디(Bruichladdich)와 포트샬롯(Port Charlotte)과 함께 "브룩라디 증류소"의 코어 라인 중 하나로, 일반적으로 매년 xx.1 / xx.2 / xx.3 (+xx.4/없는 해도 있음)의 번호를 달고 출시되는 매번이 일', '/articles/octomore-14-1/00.webp',
  'https://blog.naver.com/shakinglikebartender/223521509457', false,
  '[{"kind":"figure","src":"/articles/octomore-14-1/00.webp","width":966,"height":966},{"kind":"figure","src":"/articles/octomore-14-1/01.webp","width":966,"height":966},{"kind":"heading","text":"About The Whisky"},{"kind":"paragraph","text":"옥토모어는 브룩라디(Bruichladdich)와 포트샬롯(Port Charlotte)과 함께 \"브룩라디 증류소\"의 코어 라인 중 하나로, 일반적으로 매년 xx.1 / xx.2 / xx.3 (+xx.4/없는 해도 있음)의 번호를 달고 출시되는 매번이 일종의 한정판인 특이한 위스키입니다."},{"kind":"paragraph","text":"옥토모어는 수퍼 헤빌리 피티드(Super Heavily Peated)가 가장 큰 특징인 위스키로, 페놀 수치가 보통 100ppm을 넘기는 게 일반적이며, 페놀 수치가 높은 편에 속하는 아드벡이 일반적으로 50~60ppm인 것에 비해서도 엄청나게 높은 걸 알 수 있죠."},{"kind":"paragraph","text":"옥토모어 14.1은 2023년 출시한 에디션으로, xx.1은 스코틀랜드산 보리를 100% 사용하고, 엑스-아메리칸 오크(ex-American oak/버번 또는 테네시 위스키 캐스크)를 사용해서 숙성한다는 특징을 가지고 있습니다. 증류소에서는 이 xx.1을 각 시리즈의 중추라고 소개하고 있습니다."},{"kind":"figure","src":"/articles/octomore-14-1/02.webp","width":966,"height":543},{"kind":"figure","src":"/articles/octomore-14-1/03.webp","width":966,"height":543,"caption":"브룩라디 증류소의 옥토모어 컬렉션"},{"kind":"quote","text":"증류소: 브룩라디 증류소"},{"kind":"quote","text":"위스키 타입: 싱글 몰트"},{"kind":"quote","text":"캐스크 정보: 퍼스트 필 버번 캐스크(First Fill Bourbon) 5년 숙성"},{"kind":"quote","text":"보리 정보: 100% 스코틀랜드산 콘체르토(Concerto) / 2016년 수확"},{"kind":"quote","text":"페놀 수치: 128.9ppm"},{"kind":"quote","text":"도수: 59.6%"},{"kind":"figure","src":"/articles/octomore-14-1/04.webp","width":966,"height":966},{"kind":"heading","text":"Nose"},{"kind":"paragraph","text":"- 생각보다 강하지 않은 피트감, 숯불향, 약간의 베이컨스러운 향"},{"kind":"paragraph","text":"- 달달하고 고소한 곡식향"},{"kind":"paragraph","text":"- 허니콤과 약간의 달달한 과육의 과실"},{"kind":"heading","text":"Palate"},{"kind":"paragraph","text":"- 바나나 브륄레, 살짝 탄 것 같은 카라멜, 흑설탕"},{"kind":"paragraph","text":"- 청사과"},{"kind":"heading","text":"Finish"},{"kind":"paragraph","text":"- 달달한 훈연향과 카라멜,"},{"kind":"paragraph","text":"- 스쳐가는 레몬타르트 같은 시트러스"},{"kind":"paragraph","text":"- 끝으로 갈수록 강해지는 훈연향"},{"kind":"paragraph","text":"옥토모어 14.1은 전체적으로 ''달다''는 느낌이 강하게 들며, 이 단맛이 처음에는 피트의 향에 묻혀있다가 점점 모습을 드러내는 것 같습니다."},{"kind":"paragraph","text":"오픈 직후에는 피트가 강하지만, 좀 지나면 피트감이 생각보다는 강하게 느껴지지 않고, 버번 캐스크와 피트의 조합이 빛나는 한 잔입니다."}]'::jsonb, 'published', '2024-07-22T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'bar-leichhardt', 'bar', '라이카도 — 멋진 위스키 콜렉션', '"라이카도(Bar Leichhardt)"는 후쿠오카의 야쿠인역과 와타나베도리역 사이에 위치한 바로, 후쿠오카 내에서도 "히구치(Bar Higuchi)"와 더불어 멋진 위스키 라인업을 자랑하는 바입니다.', '/articles/bar-leichhardt/00.webp',
  'https://blog.naver.com/shakinglikebartender/223520281386', false,
  '[{"kind":"figure","src":"/articles/bar-leichhardt/00.webp","width":966,"height":543},{"kind":"figure","src":"/articles/bar-leichhardt/01.webp","width":966,"height":1288},{"kind":"paragraph","text":"\"라이카도(Bar Leichhardt)\"는 후쿠오카의 야쿠인역과 와타나베도리역 사이에 위치한 바로, 후쿠오카 내에서도 \"히구치(Bar Higuchi)\"와 더불어 멋진 위스키 라인업을 자랑하는 바입니다."},{"kind":"paragraph","text":"히구치에 비해서는 아직 국내에서 많이 알려지지 않은 탓인지 한국인 손냄이 간간히 있긴 하지만 많지는 않은 것 같습니다."},{"kind":"figure","src":"/articles/bar-leichhardt/02.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/bar-leichhardt/03.webp","width":966,"height":1288,"caption":"보모어 12년 추가 숙성 / 글렌터렛 하이볼"},{"kind":"paragraph","text":"\"라이카도\"에서는 실제 보모어의 오크를 가져와 작게 만든 오크통에 보모어 12년을 계속해서 채워서 추가 숙성하는 위스키가 있습니다."},{"kind":"paragraph","text":"하프로 마셔봤는데, 일반 12년보다 당연히 숙성감은 있었는데 그 말로만 정리하기가 어렵고, 옛날 보모어의 편린이 보이는 느낌이었습니다. 향은 약간 아쉬웠네요."},{"kind":"paragraph","text":"하이볼은 ''약간의 피트감이 있는 싱글 몰트''로 주문했는데, 윌슨 앤 모건(Wilson & Morgan)의 쿨일라와 글렌터렛을 추천해줘서 글렌터렛(Glenturret)으로 마셨습니다."},{"kind":"paragraph","text":"사실 그렇게 기대는 안됐는데, 달달하고 약간의 피트가 있는 게, 마치 ''롱로우를 고소하게 해서 하이볼로 하면 이런 느낌이 아닐까?'' 하는 느낌이었네요. 아주 맛있었습니다."},{"kind":"figure","src":"/articles/bar-leichhardt/04.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/bar-leichhardt/05.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/bar-leichhardt/06.webp","width":966,"height":1288,"caption":"Ardbeg Blaaack / Springbank 12yo 80s(?) Ceramic / Kilchoman Cognac Cask"},{"kind":"paragraph","text":"아드벡 블랙(Ardbeg Blaaack)은 제가 알기로 바틀에 양 그림이 없는 버전(46%)과 양 그림이 있는 버전(50.7%)이 있는 걸로 아는데, 전 전자를 마셨습니다."},{"kind":"paragraph","text":"뉴질랜드의 피노누아 캐스크를 썼다고 하는데....와인 캐스크의 캐릭터는 솔직히 그닥 느끼지 못했고, 아드벡의 피트감이 좀 강하게 느껴졌습니다. 다른 버전을 마셔보고 싶네요."},{"kind":"paragraph","text":"특급 시대의 스프링뱅크 도자기 바틀은 이전에도 마셔본 적이 있습니다만, 도자기병은 휘발이 용이해서 내용물이 줄어드는 경우가 많습니다."},{"kind":"paragraph","text":"이런 점 때문에 바틀의 보존 상태에 따라서 맛이 달라지는데, 이번에 마신 건 보존 상태가 안좋았는지 약간의 올드몰트 향 빼고는 힘이 상당히 빠진 느낌을 많이 받았습니다."},{"kind":"paragraph","text":"\"라이카도\"는 위스키의 종류가 정말 다양하며, 평일 기준으로 손님이 그렇게 많지 않고 차분한 느낌을 받았으며, 직원들이 아주아주 친절합니다. 위스키 추천도 맡길만하니 마음 놓고 추천 받아보는 것도 좋습니다."}]'::jsonb, 'published', '2024-07-21T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'bruichladdich-valinch-feis-ile-2024', 'spirits', '브룩라디 발린치 페스 아일 2024', '아일라(Islay) 섬에 위치한 브룩라디(Bruichladdich) 증류소에는 증류소샵에서만 구매할 수 있는 위스키 바틀이 존재합니다.', '/articles/bruichladdich-valinch-feis-ile-2024/00.webp',
  'https://blog.naver.com/shakinglikebartender/223519293671', false,
  '[{"kind":"figure","src":"/articles/bruichladdich-valinch-feis-ile-2024/00.webp","width":966,"height":966},{"kind":"figure","src":"/articles/bruichladdich-valinch-feis-ile-2024/01.webp","width":966,"height":966},{"kind":"heading","text":"About The Whisky"},{"kind":"paragraph","text":"아일라(Islay) 섬에 위치한 브룩라디(Bruichladdich) 증류소에는 증류소샵에서만 구매할 수 있는 위스키 바틀이 존재합니다. \"더 라디 발린치(The Laddie Valinch)\"가 그것으로, 이 바틀은 증류소의 직원들을 기념하기 위한 바틀로, 출시되는 바틀마다 각각 다른 직원의 얼굴을 달고 릴리즈 됩니다."},{"kind":"figure","src":"/articles/bruichladdich-valinch-feis-ile-2024/02.webp","width":966,"height":543,"caption":"브룩라디 증류소샵의 발린치 시리즈. 2024.06기준으로 73번까지 출시."},{"kind":"paragraph","text":"각 릴리즈는 싱글캐스크(Single Cask) 및 캐스크 스트렝스(Cask Strength)로 출시되며, 릴리즈마다 캐스크는 모두 다르며, 증류소 자체적으로는 증류소 현장 샵에서만 판매하고 있으며, 핸드필(Hand-filled)로도 구매할 수 있습니다. 500ml로 출시되는 건 아쉽지만, 증류소 기념품이라고 볼 수도 있죠."},{"kind":"paragraph","text":"이러한 발린치 시리즈 중에서도 증류소 직원 전체의 사진을 달고 릴리즈 된 것들이 있는데, 이 바틀들은 아일라의 연례 행사인 페스 아일(Feis Ile) 한정 바틀로, 이번에 리뷰할 위스키는 2024년 페스 아일에 릴리즈된 발린치 제품입니다."},{"kind":"quote","text":"증류소: 브룩라디 증류소"},{"kind":"quote","text":"위스키 타입: 싱글 몰트 / 싱글 캐스크 / 캐스크 스트렝스"},{"kind":"quote","text":"캐스크 정보: 세컨드 필 셰리 벗(2nd Fill Sherry Butt) 17년"},{"kind":"quote","text":"도수: 57.1%"},{"kind":"figure","src":"/articles/bruichladdich-valinch-feis-ile-2024/03.webp","width":966,"height":966},{"kind":"heading","text":"Nose"},{"kind":"paragraph","text":"- 말린 대추, 꿀, 무화과, 카카오닙, 카카오, 건과일"},{"kind":"paragraph","text":"- 꿀에 절인 대추 같은 향"},{"kind":"heading","text":"Palate"},{"kind":"paragraph","text":"- 단맛이 있긴 하지만 향만큼 달지는 않고, 약간의 스파이스"},{"kind":"paragraph","text":"- 카카오닙처럼 쌉쌀한 느낌도 남음"},{"kind":"paragraph","text":"- 약간의 꿀 같은 캐릭터가 입에 남음"},{"kind":"paragraph","text":"- 생각만큼 도수감이 느껴지지 않음"},{"kind":"heading","text":"Finish"},{"kind":"paragraph","text":"- 달달하고 안정적인 피니시"},{"kind":"paragraph","text":"- 말린 대추, 살짝의 카카오닙"},{"kind":"paragraph","text":"개인적으로 셰리 캐스크를 사용한 위스키를 그렇게 좋아하는 편은 아닌데, 이 위스키는 아주 맛있게 마셨습니다. 아마 셰리 캐스크 특유의 스파이스 캐릭터나 팥 같은 캐릭터가 강하지 않아서 그런 것 같습니다."},{"kind":"paragraph","text":"여담으로 브룩라디 발린치의 경우 대부분의 릴리즈가 좋은 평가를 받아왔습니다(위스키베이스 기준 80점대 후반). 아마 직원들을 기념하는 바틀인 만큼 캐스크 선정에 신경을 쓴 것 같은데, 이런 증류소에서 일하는 직원들은 애사심이 절로 생기겠네요."}]'::jsonb, 'published', '2024-07-20T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'bar-rummy', 'bar', '러미 — 럼을 좋아하세요?', '"러미(Rummy)"는 후쿠오카의 와타나베도리역과 야쿠인역 근처에 위치한 바로, 전 세계의 럼(Rum/Rhum/Ron)을 전문으로 하는 바입니다.', '/articles/bar-rummy/00.webp',
  'https://blog.naver.com/shakinglikebartender/223518285590', false,
  '[{"kind":"figure","src":"/articles/bar-rummy/00.webp","width":966,"height":1288,"caption":"럼주란 뭘까?"},{"kind":"paragraph","text":"\"러미(Rummy)\"는 후쿠오카의 와타나베도리역과 야쿠인역 근처에 위치한 바로, 전 세계의 럼(Rum/Rhum/Ron)을 전문으로 하는 바입니다. 나카스의 마두로(Bar Maduro)와 함께 일본 내에서도 마니악한 카테고리의 럼을 전문으로 하는 바입니다."},{"kind":"figure","src":"/articles/bar-rummy/01.webp","width":966,"height":1288,"caption":"모히또(Mojito)"},{"kind":"paragraph","text":"럼 전문 바이긴 하지만 당연히 칵테일도 가능합니다. 저는 날씨가 너무 더워서 모히또를 첫 잔으로 마셨는데, 럼을 재료로 하는 칵테일만 가능한 건지, 다른 기주의 칵테일도 가능한지까지는 모르겠네요."},{"kind":"figure","src":"/articles/bar-rummy/02.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/bar-rummy/03.webp","width":966,"height":1288,"caption":"Caroni 1997 / Uitvlugt Guyana 1995"},{"kind":"paragraph","text":"첫 잔으로는 오기 전부터 신경쓰였던 카로니 1997을 마셨습니다. 이 바틀은 이제는 폐쇄된 트리니다드의 카로니(Caroni) 증류소의 럼으로, 일본의 주류판매점인 시나노야의 도움으로 럼 전문 바인 ''러미'', ''바 럼 & 위스키(Bar Rum & Whisky/교토)''와 ''바 램프(Bar Lamp/도쿄 긴자)''에 의해 병입된 것으로 보입니다."},{"kind":"paragraph","text":"카로니 1997은 가볍지도, 그렇다고 그렇게 묵직하지도 않지만 도수감(62%)에서 오는 강렬함이 가장 기억에 남습니다. 다만, 제가 딱 좋아하는 캐릭터가 아닌데다가 다양한 럼을 접해보지 못한 저로서는 조금은 어려운 바틀이었습니다."},{"kind":"paragraph","text":"다음으로 데메라라 럼을 추천해달라고 부탁드렸는데, 아이플럭트 가이아나 1995를 추천해주셨습니다. 아마 독립병입자에서 낸 제품인 것 같은데, 제가 럼에 대해서는 아직 잘 몰라서 정확히는 모르겠습니다."},{"kind":"paragraph","text":"이 럼은 21년 숙성되었으나, 숙성감은 그렇게 느껴지지 않고, 어딘가 그라빠(Grappa)나 마르(Marc) 같은 느낌을 받았는데, 이건 카로니 1997보다 더 이해하기 어려운 바틀이었습니다."},{"kind":"figure","src":"/articles/bar-rummy/04.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/bar-rummy/05.webp","width":966,"height":1288,"caption":"Cadenhead''s Alcoholes Finos Dominicanos 11yo / Compagnie Des Indes Jamaca 12 ans"},{"kind":"paragraph","text":"다음으로 부탁드린 건 도미니카 럼이었습니다. 여기서부터는 아주 묵직하고 직관적인 단맛이 느껴지는 것이 제 취향에 딱 맞았네요."},{"kind":"paragraph","text":"''예전에 한국에서 달지 않은 도미니칸 럼을 마신적이 있는데, 좋은 기억은 아니다!''라고 불평하니, 오너가 ''도미니카 럼에서도 달지 않은 게 있긴 한데...정말 드문 경우이긴 하다.''고 하신 게 기억에 남네요."},{"kind":"paragraph","text":"마지막으로 ''펑키함의 극치''와 같은 럼을 부탁드리니 콤파니 데산드(Compagnie Des Indes)라는 독립병입자의 자메이카 럼을 추천해주셨습니다."},{"kind":"paragraph","text":"펑키한 럼을 좋아하신다면 이건 꼭 드셔보는 걸 추천드리는데, 정말정말 맛있었습니다. 도수감은 느껴지지도 않고, 정말 다채로운 캐릭터의 럼입니다."},{"kind":"figure","src":"/articles/bar-rummy/06.webp","width":966,"height":1288,"caption":"Arcabuz"},{"kind":"paragraph","text":"중간에 옆에 앉았던 단골 손님이 주신 럼도 맛있게 마셨는데, 알카버즈(Arcabuz)라는 일본에서 만들어지는 럼이라 합니다. 최근 일본에서도 많은 럼이 만들어지고 있는데, 이건 그 중에 특이하게도 럼 아그리꼴(Rhum Agricole) 스타일로 만든 제품입니다."},{"kind":"paragraph","text":"제가 마셨던 7월 10일 기준으로, 그 전주에 병입되어 판매된 블랑(Blanc-White)급으로 아직 숙성이 되지 않았다고 합니다."},{"kind":"paragraph","text":"정말 확실하게 럼 아그리꼴의 그 쿰쿰한 느낌이 나는데, 솔직히 꽤 맛있어서 놀랐습니다. 단골 손님과 오너는 일본 쇼츄에서 나는 특유의 캐릭터가 난다고 하기도 했습니다. 나중에 숙성된 걸 가지고 나올 때가 또 기대되네요."},{"kind":"paragraph","text":"''러미''는 오너 바텐더 혼자 운영하는 곳으로, 응대가 그렇게 살갑지는 않고, 단골이 많아 단골을 주로 챙기려는 성향이 있는 것 같습니다. 저는 일본어 회화가 가능했고, 다른 단골 손님과 얘기를 하다보니 같이 오너와도 이런저런 얘기를 했었습니다."},{"kind":"paragraph","text":"일본어가 유창하지 않다면 약간은 뻘쭘하게 있을 수도 있을 것 같고, 내부 흡연이 가능하니 이 점 참고해서 방문해주시기 바랍니다. 다만, 럼이라는 카테고리를 경험하고 싶다, 이미 좋아한다! 하시는 분들에게는 꼭 추천드리고 싶네요."}]'::jsonb, 'published', '2024-07-19T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'around-the-world', 'cocktail', '어라운드 더 월드', '"어라운드 더 월드(Around The World)"라는 칵테일은 비행기 세계일주 노선 운항을 기념한 칵테일 대회에서 우승한 작품으로, 미국인 바텐더의 작품이라 알려져 있다고 합니다.', '/articles/around-the-world/00.webp',
  'https://blog.naver.com/shakinglikebartender/223516976562', false,
  '[{"kind":"figure","src":"/articles/around-the-world/00.webp","width":966,"height":966},{"kind":"heading","text":"About The Cocktail"},{"kind":"paragraph","text":"\"어라운드 더 월드(Around The World)\"라는 칵테일은 비행기 세계일주 노선 운항을 기념한 칵테일 대회에서 우승한 작품으로, 미국인 바텐더의 작품이라 알려져 있다고 합니다."},{"kind":"paragraph","text":"다만, 이러한 주장이나, 칵테일 레시피는 일본에서만 있는 것으로 그 출처는 명확하지가 않습니다."},{"kind":"paragraph","text":"진(Gin), 민트 리큐르, 파인애플 주스라는 간단한 재료의 꽤나 생소한 조합의 칵테일로 궁금증을 자극하며, 상단의 표면이 하얀색 구름과 같이 있는 아름다운 초록색 칵테일입니다."},{"kind":"figure","src":"/articles/around-the-world/01.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"30ml 진(Gin)"},{"kind":"paragraph","text":"15ml 크렘 드 민트(Creme de Menthe)"},{"kind":"paragraph","text":"15ml 파인애플 주스(Pineapple Juice)"},{"kind":"paragraph","text":"1 민트 체리(Mint Cherry) - 옵션"},{"kind":"figure","src":"/articles/around-the-world/02.webp","width":966,"height":966},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 민트 체리 이외의 재료를 셰이커 안에 모두 넣어줍니다."},{"kind":"paragraph","text":"2. 셰이커에 얼음을 넣고 셰이킹해줍니다."},{"kind":"paragraph","text":"3. 칵테일 잔 안에 민트 체리를 하나 넣어줍니다."},{"kind":"paragraph","text":"(옵션)"},{"kind":"paragraph","text":"4. 셰이킹 한 칵테일을 잔에 부어줍니다."},{"kind":"figure","src":"/articles/around-the-world/03.webp","width":966,"height":966},{"kind":"figure","src":"/articles/around-the-world/04.webp","width":966,"height":966},{"kind":"paragraph","text":"이 칵테일은 진, 민트 리큐르, 파인애플이라는 생소한 조합의 칵테일인데, 진과 민트의 궁합은 워낙 좋지만 파인애플은 좀 글쎄다 싶었습니다. 그런데 의외로 잘 어울리는 것이 웃음이 지어지는 맛입니다."},{"kind":"paragraph","text":"아주 상쾌하고 약간은 달달한 맛으로, 진의 맛이 딱 중심을 잡아주고, 민트 리큐르가 시원함을, 파인애플 주스가 달달함과 과일의 캐릭터를 더해줘 보기보다 밸런스가 꽤 좋은 칵테일이라는 생각이 들었습니다."},{"kind":"paragraph","text":"만들기 전에는 레시피가 단순해 뭔가 비터나 다른 재료를 넣고 싶었지만, 마셔보고 나니 이대로도 아주 좋아서 다른 재료를 넣기가 애매하네요."},{"kind":"paragraph","text":"진의 비율이 적어 도수감이 조금 있고, 거기에 더해 시트러스 캐릭터가 있는 진과 어울리겠다 싶어서 일반 진보다는 도수가 살짝 높고(47.3%), 자몽 캐릭터가 강한 탱커레이 넘버 텐(Tanqueray No.10)을 사용했는데, 중심을 확실히 잡아줘서 좋은 선택이었던 것 같습니다."},{"kind":"paragraph","text":"\"어라운드 더 월드\" 칵테일은 다양한 레시피가 있으니 레시피를 바꾸거나 진의 종류를 바꿔 비교해 보는 것도 하나의 재미가 되겠습니다."}]'::jsonb, 'published', '2024-07-18T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'kawabata-whisky', 'bar', '카와바타 위스키', '카와바타 위스키는 후쿠오카의 나카스카와바타역 5번 출구 근처에 위치한 주류샵입니다.', '/articles/kawabata-whisky/00.webp',
  'https://blog.naver.com/shakinglikebartender/223515890625', false,
  '[{"kind":"figure","src":"/articles/kawabata-whisky/00.webp","width":966,"height":1288},{"kind":"paragraph","text":"카와바타 위스키는 후쿠오카의 나카스카와바타역 5번 출구 근처에 위치한 주류샵입니다. 1층에서는 위스키를 판매하고 있으며, 2층에서는 럼, 진, 데킬라, 와인, 꼬냑, 리큐르 등을 판매하고 있습니다."},{"kind":"figure","src":"/articles/kawabata-whisky/01.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/kawabata-whisky/02.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/kawabata-whisky/03.webp","width":966,"height":1288},{"kind":"paragraph","text":"카와바타 위스키의 가장 큰 특징은 주류샵 안에서 오크통의 위스키를 바로 꺼내서 무료로 시음을 할 수 있다는 것입니다."},{"kind":"paragraph","text":"주류샵 내부에는 5~6종의 오크통이 있는데, 이 오크통들은 롯코산 증류소에서 받는 것이며, 사쿠라 캐스크, 미즈나라 캐스크와 같이 좀처럼 접하기 어려운 오크통 또한 볼 수 있습니다. 대부분은 5년 이하 숙성의 저숙성 위스키들이며, 피티드와 논피티드 모두 있습니다."},{"kind":"paragraph","text":"직원 분에게 얘기하면 조금씩 무료로 시음이 가능하니 꼭 시음을 해보시기 바라며, 200ml의 작은 바틀로도 판매를 합니다. 저는 피티드, 사쿠라 혹스헤드 캐스크에서 피니시한 3년 숙성의 위스키를 200ml 바틀로 구매하였습니다."},{"kind":"paragraph","text":"그 외에 2층에는 다른 종류의 주류도 있으며, 화장실도 있으니 한 번 둘러보는 것도 좋겠네요."},{"kind":"figure","src":"/articles/kawabata-whisky/04.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/kawabata-whisky/05.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/kawabata-whisky/06.webp","width":966,"height":1717}]'::jsonb, 'published', '2024-07-17T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'bar-gita', 'bar', '지타 — 영화 OST와 바의 만남', '"지타(Bar Gita)"는 후쿠오카의 나카스 포장마차 거리 근처에 위치한 바로, 경력이 정말 오래돼보이는 나이가 지긋하신 오너 바텐더가 운영하는 곳입니다.', '/articles/bar-gita/00.webp',
  'https://blog.naver.com/shakinglikebartender/223516016463', false,
  '[{"kind":"figure","src":"/articles/bar-gita/00.webp","width":810,"height":1440},{"kind":"figure","src":"/articles/bar-gita/01.webp","width":810,"height":1440},{"kind":"figure","src":"/articles/bar-gita/02.webp","width":966,"height":543},{"kind":"paragraph","text":"\"지타(Bar Gita)\"는 후쿠오카의 나카스 포장마차 거리 근처에 위치한 바로, 경력이 정말 오래돼보이는 나이가 지긋하신 오너 바텐더가 운영하는 곳입니다. 바 내부에는 영화 포스터가 가득하며, 영화 OST가 계속해서 흘러나오는데, 오너의 취향을 단번에 파악할 수 있는 부분이네요."},{"kind":"figure","src":"/articles/bar-gita/03.webp","width":810,"height":1440},{"kind":"figure","src":"/articles/bar-gita/04.webp","width":966,"height":543},{"kind":"paragraph","text":"바 내부에 \"하이랜드 파크(Highland Park)\" 라인업이 꽤 있고, 증류소의 로고가 있는 오크통 끝 부분이 있는 걸 보니 오너가 하이랜드 파크를 좋아하시는 것 같습니다. 여쭤보니 오크통 끝 부분은 이전에 바텐더 연수로 증류소에 갔을 때 선물로 받았다고 하십니다."},{"kind":"figure","src":"/articles/bar-gita/05.webp","width":810,"height":1080},{"kind":"paragraph","text":"저는 늦은 시간에 찾아가 하이볼과 오너가 추천한 오리지널 칵테일을 마셨는데, 술을 꽤 마시고 방문해서 그런지 오리지널 칵테일은 찍는 걸 깜빡했네요. 과실감 있고, 그렇게 도수가 높지 않은 칵테일을 부탁드렸는데, 만족스러운 한 잔을 받았던 걸로 기억합니다."},{"kind":"paragraph","text":"내부 분위기 자체는 처음 바를 방문하는 분들도 부담스럽지 않을 정도의 분위기입니다. 다른 오센틱 바들은 아무래도 바가 익숙하지 않은 분들에게 낯설 수도 있는데, 노래도 영화 OST로 꽤나 친근하고, 딱 보이는 술병이 많지도 않아 위압감이 들지도 않습니다. 무엇보다 오너가 정말 친절하게 접객을 해주십니다."},{"kind":"paragraph","text":"나중에 후쿠오카의 여러 바에서 들은 정보인데, \"지타\"의 오너 바텐더는 이전에 많은 대회에서 수상을 하셨고, 마티니가 정말 맛있는 곳이라 합니다. 저는 시간이 안돼서 다시 방문하지 못했는데, 다음에 후쿠오카를 갈 떄 다시 들러서 꼭 마티니를 마셔보고 싶습니다."},{"kind":"paragraph","text":"마침 나카스 포장마차 거리 근처에 위치한 곳이니, 포장마차를 즐긴 후 느즈막하게 들러서 한 두잔 정도 칵테일로 분위기를 내는 것도 좋을 것 같습니다."}]'::jsonb, 'published', '2024-07-17T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'bar-vesper', 'bar', '베스퍼 — 후쿠오카의 낮술 대피소', '"베스퍼(Vesper)"는 후쿠오카의 텐진미나미역 서쪽 출구 근처의 케고 신사 바로 옆에 있는 바입니다.', '/articles/bar-vesper/00.webp',
  'https://blog.naver.com/shakinglikebartender/223514474480', false,
  '[{"kind":"figure","src":"/articles/bar-vesper/00.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/bar-vesper/01.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/bar-vesper/02.webp","width":966,"height":1717},{"kind":"paragraph","text":"\"베스퍼(Vesper)\"는 후쿠오카의 텐진미나미역 서쪽 출구 근처의 케고 신사 바로 옆에 있는 바입니다. 후쿠오카 외에도 삿포로(홋카이도), 긴자(도쿄), 교토, 쿠마모토에도 지점이 있습니다. 가장 특이한 건, 후쿠오카 지점은 오전 11시부터 바를 오픈한다는 점입니다."},{"kind":"figure","src":"/articles/bar-vesper/03.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/bar-vesper/04.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/bar-vesper/05.webp","width":966,"height":1288,"caption":"진토닉(Gin Tonic) / 탈리스커 하이볼 / 부나하벤 하이볼"},{"kind":"paragraph","text":"11시라는 이른 시간부터 오픈을 하다 보니 후쿠오카에 일찍 도착하게 되거나, 점심 즈음에 여행에서 할 일이 없으면 가게되는 것 같습니다."},{"kind":"paragraph","text":"특히나 요즘처럼 더울 때는 들러서 시원한 진토닉이나 위스키 하이볼을 마시면서 더위를 잠깐이라도 피하면 더할 나위 없이 좋겠죠."},{"kind":"figure","src":"/articles/bar-vesper/06.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/bar-vesper/07.webp","width":966,"height":1288,"caption":"파리지앵 변형(Parisian twist) / 뱀부(Bamboo) / 김렛(Gimlet)"},{"kind":"paragraph","text":"진토닉이나 하이볼이 아니더라도 다른 칵테일도 당연히 주문 가능하며, 추천을 받는 것도 좋습니다."},{"kind":"paragraph","text":"예시로 저는 \"과실감이 있고, 도수가 낮은 스터 칵테일\"을 주문하였고, 그렇게 나온 것이 파리지앵 칵테일의 변형이었습니다. 기주인 진(Gin) 대신에 피노 쉐리(Fino Sherry)를 넣어 도수를 낮추면서도 복합성을 잃지 않는 식의 변형인데, 아주 매력적인 칵테일이었습니다."},{"kind":"paragraph","text":"개인적인 감상으로는 베스퍼는 하이볼과 스터 칵테일을 잘하는 것 같으니, 하나씩 마셔보는 걸 추천드립니다."},{"kind":"paragraph","text":"제가 방문했을 때는 오너 바텐더가 안계셨지만, 응대해주신 바텐더님이 정말 친절하게 대해주셨고, 칵테일 얘기 뿐만 아니라 일상의 시시콜콜한 얘기나 농담도 함께 하면서 즐거운 시간을 보냈습니다."}]'::jsonb, 'published', '2024-07-16T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'bar-valinch', 'bar', '발린치 — 숨어있는 은근한 위스키 강자', '"발린치(Valinch)"는 후쿠오카의 텐진미나미역과 와타나베도리역 중간에 있는 바로, 꽤나 차분한 분위기의 바입니다.', '/articles/bar-valinch/00.webp',
  'https://blog.naver.com/shakinglikebartender/223512163042', false,
  '[{"kind":"figure","src":"/articles/bar-valinch/00.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/bar-valinch/01.webp","width":966,"height":1288},{"kind":"paragraph","text":"\"발린치(Valinch)\"는 후쿠오카의 텐진미나미역과 와타나베도리역 중간에 있는 바로, 꽤나 차분한 분위기의 바입니다."},{"kind":"paragraph","text":"이 바의 가장 큰 특징이라 한다면, 출시된 위스키를 바 안의 오크통에서 추가 숙성하여 판매한다는 점입니다. 오너에 의하면 현재 라가불린, 보모어, 글렌기어리가 딱 마시기 좋게 숙성되었다고 합니다."},{"kind":"figure","src":"/articles/bar-valinch/02.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/bar-valinch/03.webp","width":966,"height":1288,"caption":"글렌모렌지 10년 미즈나라 캐스크에서 추가 숙성 /                     카노스케 럼캐스크 숙성"},{"kind":"paragraph","text":"그 외에도 다양한 추가 숙성되고 있는 위스키들이 있는데, 저는 먼저 글렌모렌지 10년을 미즈나라 캐스크(Mizunara Cask)에서 추가 숙성한 걸 마셔봤습니다."},{"kind":"paragraph","text":"오너가 비교해보라고 글렌모렌지 10년을 같이 주셨는데 확실히 다르긴합니다. 다만, 미즈나라 캐스크의 캐릭터가 정확히 뭐다!라고 제가 표현을 잘 못하겠네요...."},{"kind":"paragraph","text":"오너와 이런저런 얘기를 하다가 일본에서 카노스케(Kanosuke)는 어떤 포지션인지를 물어봤습니다. 일본에서도 카노스케는 꽤 잘 만들고 있는 루키라는 인상이 있다고 하네요."},{"kind":"paragraph","text":"그러다가 카노스케 럼캐스크 숙성된 걸 5미리 남았다고 주셨는데, 개인적으로 캐스크를 정말 잘 쓴다는 인상을 받았습니다. 럼의 달달한 캐릭터를 확실히 위스키에 부여했다는 게 아주아주 맛있었습니다."},{"kind":"figure","src":"/articles/bar-valinch/04.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/bar-valinch/05.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/bar-valinch/06.webp","width":966,"height":1288,"caption":"Hazelburn 15 year Oloroso matured /                    The Art Collection Mannochmore / Octomore 08.3"},{"kind":"paragraph","text":"개인적으로 스프링뱅크의 제품을 좋아하는데, 헤이즐번 15년 올로로소 캐스크는 이전에 마셔본 적 있지만 국내에선 보기 어려운 헤이즐번의 제품이니 한 번 더 마셔봤습니다. 역시 스프링뱅크 증류소에서 나오는 제품이니 맛은 보장되어 있네요."},{"kind":"paragraph","text":"다음은 오너의 추천으로 마셨는데, The Art Collection이라는 독립병입자의 밀라노 위스키 페스티벌 & 럼 쇼 2023(Milano Whisky Festival & Rum Show 2023)을 위해 출시된 마녹모어로, 버번 혹스헤드 숙성 후 아몬티야도 캐스크에서 16개월 피니시를 거친 제품입니다. 부들부들하고, 요구르트 같은 단향이 인상적이었습니다."},{"kind":"paragraph","text":"얘기를 더 하다가 옥토모어에 대한 얘기가 나왔는데, ppm이 300 이상 되는 바틀이 있다고 하셔서 바로 주문해봤습니다. 옥토모어 08.3은 ppm이 309.1이라는 세계에서 가장 ppm이 높은 바틀로 유명한데, 맛은.... 솔직히 강렬한 피트에 곡물감이 달달하게 나지만 그렇게 복합적이지 않은, 굳이....싶은 바틀이긴 했습니다."},{"kind":"figure","src":"/articles/bar-valinch/07.webp","width":966,"height":543},{"kind":"paragraph","text":"그외에 발린치에는 스프링뱅크 몇 종류, 옥토모어 몇 종류가 있고, 독립병입자도 꽤 많이 갖춰져있습니다. 오너가 글렌모렌지를 좋아하시는지 글렌모렌지가 많이 보였고, 일본 위스키는 그렇게 많이 보이지는 않았네요."},{"kind":"paragraph","text":"오너 혼자서 운영하는 것 같고, 오너가 살짝은 거리감 있지만 사근사근하게 응대를 해주십니다. 새벽 4시까지 운영을 하니 느즈막하게 방문해서 한 잔 마시는 것도 좋을 것 같네요."}]'::jsonb, 'published', '2024-07-14T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'bar-cherokee', 'bar', '체로키 — 올드바틀과 빈티지의 천국', '"체로키(Cherokee)"는 후쿠오카 나카스의 한 빌딩에 위치한 바로, 올드바틀의 천국이라 할 수 있는 바입니다.', '/articles/bar-cherokee/00.webp',
  'https://blog.naver.com/shakinglikebartender/223512114600', false,
  '[{"kind":"figure","src":"/articles/bar-cherokee/00.webp","width":810,"height":1440},{"kind":"figure","src":"/articles/bar-cherokee/01.webp","width":810,"height":1440},{"kind":"paragraph","text":"\"체로키(Cherokee)\"는 후쿠오카 나카스의 한 빌딩에 위치한 바로, 올드바틀의 천국이라 할 수 있는 바입니다. 오래된 올드바틀의 위스키 뿐만 아니라, 올드바틀의 다른 증류주나 리큐르까지 정말 다양한 라인이 준비되어 있고, 이 재료들로 칵테일을 만들어내기도 합니다."},{"kind":"figure","src":"/articles/bar-cherokee/02.webp","width":595,"height":793},{"kind":"figure","src":"/articles/bar-cherokee/03.webp","width":810,"height":1080},{"kind":"figure","src":"/articles/bar-cherokee/04.webp","width":810,"height":1080,"caption":"네그로니(Negroni) / 캄파리(50s, 80s, current) /스푸모니(Spumoni)"},{"kind":"paragraph","text":"저는 워낙에 네그로니(Negroni)라는 칵테일과 그 재료로 들어가는 캄파리(Campari)를 매우 좋아해서 50년대, 80년대의 캄파리와 현행으로 나오는 캄파리를 비교해서 마셔보았습니다."},{"kind":"paragraph","text":"제 감상으로는 현행과 과거의 캄파리는 단맛과 쓴맛의 포인트가 다르다였습니다. 현행보다 80년대의 캄파리는 단맛과 쓴맛이 좀 더 차분하고, 용담이나 칡뿌리 같은 뿌리의 쓴맛 캐릭터를 좀 더 느낄 수 있고, 자몽과 망고의 캐릭터가 인상적인 캄파리였습니다. 50년대의 캄파리는 한방 약재들의 캐릭터가 지배적이며 좀 더 묵직한 느낌으로, 아마로 같은 인상을 강하게 받았습니다."},{"kind":"paragraph","text":"올드바틀로 만든 네그로니는 80년대의 탱커레이, 80년대의 캄파리, 90년대의 친자노 버무스로 만들어졌습니다. 맛 자체의 무게감이 현재의 네그로니와는 확연하게 차이가 나고, 단맛의 쓴맛의 캐릭터 자체가 다릅니다. 이 한 잔은 ''체로키''에 가신다면 꼭 추천드리고 싶네요."},{"kind":"paragraph","text":"그 외에도 80년대 캄파리로 만든 스푸모니를 마시면서 오너와 스푸모니의 기원에 대해서 시시콜콜한 농담을 하며 재미있게 마셨습니다. 이것도 상당히 맛있었구요."},{"kind":"figure","src":"/articles/bar-cherokee/05.webp","width":810,"height":1440},{"kind":"figure","src":"/articles/bar-cherokee/06.webp","width":810,"height":1440},{"kind":"figure","src":"/articles/bar-cherokee/07.webp","width":810,"height":1440,"caption":"마르 드 샴페인(Marc de Champagne)"},{"kind":"paragraph","text":"그 외에도 최근 마르(Marc)와 핀(Fine)에 관심이 많아 마르가 있는지 여쭤봤는데, ''마르 드 샴페인''이 있다고 해서 바로 주문했습니다. 이것도 올드바틀이라 하셨는데, 다른 마르 드 샴페인과 비교해보라고 한 잔을 더 주셨습니다."},{"kind":"paragraph","text":"하나는 맛이 세로로 느껴지고, 하나는 가로로 느껴진다는데, 표현은 이상하지만 그 말 그대로 맛이 느껴지는 게 정말 신기했습니다."},{"kind":"paragraph","text":"이렇게 ''체로키''에는 올드바틀 리큐르, 그걸 이용한 칵테일이 있을 뿐만 아니라, 올드바틀 위스키나 다른 종류의 증류주까지 정말 많은 올드바틀이 놓여져 있으며, 합리적인 가격에 경험을 할 수 있습니다. 물론 일반적인 칵테일이나, 직접 증류한 술을 활용한 칵테일 등도 다양하게 준비가 되어 있습니다."},{"kind":"paragraph","text":"올드바틀에 관심이 있으시거나, 칵테일과 리큐르에 관심이 있는 분들에게 특히 추천을 드리며, 오너에게 관련된 질문을 하면 정말 잘 설명해주시니 궁금한 것도 주저 없이 물어봐주세요."}]'::jsonb, 'published', '2024-07-14T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'bar-sebek', 'bar', '세벡 — 나카스 골목에 핀 작은 꽃', '"세벡(Sebek)"은 후쿠오카 나카스의 한 골목길에 위치한 작은 바입니다.', '/articles/bar-sebek/00.webp',
  'https://blog.naver.com/shakinglikebartender/223511381638', false,
  '[{"kind":"figure","src":"/articles/bar-sebek/00.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/bar-sebek/01.webp","width":966,"height":1717},{"kind":"paragraph","text":"\"세벡(Sebek)\"은 후쿠오카 나카스의 한 골목길에 위치한 작은 바입니다. ''헤네시 X.O 칵테일 컴페티션 2017''과 ''산토리 칵테일 어워드 2021''에서 우승을 한 ''오오츠 마키코'' 오너가 혼자 운영을 하고 있으며, 현재에도 두 대회에서 우승한 칵테일들을 맛 볼 수 있습니다."},{"kind":"paragraph","text":"''Sebek''이란 고대 이집트의 악어 머리를 하고 있는 신으로, 바의 간판과 바 내부에서도 악어와 관련된 장식물을 흔하게 찾아볼 수 있습니다. 다른 손님들과 하는 얘기를 들었는데, 오너 본인이 들인 것보다도 손님들의 선물이 많다고 하네요."},{"kind":"paragraph","text":"여담으로 \"세벡\"은 \"만화 바텐더\"와도 연관이 있습니다. 바텐더의 작가가 방문하여 취재하기도 하였고, ''바텐더 a tokyo''의 ''바의 문''이라는 에피소드에 등장하는 \"라흐므(Larme)\"라는 칵테일의 레세피를 제공하기도 하였다고 합니다."},{"kind":"figure","src":"/articles/bar-sebek/02.webp","width":966,"height":1288},{"kind":"paragraph","text":"''뚜르비옹''은  ''헤네시 X.O 칵테일 컴페티션 2017'' 우승 칵테일로, 헤네시 X.O, 아프리콧 홍차, 바나나 리큐르, 로제 시럽 등을 디켄터에 넣고 스월링한 후 서브하고, 얼음 위에 유자 가루를 가니시해주는 특이한 칵테일입니다. 맛 자체도 정말 신기한 게 헤네시 X.O라는 꼬냑에 다른 맛을 추가하여 스펙트럼을 넓힌 것 같은 맛입니다."},{"kind":"paragraph","text":"''즈이카''는 ''산토리 칵테일 어워드 2021'' 우승 칵테일로, 일본의 로쿠 진(Roku Gin), 말차 리큐르, 생강 시럽, 오오츠님이 직접 양봉한 꿀 등이 들어가는 칵테일입니다. 시트러스가 들어가지 않지만 밸런스가 좋고, 이 칵테일도 이전까지는 마셔본 적 없는 특이한 느낌의, 말차가 주가 되는 칵테일이었습니다."},{"kind":"figure","src":"/articles/bar-sebek/03.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/bar-sebek/04.webp","width":966,"height":1288},{"kind":"paragraph","text":"그 외에 다양한 칵테일이 있는데, 이렇게 더운 날에는 모히또나 진토닉을 첫 잔으로 꼭 추천하고 싶습니다. 모히또는 아마 마지막에 압생트를 살짝 뿌려주시는 것 같은데, 이게 또 모히또의 민트 캐릭터와 잘 어울립니다."},{"kind":"paragraph","text":"에스프레소 마티니는 카카오 리큐르나 카카오 닙을 칵테일에 넣으시는 거 같은데, 가니시로 올려준 카카오닙처럼 쌉쌀한 카카오 같은 맛으로, 굳이 따지자면 커피 보다는 카카오 닙 맛이 나는 에스프레소 마티니라는 인상을 받았습니다."},{"kind":"figure","src":"/articles/bar-sebek/05.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/bar-sebek/06.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/bar-sebek/07.webp","width":966,"height":1717,"caption":"애플잭(Apple Jack) / 라뇨 사보란 VSOP"},{"kind":"paragraph","text":"칵테일 외에도 다양한 위스키, 브랜디, 진 등이 있으며, 맥캘란, 하이랜드 파크, 헤네시 등의 올드바틀도 있습니다. 다만 올드바틀은 아직 판매하지 않고 있으며, 아직 판매할 시기를 정하지 못했다고 하네요."},{"kind":"paragraph","text":"다만, \"세벡\"은 칵테일을 주로 하는 바이며, 오너가 다양한 수상 경력도 가지고 있는 만큼, 칵테일을 강력하게 추천드립니다."},{"kind":"paragraph","text":"\"세벡\"은 꽤나 아기자기한 바로, 바테이블에 6자리, 4인용 테이블 하나가 끝이니, 되도록이면 붐비지 않는 시간인 오픈 직후에 방문하는 걸 추천드리며, 흡연이 가능한 바이니 저처럼 흡연을 하지 않는 분들은 특히 사람이 적은 오픈 직후가 좋겠네요."}]'::jsonb, 'published', '2024-07-13T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'bar-heart-strings', 'bar', '하트 스트링스 — 후쿠오카의 재패니즈 클래식 바', '"하트 스트링스(Heart Strings)"는 후쿠오카 나카스의 한 빌딩 5층에 위치한 바로, 딱 재패니즈 클래식 바라 할 수 있는 바입니다.', '/articles/bar-heart-strings/00.webp',
  'https://blog.naver.com/shakinglikebartender/223511440055', false,
  '[{"kind":"figure","src":"/articles/bar-heart-strings/00.webp","width":966,"height":1718},{"kind":"figure","src":"/articles/bar-heart-strings/01.webp","width":966,"height":543},{"kind":"paragraph","text":"\"하트 스트링스(Heart Strings)\"는 후쿠오카 나카스의 한 빌딩 5층에 위치한 바로, 딱 재패니즈 클래식 바라 할 수 있는 바입니다."},{"kind":"paragraph","text":"이곳의 오너 바텐더인 ''하시모토 코지''님은 약 40년 경력의 후쿠오카 내에서도 오래된 경력의 바텐더이며, ''하트 스트링스''는 1994년 오픈하여 올해로 30년이 되는 노포입니다."},{"kind":"figure","src":"/articles/bar-heart-strings/02.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/bar-heart-strings/03.webp","width":966,"height":1288,"caption":"오너 바텐더의 메이킹 / 뉴욕(New York) /                    잭로즈 하이볼(Jack Rose Highball)"},{"kind":"paragraph","text":"''하트 스트링스''에서 마신 칵테일 중 가장 인상적인 것은 ''뉴욕(New York)''이었습니다. 짐빔 화이트와 메이지야의 그레나딘을 사용하는데, 짐빔 화이트의 아몬드 같은 견과류의 맛과 확실한 달달한 석류 맛을 내는 그레나딘이 상큼하게 다가오는 게 아주아주 만족스러웠습니다."},{"kind":"paragraph","text":"''그레나딘은 수제를 사용해야 칵테일에서 제일 맛있다.''라는 제 생각을 완전히 깨주는 한 잔이었고, 짐빔 화이트의 의외의 장점을 볼 수 있었습니다."},{"kind":"paragraph","text":"오너 ''하시모토''님은 본인의 바텐더 경력에서 가장 많이 만든 칵테일이 ''뉴욕(New York)''이라 하니, 꼭 한 번 주문하는 걸 추천드립니다."},{"kind":"paragraph","text":"그레나딘과 뉴욕 칵테일에 대해 이런저런 얘기를 하다보니, 오너로부터 매장에서 사용하는 메이지야의 그레나딘 시럽을 한 병 선물로 받게 되었습니다(감사히 잘 쓰겠습니다!!)."},{"kind":"figure","src":"/articles/bar-heart-strings/04.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/bar-heart-strings/05.webp","width":966,"height":1288},{"kind":"paragraph","text":"일본에서는 올드패션드를 일반적으로 시트러스, 체리, 각설탕을 그대로 서브해주고, 손님이 직접 쇠 머들러로 으깨는 정도를 조절할 수 있게 하는데, 이곳은 또 다르게 레몬, 오렌지, 체리를 먼저 머들링하고나서 스터한 후 서브를 합니다. 아주 주시한 게 또다른 매력이 있는 올드패션드였습니다."},{"kind":"paragraph","text":"진토닉 같은 경우에는 일본에서 흔하게 사용되는 슈웹스 토닉이 아닌, 캐나다 드라이의 토닉 워터를 사용합니다. 이에 대해 오너인 ''하시모토''님은 이런저런 토닉 워터를 비교해서 맛본 적이 있는데, 본인에게도 충격이었던 것이 캐나다 드라이가 가장 맛있었다고 합니다."},{"kind":"figure","src":"/articles/bar-heart-strings/06.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/bar-heart-strings/07.webp","width":966,"height":1288,"caption":"아일라 바이올렛(Islay Violets) / 타케츠루 퓨어몰트 17년"},{"kind":"paragraph","text":"''하트 스트링스''는 물론 칵테일도 다양하나, 위스키도 다양한 종류가 있으며, 특히 재패니즈 위스키 라인업이 꽤 갖춰져있다는 인상을 받았습니다."},{"kind":"paragraph","text":"개인적으로 재패니즈 중에서는 하쿠슈를 좋아하는데, 하쿠슈 18년이 있는 바는 아주 오랜만입니다. 물론 비싸기도 하고, 오너가 굳이 마실 필요 없다고도 해서 마시진 않았습니다."},{"kind":"paragraph","text":"아일라 바이올렛(Islay Violets) 33년은 독립병입자에서 출시한 보모어(Bowmore)로, 아주 플로럴하고, 은은한 피트가 더해진 꽤나 우아한 한 잔이었습니다. 보모어를 좋아하신다면 당연히 마셔봐야 할 한 잔이며, 정확한 가격은 기억이 안나지만 그렇게 비싸지 않았던 것 같습니다."},{"kind":"paragraph","text":"타케츠루 퓨어몰트 17년은 두 번째 방문에서 마지막 잔으로 오너가 선물로 주셨습니다. 지금 구하기 힘든데 어렵게 구했다면서 한 잔 주셨는데, 겨우 두 번째 방문에서 이렇게까지 챙겨주셔서 정말 감사했습니다. 꽤 취할 즈음이어서 맛이 세세하게 기억나지는 않았지만 정말 맛있게 마신 기억이 남아있네요."},{"kind":"paragraph","text":"''하트 스트링스''는 재패니즈 클래식 바를 경험하고 싶은 분들에게 강력하게 추천드리며, 위스키 라인도 다양하게 갖춰져 있으니 위스키를 주로 드시는 분들에게도 추천드리고 싶은 곳입니다."}]'::jsonb, 'published', '2024-07-13T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'bordeaux-point-rouge', 'bar', '포인트 루즈', '"포인트 루즈(Point Rouge)"는 보르도(Bordeaux)의 ''생장(Saint-Jean)역'' 근처에 있는 바입니다.', '/articles/bordeaux-point-rouge/00.webp',
  'https://blog.naver.com/shakinglikebartender/223504265636', false,
  '[{"kind":"paragraph","text":"\"포인트 루즈(Point Rouge)\"는 보르도(Bordeaux)의 ''생장(Saint-Jean)역'' 근처에 있는 바입니다."},{"kind":"paragraph","text":"보르도에서 와인이 아니고 무슨 바를 가냐고 하실 수 있으나, 이 바는 엄청나게 많은 위스키 라인업, 특히 고숙성과 국내에서 보기 어려운 위스키를 저렴한 가격에 마실 수 있는 엄청난 바입니다."},{"kind":"figure","src":"/articles/bordeaux-point-rouge/00.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/bordeaux-point-rouge/01.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/bordeaux-point-rouge/02.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/bordeaux-point-rouge/03.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/bordeaux-point-rouge/04.webp","width":966,"height":1288},{"kind":"paragraph","text":"메뉴 중 일부인데, 단종된 맥캘란 10년이 14유로, 맥캘란 엘레강시아 1991 16유로, 맥켈란 레플리카 1876이 42유로 밖에 하지 않는 미친 가격대를 보여줍니다. 재밌는 건 라가불린 16년은 또 18유로로 비쌉니다."},{"kind":"paragraph","text":"가격이 당시 매입가로 책정된 건지, 어떻게 책정된 건지는 잘 모르겠지만 국내에서 볼 수 없거나 비싼 위스키를 아주 저렴하게 마셔볼 수 있습니다."},{"kind":"paragraph","text":"전 바로 맥캘란 10년과 엘레강시아를 주문했는데, 10년은 없다고 하더군요.....ㅠㅠ"},{"kind":"figure","src":"/articles/bordeaux-point-rouge/05.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/bordeaux-point-rouge/06.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/bordeaux-point-rouge/07.webp","width":966,"height":1717,"caption":"Macallan / Martell / George T.Stagg"},{"kind":"paragraph","text":"제가 마셔본 건 맥캘란 엘레강시아 1991(Macallan Elegancia), 마르텔 리저브 드 샹텔루 70년대 바틀(Martell Reserve de Chanteloup, Borderies), 조지 티스택(George T.Stagg 2015)이었습니다."},{"kind":"paragraph","text":"맥캘란 엘레강시아 1991는 현행의 맥캘란보다 훨씬 자연스럽고, 튀지 않는 느낌의 쉐리감인 맥캘란이었습니다만, 제가 맥캘란을 그렇게까지 선호하지는 않아 그 이상의 감상은 없었습니다."},{"kind":"paragraph","text":"마르텔 리저브 드 샹텔루 같은 경우에는 보더리 원액 단독으로 만들어진 것 같은데, 그렇게 크게 인상적이지 않았습니다."},{"kind":"paragraph","text":"BTAC의 조지 티스택은 이번에 처음 마셔봤는데, 기대감을 져버리지 않았습니다. 강력한 도수감에서 오는 타격감에 카라멜, 눅진한 체리, 바닐라, 건과일, 시나몬 등 저에게 극호인 캐릭터가 강렬하게 남았습니다."},{"kind":"paragraph","text":"\"포인트 루즈\"는 시그니처 뿐만 아니라 클래식 칵테일도 물론 판매하지만 굳이 칵테일을 마시는 것보다는 다양한 위스키, 꼬냑, 럼 등을 저렴한 가격에 맛 볼 수 있기 때문에 위스키, 꼬냑, 럼 등을 마시는 걸 추천드립니다."}]'::jsonb, 'published', '2024-07-07T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'barcelona-dr-stravinsky', 'bar', '닥터 스트라빈스키', '"닥터 스트라빈스키(Dr Stravinsky)"는 바르셀로나 대성당 근처에 위치한 바로, 2019년 The World''s Best Bars 50(월드 베스트 바)에서 25위에 이름을 올리기도 했습니다.', '/articles/barcelona-dr-stravinsky/00.webp',
  'https://blog.naver.com/shakinglikebartender/223504224649', false,
  '[{"kind":"figure","src":"/articles/barcelona-dr-stravinsky/00.webp","width":966,"height":1289},{"kind":"figure","src":"/articles/barcelona-dr-stravinsky/01.webp","width":966,"height":1288},{"kind":"paragraph","text":"\"닥터 스트라빈스키(Dr Stravinsky)\"는 바르셀로나 대성당 근처에 위치한 바로, 2019년 The World''s Best Bars 50(월드 베스트 바)에서 25위에 이름을 올리기도 했습니다."},{"kind":"paragraph","text":"닥터 스트라빈스키에서는 ''재증류, 발효, 팻  워싱(Fat Washing), 인퓨징(Infusing), 수비드 등등'' 다양한 기술을 바탕으로 칵테일을 만들어내며, 역시나 믹솔로지적인 성격이 강한 바입니다."},{"kind":"figure","src":"/articles/barcelona-dr-stravinsky/02.webp","width":966,"height":543},{"kind":"figure","src":"/articles/barcelona-dr-stravinsky/03.webp","width":966,"height":1717},{"kind":"paragraph","text":"바 내부 벽면과 백바를 보면 인퓨징 중인 주류들과 재증류, 발효, 워싱을 거친 주류들이 주로 진열되어 있으며, 미니 증류기까지 바 카운터에 두는 등 바의 아이덴티티를 쉽게 파악할 수 있도록 배치한 것이 인상적입니다."},{"kind":"figure","src":"/articles/barcelona-dr-stravinsky/04.webp","width":966,"height":966},{"kind":"figure","src":"/articles/barcelona-dr-stravinsky/05.webp","width":966,"height":966,"caption":"Tuber Negroni / Cheese Knees"},{"kind":"paragraph","text":"\"투베르 네그로니(Tuber Negroni)\"에서 ''투베르''는 트러플을 의미하는데, 메뉴의 재료 표기에서 ''black truffle mezcal''을 확인하실 수 있습니다."},{"kind":"paragraph","text":"생 트러플은 가격이 있는 편이며, 인퓨징을 한다고 하더라도 일주일도 안되는 사이에 향과 맛이 거의 빠지게 되어 바텐더분에게 물어보니 메즈칼에 트러플 오일을 워싱하는 식으로 트러플의 캐릭터를 준다고 합니다."},{"kind":"paragraph","text":"네그로니는 본래 그 재료들인 진(Gin), 버무스(Vermouth), 캄파리(Campari) 때문에 약초, 한약재스러운 맛과 향이 나는데, 거기에 트러플이 더해지니 꽤 잘 어울렸고, 쿰쿰한 향의 치즈 가니시까지 더하니 꽤 일체감 있는 향과 맛이 났습니다. 치즈를 버섯처럼 보이게 만들어 가니시한 것도 아주 마음에 드네요."},{"kind":"paragraph","text":"\"치즈 니즈(Cheese Knees)\"는 \"비즈 니스(Bee''s Knees)\"라는 클래식 칵테일의 변형으로, 기존의 ''비즈 니스''에 스모키함과 치즈를 더한 칵테일입니다. 친구가 주문해서 저는 한 두입만 마셔봐서 정확히 기억이 나지는 않는데, 꽤 괜찮은 칵테일이었습니다."},{"kind":"figure","src":"/articles/barcelona-dr-stravinsky/06.webp","width":966,"height":966},{"kind":"figure","src":"/articles/barcelona-dr-stravinsky/07.webp","width":966,"height":966,"caption":"Camp Nou / ?"},{"kind":"paragraph","text":"\"캄프 누(Camp Nou)\"는 진, 피노 쉐리, 허브 시럽, 라임 등이 들어가는 일종의 \"김렛(Gimlet)\"이라는 클래식 칵테일의 변형으로 볼 수 있으며, 신맛과 허브를 좋아하시는 분들은 아주 좋아하실 맛입니다."},{"kind":"paragraph","text":"''캄프 누''는 축구팀인 FC 바르셀로나의 홈구장으로, FC 바르셀로나의 팬인 저로서는 안시키고는 베길 수 없는 한 잔이었습니다. 솔직히 네이밍이 칵테일에 어울리는지는 차치하고, FC 바르셀로나 팬이라 밝히고 칵테일을 주문하니 바텐더분이 정말 좋아하시는 게 재밌었습니다."},{"kind":"paragraph","text":"바르셀로나에는 십스(Sips), 파라디소(Paradiso) 등과 같이 유명한 바들이 많습니다만, 저는 개인적으로 닥터 스트라빈스키를 방문할 것 같습니다."},{"kind":"paragraph","text":"맛과 가니시가 필요 이상으로 너무 복잡하지 않고 직관적인 편이며, 너무 사람이 붐비지도 않는 편이고, 일단 가격대가 다른 곳들보다는 낮은 편입니다."}]'::jsonb, 'published', '2024-07-07T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'barcelona-paradiso', 'bar', '파라디소', '"파라디소(Paradiso)"는 2015년 바르셀로나 대성당과 바르셀로네타 해변 근처에 오픈한 바로, 2023년까지 The World''s Best Bars 50(월드 베스트 바)에 6번 선정되었으며, 2022년에는 1위에 이름을 올렸습니다.', '/articles/barcelona-paradiso/00.webp',
  'https://blog.naver.com/shakinglikebartender/223503460517', false,
  '[{"kind":"figure","src":"/articles/barcelona-paradiso/00.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/barcelona-paradiso/01.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/barcelona-paradiso/02.webp","width":966,"height":1288},{"kind":"paragraph","text":"\"파라디소(Paradiso)\"는 2015년 바르셀로나 대성당과 바르셀로네타 해변 근처에 오픈한 바로, 2023년까지 The World''s Best Bars 50(월드 베스트 바)에 6번 선정되었으며, 2022년에는 1위에 이름을 올렸습니다."},{"kind":"paragraph","text":"겉으로는 파스트라미 가게처럼 보이지만, 가게 내부의 냉장고 문을 열면 바로 들어갈 수 있는 스피크이지(Speakeasy) 스타일의 바입니다."},{"kind":"paragraph","text":"파라디소는 창의적이고 비주얼적으로 아름다운 칵테일을 만들며, 시그니처 칵테일마다 멋진 가니시와 퍼포먼스까지 갖추고 있는 바로, 확실히 보는 재미가 있는 칵테일을 제공하며, 심상치 않은 형광 메뉴부터 이 바의 성격을 엿볼 수 있습니다."},{"kind":"figure","src":"/articles/barcelona-paradiso/03.webp","width":966,"height":1287},{"kind":"figure","src":"/articles/barcelona-paradiso/04.webp","width":966,"height":966},{"kind":"figure","src":"/articles/barcelona-paradiso/05.webp","width":966,"height":966,"caption":"Great Gatsby / The Cloud"},{"kind":"paragraph","text":"\"위대한 개츠비(Great Gatsby)\"는 기본적으로 올드패션드 칵테일의 구조로, ''맥캘란 12년 더블캐스크''를 기주로 하는 칵테일입니다. 그 외에 트러플, 꿀, 아마로, 라벤더 에센스 등이 들어가며, 훈연을 한 번 해주는 칵테일입니다."},{"kind":"paragraph","text":"사실 개인적인 감상으로는 ''맥캘란 12년 더블캐스크를 쓴 올드패션드''가 끝입니다. 그렇게 특별하지는 않은.....다만 ''맥캘란 12년 더블캐스크''로 만드는 올드패션드를 마셔볼 일이 없으니, 하나의 경험으로 볼 수 있겠네요."},{"kind":"paragraph","text":"\"구름(The Cloud)\"이라는 칵테일은 메즈칼, 히비스커스, 아마로 몬테네그로, 버무스, 탄산 등이 들어가는 어딘가 아메리카노 칵테일스러운 느낌이 있네요."},{"kind":"paragraph","text":"메이킹 후 잔 위에 커피 거품을 올려 마무리하는 칵테일입니다. 먼저 음료를 준비해주고, 커피 거품을 만들어서 직접 올려주는데, 시각적인 재미 하나는 확실하네요."},{"kind":"figure","src":"/articles/barcelona-paradiso/06.webp","width":966,"height":966},{"kind":"figure","src":"/articles/barcelona-paradiso/07.webp","width":966,"height":966,"caption":"Ramses / Supercool Martini"},{"kind":"paragraph","text":"\"람세스(Ramses)\"는 로쿠 진(Roku Gin), 듀어스 12년, 홉(hop) 버무스, 와인 코디얼, 아마로 등이 들어가는 달콤상큼한 캐릭터의 칵테일입니다."},{"kind":"paragraph","text":"이름에서 볼 수 있듯이 이집트와 관련된 가니시를 한 것이 특징인데, 잔을 들어보면 그 안에 미이라의 관 형태의 초콜릿이 들어있는, 아주 센스 넘치는 칵테일입니다."},{"kind":"paragraph","text":"\"과냉각 마티니(Supercool Martini)\"는 클래식 마티니에 과냉각이라는 기술을 더한 칵테일입니다. 과냉각한 물을 따르는 순간 물이 샤베트처럼 얼어붙고, 여기에 버무스를 뿌리고, 파라디소에서 재증류한 아주 차가운 진을 넣은 다음, 올리브를 꽂은 픽으로 얼음을 녹여줘 다일루션을 주는 형식입니다."},{"kind":"paragraph","text":"마티니를 만드는 과정을 재해석한 것이라 할 수 있으며, 이렇게 만드는 이유는 아주 차가운 마티니를 만들기 위해서라고 합니다."},{"kind":"paragraph","text":"파라디소는 다양한 재료와 기법으로 아주 창의적인 가니시와 퍼포먼스로 눈을 즐겁게 해주는 경험을 주는 바입니다. 저도 개인적으로 이렇게까지 시각적으로 즐거운 바는 처음이었습니다."},{"kind":"paragraph","text":"물론 칵테일은 맛도 중요하긴 하지만 시각적인 부분과 그 공간이 주는 분위기의 영향을 많이 받기도 합니다. 제가 마셨던 칵테일들은 특정 재료의 맛이 좀 튀는 경향이 있었는데, 그렇다고 맛이 없었다는 건 아니고, 이건 믹솔로지 성향의 칵테일 바라면 어쩔 수 없는 부분이라 생각합니다."},{"kind":"paragraph","text":"오픈 시에 방문하는 걸 추천드리는데, 조금만 시간이 지나면 웨이팅이 꽤 많이 늘어납니다. 저는 오픈한지 얼마 안돼서 갔는데, 친구와 30~40분 정도 기다리다가 들어갔네요."},{"kind":"paragraph","text":"아무래도 밤이 깊어질수록 바를 찾는 사람들이 많아지니 웨이팅은 더 길어질 수 있으니 이른 시간 방문하는 걸 추천드립니다."}]'::jsonb, 'published', '2024-07-06T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'paris-little-red-door', 'bar', '리틀 레드 도어', '"리틀 레드 도어"는 2012년 파리의 마레 지구에 오픈한 바로, 2023년까지 The World''s Best Bars 50(월드 베스트 바)에 10번이나 선정되었으며, 2022년에는 5위에 이름을 올리기도 했습니다.', '/articles/paris-little-red-door/00.webp',
  'https://blog.naver.com/shakinglikebartender/223500064122', false,
  '[{"kind":"figure","src":"/articles/paris-little-red-door/00.webp","width":966,"height":966},{"kind":"paragraph","text":"\"리틀 레드 도어\"는 2012년 파리의 마레 지구에 오픈한 바로, 2023년까지 The World''s Best Bars 50(월드 베스트 바)에 10번이나 선정되었으며, 2022년에는 5위에 이름을 올리기도 했습니다."},{"kind":"paragraph","text":"바의 이름 그대로 입구의 빨간색 작은 문이 아이코닉한 바로, 사실 빨간 문이 아니라 빨간 문 왼쪽편의 문으로 입장을 합니다."},{"kind":"paragraph","text":"\"리틀 레드 도어\"는 비주얼적으로도 아름답고, 창의적인 칵테일을 만들면서도 \"팜 투 글라스(Farm to Glass)\"를 추구하고 있습니다."},{"kind":"paragraph","text":"\"팜 투 글라스\"는 \"팜 투 바(Farm to Bar)\"와 같은 개념으로, 말 그대로 농장에서 자란 농작물을 글라스에, 바에 가져온다는 개념입니다."},{"kind":"paragraph","text":"좀 더 풀어보자면, 생산자와 직접적으로 연결되어 바는 좀 더 저렴한 가격에 신선한 재료, 못난이 농산물 또는 지역의 특산물을 구매하고, 생산자는 좀 더 안정적으로 농작물을 공급할 수 있게 되고, 지역 특산물을 홍보할 수 있는 등, 서로에게 윈윈이 되는 ''지속가능성, 제로 웨이스트, 커뮤니티 형성'' 등과 같은 가치를 포함하는 개념입니다."},{"kind":"paragraph","text":"국내에는 임병진 대표님의 \"참 제철\"이 대표적이라 할 수 있겠네요."},{"kind":"figure","src":"/articles/paris-little-red-door/01.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/paris-little-red-door/02.webp","width":966,"height":1288},{"kind":"paragraph","text":"메뉴는 아주 간단하게 되어 있으며, 칵테일의 이름은 주된 재료만으로 아주 간단하게 되어있습니다. 물론 클래식 칵테일도 주문 가능합니다."},{"kind":"figure","src":"/articles/paris-little-red-door/03.webp","width":966,"height":966},{"kind":"figure","src":"/articles/paris-little-red-door/04.webp","width":966,"height":966},{"kind":"figure","src":"/articles/paris-little-red-door/05.webp","width":966,"height":966},{"kind":"paragraph","text":"저는 이전에 아마투스(Amathus)에서 마신 마르(Marc)가 정말 인상적이었어서 마르 드 부르고뉴(Marc de Bourgogne)가 들어간 \"라즈베리(Raspberry)\"를 첫 잔으로 주문했습니다."},{"kind":"paragraph","text":"아주 강렬한 상큼달콤한 라즈베리 느낌의 칵테일로 정말 만족스러운 첫 잔이었습니다. 다만, 마르의 캐릭터가 그닥 나지 않아서 ''꼭 마르를 썼어야 했나?''와 ''왜 무알콜인 라이어스(Lyre''s)의 제품을 사용했을까?''라는 의문이 들기도 했습니다."},{"kind":"paragraph","text":"두 번째 잔으로는 파리에 도착해서 케임브리지 퍼블릭 하우스(Cambridge Public House)와 해리스 뉴욕 바(Harry''s New York Bar)에 이어 세 번째로 \"사이드카(Sidecar)\"를 주문했습니다."},{"kind":"paragraph","text":"그렇게 뭐 크게 기억에 남지 않는 사이드카였고, 다른 오리지널 칵테일을 마시고 싶었지만, 일이 생겨서 사이드카를 마지막으로 하고 일어나야 했습니다."},{"kind":"figure","src":"/articles/paris-little-red-door/06.webp","width":966,"height":543},{"kind":"paragraph","text":"\"리틀 레드 도어\"는 전체적으로 아주 부산스러운 느낌으로, 약간은 클럽 비슷한 느낌을 받기도 했습니다. 예약은 받지 않고 워크인으로만 방문할 수 있는데, 웨이팅은 필수일 정도로 엄청난 핫플입니다."},{"kind":"paragraph","text":"처음 방문했을 때에는 웨이팅 엄두가 안나서 들어가지 못했고, 이틀 뒤에 혼자 가서야 15분 정도 웨이팅을 하고 들어갔습니다. 혼자 가는 경우에는 그래도 좀 더 빨리 입장할 수 있습니다."},{"kind":"paragraph","text":"내부는 노래가 아주 큰데다가 사람도 많으니 꽤나 시끄러운데, 여기에 더해 메이킹 하는 바텐더분이 불필요할정도로 요란하게 메이킹을 해서(그러다가 잔도 깨고.....) 분위기가 정말정말 부산스럽습니다."},{"kind":"paragraph","text":"칵테일의 경우, 리틀 레드 도어는 다른 유럽의 여느 바처럼 믹솔로지적인 성격이 아주 강해서 클래식 칵테일보다는 리틀 레드 도어의 오리지널 칵테일들을 추천드리는 편입니다."},{"kind":"paragraph","text":"혹시나 웨이팅이 너무 길다 싶으면 케임브리지 퍼블릭 하우스와 가까우니, 비교적 사람이 덜 붐비는 케임브리지 퍼블릭 하우스를 방문하시는 것도 좋은 대안입니다."}]'::jsonb, 'published', '2024-07-03T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'paris-the-cambridge-public-house', 'bar', '케임브리지 퍼블릭 하우스', '"케임브리지 퍼블릭 하우스"는 2019년 파리의 마레 지구에 오픈한 바로, 2023년에는 The World''s Best Bars(월드 베스트 바)에서 38위에 이름을 올렸습니다.', '/articles/paris-the-cambridge-public-house/00.webp',
  'https://blog.naver.com/shakinglikebartender/223497648855', false,
  '[{"kind":"paragraph","text":"\"케임브리지 퍼블릭 하우스\"는 2019년 파리의 마레 지구에 오픈한 바로, 2023년에는 The World''s Best Bars(월드 베스트 바)에서 38위에 이름을 올렸습니다. 편안하고 친근한 분위기의 펍(이름에서도 볼 수 있듯이, 영국식 펍)과 칵테일 바의 서비스 및 전문성을 결합하여 칵테일-펍을 지향한다고 합니다."},{"kind":"figure","src":"/articles/paris-the-cambridge-public-house/00.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/paris-the-cambridge-public-house/01.webp","width":966,"height":1288,"caption":"케임브리지 퍼블릭 하우스 내부 전경"},{"kind":"figure","src":"/articles/paris-the-cambridge-public-house/02.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/paris-the-cambridge-public-house/03.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/paris-the-cambridge-public-house/04.webp","width":966,"height":1288},{"kind":"paragraph","text":"케임브리지 퍼블릭 하우스의 칵테일 메뉴는 크게 ''이주의 칵테일'', 시즌별? 칵테일, 오리지널 칵테일로 나뉘어져 있고, 메뉴에 없는 칵테일도 문의해서 주문이 가능합니다. 그 외에도 음식, 맥주, 내추럴 와인 등이 메뉴에 있습니다. 저와 친구는 사진에 있는 ''Final Credits''와 ''Pimm''s 6.0''을 첫 잔으로 주문했습니다."},{"kind":"figure","src":"/articles/paris-the-cambridge-public-house/05.webp","width":966,"height":966},{"kind":"figure","src":"/articles/paris-the-cambridge-public-house/06.webp","width":966,"height":966},{"kind":"figure","src":"/articles/paris-the-cambridge-public-house/07.webp","width":966,"height":966,"caption":"Final Credits / Pimm''s 6.0 / Sidecar"},{"kind":"paragraph","text":"''Final Credits''는 딸기에 라이 위스키(Rye Whiskey)와 깔바도스(Calvados)를 기주로 하는 점과 아유크(Ayuuk)라는 처음 보는 리큐르에 호기심이 생겨서 주문을 하였습니다. 나중에 찾아보니 아유크는 파실라 믹세 칠리(Pasilla Mixe Chili)라는 달콤하고 스모키한 캐릭터를 가진 고추를 주재료로 하는 리큐르라고 합니다. 개인적으로 좋아하는 하이볼 형태의 칵테일로, 다소 달달하고 깔끔한 느낌의 칵테일이었습니다."},{"kind":"paragraph","text":"''Pimm''s 6.0''은 영국의 핌스(Pimm''s)라는 영국의 리큐르가 주가되도록 만든 칵테일로, 바의 오리지널 메뉴 중 하나로 자리잡았다는 점은 영국식 펍의 느낌과 칵테일 바의 결합을 지향하는 바의 성향을 아주 잘 보여주는 칵테일이라 할 수 있습니다. 아무래도 핌스 컵이 영국의 인기 칵테일이니. ''Pimm''s 6.0''은 로제와인스러운 핌스컵과 같은 칵테일로, 로제와인을 좋아하신다면 특히 좋아하시지 않을까 싶습니다."},{"kind":"paragraph","text":"마지막 잔은 ''파리에 왔으니 사이드카를 마셔야지!!''라는 극히 개인적인 생각으로 사이드카를 주문했는데, 설탕으로 리밍을 한 사이드카가 나왔습니다. 이런 사이드카는 동양쪽에서는 보기 어렵지만, 서양쪽에서는 가끔 볼 수 있는 형태의 사이드카입니다. 맛이 없지는 않지만 사이드카는 음 우리나라에서 마시는 걸로....(우리나라 바텐더 분들이 사이드카 잘 만들어요...)"},{"kind":"paragraph","text":"케임브리지 퍼블릭 하우스는 다른 칵테일 바들에 비해서는 확실히 편안한 분위기로, 전문적인 바에 익숙하지 않는 분들에게 특히 추천드립니다. 시즌별이나 오리지널 칵테일들을 마실 걸 추천드리는데, 국내에서 보기 어려운 재료들을 다양하게 사용을 하기도 하고, 무엇보다 클래식 칵테일보다는 오리지널이 더 맛있었습니다."}]'::jsonb, 'published', '2024-07-01T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'paris-chartreuse-paris-vauvert', 'bar', '샤르트뢰즈 파리-보베르', '샤르트뢰즈는 컬트적인 인기를 끌고 있는 프랑스의 허브 리큐르로, 그 기원이 아주 오래된 리큐르입니다.', '/articles/paris-chartreuse-paris-vauvert/00.webp',
  'https://blog.naver.com/shakinglikebartender/223497553700', false,
  '[{"kind":"paragraph","text":"샤르트뢰즈는 컬트적인 인기를 끌고 있는 프랑스의 허브 리큐르로, 그 기원이 아주 오래된 리큐르입니다."},{"kind":"paragraph","text":"샤르트뢰즈의 전설은 프랑스의 앙리 4세 때인 1605년 프랑스의 카르투시오회 수도자들이 후에 프랑스의 원수가 된 프랑수아-안니발 데스트레(François-Annibal d''Estrées)에게서 출처를 정확히 알 수 없는 장수의 비약으로 알려진 레시피를 받은 것에서 시작되었다고 합니다."},{"kind":"figure","src":"/articles/paris-chartreuse-paris-vauvert/00.webp","width":266,"height":400,"caption":"https://www.chartreuse.fr/en/produit/vegetable-elixir/"},{"kind":"paragraph","text":"이 문서는 1737년에 그랑 샤르트뢰즈 수도원(Grande Chartreuse)로 옮겨졌고, 수도사들에 의해서, 특히 제롬 모벡(Jérôme Maubec)의 큰 도움을 통해 1764년 샤르트뢰즈 그린의 원형인 \"엘릭시르 베제탈 드 라 그랑 샤르트뢰즈(ELIXIR VÉGÉTAL DE LA GRANDE-CHARTREUSE)\"를 만들어냅니다."},{"kind":"paragraph","text":"이후 레시피는 한 번도 바뀌지 않았다고 하며, 이 제품은 국내에서는 볼 수 없지만 일본에서는 비교적 쉽게 찾아볼 수 있습니다."},{"kind":"paragraph","text":"이후 1840년에 국내에는 샤르트뢰즈 그린(Chartreuse Green)과 샤르트뢰즈 옐로우(Chartreuse Yellow)로 알려진 샤르트뢰즈 베르테(Chartreuse Verte)와 샤르트뢰즈 존(Chartreuse Jaune)이 \"엘릭시르 베제탈 드 라 그랑 샤르트뢰즈\"를 바탕으로 만들어졌고, 그 인기로 인해 \"술의 여왕/리큐르의 여왕(Reine des Liqueurs)\"이라 불리기도 했습니다."},{"kind":"figure","src":"/articles/paris-chartreuse-paris-vauvert/01.webp","width":966,"height":1482},{"kind":"paragraph","text":"\"샤르트뢰즈 파리-보베르\"는 파리 오데옹(Odeon)역 바로 앞에 위치한 샤르트뢰즈 전용샵입니다. 런던에서 우연히 주류샵인 아마투스(Amathus)를 찾은 것처럼, 이 곳도 점심에 식당 웨이팅을 위해 시간을 보내다가 우연히 찾게 된 곳입니다."},{"kind":"figure","src":"/articles/paris-chartreuse-paris-vauvert/02.webp","width":966,"height":404},{"kind":"figure","src":"/articles/paris-chartreuse-paris-vauvert/03.webp","width":966,"height":1708},{"kind":"paragraph","text":"말이 리쿼샵이지, 샤르트뢰즈에 관한 역사나 옛날 바틀들 또한 구경할 수 있을 정도로 거의 샤르트뢰즈 박물관이라 할 수 있습니다."},{"kind":"paragraph","text":"샤르트뢰즈는 옛날 바틀들이 엄청난 가치를 가지고 있기 때문에 보기가 정말 어려운데, 이 곳에서는 다양한 옛날 바틀들을 구경할 수 있습니다."},{"kind":"figure","src":"/articles/paris-chartreuse-paris-vauvert/04.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/paris-chartreuse-paris-vauvert/05.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/paris-chartreuse-paris-vauvert/06.webp","width":966,"height":1717},{"kind":"paragraph","text":"샤르트뢰즈 그린과 옐로우는 기본이며, 그 외의 라인들을 모두 취급하고 있습니다. 저는 작은 도자기 바틀에 들어있는 엘릭시르 베제탈과 1084년 성 브루노가 카르투지오 수도회를 창립한 지 900주년을 기념하기 위해 카르투지오회 신부들이 1984년에 처음 만들어졌다고 하는 \"LIQUEUR DU 9e CENTENAIRE\"를 구매하고 싶었지만, 이미 위스키를 구매해서 참을 수 밖에 없었습니다...."},{"kind":"figure","src":"/articles/paris-chartreuse-paris-vauvert/07.webp","width":966,"height":752},{"kind":"paragraph","text":"진열된 상품을 지나쳐서 들어가면, 샤르트뢰즈 내부의 자체 바가 있습니다. 여기서 제품을 시음하거나 칵테일을 주문할 수 있는 것 같은데, 제가 방문한 날에는 하필 바가 쉬어서 아쉽게도 이용하지는 못했네요...."},{"kind":"paragraph","text":"파리 시내에서 샤르트뢰즈를 시음(아마 저렴하게 유료로)할 수 있으며, 샤르트뢰즈의 팬이라면 한 번쯤 방문해서 사진을 남기거나, 기념품을 살만한 곳입니다."}]'::jsonb, 'published', '2024-07-01T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'london-amathus', 'bar', '아마투스', '"Amathus"는 런던 소호에 위치한 주류샵으로 위스키 뿐만 아니라, 와인, 럼, 진, 데낄라, 메즈칼, 브랜디, 꼬냑, 리큐르 등 정말 다양한 주류를 판매하는 곳입니다.', '/articles/london-amathus/00.webp',
  'https://blog.naver.com/shakinglikebartender/223495440090', false,
  '[{"kind":"paragraph","text":"\"Amathus\"는 런던 소호에 위치한 주류샵으로 위스키 뿐만 아니라, 와인, 럼, 진, 데낄라, 메즈칼, 브랜디, 꼬냑, 리큐르 등 정말 다양한 주류를 판매하는 곳입니다. 저는 지나가다가 우연히 방문했는데, 우연히 들른 곳 치고 라인업도 좋고 시음도 가능해서 추천드릴 겸 소개를 해드리려합니다."},{"kind":"figure","src":"/articles/london-amathus/00.webp","width":966,"height":1289},{"kind":"figure","src":"/articles/london-amathus/01.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/london-amathus/02.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/london-amathus/03.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/london-amathus/04.webp","width":966,"height":1717},{"kind":"paragraph","text":"사진으로는 모두 담지 못했지만, 대부분의 주류들의 라인업이 정말 좋고, 위스키나 꼬냑 같은 경운에는 고숙성 라인업도 꽤 많이 있습니다. 또한 핀(Fine de Bourgogne) 드 부르고뉴나 마르 드 부르고뉴(Marc de Bourgogne) 등과 같이 국내에서 보기 힘든 주류도 꽤 있습니다. 제가 따로 주류를 구매한 건 아니여서 가격대가 어떻게 형성되어 있는지는 정확히 모르겠지만, 사진에 가격이 적혀있으니 필요하신 분들은 참고하시면 좋을 것 같습니다."},{"kind":"figure","src":"/articles/london-amathus/05.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/london-amathus/06.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/london-amathus/07.webp","width":966,"height":1717},{"kind":"paragraph","text":"아마투스에서는 무료로 시음도 가능한데, 직원에게 문의하시면 됩니다. 특정 브랜드를 지목해도 되고, 어떤 느낌을 찾고 있는지를 문의하셔도 됩니다. 저는 국내에서는 찾아보기 어려운 주류를 위주로 시음을 했는데, 그 중 럼인 리얼 캑코이(Real McCoy)는 크게 기억이 나지는 않았고, 메즈칼(Mezcal)인 알리푸스(Alipus)는 메즈칼 치고는 스모키함이 조금은 덜 느껴졌고, 풀 같은 캐릭터가 느껴져 개인적으로는 만족스럽지 못한 맛이었습니다."},{"kind":"paragraph","text":"제가 시음한 것 중에 제일 추천드리고 싶은 건 마르 드 부르고뉴입니다. 제가 유럽에 갔을 때 가장 마셔보고 싶었던 것들이 핀(Fine)과 마르(Marc)인데, 여기저기 찾아봐도 여기 말고는 찾지 못했던 점이 아쉬울 정도입니다. 마르는 간략하게 설명하자면 와인을 만들고 남은 포도 찌꺼기(껍질과 씨)를 증류해서 만든 것으로, 프랑스에서는 마르(Marc)로, 이탈리아에서는 그라빠(Grappa)라 불립니다. 핀의 경우는 와인을 숙성한 후 오크통의 바닥에 모이는 와인 찌꺼기로 만들어집니다."},{"kind":"paragraph","text":"직원에게 핀이나 마르가 있는지 물어보았는데, \"판매 상품만 있는데....잠깐 기다려봐\"라 하더니 저 바틀을 시음할 수 있도록 해줬습니다. 시음한 마르는 부르고뉴에 위치한 자쿨로(Jacoulot)의 마르 드 부르고뉴로 아마투스의 45주년을 기념하기 위해 만든 바틀입니다. 마르에 대한 저의 감상은 다른 증류주에서 느낄 수 없는 새로움, 변화무쌍하다는 것입니다. 약간의 프루티함에 너티함, 카라멜 같은 향이 나며, 맛에서는 껍질의 캐릭터가 확실히 느껴지고, 약간의 압생트 같은 풀의 캐릭터를 느낄 수 있었습니다."},{"kind":"paragraph","text":"적다보니 마르의 시음기처럼 되어버렸는데, 마르나 핀은 일본의 바에서도 간혹 볼 수 있으니 한 번쯤은 기회가 되신다면 마셔보시는 걸 추천드립니다(후쿠오카의 히구치에서도 본 기억이 있군요)."},{"kind":"paragraph","text":"정리하자면 아마투스는 정말 많은 라인업의 주류가 있는 리커샵으로, 시음도 일단은 무제한으로 가능합니다. 직원분들도 친절하시고, 술에 대한 지식이 많을 수록 좀 더 깊은 대화를 나누기에도 좋을 것 같습니다. 이렇게 얘기를 나누거나, 특정 주류(특히 매니악한 거....)를 시음할 수 있는지 문의를 하면 최대한 시음을 도와주려고 하니 꼭 방문해서 시음해 보는 걸 추천드립니다."}]'::jsonb, 'published', '2024-06-29T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'paris-harrys-new-york-bar', 'bar', '해리스 뉴욕바', '"Harry''s New York Bar"를 특별하게 만드는 건 역시 많은 클래식 칵테일이 만들어진 역사적인 장소라는 점일 것인데, 이 곳에서는 사이드카(Sidecar), 블러디 메리(Bloody Mary), 프렌치 75(French 75) 등과 같은', '/articles/paris-harrys-new-york-bar/00.webp',
  'https://blog.naver.com/shakinglikebartender/223494322550', false,
  '[{"kind":"figure","src":"/articles/paris-harrys-new-york-bar/00.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/paris-harrys-new-york-bar/01.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/paris-harrys-new-york-bar/02.webp","width":966,"height":1717,"caption":"바의 내부. 벽면의 천원이 눈에 띈다"},{"kind":"paragraph","text":"Classics"},{"kind":"figure","src":"/articles/paris-harrys-new-york-bar/03.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/paris-harrys-new-york-bar/04.webp","width":966,"height":1288},{"kind":"figure","src":"/articles/paris-harrys-new-york-bar/05.webp","width":966,"height":543,"caption":"신문 같은 느낌의 메뉴"},{"kind":"paragraph","text":"\"Harry''s New York Bar\"를 특별하게 만드는 건 역시 많은 클래식 칵테일이 만들어진 역사적인 장소라는 점일 것인데, 이 곳에서는 사이드카(Sidecar), 블러디 메리(Bloody Mary), 프렌치 75(French 75) 등과 같은 클래식 칵테일들이 탄생하였습니다."},{"kind":"figure","src":"/articles/paris-harrys-new-york-bar/06.webp","width":966,"height":966},{"kind":"figure","src":"/articles/paris-harrys-new-york-bar/07.webp","width":966,"height":966,"caption":"사이드카 / 블러디 메리 / 프렌치 75"},{"kind":"paragraph","text":"기주로는 레미 마틴 1738을 사용하였는데, 그래서인지 아니면 꼬냑의 비율 자체가 많아서인지 도수감이 좀 있는 사이드카였습니다. 저는 개인적으로 최애 칵테일 TOP5 에 사이드카는 꼭 들어가는 칵테일인만큼 사이드카의 탄생지에서 사이드카를 마셨다는 것 자체가 너무 즐거웠습니다. 프렌치 75는 보편적으로 아는 레시피에서 잔에 압생트를 린싱하는 것 같았습니다."},{"kind":"paragraph","text":"혹시라도 블러디 메리를 주문하시려는 분들께 미리 경고 드릴만한 게, 여기 블러디 메리 간이 정말정말 쎕니다. 블러디 메리에는 보드카에 타바스코, 소금, 후추, 토마토 주스 등이 들어가는데, 재료와 맛을 잘 모르시고 주문했다가 반도 못마시는 불상사가 발생할 수도...."},{"kind":"paragraph","text":"제가 방문한 날에는 프랑스에서 노르망디 상륙작전 80주년 행사를 했던 탓인지 대부분의 손님이 미국인이었습니다. 일요일 이외에는 아주 이른 시간인 12시에 오픈을 해서 파리 여행 중간에 잠깐 들러서 한 잔 하기에 꽤 좋습니다."},{"kind":"paragraph","text":"솔직하게 맛 자체가 아주 맛있다고 할 수는 없지만, 역사적인 바로 관광 겸 한 잔 하는 걸 추천드리고, 사이드카의 팬이라 하신다면 반드시 방문하는 것을 추천드립니다."},{"kind":"paragraph","text":"좀 더 많은 칵테일 정보는"}]'::jsonb, 'published', '2024-06-28T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'london-the-melody-whisky-bar', 'bar', '멜로디 위스키 바', '"The Melody Whisky Bar"는 런던 해머스미스에 위치한 바로, 칵테일도 제공하지만 이름 그대로 위스키를 주력으로 하는 바입니다.', '/articles/london-the-melody-whisky-bar/00.webp',
  'https://blog.naver.com/shakinglikebartender/223494430126', false,
  '[{"kind":"paragraph","text":"\"The Melody Whisky Bar\"는 런던 해머스미스에 위치한 바로, 칵테일도 제공하지만 이름 그대로 위스키를 주력으로 하는 바입니다. 런던으로 향하기 전에 캠벨타운에 위치한 카덴헤드(Cadenhead)의 테이스팅 샵 직원과 얘기하던 중에 위스키 라인업이 좋다고 추천을 받았았고, 저는 패피 반 윙클을 마시기 위해서 방문했습니다."},{"kind":"figure","src":"/articles/london-the-melody-whisky-bar/00.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/london-the-melody-whisky-bar/01.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/london-the-melody-whisky-bar/02.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/london-the-melody-whisky-bar/03.webp","width":966,"height":1717},{"kind":"figure","src":"/articles/london-the-melody-whisky-bar/04.webp","width":966,"height":1717,"caption":"엄청난 콜렉션"},{"kind":"paragraph","text":"예 뭐....런던에 한해서는 위스키의 종류와 희귀 바틀들이 가장 많은 바가 아닐까 싶습니다. 패피 반 윙클(Pappy Van Winkle) 뿐만 아니라 BTAC, 페쇠 증류소(로즈뱅크, 포트엘렌 등), 치치부, 가루이자와, 다양한 고숙성, 다수의 독립병입자, 증류소 핸드필 등 군침 흘릴만한 위스키들이 즐비해있습니다."},{"kind":"paragraph","text":"Winkle Flight"},{"kind":"figure","src":"/articles/london-the-melody-whisky-bar/05.webp","width":966,"height":543},{"kind":"paragraph","text":"- Old Rip Van Winkle 10 Year old -"},{"kind":"paragraph","text":"- Van Winkle Special Reserve 12 Year old -"},{"kind":"paragraph","text":"- Van Winkle Family Reserve Rye 13 Year old -"},{"kind":"paragraph","text":"- Pappy Van Winkle 15 Year old -"},{"kind":"paragraph","text":"- Pappy Van Winkle 20 Year old -"},{"kind":"paragraph","text":"윙클 플라이트 메뉴는 위의 총 5가지의 위스키가 10ml씩 제공됩니다. 10ml를 누구 코에 붙이냐 싶지만, 패피는 국내에서 마셔보기도 힘들고, 마셔도 엄청나게 비싼 가격이라 5종을 마셔볼 수 있는 기회만으로도 아주아주 감사합니다. 참고로 가격은 86파운드(서비스 차지 별도)로 약 15만원입니다. 서비스 차지까지 붙어서 저는 아마 17만원 정도 나온 것 같습니다."},{"kind":"paragraph","text":"패피 반 윙클에 대한 제 인상은 실망 그 자체였습니다. 먼저 올드 립 반 윙클 10년과 반 윙클 12년은 불쾌할 정도의 상한 유제품(특히 우유) 냄새가 났고, 라이는 크게 기억에 남지 않았으며, 15년과 20년은 숙성 년수가 주는 기대감을 전혀 채워주지 못했습니다. 복합성도 크게 느껴지지도 않고.....초반에 상한 유제품 냄새에서 흠칫해서 그런지 이후 마실 때에도 그다지 인상적인 느낌은 아니었습니다."},{"kind":"paragraph","text":"제일 기대한 20년은 캐릭터들이 밸런스 좋게 이루어지긴 했습니다만....복합적이라는 생각이 들지는 않았던데다가 캐릭터를 캐치하기가 애매했습니다. 오히려 15년이 좀 더 맛이 강하고 복합적으로 느껴졌는데, 아마도 도수가 53.5%로 다른 40도대인 라인들에 비해 높아서 그런 것 같습니다."},{"kind":"paragraph","text":"제 입맛에는 이래저래 전체적으로 실망스러웠으나, 버번의 끝판왕을 아주 좋은 가격으로 마셔볼 수 있었다는 점에 의의를 두었습니다. 바의 직원들이 아주 친절했고, 좋은 가격에 좋은 위스키 라인업을 가지고 있으니 런던 여행 시에 한 번쯤은 방문해보시는 걸 추천드립니다."}]'::jsonb, 'published', '2024-06-28T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'london-soma', 'bar', '소마', '"Bar SOMA"는 런던 소호에 위치한 바로, 2021년에 오픈한 아직 어린 바입니다. 저는 국내의 "뽐(Pomme)"이라는 바의 현재 매니저님에게 추천을 받아서 방문하게 되었습니다.', '/articles/london-soma/00.webp',
  'https://blog.naver.com/shakinglikebartender/223493239728', false,
  '[{"kind":"paragraph","text":"\"Bar SOMA\"는 런던 소호에 위치한 바로, 2021년에 오픈한 아직 어린 바입니다. 저는 국내의 \"뽐(Pomme)\"이라는 바의 현재 매니저님에게 추천을 받아서 방문하게 되었습니다."},{"kind":"paragraph","text":"\"SOMA\"란 ''증류 및 추출''을 의미하는 베다 산스크리트어 단어이며, 이 바에서는 클래식 칵테일을 재해석하면서 인도 등지의 재료를 사용하는 것을 주로 한다고 합니다."},{"kind":"paragraph","text":"\"SOMA\"는 스피크이지(Speakeasy)가 컨셉인 바로, 처음 간다면 저처럼 약간 헤멜 수 있습니다. 먼저 아래 사진과 같은 간판을 찾으시면 그 옆에 가드가 앉아 있을텐데, 그 가드에게 말을 걸면 안내를 해줍니다. 그 후 어두운 공간에서 계단을 한 층 내려가 입장하게 됩니다."},{"kind":"figure","src":"/articles/london-soma/00.webp","width":600,"height":799,"caption":"SOMA의 간판"},{"kind":"paragraph","text":"처음 방문할 때는 저처럼 간판만 보고 옆 가게로 착각하고 들어가려는 일이 발생할 수 있으니, 문 앞의 가드분에게 말을 걸어주세요. 저 같은 경우에는 간판 잘 찾고 옆 가게로 가려는 걸 가드분이 말을 걸어주셔서 제대로 들어갔습니다 ㅎㅎㅎ"},{"kind":"figure","src":"/articles/london-soma/01.webp","width":600,"height":1066},{"kind":"figure","src":"/articles/london-soma/02.webp","width":600,"height":1066},{"kind":"figure","src":"/articles/london-soma/03.webp","width":600,"height":1066},{"kind":"paragraph","text":"\"SOMA\"의 주요 메뉴를 살펴보면 칵테일의 주요 캐릭터가 큰 글자로 되어있고, 그 밑으로는 재료가, 그 위로 원형이 되는 클래식 칵테일이 괄호로 표기되어 있습니다.  일단 칵테일의 캐릭터를 크게 써놓으니 주문하기에 어렵지가 않다는 점은 매우 좋은 점이라 생각됩니다."},{"kind":"figure","src":"/articles/london-soma/04.webp","width":600,"height":600},{"kind":"figure","src":"/articles/london-soma/05.webp","width":600,"height":600},{"kind":"paragraph","text":"첫 잔으로는 저와 친구는 ''캐슈(CASHEW)''와 ''리프(LEAF)''를 주문했습니다."},{"kind":"paragraph","text":"''캐슈''는 네그로니의 변형으로, 보타니컬한 진 대신에 어시(earthy)하고 스모키한 메즈칼을 기주로 하며, 구운 캐슈넛과 커피 열매의 과육인 카스카라(Cascara)를 사용해서 만들어진 버무스를 사용한 것을 특징으로 합니다. 스모키한 네그로니에 약간의 너티함이 추가된 듯한 느낌이었습니다."},{"kind":"paragraph","text":"''리프''는 김렛의 변형으로 오리엔탈 스파이스의 캐릭터가 특징인 오피르(Opihr) 진을 기주로, 라임 잎과 커리 잎을 사용하는, 향신료의 느낌이 가득한 조합의 김렛을 만들어냅니다."},{"kind":"paragraph","text":"보통의 김렛과는 다르게 투명화를 거친 것으로 산미는 크게 느껴지지 않고, 라임 오일(?)을 그 위에 떨어뜨린 식으로 김렛의 캐릭터를 잃지 않도록 하는 느낌이었습니다."},{"kind":"figure","src":"/articles/london-soma/06.webp","width":966,"height":966},{"kind":"figure","src":"/articles/london-soma/07.webp","width":966,"height":966},{"kind":"paragraph","text":"다음잔으로는 ''코코넛(COCONUT)''과 ''커피(COFFEE)''를 주문했는데, ''코코넛''은 비주얼적으로 꽤 예뻐서인지 꽤 많은 사람들이 주문하는 메뉴였습니다."},{"kind":"paragraph","text":"''코코넛''에는 코코넛 요거트, 시트러스 블러썸(아마도 시트러스 오일 또는 추출물), 핑크 자몽 소다가 들어가는데 재료의 조합이 꽤 직관적으로 느껴지는 맛이었습니다."},{"kind":"paragraph","text":"''커피''는 카카오 럼과 VS급 꼬냑을 기주로, 다양한 향신료가 들어가는 탄다이(인도의 음료)에 버터스카치가 들어가는 칵테일인데, 이게 맛이 그냥 스카치 캔디 커피맛과 완~~~전히 똑같습니다."},{"kind":"paragraph","text":"버터스카치와 커피의 캐릭터가 지배적이었는데, 향신료의 느낌이 거의 느껴지지 않았다는 점이 아쉬웠습니다. 이 뒤로 인도의 진을 쓴 진토닉과 위스키 사워를 시켰는데, 굳이 리뷰할 정도의 것은 아니었네요."},{"kind":"paragraph","text":"전체적으로 ''바 소마''는 믹솔로지(Mixology)적인 성격이 강한데, 차별점이라 한다면 클래식 칵테일에서 영감을 받지만 그 구조를 완전히 따라가지는 않는다는 점과 인도의 향신료를 적극적으로 사용한다는 점을 들 수 있습니다."},{"kind":"paragraph","text":"평소에 국내에서 접하기 어려운 재료들, 특히 향신료나 인도의 진 등을 경험할 수 있다는 점에서 아주 좋았습니다."}]'::jsonb, 'published', '2024-06-27T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'london-tayer-elementary', 'bar', '테이어 + 엘리멘트리', '"Tayēr + Elementary"는 영국 런던에 위치한 바로, 2019년에 주류 및 바텐딩 업계에서 다양한 상을 수상하고 많은 존경을 받는 알렉스 크라테나(Alex Kratena)와 모니카 버그(Monica Berg)에 의해 오픈된 바입니다.', '/articles/london-tayer-elementary/00.webp',
  'https://blog.naver.com/shakinglikebartender/223489497394', false,
  '[{"kind":"paragraph","text":"\"Tayēr + Elementary\"는 영국 런던에 위치한 바로, 2019년에 주류 및 바텐딩 업계에서 다양한 상을 수상하고 많은 존경을 받는 알렉스 크라테나(Alex Kratena)와 모니카 버그(Monica Berg)에 의해 오픈된 바입니다."},{"kind":"paragraph","text":"오픈한 직후 2020년부터 2023년까지 The World''s Best Bars(월드 베스트 바)에 연속으로 TOP10에 위치했으며, 2021년과 2022년 연속으로 2위를 차지하기도 할 정도로 인정을 받고 있는 바 입니다."},{"kind":"paragraph","text":"이름의 ''+''가 눈에 띄는데, 사실 이 바는 ''Tayēr''와 ''Elementary'', 이 두 공간으로 각각 테마에 의해 나뉘어져 있습니다."},{"kind":"paragraph","text":"바에 들어서면 먼저 ''Elementary'' 공간에 들어가게 되는데, 이 공간에서는 주로 RTD에 가까울 정도의 미리 만들어진(Pre-batched) 칵테일, 맥주, 와인 등을 마셔볼 수 있습니다."},{"kind":"paragraph","text":"그 너머의 ''Tayēr'' 공간에서는 이 바의 진면목을 볼 수 있는데, 아래 사진처럼 아예 메뉴 자체도 다르고, 메이킹을 하는 칵테일을 주로 서브합니다."},{"kind":"paragraph","text":"''Tayēr'' 공간을 이용하기 위해서는 사전에 예약을 하시거나, 방문 시에 직원 분에게 꼭 ''Tayēr'' 공간을 방문하고 싶다고 말씀해주셔야 합니다(특히 외국 바나 주류샵 등은 얘기해야 안내를 하는 경우가 왕왕 있어 꼭 문의를 하는 편이 좋습니다)."},{"kind":"figure","src":"/articles/london-tayer-elementary/00.webp","width":600,"height":600},{"kind":"paragraph","text":"Elementary"},{"kind":"figure","src":"/articles/london-tayer-elementary/01.webp","width":600,"height":600},{"kind":"paragraph","text":"첫 잔으로 저와 제 친구는 각각 \"페니실린(Penicilin)\"과 \"라즈베리 캄파리 소다(Raspberry Campari Soda)\"를 주문했습니다. 페니실린은 미리 투명화를 한 상태로 서브하였고, 라즈베리 캄파리 소다는 라즈베리를 캄파리에 인퓨징해서 서브한 것으로 보입니다."},{"kind":"paragraph","text":"페니실린은 아몬티야도 쉐리의 캐릭터를 더했지만 투명화한 것 빼고는 그렇게 특별하다는 생각은 별로 들지 않았고, 오히려 기존의 강렬함이 없이 너무 점잖은 느낌이 들었습니다. 라즈베리 캄파리 소다는 기존의 캄파리 소다의 쌉쌀달달함에 상큼함을 더해 리프레시하기에 아주 좋은 음료였습니다."},{"kind":"figure","src":"/articles/london-tayer-elementary/02.webp","width":600,"height":600},{"kind":"paragraph","text":"두 번째 잔으로는 \"한 입 마티니(One Sip Martini)\"를 주문했는데, 꽤나 귀여운 모습으로 이름에 걸맞는 비주얼의 마티니가 나왔습니다. 서브를 해주면서 이름대로 원샷이 권장사항이지만, 꼭 그러지 않아도 된다는 설명은 덤."},{"kind":"paragraph","text":"맛 자체는 마티니 치고는 꽤 도수감이 적게 느껴져 마일드했고, 피노 쉐리의 캐릭터가 많이 느껴졌는데, 원래 이렇게 작은 사이즈로 나오는 마티니들은 가볍게 마실 수 있도록 만들어주는 경우가 많기 때문에 고개가 끄덕여지는 맛이었습니다."},{"kind":"paragraph","text":"Tayēr"},{"kind":"figure","src":"/articles/london-tayer-elementary/03.webp","width":600,"height":600},{"kind":"paragraph","text":"저는 바에 방문한 후에야 공간이 나뉘어져 있는 걸 알고, 직원 분께 문의를 하였고, 운 좋게도 20~30분 정도가 지나 ''Tayēr'' 공간에 입장할 수 있었습니다."},{"kind":"paragraph","text":"앞서 말했듯이, 문의하지 않으면 먼저 물어봐주지 않으니 꼭꼭 ''Tayēr'' 공간을 이용할 수 있는지 문의하시고 ''Tayēr'' 공간을 이용하시는 걸 추천드립니다. 이렇게까지 얘기하는 이유는 ''Tayēr''가 ''Elementary''와 메뉴 자체가 다르고, 좀 더 메이킹하는 것을 볼 수 있어서 그렇습니다."},{"kind":"figure","src":"/articles/london-tayer-elementary/04.webp","width":600,"height":600},{"kind":"figure","src":"/articles/london-tayer-elementary/05.webp","width":600,"height":600},{"kind":"paragraph","text":"''Tayēr''의 칵테일 메뉴는 매일 바뀐다고 하며, 이름이 아닌 재료만이 적혀 있는 것이 큰 특징입니다."},{"kind":"paragraph","text":"이 날 제 친구가 주문한 칵테일(첫 번째와 두 번째 사진)이 친구의 주문을 마지막으로 매진되었는데, 왜 매진되었을지 알 정도로 정말 맛있는 한 잔이었습니다. 럼과 피트 위스키의 조합, 마티니스러운 구성, 구운 파인애플과 버터라는 독창적인 재료까지 ''Tayēr''의 성격을 아주 잘 보여주는 칵테일이었습니다."},{"kind":"figure","src":"/articles/london-tayer-elementary/06.webp","width":600,"height":600},{"kind":"figure","src":"/articles/london-tayer-elementary/07.webp","width":600,"height":600},{"kind":"paragraph","text":"그 뒤로도 두 잔씩을 더 시켰는데, 메뉴에 이름이 정해져 있는 게 아니라서 리뷰로 풀어내기가 어려운 데다가, 사실 이후로는 개인적인 입맛에서 인상적인 느낌을 받은 칵테일은 없었기도 했습니다. 다만, 단순한 칵테일 구조를 재밌는 재료와 조합 등을 통해 매력적인 칵테일을 만들어내는 것은 충분한 재미요소였습니다."},{"kind":"paragraph","text":"전체적으로 \"Tayēr + Elementary\"는 많은 서양의 바들이 그렇듯 믹솔로지(Mixology)스러운 성향이 강하며, 이런 점에 부담스러움을 느낄 분들도 있을 거라 생각합니다."},{"kind":"paragraph","text":"그렇지만 창의적인 재료의 선택, 조합, 기법, 국내에서는 구할 수 없는 주류의 사용 등등 다양한 부분에 있어서 충분히 즐길 점이 많다고 생각됩니다. 또한 직원분들도 매우 친절하니 망설이지 말고 물어보시고, 칵테일 추천도 받아보는 것을 추천드립니다."},{"kind":"paragraph","text":"좀 더 많은 칵테일 정보는"}]'::jsonb, 'published', '2024-06-24T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'naked-and-famous', 'cocktail', '네이키드 앤 페이머스', '네이키드&페이머스(Naked&Famous)는 2011년 현대의 모던 클래식 칵테일에 많은 영향을 준 바인 뉴욕의 데스앤코(Death&Co)에서 호아킨 시모(Joaquin Simo)에 의해서 만들어졌습니다.', '/articles/naked-and-famous/00.webp',
  'https://blog.naver.com/shakinglikebartender/223459736206', false,
  '[{"kind":"figure","src":"/articles/naked-and-famous/00.webp","width":966,"height":966},{"kind":"paragraph","text":"About the Drink"},{"kind":"paragraph","text":"네이키드&페이머스(Naked&Famous)는 2011년 현대의 모던 클래식 칵테일에 많은 영향을 준 바인 뉴욕의 데스앤코(Death&Co)에서 호아킨 시모(Joaquin Simo)에 의해서 만들어졌습니다."},{"kind":"paragraph","text":"컬트적인 인기를 끌고 있는 ‘라스트 워드(Last Word)’라는 칵테일을 좋아하는 분들이라면 이 칵테일의 레시피에 아주 익숙할 텐데, 샤르트뢰즈(옐로지만)를 포함한 4가지 재료가 동일하게 22.5ml씩 들어가기 때문일 겁니다."},{"kind":"paragraph","text":"실제로 호아킨 시모는 ‘라스트 워드(Last Word)’와 ‘페이퍼 플레인(Paper Plane)’이라는 칵테일을 매시업해서 이 칵테일을 만들어 냈습니다(본인이 두 칵테일의 사생아 격이다라고 말했으니)."},{"kind":"paragraph","text":"이 칵테일에서는 라스트 워드의 ‘그린 샤르트뢰즈’ 대신 좀 더 달고 도수가 낮은 ‘옐로우 샤르트뢰즈’를 사용하고, ‘아페롤’을 통해 시트러스와 달큰쌉쌀한 캐릭터를 더해줍니다."},{"kind":"paragraph","text":"여기에 ‘메즈칼’이라는 ‘데낄라’의 친척격인 아가베 증류주가 들어가는데, ‘진’이나 ‘버번’보다는 단순하지만 아가베 특유의 달콤함에 더해 메즈칼 특유의 어씨(earthy)함과 스모키함으로 칵테일에 재미를 더해줍니다."},{"kind":"paragraph","text":"최근 몇 년간 서양의 바 신을 중심으로 메즈칼 칵테일이 범람하였는데, 그 와중에도 유달리 유명세를 탄 칵테일 중 하나이며, 모던 클래식 칵테일에서 당당하게 한자리를 차지하고 있습니다."},{"kind":"figure","src":"/articles/naked-and-famous/01.webp","width":966,"height":725},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"22.5ml 메즈칼 (Mezcal)"},{"kind":"paragraph","text":"22.5ml 옐로우 샤르트뢰즈 (Yellow Chartreuse)"},{"kind":"paragraph","text":"22.5ml 아페롤 (Aperol)"},{"kind":"paragraph","text":"22.5ml 라임 즙 (Lime Juice)"},{"kind":"figure","src":"/articles/naked-and-famous/02.webp","width":966,"height":1287},{"kind":"heading","text":"How to Mix"},{"kind":"paragraph","text":"1. 모든 재료를 셰이커 안에 넣어줍니다."},{"kind":"paragraph","text":"2. 셰이커에 얼음을 넣고 셰이킹 해줍니다."},{"kind":"paragraph","text":"3. 셰이킹 후 잔에 따라줍니다."},{"kind":"paragraph","text":"네이키드&페이머스의 가장 큰 매력은 역시 그 재료의 조합이라 할 수 있습니다. 레시피의 구조 자체는 단순하나, 메즈칼이라는 아직 우리나라에서 익숙하지 않은 재료를 통해 예상치 못한 재미를 줍니다."},{"kind":"paragraph","text":"시트러스+달달함+스모키함+허브의 모든 재료가 자기주장이 강하지만 캐릭터 중 어느 하나가 부담스럽게 튀지 않고 복합적으로 나는데, 꽤 복잡하고 오묘한 맛입니다."},{"kind":"paragraph","text":"메즈칼은 아가베(Agave)를 주원료로 하는 증류주로, 데깔라와 일종의 친척 관계에 있다고 할 수 있습니다. 다만, 주원료인 아가베의 종류·지역·생산방법 등에서 많은 차이가 나며, 그로 인해 메즈칼은 어씨(earthy)함과 스모키함이라는 유니크한 캐릭터를 가지게 됩니다."},{"kind":"paragraph","text":"메즈칼은 아직까지 우리나라에서 익숙하지 않은 증류주이지만, 서양권에서 발표하는 주류 트렌드에서 몇 년간 메즈칼(또는 데낄라를 포함하는 아가베 증류주)이 많은 인기를 끌고 유행할 것이라고 전망해왔습니다."},{"kind":"paragraph","text":"실제로 최근 십여 년 사이에 서양에서 많은 인기를 얻으면서 많은 메즈칼 칵테일이 만들어졌으며, 다양한 메즈칼 제품이 만들어졌습니다."},{"kind":"paragraph","text":"최근 2~3년 사이에 국내에서 좋은 퀄리티의 메즈칼이 많이 수입되었고, 바에서도 종종 찾을 수 있게 되었으니, 바에서 메즈칼이 보인다면 주저하지 마시고 메즈칼을 이용한 칵테일에 도전해 보시는 걸 추천드립니다."},{"kind":"paragraph","text":"좀 더 많은 칵테일 정보는"}]'::jsonb, 'published', '2024-05-27T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'yukiguni', 'cocktail', '설국', '설국은 일본에서 만들어진 일본의 스탠다드 칵테일(클래식 칵테일)로, 바텐더 이야마 케이이치에 의해 만들어졌습니다.', '/articles/yukiguni/00.webp',
  'https://blog.naver.com/shakinglikebartender/223348256651', false,
  '[{"kind":"figure","src":"/articles/yukiguni/00.webp","width":966,"height":725},{"kind":"paragraph","text":"About the Drink"},{"kind":"paragraph","text":"설국은 일본에서 만들어진 일본의 스탠다드 칵테일(클래식 칵테일)로, 바텐더 이야마 케이이치에 의해 만들어졌습니다. 이야마 옹은 1958년 산토리(당시에는 코토부키야)가 주최하는 제3회 홈 칵테일 콩쿨에서 설국으로 우승(1959년 수상)을 하였고, 이후 칵테일이 유명세를 타면서 일본의 스탠다드 칵테일로 자리 잡았다고 합니다."},{"kind":"paragraph","text":"이야마 옹은 1955년 본인의 고향인 야마가타현 사카타시 바&카페인 ‘쾰른’을 개업했으며, 90이 넘은 나이에도 바에 서서 설국을 만들었다고 하며, 2021년 5월 10일 오래된 바텐더 생활을 마치고 고인이 되었다고 합니다."},{"kind":"paragraph","text":"현재에는 아들이 자리를 이어받아 운영하고 있는 것으로 보이는데, 구글 맵에는 폐업이라 되어있으나 잘못된 정보인 것 같고, 아직까지 ‘쾰른’에서는 유키구니가 만들어지고 있습니다."},{"kind":"paragraph","text":"2018년에는 이 칵테일에 대한 영화 <YUKIGUNI>가 일본에서 만들어졌을 정도로 꽤나 인기 있는 칵테일이었지 않았을까 생각해봅니다."},{"kind":"paragraph","text":"잔의 림에 장식된 설탕이 눈을 형상화하며, 녹색의 체리는 겨울의 눈 밑에서 봄을 힘차게 기다리고 있는 녹색(생명력?)을 형상화한 것이라 하며, 꽤나 직관적이면서도 이름이 걸맞는 칵테일입니다."},{"kind":"figure","src":"/articles/yukiguni/01.webp","width":966,"height":725},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"40ml 보드카"},{"kind":"paragraph","text":"10ml 화이트 큐라소"},{"kind":"paragraph","text":"10ml 라임 코디얼"},{"kind":"paragraph","text":"가니쉬: 설탕 리밍 & 녹색 체리"},{"kind":"figure","src":"/articles/yukiguni/02.webp","width":966,"height":725,"caption":"설탕을 리밍할 때는 잔 안으로 설탕이 들어가지 않게 하자"},{"kind":"paragraph","text":"How to Mix?"},{"kind":"paragraph","text":"1. 잔 바깥 부분에 설탕을 묻히고,"},{"kind":"paragraph","text":"녹색 체리를 잔 안에 떨어뜨려줍니다."},{"kind":"paragraph","text":"*잔 안쪽으로 설탕이 묻지 않도록 주의할 것!"},{"kind":"paragraph","text":"2. 가니쉬 이외의 재료를 쉐이커에 넣어줍니다."},{"kind":"paragraph","text":"3. 쉐이킹 후 잔에 따라줍니다."},{"kind":"figure","src":"/articles/yukiguni/03.webp","width":966,"height":966},{"kind":"paragraph","text":"먼저 재료에 있어서 생라임즙을 사용할지, 라임 코디얼을 사용할지 헷갈릴 수 있습니다. 몇몇 레시피에서도 생라임즙을 사용하는 경우가 있기도 합니다."},{"kind":"paragraph","text":"다만, 설국이 만들어진 1958년 당시에는 일본에서 라임을 구하기가 어려웠을테니 라임 코디얼을 사용했지 않을까라는 추론이 가능합니다."},{"kind":"paragraph","text":"무엇보다 원작자인 이야마 옹이 메이킹하는 영상을 보면 산토리의 라임 코디얼을 사용하고 있는 것을 볼 수 있으며, 참고로 화이트 큐라소, 보드카 모두 산토리의 제품을 사용하는 것을 보아 오리지널은 라임 코디얼을 사용한 것이 아닐까 어느 정도 확신할 수 있습니다. 설탕의 경우는 상백당을 믹서기에 갈아서 사용한다는 것 같습니다."},{"kind":"paragraph","text":"다만, 오리지널을 마셔보고 본인의 입맛에 맞게 변형하는 것도 하나의 재미이니 오리지널부터 마셔보시는 걸 추천드립니다."},{"kind":"paragraph","text":"도수가 꽤나 높지만 알콜감이 그렇게 심하지는 않으며, 단맛과 신맛이 은근히 밸런스 좋게 느껴진 점이 꽤 마음에 들었습니다. 생즙을 사용하지 않아 어딘가 올드한 정취가 들기도 하는 칵테일이기도 합니다."},{"kind":"paragraph","text":"좀 더 많은 칵테일 정보는"}]'::jsonb, 'published', '2024-02-08T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'brandy-crusta', 'cocktail', '브랜디 크러스타', '브랜디 크러스타는 1850년대에 뉴올리언스 지방에서 바텐더로 활동하던 Joseph Santini에 의해 만들어졌으며, 1862년 Jerry Thomas의 저서인 ''Bartender''s Guide''에 처음 기록되었다고 합니다.', '/articles/brandy-crusta/00.webp',
  'https://blog.naver.com/shakinglikebartender/223336279208', false,
  '[{"kind":"figure","src":"/articles/brandy-crusta/00.webp","width":966,"height":966},{"kind":"paragraph","text":"About the Drink"},{"kind":"paragraph","text":"브랜디 크러스타는 1850년대에 뉴올리언스 지방에서 바텐더로 활동하던 Joseph Santini에 의해 만들어졌으며, 1862년 Jerry Thomas의 저서인 ''Bartender''s Guide''에 처음 기록되었다고 합니다. 하지만 크게 인기를 끌지는 못했는지 2000년대 전까지 잊혀져 있다가, ''Imbibe!''의 저자 David Wondrich와 뉴올리언스 지역에서 활동하고 있는 바텐더 Chris Hannah 등의 노력으로 다시 각광을 받기 시작했습니다."},{"kind":"paragraph","text":"이 칵테일이 만들어진 19세기말에서 20세기 초에는 마라스키노 리큐르의 인기에 힘입어 임프루브드 위스키 칵테일(Improved Whiskey Cocktail), 에비에이션(Aviation), 라스트 워드(Last Word) 등 마라스키노 리큐르를 사용한 칵테일들이 많이 등장했는데, 참 이상하게도 이런 칵테일들은 모두 사장될 뻔한 위험을 겪은 친구들(현재 라스트 워드의 컬트적인 인기는 차치하고)이라는 공통점이 있습니다."},{"kind":"paragraph","text":"브랜디 크러스타는 사이드카와의 관계에서 항상 \"브랜디 크러스타가 사이드카의 원형인가\"라는 논쟁을 불러일으킵니다. 브랜디, 레몬즙, 큐라소(또는 트리플섹)이라는 공통적인 재료와 맛의 프로파일 때문이죠. 그러나 사이드카가 처음 만들어졌을 때는 잔에 설탕으로 가니시를 하지도 않았고, 크러스타와 사이드카를 구성하는 시트러스의 양과 설탕의 유무로 인해 \"사이드카의 원형은 데이지 칵테일\"이라는 주장과 대립각을 이루게 됩니다."},{"kind":"paragraph","text":"본래 크러스타는 레몬즙이 조금 들어가는 반면에(제 레시피에는 많이 들어가기는 합니다만....), 사이드카에는 레몬즙이 비교적 많이 들어가고, 사이드카는 당을 오렌지 큐라소(또는 트리플섹)으로 대체했으며, 데이지 칵테일(진 + 큐라소 + 레몬즙 + 약간의 탄산수)의 변형에 좀 더 부합하다는 것입니다. 저는 이런 주장에 기본적으로 동의합니다만, 사이드카와 브랜디 크러스타가 비슷한 프로파일을 가진다는 것 자체는 부정할 수 없는 사실이긴 합니다."},{"kind":"paragraph","text":"따라서 어느 쪽 주장이 꼭 맞냐 보다는 어떤 식으로 본인이 브랜디 크러스타와 사이드카에 접근하려는지에 좀 더 주안점을 주면 될 것 같습니다."},{"kind":"figure","src":"/articles/brandy-crusta/01.webp","width":966,"height":725},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"50ml 꼬냑"},{"kind":"paragraph","text":"10ml 오렌지 큐라소 / 트리플섹"},{"kind":"paragraph","text":"10ml 마라스키노 리큐르"},{"kind":"paragraph","text":"20ml 레몬 즙"},{"kind":"paragraph","text":"5ml 심플 시럽"},{"kind":"paragraph","text":"2dashes 앙고스투라 비터스"},{"kind":"paragraph","text":"가니쉬: 설탕 리밍 & 길다란 레몬 필"},{"kind":"figure","src":"/articles/brandy-crusta/02.webp","width":966,"height":966},{"kind":"paragraph","text":"How to Mix?"},{"kind":"paragraph","text":"1. 잔 바깥 부분에 설탕을 두껍게 묻히고, 긴 레몬 필을 둥글게 말아 림 안쪽에 고정해줍니다."},{"kind":"paragraph","text":"2. 가니쉬 이외의 재료를 모두 쉐이커에 넣어줍니다."},{"kind":"paragraph","text":"3. 쉐이킹 후 잔에 따라줍니다."},{"kind":"figure","src":"/articles/brandy-crusta/03.webp","width":966,"height":966},{"kind":"figure","src":"/articles/brandy-crusta/04.webp","width":966,"height":725},{"kind":"paragraph","text":"브랜디 크러스타는 레시피가 정말 많기 때문에 이것저것 찾아보시고 가장 맛있겠다 싶은 레시피를 사용하시거나, 조정하시는 것을 추천드리며, 꼬냑의 경우는 어느정도 퀄리티가 있는 종류를 사용하시는 걸 추천드립니다. 아무래도 꼬냑의 맛에 따라 칵테일의 맛에 차이가 많이 차이가 나게 됩니다."},{"kind":"paragraph","text":"개인적인 감상으로는 \"사이드카를 좋아하는데, 브랜디 크러스타를 마셔보지 않았다는 것은 죄악\"이라는 생각이 드는 한 잔이었습니다."},{"kind":"paragraph","text":"마실 때에는 가니시한 레몬 필의 한 부분을 잔 아래로 꾹 눌러주신 후에 드시면 됩니다. 전체적으로 꼬냑의 아로마틱함, 룩사르도의 달달한 체리, 그랑 마르니에에서 오는 오렌지, 레몬의 시트러스함이 모두 뭉뜽그러져서 나는 맛이 아주 일품입니다."},{"kind":"paragraph","text":"이전에 올렸던 포스팅에서도 언급했듯이, 저는 마라스키노 리큐르 자체는 그닥 좋아하지는 않습니다만.....에비에이션, 라스트 워드도 그렇고, 이 칵테일도 그렇고 마라스키노 리큐르가 들어간 칵테일은 대부분 맛있게 마신게 참 신기합니다."},{"kind":"paragraph","text":"좀 더 많은 칵테일 정보는"}]'::jsonb, 'published', '2024-01-28T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'greenhorn', 'cocktail', '그린혼', '비주얼에서부터 강렬한 Greenhorn 칵테일은 2022년 미국 텍사스의 휴스턴에 있는 Refuge라는 바에서 바텐더(그리고 오너인) Bobby Heugel에 의해서 만들어졌습니다.', '/articles/greenhorn/00.webp',
  'https://blog.naver.com/shakinglikebartender/223226334602', false,
  '[{"kind":"figure","src":"/articles/greenhorn/00.webp","width":966,"height":723},{"kind":"paragraph","text":"About the Drink"},{"kind":"paragraph","text":"비주얼에서부터 강렬한 Greenhorn 칵테일은 2022년 미국 텍사스의 휴스턴에 있는 Refuge라는 바에서 바텐더(그리고 오너인) Bobby Heugel에 의해서 만들어졌습니다."},{"kind":"paragraph","text":"그는 자신이 가장 좋아하는 맛의 조합인 아가베 증류주와 멜론의 조합에서 영감을 얻어 이 칵테일을 만들었다고 하며, 그 결과 \"네그로니류에서 튀어나온 흥미로운(의역)\" 맛을 내게 되었다고 그는 말합니다."},{"kind":"paragraph","text":"데킬라 + 미도리 + 수즈의 조합은 정말이지 어디서도 보기 힘든 조합이고, 특히 블랑코 데킬라와 미도리는 스터하는 칵테일에서는 더더욱 보기가 힘들죠. 여기에 수즈를 사용한 것을 보면 원작자는 어느정도 화이트 네그로니의 캐릭터에서 영감을 받았을지도 모르겠습니다."},{"kind":"figure","src":"/articles/greenhorn/01.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"37.5ml 블랑코 데킬라 (Blanco Tequila)"},{"kind":"paragraph","text":"30ml 미도리 (Midori)"},{"kind":"paragraph","text":"22.5ml 수즈 (Suze)"},{"kind":"paragraph","text":"가니쉬: 그린 체리"},{"kind":"paragraph","text":"데킬라는 본인이 선호하는 블랑코(=실버, 플라타) 데킬라를 사용하되, 미도리와 수즈는 되도록이면 그대로 사용하시는 걸 추천드립니다."},{"kind":"paragraph","text":"그린 체리 같은 경우는 구하는 데에 꽤 난이도가 있는데, 저 같은 경우에는 예~전에 쿠팡에서 영어로 green cherry, mint cherry로 검색해서 간신히 찾았었습니다. 작성하는 날짜 기준으로 판매 중지가 되어있네요...."},{"kind":"paragraph","text":"다만, 맛에 영향을 주는 가니쉬는 아니니 생략하거나 빨간색의 체리를 사용하셔도 무방합니다."},{"kind":"figure","src":"/articles/greenhorn/02.webp","width":966,"height":725},{"kind":"paragraph","text":"How to Mix?"},{"kind":"paragraph","text":"1. 가니쉬 이외의 재료를 모두 믹싱 글라스에 넣습니다."},{"kind":"paragraph","text":"2. 믹싱글라스에 얼음을 채워주고, 스터합니다."},{"kind":"paragraph","text":"3. 칠링한 칵테일 글라스에 따라주고, 그린 체리를 넣어 가니쉬해줍니다."},{"kind":"figure","src":"/articles/greenhorn/03.webp","width":966,"height":966},{"kind":"paragraph","text":"색깔, 가니쉬, 재료 뭐 하나 빠짐 없이 칵테일 애호가들이라면 흥미가 생길만한 칵테일입니다. 사실 미도리는 그 색과 우리나라에서는 캐주얼한 칵테일에 많이 들어가서 저평가되어 있다고 생각되는데, 이 칵테일은 미도리를 재평가하게 해줄만한 칵테일이라고 생각됩니다. 저에게 또한 미도리에 대한 인상을 바꿔준 칵테일이었습니다."},{"kind":"paragraph","text":"데킬라의 아가베 느낌이 수즈의 맛과 함께 잘 드러나고, 거기에 미도리의 달달한 멜론맛이 약간 추가되는 느낌이었습니다. 수즈로 인해 쌉쌀하기는 하지만 어느 정도 단 느낌이 있습니다. 색과 미도리 때문에 엄청 달 것 같지만 전혀 그맇지 않고, 오히려 저는 단맛보다는 쌉쌀한 맛이 약간 더 잘 느껴졌습니다."},{"kind":"paragraph","text":"참 오묘한 맛이지만 생각보다 맛의 조화 자체는 잘 맞았고, 쌉쌀함과 단맛의 밸런스를 위해 당을 약간 추가해도 좋을 것 같습니다(특히, 아가베 시럽). 술만 들어간데다가 스터하는 칵테일이라 도수감이 좀 쎄게 느껴집니다."},{"kind":"paragraph","text":"개인적으로 입맛에 맞는 칵테일은 아니었지만 유니크한 조합의 칵테일이니 한 번쯤은 마셔보는 걸 추천드립니다."},{"kind":"paragraph","text":"좀 더 많은 칵테일 정보는"}]'::jsonb, 'published', '2023-10-02T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'pelican', 'cocktail', '펠리컨', '펠리컨은 2015년경에 뉴욕 Attaboy라는 바에서 Andrew Rice에 의해 만들어졌습니다.', '/articles/pelican/00.webp',
  'https://blog.naver.com/shakinglikebartender/223128021837', false,
  '[{"kind":"figure","src":"/articles/pelican/00.webp","width":966,"height":773},{"kind":"paragraph","text":"- About the Drink -"},{"kind":"paragraph","text":"펠리컨은 2015년경에 뉴욕 Attaboy라는 바에서 Andrew Rice에 의해 만들어졌습니다. 이 Attaboy라는 바는 현대 칵테일에 아주 큰 영향을 준 바인 Milk & Honey가 처음 있던 자리에 오픈한 바입니다."},{"kind":"paragraph","text":"Attaboy를 오픈한 건 Sam Ross인데, Milk & Honey의 창업자 Sasha Petraske의 제자 중 한 명으로 제자가 스승의 바를 이어 새로운 바를 오픈한 것입니다. Milk & Honey는 사라졌고, Sasha Petraske는 2015년 42세의 나이로 갑작스럽게 세상을 떠났지만, 그가 남긴 유산은 계속 이어지고 있습니다."},{"kind":"figure","src":"/articles/pelican/01.webp","width":966,"height":966},{"kind":"heading","text":"Ingredients"},{"kind":"paragraph","text":"30ml 퍼넷 브랑카(Fernet Branca)"},{"kind":"paragraph","text":"30ml 브랑카 멘타(Branc Menta)"},{"kind":"paragraph","text":"30ml 커피 리큐르(Coffee Liqueur)"},{"kind":"paragraph","text":"생크림"},{"kind":"paragraph","text":"+ 옵션"},{"kind":"paragraph","text":"3 - 5ml 설탕 시럽"},{"kind":"paragraph","text":"초콜릿 비터(Chocolate Bitters) 1 대시"},{"kind":"paragraph","text":"정말 특이하게 퍼넷이 주가 되는 칵테일이며, 레시피만 봤을 때는 정말 괴랄하기 짝이 없는 칵테일입니다."},{"kind":"paragraph","text":"원래 재료 중에 커피 리큐르는 카페 롤리타(Caffe Lolita)가 사용되는데 우리나라에 수입이 되질 않습니다. Educated Barfly의 Leandro DiMonriva는 카페 롤리타에 대한 대안으로 미스터 블랙에 약간의 시럽과 초콜릿 비터를 넣는 것을 추천했는데, 카페 롤리타가 좀 더 달고, 미스터 블랙에는 없는 초콜릿 노트가 있기 때문이라고 합니다."},{"kind":"paragraph","text":"How to Mix?"},{"kind":"paragraph","text":"1. 생크림 이외의 재료를 믹싱 글라스에 넣어줍니다."},{"kind":"paragraph","text":"2. 얼음을 채워주고, 스터를 한 후에 칵테일 글라스(닉앤노라)에 따라줍니다."},{"kind":"paragraph","text":"3. 생크림을 약간 휘핑한 후, 칵테일 위에 플로탕해줍니다."},{"kind":"figure","src":"/articles/pelican/02.webp","width":966,"height":966},{"kind":"paragraph","text":"앞서 말했듯이 레시피 자체는 꽤나 매니악합니다. 꽤 쓰고 허브감이 강렬할 것 같은데, 의외로 생크림이 그런 맛을 꽤 줄여줘서 적당한 허브감과 약간은 강한 민트, 조금의 커피와 초콜릿의 뉘앙스가 납니다. 생크림이 정말 중요한 역할을 하는 게, 생크림이 없이 마시면 허브와 민트의 느낌이 필요 이상으로 느껴집니다. 생크림이 어찌보면 맛의 밸런스를 잡아준다고 볼 수도 있겠네요."},{"kind":"paragraph","text":"여기에 초콜릿의 뉘앙스가 더 나면 개인적으로는 좋을 것 같고, 초코가 가미된 디저트와 먹으면 최고의 시너지를 낼 것 같습니다."},{"kind":"paragraph","text":"칵테일의 외관과 맛이 이전에 소개한 도미니카나와 비슷하다는 생각을 떨칠 수가 없는데, 이 칵테일이 탄생한 Attavoy의 전신이 Milk & Honey이고, 원작자인 Andrew Rice가 Milk & Honey에서 근무했던 Sam Ross의 직원인 셈이니 어찌 보면 거기에서 아이디어를 얻었을지도 모른다는 추측을 조심스럽게 해봅니다."},{"kind":"paragraph","text":"좀 더 많은 칵테일 정보는"}]'::jsonb, 'published', '2023-06-13T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'creme-de-violette', 'cocktail', '제비꽃으로 만든 신비로운 리큐어', '크렘 드 바이올렛(Creme de Violet / Violette)은 첫 눈에도 단번에 눈길을 사로잡을 법한 보랏빛이 아주 매력적인 리큐어입니다.', '/articles/creme-de-violette/00.webp',
  'https://blog.naver.com/shakinglikebartender/222788493896', false,
  '[{"kind":"paragraph","text":"About the Liqueur"},{"kind":"figure","src":"/articles/creme-de-violette/00.webp","width":966,"height":543},{"kind":"paragraph","text":"크렘 드 바이올렛(Creme de Violet / Violette)은 첫 눈에도 단번에 눈길을 사로잡을 법한 보랏빛이 아주 매력적인 리큐어입니다."},{"kind":"paragraph","text":"크렘 드 바이올렛은 그 이름에서도 알 수 있듯이 제비꽃을 이용하여 만들어지며, 주정 또는 브랜디를 베이스로 한다고 합니다."},{"kind":"figure","src":"/articles/creme-de-violette/01.webp","width":966,"height":966,"caption":"비터 트루스 사의 바이올렛 리큐어"},{"kind":"paragraph","text":"크렘 드 바이올렛은 원체 생산량이 적은 술이었는데, 1960년대에 들어서는 거의 자취를 감추다시피 했다고 합니다."},{"kind":"paragraph","text":"다행히도 이후 클래식, 크래프트 칵테일 바람이 불기 시작하면서 다양한 브랜드에서 생산하게 되었으나, 우리나라에서는 여전히 거의 구할 수 없는 리큐르 중 하나입니다."},{"kind":"paragraph","text":"흔히 파르페 아무르(Parfait Amour)라는 리큐어와 혼용되기도 하는데, 두 리큐어는 맛과 향이 전혀 다르니 주의해주세요!!"},{"kind":"figure","src":"/articles/creme-de-violette/02.webp","width":966,"height":966,"caption":"에비에이션"},{"kind":"paragraph","text":"크렘 드 바이올렛을 사용하는 대표적인 칵테일은 에비에이션이 있으니 꼭 한번 기회가 된다면 마셔보는 걸 추천드립니다."},{"kind":"paragraph","text":"2023.02.22 내용 추가"},{"kind":"paragraph","text":"* 저는 크렘 드 바이올렛을 예~전에 바이배럴에서 구매했었습니다."},{"kind":"paragraph","text":"아마 지금은 세찌리쿼에도 있는 걸로 알고 있어요!"},{"kind":"paragraph","text":"더 많은 칵테일 정보는"}]'::jsonb, 'published', '2022-06-25T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'aviation', 'cocktail', '에비에이션, 크렘 드 바이올렛의 진면목', '에비에이션은 1916년 뉴욕 Wallick 호텔의 헤드바텐더였던 Hugo Ensslin의 저서인 "Recipes for Mixed Drinks"에서 처음 등장했다고 합니다.', '/articles/aviation/00.webp',
  'https://blog.naver.com/shakinglikebartender/222788482366', false,
  '[{"kind":"figure","src":"/articles/aviation/00.webp","width":966,"height":966,"caption":"인스타그램 @shakinglikebartender"},{"kind":"paragraph","text":"About the Drink"},{"kind":"paragraph","text":"에비에이션은 1916년 뉴욕 Wallick 호텔의 헤드바텐더였던 Hugo Ensslin의 저서인 \"Recipes for Mixed Drinks\"에서 처음 등장했다고 합니다."},{"kind":"paragraph","text":"에비에이션은 100년이 넘는 시간 동안 역사에서 잊혀지기도 했던, 참 다사다난한 칵테일인데 바로 그 주재료인 크렘 드 바이올렛(Creme de Violet / Violette)때문입니다."},{"kind":"paragraph","text":"이 바이올렛 리큐르는 이름에서도 알 수 있듯이 제비꽃이 주재로인 리큐르로, 애초에 생산량이 많지도 않았는데 급기야 1960년대에는 거의 자취를 감추다시피 했습니다. 다행히도 이후 클래식, 크래프트 칵테일 바람이 불어 다양한 브랜드에서 생산하게 되었으나, 여전히 우리나라에서는 거의 구할 수 없는 리큐르 중 하나입니다."},{"kind":"heading","text":"Ingredients"},{"kind":"figure","src":"/articles/aviation/01.webp","width":966,"height":966},{"kind":"paragraph","text":"에비에이션은 진(60ml)이 베이스가 되는 칵테일로, 크렘 드 바이올렛(7.5ml), 마라스키노 리큐르(6ml), 레몬즙(22.5ml) 그리고 심플 시럽(5ml)이 들어갑니다. 참고로 개인적으로 마라스키노 리큐를를 별로 안좋아해서 비율을 좀 줄였습니다."},{"kind":"paragraph","text":"How to Mix?"},{"kind":"paragraph","text":"1. 모든 재료를 쉐이커 안에 넣어줍니다."},{"kind":"paragraph","text":"2. 쉐이커에 얼음을 채우고, 쉐이킹 해줍니다."},{"kind":"paragraph","text":"3. 칵테일 글라스에 쉐이킹한 칵테일을 따라줍니다."},{"kind":"paragraph","text":"4. 잔에 체리를 하나 퐁당 떨어트려줍니다(옵션)."},{"kind":"figure","src":"/articles/aviation/02.webp","width":966,"height":966},{"kind":"paragraph","text":"비쥬얼만 봐도 바로 이름과 연관을 지을 수 있는 게, 칵테일 색 자체가 하늘색이고, 쉐이킹으로 인해 생긴 약간의 거품층이 구름 같아보입니다."},{"kind":"paragraph","text":"비터트루스의 바이올렛 리큐르 자체가 꽃향이 과하지 않아 사실 그렇게 많이 느껴지지는 않지만, 다른 재료들의 맛을 헤치지 않는 선에서 달달하게 느껴진 것 같습니다. 또한 산뜻하고, 약간 시트러시한 게 요즘 같이 더운 날씨에 마시면 리프레싱할 수 있을 것 같습니다."},{"kind":"paragraph","text":"에비에이션이 맛없다고 하는 글을 꽤 많이 봤는데, 저는 꽤 맛있게 마셨습니다."},{"kind":"paragraph","text":"좀 더 많은 칵테일 정보는"}]'::jsonb, 'published', '2022-06-25T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'champs-elysees', 'cocktail', '눈이 번쩍 떠질만큼 자극적인 샹젤리제 칵테일', '프랑스 파리의 거리와 동명의 이름을 가진 칵테일, 샹젤리제는 1925년 Nina Toye와 Arthur H.', '/articles/champs-elysees/00.webp',
  'https://blog.naver.com/shakinglikebartender/222532101445', false,
  '[{"kind":"paragraph","text":"About the Drink"},{"kind":"paragraph","text":"프랑스 파리의 거리와 동명의 이름을 가진 칵테일, 샹젤리제는 1925년 Nina Toye와 Arthur H. Adair의 저서 \"Drinks-Long and Short\"에서 처음 등장했습니다."},{"kind":"paragraph","text":"이 칵테일은 사이드카(Sidecar)의 변형으로, 오렌지 큐라소(Orange Curaçau) 또는 그랑 마르니에(Grand Marnier)대신 그린 샤르트뢰즈(Green Chartreuse)를 사용한 것입니다. 예상치 못한 조합이기는 하지만 처음 맛을 보시는 순간 눈이 확 떠질만큼 자극적이고 재미있는 경험을 하실 수 있습니다."},{"kind":"paragraph","text":"개인적으로는 샹젤리제 칵테일의 원형격인 사이드카보다 자극적이고 다채롭다고 생각하는데 국내에서는 거의 알려져 있지 않은 것에 놀랐습니다."},{"kind":"paragraph","text":"Ingredients?"},{"kind":"figure","src":"/articles/champs-elysees/00.webp","width":966,"height":966},{"kind":"paragraph","text":"샹젤리제에 들어가는 술은 코냑(60ml)과 허브리큐르인 ''리큐르의 여왕'' 그린 샤르트뢰즈(15ml)이며, 그 외에 레몬 즙(15ml)과 심플 시럽(7.5ml)이 들어갑니다."},{"kind":"paragraph","text":"제가 사용한 피에르 페랑(Pierre Ferrand)는 도수도 45도로 높고, 꽤 화사한 코냑으로 칵테일 용으로 주로 사용하고 있습니다."},{"kind":"paragraph","text":"How to Mix?"},{"kind":"paragraph","text":"1. 모든 재료를 셰이커 안에 넣어줍니다."},{"kind":"paragraph","text":"2. 셰이커에 얼음을 채우고 셰이킹을 해줍니다."},{"kind":"paragraph","text":"3. 칵테일 글라스에 셰이킹한 칵테일을 따라줍니다."},{"kind":"paragraph","text":"4. 레몬 필로 가니시를 해줍니다."},{"kind":"figure","src":"/articles/champs-elysees/01.webp","width":966,"height":966},{"kind":"paragraph","text":"한 모금을 마시자마자 엄청나게 강렬하고 자극적인 맛으로 인해 ''이런 칵테일이 있다고?'' 하며 눈이 번쩍 떠집니다."},{"kind":"paragraph","text":"이 칵테일에 샤르트뢰즈는 15ml만 들어갔는데도 불구하고 60ml 들어간 코냑보다 더욱 빛이 납니다. 샤르트뢰즈의 허브감과 더불어 레몬의 신맛이 눈에 띄는데, 약간의 시럽으로 신맛이 지나치지 않게 밸런스를 잘 이뤄줍니다."},{"kind":"paragraph","text":"코냑, 샤르트뢰즈와 레몬이 만나 민티함이 느껴지는 것 같은 착각이 날 정도로 아주 상쾌한 맛이 납니다. 리프레시가 필요할 때 가장 먼저 찾을 것 같은 칵테일입니다."},{"kind":"paragraph","text":"더 많은 칵테일 정보는"}]'::jsonb, 'published', '2021-10-09T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'talisker-port-ruighe', 'spirits', '탈리스커 포트 리', '스카이(Skye)섬에서 가장 큰 마을이자 항구인', '/articles/talisker-port-ruighe/00.webp',
  'https://blog.naver.com/shakinglikebartender/222525449933', false,
  '[{"kind":"figure","src":"/articles/talisker-port-ruighe/00.webp","width":966,"height":966},{"kind":"heading","text":"About The Whisk(e)y"},{"kind":"paragraph","text":"이 위스키는 탈리스커 디스틸러리가 있는"},{"kind":"paragraph","text":"스카이(Skye)섬에서 가장 큰 마을이자 항구인"},{"kind":"paragraph","text":"포트리(Portree)의 이름에서 따왔다고 합니다."},{"kind":"paragraph","text":"다만 스펠링이 다른데, 이는 게일어로 발음상 포트 리가 된다고 합니다."},{"kind":"paragraph","text":"이 위스키는 포트 캐스크에서 마지막으로 잠시 숙성되었는데"},{"kind":"paragraph","text":"위스키의 이름인 포트 리와 라임을 잘 맞췄다는 게 재미있는 점이고,"},{"kind":"paragraph","text":"아마 디스틸러리에서 작명을 할 때 이를 감안한 것 같습니다."},{"kind":"paragraph","text":"2013년 탈리스커의 정규 라인으로서 릴리즈되었지만"},{"kind":"paragraph","text":"국내에 들어온 지는 오래되지 않은 것 같습니다."},{"kind":"figure","src":"/articles/talisker-port-ruighe/01.webp","width":966,"height":966},{"kind":"heading","text":"Nose"},{"kind":"paragraph","text":"탈리스커의 향이 아주 부드럽게 나며, 그 너머로 과실향이 납니다."},{"kind":"paragraph","text":"탈리스커 10년은 알콜 향이 조금 튀는 반면에,"},{"kind":"paragraph","text":"탈리스커 포트 리는 전혀 그런 향이 없고 아주 점잖습니다."},{"kind":"paragraph","text":"탈리스커 라인 중에서는 가장 점잖고 밸런스가 잡힌 향을 가지고 있지 않을까 생각됩니다."},{"kind":"heading","text":"Palate"},{"kind":"paragraph","text":"탈리스커의 맛을 잃지 않으나 훨씬 부드럽고 프루티합니다."},{"kind":"paragraph","text":"개인적으로 탈리스커 10년보다 짠맛이 더 잘 느껴지는 것 같은데"},{"kind":"paragraph","text":"거의 소금을 혀에 직접 대는 정도의 짠맛이 느껴질 정도였습니다."},{"kind":"paragraph","text":"처음 오픈 했을 때는 잘 몰랐었는데,"},{"kind":"paragraph","text":"에어링이 진횅된 이후로는 달달한 과실과 은은한 꿀의 맛이 나기도 합니다."},{"kind":"heading","text":"Finish"},{"kind":"paragraph","text":"맛에서 느껴진 것과 거의 비슷한 향이 피니쉬에도 이어집니다."},{"kind":"paragraph","text":"탈리스커 특유의 피트향이 나며, 여기에 포트 캐스크의 캐릭터가 약간 더해지면서"},{"kind":"paragraph","text":"아주 둥글둥글한 피니쉬를 만들어냅니다."},{"kind":"paragraph","text":"인스타그램"}]'::jsonb, 'published', '2021-10-03T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'dominicana', 'cocktail', '완벽한 디저트 칵테일, 도미니카나', '도미니카나는 전설적인 바텐더 사샤 페트라스케(Sasha Petraske)가 자신의 바 Milk & Honey에서 2011년 처음 만든 시그니처 칵테일입니다.', '/articles/dominicana/00.webp',
  'https://blog.naver.com/shakinglikebartender/222522307570', false,
  '[{"kind":"paragraph","text":"About the Drink"},{"kind":"paragraph","text":"도미니카나는 전설적인 바텐더 사샤 페트라스케(Sasha Petraske)가 자신의 바 Milk & Honey에서 2011년 처음 만든 시그니처 칵테일입니다. 얼핏보면 화이트 러시안(White Russian)의 변형처럼 보이기도 하는 이 칵테일은 화이트 러시안보다 훨씬 풍부한 맛을 내며, 럼과 커피의 조화를 잘 엿볼 수 있습니다."},{"kind":"paragraph","text":"원래는 도미니카 럼을 사용하지만 국내에서 고숙성의 퀄리티가 좋은 도미니카 럼을 구하기가 어려워 개인 취향에 맞는 에이지드 럼을 사용해주시면 될 것 같습니다."},{"kind":"paragraph","text":"Ingredients?"},{"kind":"figure","src":"/articles/dominicana/00.webp","width":966,"height":966},{"kind":"paragraph","text":"도미니카나에는 에이지드 럼과 커피 리큐어 그리고 생크림이 들어갑니다."},{"kind":"paragraph","text":"에이지드 럼과 커피 리큐어는 본인의 취향에 맞춰 사용하시면 됩니다. 개인적으로 커피 리큐어는 미스터 블랙을 가장 좋아하는데, 디플로마티코 리제르바 익스클루시바의 초콜렛과 설탕의 깊은 풍미가 미스터 블랙과 잘 어울릴 것 같아 이 조합을 사용하였습니다."},{"kind":"paragraph","text":"How to Mix?"},{"kind":"paragraph","text":"1. 에이지드 럼과 커피 리큐르를 45ml씩 믹싱글라스에 넣습니다."},{"kind":"paragraph","text":"2. 믹싱글라스를 얼음으로 채워주고 스터해줍니다."},{"kind":"paragraph","text":"3. 차갑게 해놓은 칵테일 글라스에 스터한 것을 따라줍니다."},{"kind":"paragraph","text":"4. 생크림을 살짝 흔들어 줍니다."},{"kind":"paragraph","text":"5.흔든 생크림을 조심스럽게 플로팅해줍니다."},{"kind":"figure","src":"/articles/dominicana/01.webp","width":966,"height":966},{"kind":"paragraph","text":"술과 플로팅된 술은 완벽하게 나뉘어져 있어야 하는데, 플로팅 전에 생크림을 살짝 흔들어주는 것이 팁입니다."},{"kind":"paragraph","text":"입에 대자마자 부들부들한 생크림의 감촉이 느껴지고, 생크림과 함께 럼과 커피 리큐르를 섞는 것이 입 안으로 들어오는데 깊은 풍미와 달달한 맛이 나는 크리미한 커피를 마시는 것 같습니다."},{"kind":"paragraph","text":"완벽한 디저트 칵테일로 달달한 칵테일을 찾으시는 분들에게 추천드립니다."},{"kind":"paragraph","text":"더 많은 칵테일 정보는"}]'::jsonb, 'published', '2021-09-30T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'last-word', 'cocktail', '금주법 시대의 칵테일, 라스트 워드', '라스트 워드는 금주법 이전 시대에 만들어진 칵테일로, Detroit Athletic Club의 잡지 1916년 7-8월호에 첨부된 칵테일 메뉴판에 단순히 레시피 없이 그 이름만 기록된 것이 가장 최초의 기록이라고 합니다.', '/articles/last-word/00.webp',
  'https://blog.naver.com/shakinglikebartender/222517500244', false,
  '[{"kind":"paragraph","text":"About the Drink"},{"kind":"paragraph","text":"라스트 워드는 금주법 이전 시대에 만들어진 칵테일로, Detroit Athletic Club의 잡지 1916년 7-8월호에 첨부된 칵테일 메뉴판에 단순히 레시피 없이 그 이름만 기록된 것이 가장 최초의 기록이라고 합니다."},{"kind":"paragraph","text":"이후 1951년 Ted Saucier의 칵테일 저서인 ''Bottoms Up!''에서 그 레시피와 Detroit Athletic Club에 얽힌 간단한 역사에 대해 기록되었습니다."},{"kind":"paragraph","text":"처음 알려진 레시피는 모든 재료가 동일한 비율로 들어간 것이었지만 시간이 지나면서 다른 비율의 레시피도 나오게됐으며, 다양한 배리에이션(변형)들이 등장하게 되었습니다."},{"kind":"paragraph","text":"Ingredients?"},{"kind":"figure","src":"/articles/last-word/00.webp","width":966,"height":966},{"kind":"paragraph","text":"라스트 워드에 들어가는 재료는 마라스키노 리큐르, 그린 샤트르뢰즈, 진, 라임즙이며 모든 재료를 동일한 비율로 넣어줍니다."},{"kind":"paragraph","text":"룩사르도 마라스키노는 체리 리큐르로 아주 드라이하며, 샤르트뢰즈는 ''리큐르의 여왕''이라는 별명을 가진 허브 리큐르입니다. 진은 여러분이 선호하는 진을 사용해주세요."},{"kind":"paragraph","text":"How to Mix?"},{"kind":"paragraph","text":"1. 모든 재료를 22.5ml씩 셰이커 안에 넣어줍니다."},{"kind":"paragraph","text":"2. 셰이커에 얼음을 채우고 셰이킹을 해줍니다."},{"kind":"paragraph","text":"3. 칵테일 글라스에 셰이킹한 칵테일을 따라줍니다."},{"kind":"paragraph","text":"4. 마라스키노 체리를 넣어서 가니시를 해줍니다."},{"kind":"figure","src":"/articles/last-word/01.webp","width":966,"height":966,"caption":"완성된 라스트 워드 (Last Word)"},{"kind":"paragraph","text":"만들어진 라스트 워드는 그린 샤르트뢰즈와 라임즙으로 인해 녹색을 띄게 됩니다."},{"kind":"paragraph","text":"라스트 워드에 대해서 얘기할 때 빠지지 않는 것이 ''밸런스''입니다. 샤르트뢰즈의 허브감, 마라스키노의 드라이함, 라임의 시트러시함, 진의 복잡함이 모두 일체감 있게 잘 느껴집니다."},{"kind":"paragraph","text":"재미있는 점은 이 칵테일에 들어가는 세 가지 술이 모두 자기주장이 아주 강하고, 시럽이 들어가지 않는데도 불구하고 꽤나 완벽한 밸런스를 이룬다는 점입니다."},{"kind":"paragraph","text":"더 많은 칵테일에 관한 정보는"}]'::jsonb, 'published', '2021-09-26T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'garibaldi', 'cocktail', '캄파리-오렌지 말고 가리발디', '캄파리와 가장 잘 어울리는 조합은 뭐니뭐니해도 오렌지입니다.', '/articles/garibaldi/00.webp',
  'https://blog.naver.com/shakinglikebartender/222517436206', false,
  '[{"kind":"paragraph","text":"캄파리는 이탈리아의 쌉쌀-달달한 리큐르로,"},{"kind":"paragraph","text":"다양한 칵테일에 이용되고 있으며"},{"kind":"paragraph","text":"전세계에서 큰 사랑을 받고 있습니다."},{"kind":"paragraph","text":"캄파리와 가장 잘 어울리는 조합은 뭐니뭐니해도 오렌지입니다."},{"kind":"paragraph","text":"캄파리 자체에서도 오렌지의 단 맛이 나 좋은 조합을 이루며,"},{"kind":"paragraph","text":"캄파리-오렌지는 캄파리의 쓴 맛을 줄이고 오렌지즙의 단 맛을 통해"},{"kind":"paragraph","text":"캄파리를 부담되지 않고 간편하게 즐길 수 있는 칵테일 중 하나입니다."},{"kind":"paragraph","text":"가리발디는 이 캄파리-오렌지를"},{"kind":"paragraph","text":"좀 더 재미있고 부드럽게 즐길 수 있는 칵테일입니다."},{"kind":"paragraph","text":"About The Drink"},{"kind":"paragraph","text":"가리발디는 이탈리아 통일 영웅인데"},{"kind":"paragraph","text":"왜 칵테일에 이런 이름을 붙였을지 의문일 수도 있습니다."},{"kind":"paragraph","text":"여기에는 두가지 설이 있습니다."},{"kind":"paragraph","text":"첫째로는"},{"kind":"paragraph","text":"재료 중 하나인 캄파리는 이탈리아의 북부인 밀라노에서,"},{"kind":"paragraph","text":"오렌지는 이탈리아의 남부에서 가져와"},{"kind":"paragraph","text":"잔 안에서 하나의 칵테일로 완성되어"},{"kind":"paragraph","text":"이탈리아의 통일을 의미한다는 것"},{"kind":"paragraph","text":"둘째로는"},{"kind":"paragraph","text":"가리발디의 군대인 ''붉은 셔츠단 / 가리발디니''가"},{"kind":"paragraph","text":"입던 옷의 색과 닮았다는 것"},{"kind":"paragraph","text":"둘 중 무엇이든 가리발디와 관련이 있어 이러한 이름이 붙은 것으로 보입니다."},{"kind":"paragraph","text":"단순한 캄파리-오렌지였던 이 칵테일이 유명세를 얻게 된 것은"},{"kind":"paragraph","text":"뉴욕의 단테 바(bar Dante)의 나렌 영(Naren Young)에 의해서입니다."},{"kind":"paragraph","text":"그는 오렌지 즙을 블랜더에 넣고 돌려 최대한으로 공기를 주입하였으며,"},{"kind":"paragraph","text":"이를 통해 지루했던 캄파리-오렌지를 특별한 칵테일로 변모시켰습니다."},{"kind":"paragraph","text":"Ingredients?"},{"kind":"figure","src":"/articles/garibaldi/00.webp","width":966,"height":966},{"kind":"paragraph","text":"재료는 캄파리와 오렌지(또는 과즙 100% 오렌지 주스) 2가지로"},{"kind":"paragraph","text":"구하기 아주 간단합니다."},{"kind":"paragraph","text":"캄파리는 이마트나 편의점에서도 쉽게 구할 수 있습니다."},{"kind":"paragraph","text":"How to Mix?"},{"kind":"paragraph","text":"1. 롱 글라스에 얼음을 채우고,"},{"kind":"paragraph","text":"캄파리를 45ml, 오렌지 즙을 30ml를 넣어주고 짧게 스터해줍니다."},{"kind":"paragraph","text":"2. 셰이커(블렌더를 이용해도 됨)에 오렌지 즙 90ml를 넣고"},{"kind":"paragraph","text":"강하게 셰이킹을 해줍니다."},{"kind":"paragraph","text":"3. 잔 안에 있는 캄파리와 섞이지 않게"},{"kind":"paragraph","text":"셰이킹한 오렌지 즙을 조심스럽게 잔 안에 따라줍니다."},{"kind":"paragraph","text":"4. 오렌지 휠 반쪽으로 가니시를 해줍니다."},{"kind":"figure","src":"/articles/garibaldi/01.webp","width":966,"height":966},{"kind":"paragraph","text":"이 칵테일의 키는 오렌지 즙을 강하게 흔들어"},{"kind":"paragraph","text":"공기를 억지로 주입해주는 것입니다."},{"kind":"paragraph","text":"이러한 과정을 거치게 되면 오렌지 즙은 아주 부드러워지게 되어"},{"kind":"paragraph","text":"캄파리의 쓴맛을 좀 더 잘 잡아주기 때문에"},{"kind":"paragraph","text":"일반 캄파리-오렌지보다 훨씬 마시기 편해집니다."},{"kind":"paragraph","text":"''일반적인 캄파리-오렌지와 큰 차이가 나겠어?''"},{"kind":"paragraph","text":"라고 생각할 수도 있지만 칵테일의 질감에서 아주 큰 차이가 납니다."},{"kind":"paragraph","text":"제대로 공기가 주입되면 아주 부드러워지고,"},{"kind":"paragraph","text":"캄파리의 쓴맛과 오렌지 즙의 단맛이 절묘한 밸런스를 이루게 됩니다."},{"kind":"paragraph","text":"인스타그램"}]'::jsonb, 'published', '2021-09-26T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'arran-machrie-moor-cs', 'spirits', '아란 마크리 무어 CS', '마크리 무어 CS는 CS 위스키들 중에서도 유명해', '/articles/arran-machrie-moor-cs/00.webp',
  'https://blog.naver.com/shakinglikebartender/222517346261', false,
  '[{"kind":"paragraph","text":"제가 마크리 무어 CS를 처음 만난 건"},{"kind":"paragraph","text":"광교에 있는 바 글렌베니였습니다."},{"kind":"figure","src":"/articles/arran-machrie-moor-cs/00.webp","width":966,"height":543},{"kind":"paragraph","text":"마크리 무어 CS는 CS 위스키들 중에서도 유명해"},{"kind":"paragraph","text":"언젠가 한 번쯤은 마셔보고 싶던 찰나에"},{"kind":"paragraph","text":"백 바에 있는 보틀을 보고 바로 주문을 했습니다."},{"kind":"paragraph","text":"이 한 잔에 마크리 무어 CS의 매력에 빠져들었고,"},{"kind":"paragraph","text":"때마침 와인앤모어에서 할인행사를 해서 보틀째로 구입을 하게 되었습니다."},{"kind":"paragraph","text":"여담으로 글렌베니는 수원에 있는"},{"kind":"paragraph","text":"몇 안되는 괜찮은 바입니다."},{"kind":"paragraph","text":"특히 위스키 종류가 다양하고, 바텐더분의 서비스가 아주 친절하니"},{"kind":"paragraph","text":"수원 지역에 사는 분들에게 추천합니다!"},{"kind":"paragraph","text":"위스키 뿐만아니라 칵테일도 주문할 수 있습니다."},{"kind":"figure","src":"/articles/arran-machrie-moor-cs/01.webp","width":966,"height":966,"caption":"포장과 보틀 디자인부터 매력적"},{"kind":"heading","text":"About The Whisk(e)y"},{"kind":"paragraph","text":"마크리 무어라는 이름 자체는 아란 섬 서쪽 해안의 피트 습지에서 따온 것입니다."},{"kind":"paragraph","text":"보틀의 개는 아란 섬 지역의 전설에서 아이디어를 얻은 것으로,"},{"kind":"paragraph","text":"전설 속의 거인 전사인 핑갈(Fingal)이"},{"kind":"paragraph","text":"자신이 가장 좋아하는 개인 브랜(Bran)을"},{"kind":"paragraph","text":"마크리 무어 지역에 있는 자신의 의자인 큰 돌에 묶어둔 것에서 영감을 얻었다고 합니다."},{"kind":"paragraph","text":"CS 제품답게 아주 높은 도수를 자랑하며"},{"kind":"paragraph","text":"원래는 한정판 제품의 개념으로 출시되어 각 배치마다 도수가 달랐지만,"},{"kind":"paragraph","text":"마크리 무어가 엄청난 인기를 끌면서"},{"kind":"paragraph","text":"2018년 아란 디스틸러리는 이를 정규 라인으로 들이게 됩니다."},{"kind":"paragraph","text":"정규 라인으로 들인 이후부터는 56.2도로 고정되었습니다."},{"kind":"figure","src":"/articles/arran-machrie-moor-cs/02.webp","width":966,"height":966},{"kind":"heading","text":"Nose"},{"kind":"paragraph","text":"향 자체는 꽤 프루티 하며 서양배의 향이 약간 납니다."},{"kind":"paragraph","text":"피트향이 느껴지기는 하지만"},{"kind":"paragraph","text":"아일라 지역의 피트와는 결이 다른 부드러운 피트함이 느껴집니다."},{"kind":"paragraph","text":"전체적으로 프루티함과 피트함이 기분 좋은 밸런스를 이룹니다."},{"kind":"heading","text":"Palate"},{"kind":"paragraph","text":"부드럽지만 역시 고도수답게 목을 뜨겁게 데워줍니다."},{"kind":"paragraph","text":"맛은 향에 이어서 뭐라고 딱 집을 수는 없지만 과일의 맛이 꽤 납니다."},{"kind":"paragraph","text":"마지막에는 약간의 꿀과 초콜릿스러운 맛이 혀끝에 남았습니다."},{"kind":"paragraph","text":"고도수이지만 전체적으로 맛은 달달하고 부드러운 편인데,"},{"kind":"paragraph","text":"이게 CS의 가장 큰 매력이라 생각됩니다."},{"kind":"paragraph","text":"물을 조금 첨가하면 약간의 라즈베리의 풍미가 느껴지는데"},{"kind":"paragraph","text":"정말 짧은 순간에 느껴지며, 이어서 빵의 풍미가 납니다."},{"kind":"paragraph","text":"물을 넣으면 맛이 풀리지만 반대로 향과 피니쉬를 많이 잃게 되는데,"},{"kind":"paragraph","text":"개인적으로 피니쉬를 좋아해서 물을 첨가하지 않는 게"},{"kind":"paragraph","text":"개인적인 입맛에 맞았습니다."},{"kind":"heading","text":"Finish"},{"kind":"paragraph","text":"피니쉬로 첫번째 숨에 강렬하지만 부드러운 피트의 향이 폭발하고,"},{"kind":"paragraph","text":"두 번째 숨부터 피트향이 은은하고 부드럽고 달달해집니다."},{"kind":"paragraph","text":"피니쉬는 꽤 긴 편으로"},{"kind":"paragraph","text":"처음의 강렬함이 지나가면 부드럽고 은은하게 계속됩니다."},{"kind":"paragraph","text":"피니쉬에서도 아일라 지역의 피트와는 다르게"},{"kind":"paragraph","text":"부드러운 피트함이 느껴집니다."},{"kind":"figure","src":"/articles/arran-machrie-moor-cs/03.webp","width":966,"height":966},{"kind":"paragraph","text":"인스타그램"}]'::jsonb, 'published', '2021-09-26T00:00:00Z'
);

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'espresso-martini-mr-black', 'cocktail', '미스터블랙으로 만든 에스프레소 마티니', '일단 미스터블랙이라는 리큐르에 대해서 알아야 합니다.', '/articles/espresso-martini-mr-black/00.webp',
  'https://blog.naver.com/shakinglikebartender/222323597775', false,
  '[{"kind":"paragraph","text":"미스터블랙으로 만든 에스프레소 마티니는"},{"kind":"paragraph","text":"어떤 게 특별할까요?"},{"kind":"paragraph","text":"일단 미스터블랙이라는 리큐르에 대해서 알아야 합니다."},{"kind":"paragraph","text":"미스터블랙은 쉽게 말해서 설탕은 적게 넣어"},{"kind":"paragraph","text":"단 맛을 줄이고,"},{"kind":"paragraph","text":"커피 함량을 높여 커피 본연의 향과 맛에 집중한"},{"kind":"paragraph","text":"리큐르라고 보면 되죠."},{"kind":"paragraph","text":"미스터블랙은"},{"kind":"paragraph","text":"에스프레소와 미스터블랙의 비율을 1:2로 하는"},{"kind":"paragraph","text":"자신들만의 에스프레소 마티니 레시피를 만들었습니다."},{"kind":"paragraph","text":"별로 특별할 것 없다고 생각할 수 있지만"},{"kind":"paragraph","text":"보드카를 넣지 않고 커피와 커피리큐르만 들어간 칵테일로 커피 본연의 맛에 집중한 칵테일이라는 것이 특별합니다."},{"kind":"paragraph","text":"커피 자체의 맛이라는 본인들의 강점을"},{"kind":"paragraph","text":"잘 반영한 칵테일이라고 할 수 있죠."},{"kind":"paragraph","text":"만드는 것 자체는 간단합니다."},{"kind":"paragraph","text":"에스프레소 1온스(30ml)와 미스터블랙 2온스(60ml)를 셰이커에 넣고"},{"kind":"paragraph","text":"얼음을 채워준 후"},{"kind":"paragraph","text":"강하게 셰이킹을 하면 됩니다."},{"kind":"paragraph","text":"셰이킹은 \"셰이커가 차가워져서 잡고 있지 못할 정도\","},{"kind":"paragraph","text":"대략 8~12초 동안 셰이킹 해주면 됩니다."},{"kind":"figure","src":"/articles/espresso-martini-mr-black/00.webp","width":966,"height":664,"caption":"완성된 미스터블랙 에스프레소 마티니"},{"kind":"paragraph","text":"사진에서 볼 수 있는 것처럼"},{"kind":"paragraph","text":"거품이 아주 오밀조밀하게 만들어집니다."},{"kind":"paragraph","text":"에스프레소뿐만 아니라 미스터블랙 자체에도 커피가 들어있기 때문에 거품 층이 더 잘 형성되는 것 같습니다."},{"kind":"paragraph","text":"미스터블랙에서 주는 약간의 단맛만 있기 때문에"},{"kind":"paragraph","text":"깔루아로 만든 에스프레소 마티니보다 훨씬 단맛이 적습니다."},{"kind":"paragraph","text":"그렇지만 커피 본연의 쌉쌀한 향과 맛은 더욱 잘 살리고 있네요."},{"kind":"paragraph","text":"그렇기 때문에 커피의 쌉쌀한 맛을 선호하는 사람들에게는"},{"kind":"paragraph","text":"미스터블랙으로 만드는 에스프레소 마티니를,"},{"kind":"paragraph","text":"단맛의 칵테일을 선호하는 사람들에게는"},{"kind":"paragraph","text":"깔루아로 만드는 에스프레소 마티니를 추천하고 싶습니다."},{"kind":"paragraph","text":"주의할 점으로는"},{"kind":"paragraph","text":"카페인이 무지막지하게 들어간 칵테일이라는 것입니다."},{"kind":"paragraph","text":"미스터블랙 1온스(30ml)와 에스프레소 1온스(30ml)에 들어있는 카페인의 함량이 같은데"},{"kind":"paragraph","text":"결국 한 잔에 에스프레소 3샷을 마시는 것이죠."},{"kind":"paragraph","text":"마시는 날 잠은 다 잤다고 봐야 할 듯"},{"kind":"paragraph","text":"다행인 것은 도수가 보드카가 들어가지 않고"},{"kind":"paragraph","text":"미스터블랙이 23도이기 때문에"},{"kind":"paragraph","text":"기존의 에스프레소 마티니보다 훨씬 낮다는 것"},{"kind":"paragraph","text":"조만간 바에서도 미스터블랙으로 만든 칵테일들을"},{"kind":"paragraph","text":"만나게 되면 좋겠습니다."},{"kind":"paragraph","text":"#칵테일 #커피 #커피칵테일 #에스프레소 #마티니 #미스터블랙 #리큐르 #리큐어"},{"kind":"paragraph","text":"#홈텐딩 #홈칵테일 #홈바"},{"kind":"paragraph","text":"인스타그램"}]'::jsonb, 'published', '2021-04-26T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
FROM article a, cocktail c
WHERE a.slug = 'espresso-martini-mr-black' AND c.slug = 'espresso';

INSERT INTO article (slug, category, title, dek, hero, source_url, is_sponsored, body, status, published_at)
VALUES (
  'espresso-martini-2021', 'cocktail', '커피를 좋아한다면 꼭 한 번 마셔봐야 하는 칵테일, 에스프레소 마티니', '오히려 블랙 러시안의 베리에이션이라고 봐야 하죠.', '/articles/espresso-martini-2021/00.webp',
  'https://blog.naver.com/shakinglikebartender/222323553996', false,
  '[{"kind":"paragraph","text":"에스프레소 마티니는 이름에서도 알 수 있듯이"},{"kind":"paragraph","text":"에스프레소가 들어간 칵테일입니다."},{"kind":"paragraph","text":"마티니 베리에이션으로 분류하고 있지만"},{"kind":"paragraph","text":"마티니 칵테일과는 관련이 없고"},{"kind":"paragraph","text":"오히려 블랙 러시안의 베리에이션이라고 봐야 하죠."},{"kind":"paragraph","text":"단지 90년대에 V자 형태의 마티니 글라스에"},{"kind":"paragraph","text":"보드카가 들어간 칵테일의 이름을 마티니로 붙이는 것이 유행하면서 이름이 변형된 경우로,"},{"kind":"paragraph","text":"원래의 이름은 보드카 에스프레소(Vodka Espresso)"},{"kind":"paragraph","text":"이전에는 좀 더 직관적인 이름이었네요."},{"kind":"figure","src":"/articles/espresso-martini-2021/00.webp","width":342,"height":395,"caption":"영국의 전설적인 바텐더 딕 브래드셀(Dick Bradsell),        출처 sub13.net"},{"kind":"paragraph","text":"에스프레소 마티니는 80년대 영국의 바텐더 딕 브래드셀(Dick Bradsell)에 의해서 탄생되었습니다."},{"kind":"paragraph","text":"1983년 딕 브레드셀이 소호의 한 레스토랑에서"},{"kind":"paragraph","text":"일하던 당시 런던의 한 톱 모델이"},{"kind":"paragraph","text":"\"잠을 깨워줄 수 있는 술\"을 부탁했습니다."},{"kind":"paragraph","text":"후에 브래드셀은"},{"kind":"paragraph","text":"\"내가 음료를 서빙하는 곳 바로 옆에 커피 머신이 있었고, 모든 사람들이 보드카를 마시던 시절이었다.\"라며"},{"kind":"paragraph","text":"에스프레소 마티니의 탄생 비화를 회상하였습니다."},{"kind":"paragraph","text":"여담으로 이 톱 모델에 대해서"},{"kind":"paragraph","text":"케이트 모스(Kate Moss) 또는 나오미 캠벨(Naomi Cambell)일 것이라는 추측이 나왔지만"},{"kind":"paragraph","text":"당시 케이트 모스가 9살, 나오미 캠벨이 13살이었기 때문에 그저 카더라에 불과했죠."},{"kind":"paragraph","text":"브래드셀은 이 모델이 누구였는지에 대해서는 밝히지 않았다고 합니다."},{"kind":"paragraph","text":"처음 탄생되었을 때는"},{"kind":"paragraph","text":"보드카 에스프레소라는 이름으로 소개되었지만"},{"kind":"paragraph","text":"이후 90년대를 지나면서 그 당시 유행하던 칵테일 작명법으로 에스프레소 마티니라는 이름으로 바뀌게 됩니다."},{"kind":"paragraph","text":"에스프레소 마티니는 크게 두 가지 레시피가 있습니다."},{"kind":"paragraph","text":"저는 이 중에서 더 간편한 레시피를 선호하는 편이에요."},{"kind":"paragraph","text":"바로 ''1:1:1'' 레시피입니다."},{"kind":"paragraph","text":"에스프레소 마티니에 들어가는 재료인"},{"kind":"paragraph","text":"에스프레소, 보드카, 커피리큐르를 같은 비율로 넣어주면 되는 간단한 레시피입니다."},{"kind":"paragraph","text":"에스프레소는 되도록이면"},{"kind":"paragraph","text":"방금 내려서 크레마가 가득한 걸 사용해 주세요."},{"kind":"paragraph","text":"''차가운 칵테일에 뜨거운 에스프레소?''라고"},{"kind":"paragraph","text":"생각하실 수 있지만 에스프레소의 크레마가 이 칵테일의 생명이라 할 수 있습니다."},{"kind":"paragraph","text":"저는 집에 돌체가 있어 쉽게 구할 수 있지만"},{"kind":"paragraph","text":"집에 커피 머신이 없는 분들은 집 근처의"},{"kind":"paragraph","text":"카페나 편의점에서 에스프레소를 구매하시면 됩니다."},{"kind":"figure","src":"/articles/espresso-martini-2021/01.webp","width":406,"height":406},{"kind":"figure","src":"/articles/espresso-martini-2021/02.webp","width":383,"height":383},{"kind":"figure","src":"/articles/espresso-martini-2021/03.webp","width":402,"height":402},{"kind":"figure","src":"/articles/espresso-martini-2021/04.webp","width":409,"height":409,"caption":"셰이킹은 강하게!"},{"kind":"paragraph","text":"셰이커에 에스프레소, 보드카, 커피리큐르를"},{"kind":"paragraph","text":"각각 1온스(30ml) 씩 넣어주시고"},{"kind":"paragraph","text":"얼음으로 셰이커를 채운 다음"},{"kind":"paragraph","text":"다른 칵테일을 만들 때보다 강하게 셰이킹 해주시면 됩니다."},{"kind":"paragraph","text":"셰이킹 시간은"},{"kind":"paragraph","text":"\"셰이커가 차가워져서 잡고 있기 어려울 정도\","},{"kind":"paragraph","text":"대략 8~10초 길면 12초 정도가 됩니다."},{"kind":"paragraph","text":"셰이킹을 하고 나면 자잘한 얼음조각이 나오게 되는데"},{"kind":"paragraph","text":"이런 얼음조각들이 녹으면 칵테일에 예상보다"},{"kind":"paragraph","text":"물이 더 들어가게 되어 맛이 변하게 됩니다."},{"kind":"paragraph","text":"얼음조각들이 칵테일에 들어가지 않게"},{"kind":"paragraph","text":"아래 사진처럼 더블 스트레인을 하는 걸 추천드립니다."},{"kind":"figure","src":"/articles/espresso-martini-2021/05.webp","width":436,"height":436,"caption":"''스트레인(Strain)''이란 완성된 칵테일을 얼음과 분리하여 잔에 따라주는 과정"},{"kind":"paragraph","text":"마지막으로 옵션이지만"},{"kind":"paragraph","text":"커피콩으로 가니시를 하면 에스프레소 마티니가 완성됩니다."},{"kind":"figure","src":"/articles/espresso-martini-2021/06.webp","width":966,"height":543,"caption":"완성된 에스프레소 마티니"},{"kind":"paragraph","text":"에스프레소 마티니의 가장 큰 매력은"},{"kind":"paragraph","text":"에스프레소의 크레마로 인해 생기는 거품 층입니다."},{"kind":"paragraph","text":"다른 아메리카노나 콜드브루로는 거품 층이 생기지 않거나 너무 적은 거품 층이 생기게 됩니다."},{"kind":"paragraph","text":"거품 층을 제대로 만들기 위한 방법으로는"},{"kind":"paragraph","text":"1. 갓 내린 에스프레소를 사용하기"},{"kind":"paragraph","text":"2. 강하게 셰이킹 하기"},{"kind":"paragraph","text":"가 있습니다."},{"kind":"paragraph","text":"에스프레소 마티니는 커피를 좋아하는 분들이"},{"kind":"paragraph","text":"특히 좋아할 만한 칵테일입니다."},{"kind":"paragraph","text":"다만 30도 정도 되는 도수가 높은 술이기 때문에"},{"kind":"paragraph","text":"주의해서 마셔주세요!"},{"kind":"paragraph","text":"#칵테일 #커피칵테일 #커피 #에스프레소 #마티니 #앱솔루트 #보드카 #깔루아"},{"kind":"paragraph","text":"#홈텐딩 #홈칵테일 #홈바"}]'::jsonb, 'published', '2021-04-26T00:00:00Z'
);
INSERT INTO article_related_cocktail (article_id, cocktail_id, position)
SELECT a.id, c.id, 0
